# ----------------------------------------------------------------------------
# Gate.io private API — HMAC-SHA512 request signing (APIv4 scheme) and
# credential storage. Kept fully separate from the public GATE_BASE calls
# used everywhere else in this file: those never need a key/secret at all.
# ----------------------------------------------------------------------------
GATE_API_KEY = ""
GATE_API_SECRET = ""
_credentials_lock = threading.Lock()

# ============================================================================
# v0.99.331 — per-module Gate sub-account API keys, per user request ("для
# одного конкретного индикатора выбрать свои api для биржи", sub-account).
# A module with its own keys trades, sizes (balance), checks positions,
# reconciles and closes ONLY through them; everything else keeps the main
# keys. Every private request picks its keys from a thread-local "current
# account", set by using_account(mode) around execute_autotrade() and the
# few other per-module exchange actions. NO silent fallback: if a module's
# own keys fail, the request fails (logged + Telegram) — never the main
# account's money.
# Stored in their own file (chmod 600), separate from the main keys file.
# ============================================================================
MODULE_ACCOUNT_MODES = ("neuro", "snr", "prv", "zones", "emw")  # v0.99.336 — same order as the tabs; v0.99.398 — Sweep removed
MODULE_ACCOUNT_LABELS = {"msnr": "MSNR", "lsw": "Sweep", "neuro": "Neuro", "snr": "S/R Zones", "prv": "Peak Reversal", "zones": "Зоны", "emw": "EMA W/M"}
MODULE_CREDENTIALS_FILE = os.environ.get(
    "VP_MODULE_CREDENTIALS_FILE",
    os.path.join(os.path.dirname(os.path.abspath(__file__)), "vp_poc_module_credentials.json"),
)
MODULE_CREDENTIALS = {}      # mode -> {"api_key": ..., "api_secret": ...}
_acct_ctx = threading.local()


def account_id_for_mode(mode):
    return mode if mode in MODULE_CREDENTIALS else "default"


def account_label(acc_id):
    return "основной" if acc_id in (None, "default") else f"суб-аккаунт {MODULE_ACCOUNT_LABELS.get(acc_id, acc_id)}"


def current_account_id():
    return getattr(_acct_ctx, "account", None) or "default"


def _acct_prefix():
    acc = current_account_id()
    return "" if acc == "default" else f"[{account_label(acc)}] "


class using_account:
    """with using_account("snr"): ... — every signed request inside goes
    through S/R's own keys if it has them, else the main keys."""
    def __init__(self, mode):
        self.acc = account_id_for_mode(mode) if mode else "default"

    def __enter__(self):
        self.prev = getattr(_acct_ctx, "account", None)
        _acct_ctx.account = self.acc
        return self

    def __exit__(self, *exc):
        _acct_ctx.account = self.prev
        return False


def _current_credentials():
    acc = current_account_id()
    if acc != "default":
        c = MODULE_CREDENTIALS.get(acc) or {}
        return c.get("api_key", ""), c.get("api_secret", ""), acc   # no fallback to the main keys
    return GATE_API_KEY, GATE_API_SECRET, acc


def all_account_ids():
    """Main account + each module account with its own keys (for reconcile)."""
    return ["default"] + [m for m in MODULE_ACCOUNT_MODES if m in MODULE_CREDENTIALS]


def load_module_credentials():
    if not os.path.exists(MODULE_CREDENTIALS_FILE):
        return
    try:
        with open(MODULE_CREDENTIALS_FILE) as f:
            saved = json.load(f) or {}
        with _credentials_lock:
            MODULE_CREDENTIALS.clear()
            for m, c in saved.items():
                if m in MODULE_ACCOUNT_MODES and c.get("api_key") and c.get("api_secret"):
                    MODULE_CREDENTIALS[m] = {"api_key": c["api_key"], "api_secret": c["api_secret"]}
    except Exception as e:
        log_error(f"load_module_credentials: {e}")


def save_module_credentials(mode, api_key=None, api_secret=None):
    """Set (both given) or clear (both None) one module's own keys."""
    with _credentials_lock:
        if api_key and api_secret:
            MODULE_CREDENTIALS[mode] = {"api_key": api_key, "api_secret": api_secret}
        else:
            MODULE_CREDENTIALS.pop(mode, None)
        try:
            tmp_path = MODULE_CREDENTIALS_FILE + ".tmp"
            with open(tmp_path, "w") as f:
                json.dump(MODULE_CREDENTIALS, f)
            os.chmod(tmp_path, 0o600)
            os.replace(tmp_path, MODULE_CREDENTIALS_FILE)
        except Exception as e:
            log_error(f"save_module_credentials: {e}")


def save_credentials(api_key, api_secret):
    """Writes to CREDENTIALS_FILE, chmod 600 (owner read/write only) — best
    effort on platforms that support it; Termux/Android generally does."""
    global GATE_API_KEY, GATE_API_SECRET
    with _credentials_lock:
        GATE_API_KEY = api_key
        GATE_API_SECRET = api_secret
        try:
            tmp_path = CREDENTIALS_FILE + ".tmp"
            with open(tmp_path, "w") as f:
                json.dump({"api_key": api_key, "api_secret": api_secret}, f)
            os.chmod(tmp_path, 0o600)
            os.replace(tmp_path, CREDENTIALS_FILE)
        except Exception as e:
            log_error(f"save_credentials: {e}")


def load_credentials():
    global GATE_API_KEY, GATE_API_SECRET
    if not os.path.exists(CREDENTIALS_FILE):
        return
    try:
        with open(CREDENTIALS_FILE) as f:
            saved = json.load(f)
        with _credentials_lock:
            GATE_API_KEY = saved.get("api_key", "")
            GATE_API_SECRET = saved.get("api_secret", "")
    except Exception as e:
        log_error(f"load_credentials: {e}")


def gate_signed_request(method, url_path, query_string="", body=None, timeout=HTTP_TIMEOUT, retry_on_timeout=False):
    """One request to Gate's authenticated futures API. url_path is the path
    only (e.g. "/futures/usdt/orders"), no host/prefix. body, if given, is
    the dict that will become the JSON payload — signed over its exact
    serialized bytes, so build it once and reuse the same object for both
    signing and sending rather than re-serializing (a different key order
    would still hash the same content, but simpler to just sign what's
    actually sent).
    Signature scheme (Gate APIv4): SIGN = HexEncode(HMAC_SHA512(secret,
    Method + "\\n" + URL + "\\n" + QueryString + "\\n" + HexEncode(SHA512(Payload)) + "\\n" + Timestamp))."""
    api_key, api_secret, _acc = _current_credentials()   # v0.99.331 — per-module sub-account keys
    if not api_key or not api_secret:
        raise RuntimeError(f"Gate.io API credentials not configured ({account_label(_acc)})")
    payload_str = json.dumps(body) if body is not None else ""
    hashed_payload = hashlib.sha512(payload_str.encode("utf-8")).hexdigest()
    full_url_path = "/api/v4" + url_path
    url = f"{GATE_BASE_HOST}{full_url_path}"
    if query_string:
        url += f"?{query_string}"
    # v0.99.112, per direct user report (screenshot: "HTTPSConnectionPool
    # (host='api.gateio.ws', port=443): Read timed out. (read timeout=15)"
    # during a real LONG autotrade attempt, 9 such errors in the log) —
    # this function previously had NO retry at all; a single transient
    # timeout anywhere in execute_autotrade()'s own multi-call flow
    # aborted the whole thing straight to a bare ERROR, wasting a
    # genuinely good signal. retry_on_timeout defaults to False (keeps
    # every existing caller's behavior unchanged) — only READ-ONLY or
    # genuinely IDEMPOTENT calls should ever opt into it. Deliberately
    # NOT applied to order placement: if a timeout happens AFTER Gate's
    # server already processed the order but BEFORE the response
    # reached this client, blindly resending would place a SECOND,
    # duplicate order — a much worse outcome than one wasted signal.
    # Each retry attempt regenerates the timestamp/signature from
    # scratch (not just resending the same signed payload) — Gate's own
    # signature scheme has a timestamp tolerance window, and reusing a
    # timestamp from a request that already waited out a full timeout
    # once risks the retry itself being rejected as stale.
    attempts = 3 if retry_on_timeout else 1
    last_timeout_error = None
    for attempt in range(attempts):
        ts = str(time.time())
        sign_string = f"{method}\n{full_url_path}\n{query_string}\n{hashed_payload}\n{ts}"
        sign = hmac.new(api_secret.encode("utf-8"), sign_string.encode("utf-8"), hashlib.sha512).hexdigest()
        headers = {
            "KEY": api_key, "Timestamp": ts, "SIGN": sign,
            "Accept": "application/json", "Content-Type": "application/json",
        }
        try:
            r = requests.request(method, url, headers=headers, data=payload_str if body is not None else None, timeout=timeout)
        except (requests.exceptions.Timeout, requests.exceptions.ConnectionError) as e:
            last_timeout_error = e
            if attempt < attempts - 1:
                time.sleep(1)
                continue
            raise
        if not r.ok:
            # Gate's error responses carry a JSON body ({"label":..., "message":...})
            # that raise_for_status()'s generic "400 Client Error" text throws away —
            # exactly the detail needed to diagnose a rejected order without guessing.
            try:
                detail = r.json()
            except Exception:
                detail = r.text
            raise requests.exceptions.HTTPError(f"{r.status_code} error for {method} {url_path}: {detail}", response=r)
        return r.json() if r.text else None
    raise last_timeout_error


