def _msnr_nf_trade_r(t):
    """Net R of a closed trade (Neuro-filter reports; shared with Sweep's
    old records)."""
    if t.get("r") is not None:
        return float(t["r"])
    if t.get("result") == "WIN" and t.get("rr") is not None:
        return float(t["rr"])
    if t.get("result") == "LOSS":
        return -1.0
    return None


def _msnr_nf_stats(rows):
    closed = [r for r in rows if r["r"] is not None]
    n = len(closed)
    if not n:
        return {"n": 0, "wr": None, "avg_r": None}
    wins = sum(1 for r in closed if r["r"] > 0)
    return {"n": n, "wr": round(wins / n * 100, 1), "avg_r": round(sum(r["r"] for r in closed) / n, 3)}


REPORT_TEST_TOP_K = 3      # v0.99.380 — filters judged on test (the best 3 on train)
REPORT_ACCEPT_T = 2.0      # ... and they must separate on test by t >= 2


def _pooled_split_t(kept, removed):
    """Two-sample t (kept vs removed) with the pooled spread of both — the
    same shape as the MSNR/Sweep per-coin filter acceptance."""
    if len(kept) < 2 or len(removed) < NEURO_TF_MIN_REMOVED:
        return None
    allr = kept + removed
    ma = sum(allr) / len(allr)
    sd = math.sqrt(sum((x - ma) ** 2 for x in allr) / (len(allr) - 1))
    se = sd * math.sqrt(1 / len(kept) + 1 / len(removed))
    return (sum(kept) / len(kept) - sum(removed) / len(removed)) / se if se > 0 else None


def strategy_filter_report_v1(rows_by_sym):
    """v0.99.337 — shared core of the candidate-filter reports (MSNR's
    Neuro-filter report, S/R's filter report). rows_by_sym: {symbol:
    (train_rows, test_rows)}, row = {"r": trade R or None, "c": {cond: value}}.
    Picks on TRAIN, reports TEST; ranks filters that worsen no coin first,
    then test-WR gain, then fewest trades lost."""
    if not rows_by_sym:
        return None
    train = [r for tr, _ in rows_by_sym.values() for r in tr]
    test = [r for _, te in rows_by_sym.values() for r in te]
    base_train = _msnr_nf_stats(train)
    base_test = _msnr_nf_stats(test)
    # candidates: every (condition, value) seen on train, as "exclude" and "only"
    cands = set()
    for r in train:
        for k, v in r["c"].items():   # Neuro combo conditions + strategy-specific ones (categorical only)
            if (v is not None and not isinstance(v, (list, dict))
                    and (k in _neuro_combo_keys() or k.startswith("snr_"))):
                cands.add((k, v))
    scored = []
    for k, v in cands:
        for mode in ("exclude", "only"):
            keep = (lambda c, k=k, v=v: c.get(k) != v) if mode == "exclude" else (lambda c, k=k, v=v: c.get(k) == v)
            tr_kept = [r for r in train if keep(r["c"])]
            st_tr = _msnr_nf_stats(tr_kept)
            if not st_tr["n"] or st_tr["n"] < MSNR_NF_MIN_KEEP * base_train["n"] or st_tr["wr"] <= base_train["wr"]:
                continue   # selection on TRAIN only
            te_kept = [r for r in test if keep(r["c"])]
            st_te = _msnr_nf_stats(te_kept)
            if st_te["n"] < MSNR_NF_MIN_TEST_TRADES or st_te["n"] < MSNR_NF_MIN_KEEP * base_test["n"]:
                continue
            per_coin, better, worse, same = {}, 0, 0, 0
            for sym, (_tr, te) in rows_by_sym.items():
                b = _msnr_nf_stats(te)
                a = _msnr_nf_stats([r for r in te if keep(r["c"])])
                per_coin[sym] = {"n_b": b["n"], "n_a": a["n"], "wr_b": b["wr"], "wr_a": a["wr"],
                                 "r_b": b["avg_r"], "r_a": a["avg_r"]}
                if not b["n"]:
                    continue
                if a["n"] == b["n"]:
                    same += 1
                elif a["n"] and a["wr"] > b["wr"]:
                    better += 1
                elif a["n"] and a["wr"] == b["wr"]:
                    same += 1
                else:
                    worse += 1
            scored.append({
                "key": k, "value": v, "mode": mode,
                "label": f"{'убрать' if mode == 'exclude' else 'только'}: {NEURO_COND_LABELS.get(k, k)} = {v}",
                "kept_pct": round(st_te["n"] / base_test["n"] * 100, 1),
                "n_b": base_test["n"], "n_a": st_te["n"],
                "wr_b": base_test["wr"], "wr_a": st_te["wr"],
                "r_b": base_test["avg_r"], "r_a": st_te["avg_r"],
                "coins_better": better, "coins_worse": worse, "coins_same": same,
                "coins_total": better + worse + same,
                "all_coins_ok": worse == 0 and better > 0,
                "per_coin": per_coin,
            })
    # user's rule: every coin must gain (no coin worse), then biggest test WR gain,
    # then fewest trades lost
    scored.sort(key=lambda x: (not x["all_coins_ok"], -(x["wr_a"] - x["wr_b"]), -x["kept_pct"]))
    # v0.99.337 — drop mirror duplicates ("убрать weekend" == "только weekday"): same kept trades
    _seen, _uniq = set(), []
    for x in scored:
        sig = (x["n_a"], x["wr_a"], x["r_a"], tuple(sorted((k, v["n_a"], v["wr_a"]) for k, v in x["per_coin"].items())))
        if sig not in _seen:
            _seen.add(sig)
            _uniq.append(x)
    scored = _uniq
    out = {"computed_at": time.time(), "coins": len(rows_by_sym), "train_trades": base_train["n"],
           "base": base_test, "top": scored[:10],
           "all_coins_ok_n": sum(1 for x in scored if x["all_coins_ok"]), "candidates_n": len(scored)}
    return out


def strategy_filter_report(rows_by_sym, rule="v1"):
    """v0.99.381 — S/R, Sweep and P/R keep the original rule (v1: 🏆 = no coin
    worse + biggest test WR gain); MSNR uses the rethought one (v2, see
    strategy_filter_report_v2) — per user: "везде логика устраивала, кроме
    MSNR"."""
    return strategy_filter_report_v2(rows_by_sym) if rule == "v2" else strategy_filter_report_v1(rows_by_sym)


def strategy_filter_report_v2(rows_by_sym):
    """v0.99.337 — shared core of the candidate-filter reports (MSNR, S/R,
    Sweep, P/R). rows_by_sym: {symbol: (train_rows, test_rows)}, row =
    {"r": trade R, "c": {cond: value}}.
    v0.99.379 — rethought (user: "в MSNR фильтры Neuro никогда не дадут
    результат, чтобы все монеты стали лучше"): "every coin better" is almost
    impossible with dozens of coins and a few test trades each, and the old
    ranking by TEST gain let the test part pick the winner. Now:
    - candidates are chosen and RANKED on TRAIN only (pooled t of the trades a
      filter keeps vs the ones it removes, pooled over all coins);
    - TEST only decides pass/fail: the removed test trades must be clearly
      worse (pooled t >= 1), the kept average R higher, and more coins better
      than worse;
    - 🏆 = the best-on-train filter that passes the test."""
    if not rows_by_sym:
        return None
    train = [r for tr, _ in rows_by_sym.values() for r in tr]
    test = [r for _, te in rows_by_sym.values() for r in te]
    base_train = _msnr_nf_stats(train)
    base_test = _msnr_nf_stats(test)
    cands = set()
    for r in train:
        for k, v in r["c"].items():   # Neuro combo conditions + strategy-specific ones (categorical only)
            if (v is not None and not isinstance(v, (list, dict))
                    and (k in _neuro_combo_keys() or k.startswith("snr_"))):
                cands.add((k, v))
    scored = []
    for k, v in cands:
        for mode in ("exclude", "only"):
            keep = (lambda c, k=k, v=v: c.get(k) != v) if mode == "exclude" else (lambda c, k=k, v=v: c.get(k) == v)
            tr_kept = [r["r"] for r in train if r["r"] is not None and keep(r["c"])]
            tr_rem = [r["r"] for r in train if r["r"] is not None and not keep(r["c"])]
            if not tr_kept or len(tr_kept) < MSNR_NF_MIN_KEEP * base_train["n"]:
                continue
            train_t = _pooled_split_t(tr_kept, tr_rem)
            if train_t is None or train_t <= 0:
                continue   # selection on TRAIN only
            te_kept_rows = [r for r in test if keep(r["c"])]
            st_te = _msnr_nf_stats(te_kept_rows)
            if st_te["n"] < MSNR_NF_MIN_TEST_TRADES or st_te["n"] < MSNR_NF_MIN_KEEP * base_test["n"]:
                continue
            te_kept = [r["r"] for r in test if r["r"] is not None and keep(r["c"])]
            te_rem = [r["r"] for r in test if r["r"] is not None and not keep(r["c"])]
            test_t = _pooled_split_t(te_kept, te_rem)
            per_coin, better, worse, same = {}, 0, 0, 0
            for sym, (_tr, te) in rows_by_sym.items():
                b = _msnr_nf_stats(te)
                a = _msnr_nf_stats([r for r in te if keep(r["c"])])
                per_coin[sym] = {"n_b": b["n"], "n_a": a["n"], "wr_b": b["wr"], "wr_a": a["wr"],
                                 "r_b": b["avg_r"], "r_a": a["avg_r"]}
                if not b["n"]:
                    continue
                if a["n"] == b["n"]:
                    same += 1
                elif a["n"] and a["avg_r"] > b["avg_r"]:
                    better += 1
                elif a["n"] and a["avg_r"] == b["avg_r"]:
                    same += 1
                else:
                    worse += 1
            passes = (test_t is not None and test_t >= REPORT_ACCEPT_T
                      and st_te["avg_r"] > base_test["avg_r"] and better > worse)
            scored.append({
                "key": k, "value": v, "mode": mode,
                "label": f"{'убрать' if mode == 'exclude' else 'только'}: {NEURO_COND_LABELS.get(k, k)} = {v}",
                "kept_pct": round(st_te["n"] / base_test["n"] * 100, 1),
                "n_b": base_test["n"], "n_a": st_te["n"],
                "wr_b": base_test["wr"], "wr_a": st_te["wr"],
                "r_b": base_test["avg_r"], "r_a": st_te["avg_r"],
                "train_t": round(train_t, 2), "test_t": round(test_t, 2) if test_t is not None else None,
                "coins_better": better, "coins_worse": worse, "coins_same": same,
                "coins_total": better + worse + same,
                "all_coins_ok": passes,   # kept name for the UI: now "passed the test"
                "per_coin": per_coin,
            })
    # only the REPORT_TEST_TOP_K strongest-on-train filters are judged on test
    # (testing hundreds of candidates on the same test part would let some
    # pass by pure chance); the rest are listed for information only
    scored.sort(key=lambda x: -x["train_t"])
    for i, x in enumerate(scored):
        x["tested"] = i < REPORT_TEST_TOP_K
        x["all_coins_ok"] = x["all_coins_ok"] and x["tested"]
    # ranking: passed first, then by TRAIN strength only
    scored.sort(key=lambda x: (not x["all_coins_ok"], -x["train_t"]))
    # v0.99.337 — drop mirror duplicates ("убрать weekend" == "только weekday"): same kept trades
    _seen, _uniq = set(), []
    for x in scored:
        sig = (x["n_a"], x["wr_a"], x["r_a"], tuple(sorted((k, v["n_a"], v["wr_a"]) for k, v in x["per_coin"].items())))
        if sig not in _seen:
            _seen.add(sig)
            _uniq.append(x)
    scored = _uniq
    out = {"computed_at": time.time(), "coins": len(rows_by_sym), "train_trades": base_train["n"],
           "base": base_test, "top": scored[:10], "rule": "v2",
           "all_coins_ok_n": sum(1 for x in scored if x["all_coins_ok"]), "candidates_n": len(scored)}
    return out


# ============================================================================
# v0.99.364 — Neuro filter INSIDE the backtests of MSNR / S/R / P/R / Sweep
# (user: "топ 1 фильтр сразу применять, чтобы живые сигналы и тест+трейн
# были с учётом фильтра ... и для sweep и для msnr"). Per coin ONE Neuro
# condition ("убрать X" / "только X") is picked on the TRAIN part only
# (best t-stat of net R, keeps >= half the trades); the TEST part decides
# whether it is accepted (each module's own pass rule). An accepted filter
# is stored with the coin's result and applied to its live signals too.
# ============================================================================
NEURO_TF_MIN_KEEP = 0.5          # filter must keep >= 50% of train trades
NEURO_TF_MIN_TRAIN = 15          # and at least this many
NEURO_TF_MIN_TEST = 8            # test trades left after filtering, for MSNR/Sweep acceptance
NEURO_TF_MIN_REMOVED = 5         # MSNR/Sweep: the filter must remove at least this many test trades
NEURO_TF_ACCEPT_T = 1.0          # ... and those must be worse than the kept ones by t >= this
_NEURO_COND_SEM = threading.Semaphore(int(os.environ.get("VP_NEURO_COND_PARALLEL", 8)))   # v0.99.367 — was 2; series are memory-heavy (~25 MB each while computed)
_neuro_cond_cache = {}           # symbol -> {"t": created, "c": {1h bar time: cond dict}}
_neuro_cond_cache_lock = threading.Lock()
NEURO_COND_CACHE_TTL = 6 * 3600
NEURO_COND_CACHE_MAX_SYMBOLS = 200
_neuro_key_tuples = {}           # interned key orders: cached conditions are stored as (keys, values) tuples (~5x smaller than dicts)


def _cond_pack(c):
    if c is None:
        return None
    ks = tuple(c.keys())
    ks = _neuro_key_tuples.setdefault(ks, ks)
    return (ks, tuple(c.values()))


def _cond_unpack(p):
    return None if p is None else dict(zip(p[0], p[1]))


def _neuro_cond_bar(t):
    """1h bar whose close is the last one at or before `t` (no look-ahead):
    the bar that OPENED at least one hour before the signal."""
    t = int(t)
    return (t - 3600) - (t - 3600) % 3600


def neuro_conditions_for_times(symbol, times):
    """{time: cond dict or None} — Neuro conditions of the last 1h bar that
    CLOSED before each time. Cached per symbol (only the bars asked for);
    missing ones are computed over [earliest missing - 120 days, now]."""
    times = [int(t) for t in times if t]
    if not times:
        return {}
    now = time.time()
    with _neuro_cond_cache_lock:
        ent = _neuro_cond_cache.get(symbol)
        if ent and now - ent["t"] > NEURO_COND_CACHE_TTL:
            ent = None
            _neuro_cond_cache.pop(symbol, None)
        have = dict(ent["c"]) if ent else {}
    need = sorted({_neuro_cond_bar(t) for t in times} - set(have))
    if need:
        # wait for a slot while staying "alive" for the progress watchdogs
        while not _NEURO_COND_SEM.acquire(timeout=20):
            neuro_check_cancel()
        try:
            neuro_check_cancel()
            start_ts = need[0] - 120 * 86400
            end_ts = int(now)
            h1 = get_candles_range(symbol, NEURO_TF, start_ts, end_ts) or []
            got = {}
            if len(h1) >= 300:
                htf = get_candles_range(symbol, "4h", start_ts, end_ts) or []
                d1 = get_candles_range(symbol, "1d", start_ts, end_ts) or []
                btc = None if symbol == "BTC_USDT" else (get_candles_range("BTC_USDT", NEURO_TF, start_ts, end_ts) or [])
                eth = None if symbol == "ETH_USDT" else (get_candles_range("ETH_USDT", NEURO_TF, start_ts, end_ts) or [])
                funding = neuro_fetch_funding_rate(symbol, start_ts, end_ts)
                neuro_set_index_context(symbol, start_ts, end_ts)
                try:
                    oi = get_contract_stats(symbol, interval="1h", limit=999)
                except Exception:
                    oi = []
                # v0.99.371 — the heavy series runs in neuro_conditions_core()
                # (a worker process on another core when enabled)
                res = calc_run("neuro_conditions_core", {
                    "h1": h1, "htf": htf, "funding": funding, "btc": btc, "d1": d1, "oi": oi, "eth": eth,
                    "index_close": {str(k): v for k, v in (getattr(_neuro_ctx, "index_close", None) or {}).items()},
                    "need": need})
                for bt in need:
                    c = res.get(str(bt))
                    got[bt] = _cond_pack(c) if c is not None else None
                neuro_clear_index_context()
            else:
                got = {bt: None for bt in need}
        finally:
            _NEURO_COND_SEM.release()
        have.update(got)
        with _neuro_cond_cache_lock:
            ent = _neuro_cond_cache.get(symbol)
            if ent:
                ent["c"].update(got)
            else:
                if len(_neuro_cond_cache) >= NEURO_COND_CACHE_MAX_SYMBOLS:
                    oldest = min(_neuro_cond_cache, key=lambda k: _neuro_cond_cache[k]["t"])
                    _neuro_cond_cache.pop(oldest, None)
                _neuro_cond_cache[symbol] = {"t": now, "c": dict(got)}
    return {t: _cond_unpack(have.get(_neuro_cond_bar(t))) for t in times}


def neuro_conditions_core(h1, htf, funding, btc, d1, oi, eth, index_close, need):
    """v0.99.371 — pure part of neuro_conditions_for_times(): the full Neuro
    condition series, returned only for the requested 1h bars
    ({str(bar time): cond dict or None})."""
    _neuro_ctx.index_close = {int(k): v for k, v in (index_close or {}).items()}
    try:
        conds = neuro_compute_conditions(h1, htf, funding, btc, d1, oi, eth)
    finally:
        _neuro_ctx.index_close = {}
    idx = {c["time"]: i for i, c in enumerate(h1)}
    out = {}
    for bt in need:
        i = idx.get(bt)
        out[str(bt)] = conds[i] if i is not None and i < len(conds) else None
    return out


def neuro_filter_label(f):
    return f"{'убрать' if f['mode'] == 'exclude' else 'только'}: {NEURO_COND_LABELS.get(f['key'], f['key'])} = {f['value']}"


def neuro_filter_pass(f, cond):
    """True = the trade/signal is kept. Unknown conditions (no data) are
    kept — the same rule in the backtest and live."""
    if not f or cond is None:
        return True
    v = cond.get(f["key"])
    if v is None:
        return True
    return (str(v) != str(f["value"])) if f["mode"] == "exclude" else (str(v) == str(f["value"]))


def _tstat(rs):
    n = len(rs)
    if n < 2:
        return None
    m = sum(rs) / n
    var = sum((x - m) ** 2 for x in rs) / (n - 1)
    return m / math.sqrt(var / n) if var > 0 else None


def neuro_pick_trade_filter(train_rows):
    """train_rows: [(net R, cond dict or None)]. Returns the single filter
    with the best train t-stat of net R that beats no filter, or None.
    Uses ONLY the train rows — the test part must not influence it."""
    n = len(train_rows)
    base = _tstat([r for r, _ in train_rows])
    if base is None or n < NEURO_TF_MIN_TRAIN:
        return None
    keys = set(_neuro_combo_keys())
    cands = set()
    for _, c in train_rows:
        if c:
            for k, v in c.items():
                if k in keys and v is not None and not isinstance(v, (list, dict)):
                    cands.add((k, str(v)))
    best = None
    need = max(NEURO_TF_MIN_TRAIN, NEURO_TF_MIN_KEEP * n)
    for k, v in sorted(cands):
        for mode in ("exclude", "only"):
            f = {"key": k, "value": v, "mode": mode}
            kept = [r for r, c in train_rows if neuro_filter_pass(f, c)]
            if len(kept) < need or len(kept) == n:
                continue
            t = _tstat(kept)
            if t is not None and t > base and (best is None or t > best[0]):
                best = (t, f)
    if not best:
        return None
    f = dict(best[1])
    f["label"] = neuro_filter_label(f)
    f["train_t_before"], f["train_t_after"] = round(base, 2), round(best[0], 2)
    return f


def neuro_filter_live_check(symbol, f, sig_time):
    """(keep, cond value) for a live signal under the coin's accepted filter."""
    if not f or not NEURO_TRADE_FILTER_ENABLED:
        return True, None
    try:
        cond = neuro_conditions_for_times(symbol, [sig_time]).get(int(sig_time))
    except NeuroCancelled:
        raise
    except Exception as e:
        log_error(f"neuro filter live {symbol}: {e}")
        return True, None
    v = cond.get(f["key"]) if cond else None
    return neuro_filter_pass(f, cond), v


def neuro_split_filter_for_trades(symbol, trades, split_time, r_of, time_key="time"):
    """MSNR / Sweep helper: pick a filter on trades with time <= split_time,
    accept it only if the test part (time > split_time) gets a better mean
    net R while keeping >= 50% (and >= NEURO_TF_MIN_TEST) of its trades.
    Returns (filter or None, info dict for the UI)."""
    closed = [t for t in trades if r_of(t) is not None and t.get(time_key)]
    if len(closed) < NEURO_TF_MIN_TRAIN + NEURO_TF_MIN_TEST:
        return None, {"status": "мало сделок"}
    cmap = neuro_conditions_for_times(symbol, [t[time_key] for t in closed])
    rows = [(r_of(t), cmap.get(int(t[time_key])), t[time_key] <= split_time) for t in closed]
    train = [(r, c) for r, c, is_tr in rows if is_tr]
    test = [(r, c) for r, c, is_tr in rows if not is_tr]
    f = neuro_pick_trade_filter(train)
    if not f:
        return None, {"status": "на обучающей части ни одно условие не помогло"}
    kept = [r for r, c in test if neuro_filter_pass(f, c)]
    removed = [r for r, c in test if not neuro_filter_pass(f, c)]
    b_mean = sum(r for r, _ in test) / len(test) if test else None
    a_mean = sum(kept) / len(kept) if kept else None
    info = {"label": f["label"], "test_n_before": len(test), "test_n_after": len(kept),
            "test_r_before": round(b_mean, 3) if b_mean is not None else None,
            "test_r_after": round(a_mean, 3) if a_mean is not None else None}
    # accepted only if, on the untouched test part, the trades it removes
    # were clearly worse than the ones it keeps (one-sided Welch t >= 1) —
    # a mere tiny improvement happens by chance for about half of all filters
    # (two-sample t with the pooled spread of the whole test part)
    t_diff = None
    if len(kept) >= 2 and len(removed) >= NEURO_TF_MIN_REMOVED:
        mk, mr = sum(kept) / len(kept), sum(removed) / len(removed)
        allr = kept + removed
        ma = sum(allr) / len(allr)
        sd = math.sqrt(sum((x - ma) ** 2 for x in allr) / (len(allr) - 1))   # pooled: a few identical removed losses can't fake a huge t
        se = sd * math.sqrt(1 / len(kept) + 1 / len(removed))
        t_diff = (mk - mr) / se if se > 0 else None
    info["test_t"] = round(t_diff, 2) if t_diff is not None else None
    ok = (kept and len(kept) >= max(NEURO_TF_MIN_TEST, NEURO_TF_MIN_KEEP * len(test))
          and b_mean is not None and a_mean > b_mean
          and t_diff is not None and t_diff >= NEURO_TF_ACCEPT_T)
    info["status"] = "принят" if ok else "отклонён проверочной частью"
    return (f if ok else None), info


def _rr_trade_net_r(t):
    """MSNR / Sweep trade -> net R after fees (WIN +rr, LOSS -1), else None."""
    if t.get("result") == "WIN" and t.get("rr") is not None:
        r = float(t["rr"])
    elif t.get("result") == "LOSS":
        r = -1.0
    else:
        return None
    return r - trade_fee_r(t.get("entry"), t.get("sl"))


def _trades_sig(trades):
    ts = [t.get("time") for t in trades if t.get("time")]
    return [len(trades), min(ts) if ts else None, max(ts) if ts else None]


def _filter_split_time(trades):
    closed = sorted((t for t in trades if _rr_trade_net_r(t) is not None and t.get("time")), key=lambda t: t["time"])
    if len(closed) < NEURO_TF_MIN_TRAIN + NEURO_TF_MIN_TEST:
        return None
    return closed[max(1, int(len(closed) * MSNR_NF_TRAIN_FRAC)) - 1]["time"]


def _apply_filter_to_trades(symbol, trades, f):
    cm = neuro_conditions_for_times(symbol, [t["time"] for t in trades if t.get("time")])
    return [t for t in trades if not t.get("time") or neuro_filter_pass(f, cm.get(int(t["time"])))]


def lsw_apply_neuro_trade_filters(loop_name="lsw_neuro_filter_loop"):
    """v0.99.364 — same as msnr_apply_neuro_trade_filters() for Sweep: the
    accepted filter rewrites the coin's trade list + summary, and its live
    eligibility / directions are recomputed with lsw_live_decision()."""
    with state_lock:
        results = dict(STATE.get("lsw_backtest_results") or {})
        fmap = dict(STATE.get("lsw_trade_filters") or {})
    changed = {}
    for sym, trades in results.items():
        prev = fmap.get(sym) or {}
        if not trades or prev.get("sig_after") == _trades_sig(trades):
            continue   # this list is already the filtered/decided one
        heartbeat(loop_name)
        info = {"status": "мало сделок"}
        f = None
        try:
            split = _filter_split_time(trades)
            if split is not None:
                f, info = neuro_split_filter_for_trades(sym, trades, split, _rr_trade_net_r)
        except Exception as e:
            log_error(f"lsw neuro trade filter {sym}: {e}")
            continue
        kept = _apply_filter_to_trades(sym, trades, f) if f else trades
        changed[sym] = (trades, f, info, kept)
    if not changed:
        return
    with state_lock:
        res = STATE["lsw_backtest_results"]
        fm = STATE.setdefault("lsw_trade_filters", {})
        for sym, (trades, f, info, kept) in changed.items():
            if res.get(sym) is not trades:
                continue
            entry = {"info": info, "sig_after": _trades_sig(kept)}
            if f:
                before = STATE["lsw_backtest_summary"].get(sym) or {}
                entry["filter"] = {k: f[k] for k in ("key", "value", "mode", "label")}
                entry["before"] = {"n": before.get("n"), "win_rate": before.get("win_rate")}
                res[sym] = kept
                summary = lsw_summarize_backtest(kept, before.get("split_time"))   # v0.99.396
                STATE["lsw_backtest_summary"][sym] = summary
                is_live, dirs = lsw_live_decision(summary)
                if is_live and sym not in STATE["lsw_live_universe"]:
                    STATE["lsw_live_universe"].append(sym)
                elif not is_live and sym in STATE["lsw_live_universe"]:
                    STATE["lsw_live_universe"].remove(sym)
                if dirs is not None:
                    STATE["lsw_live_directions"][sym] = dirs
            fm[sym] = entry
    save_state()


def lsw_neuro_filter_analysis():
    """v0.99.360 — same report for Sweep (user: "может и sweep прогонять по
    фильтрам Neuro?"). Sweep trades have the same shape as MSNR's (WIN =
    +rr, LOSS = -1R, TIMEOUT ignored), so the identical pipeline applies:
    Neuro conditions on the last 1h bar CLOSED before the signal, pick on
    the first 70% of each coin's trades, judge on the last 30%.
    Informational only — nothing is applied to Sweep's trading."""
    with state_lock:
        results = {k: list(v or []) for k, v in (STATE.get("lsw_backtest_results") or {}).items()}
    rows_by_sym = neuro_filter_rows_by_sym(results, "lsw_neuro_filter_loop", "lsw_neuro_filter_analysis")
    if rows_by_sym is None:
        return None
    out = strategy_filter_report(rows_by_sym)
    if out is None:
        return None
    with state_lock:
        STATE["lsw_neuro_filters"] = out
    return out


def lsw_neuro_filter_loop():
    nf_startup_wait(LSW_NF_TRIGGER, 1500, "lsw_neuro_filters", "lsw_neuro_filter_loop", "lsw")   # v0.99.385
    while True:
        LSW_NF_TRIGGER.clear()
        _nf_on = LSW_ENABLED
        if _nf_on:
            bt_log_start("lsw_nf")   # v0.99.393
        _nf_ok, _nf_err = True, None
        try:
            if LSW_ENABLED:
                lsw_neuro_filter_analysis()
                if NEURO_TRADE_FILTER_ENABLED:
                    lsw_apply_neuro_trade_filters()   # v0.99.364
        except Exception as e:
            _nf_ok, _nf_err = False, str(e)[:80]
            log_error(f"lsw_neuro_filter_loop: {e}")
        if _nf_on:
            bt_log_end("lsw_nf", ok=_nf_ok, note=_nf_err)   # v0.99.393
        # v0.99.393 — only after the next backtest (trigger); was also every
        # 6h on unchanged trades
        bt_wait("lsw_nf", LSW_NF_TRIGGER, NF_IDLE_SEC, "lsw_neuro_filter_loop", trigger_reason="после бэктеста", scheduled=False)   # after every Sweep backtest (trigger) or 6h


def neuro_filter_rows_by_sym(results, loop_name, err_name):
    """v0.99.360 — factored out of msnr_neuro_filter_analysis() unchanged:
    {symbol: [trade]} (trade: time, result WIN/LOSS/TIMEOUT, rr) ->
    {symbol: (train_rows, test_rows)} for strategy_filter_report(), or None
    when there is nothing to analyse."""
    results = {k: v for k, v in results.items() if len([t for t in v if _msnr_nf_trade_r(t) is not None]) >= 5}
    if not results:
        return None
    rows_by_sym = {}
    for sym, trades in results.items():
        heartbeat(loop_name)
        # v0.99.364 — conditions come from the shared per-symbol cache
        # (neuro_conditions_for_times: same "last 1h bar CLOSED before the
        # signal" rule), instead of recomputing every coin's full series on
        # every report run
        try:
            cmap = neuro_conditions_for_times(sym, [t["time"] for t in trades if t.get("time")])
        except Exception as e:
            log_error(f"{err_name} {sym}: {e}")
            continue
        rows = []
        for t in sorted(trades, key=lambda x: x.get("time") or 0):
            r = _msnr_nf_trade_r(t)
            if r is None or not t.get("time"):
                continue
            c = cmap.get(int(t["time"]))
            if c is None:
                continue
            rows.append({"r": r, "c": c})
        if len(rows) >= 5:
            cut = max(1, int(len(rows) * MSNR_NF_TRAIN_FRAC))
            rows_by_sym[sym] = (rows[:cut], rows[cut:])
    return rows_by_sym


def ft5_backtest_loop():
    # v0.99.267 -- staggered backtest-cycle startup, see msnr_backtest_
    # loop()'s own comment for the full reasoning. This module's first
    # cycle waits 270s before starting, spreading all 7 backtest
    # loops' initial burst of network activity across ~9 minutes
    # instead of all colliding on the shared semaphore at once.
    # v0.99.272 -- CRITICAL FIX, per direct user report that "Очистить
    # FT5"/a restart button did nothing right after a fresh restart:
    # this used to be a PLAIN time.sleep(), which FT5_BACKTEST_TRIGGER.
    # set() has no way to interrupt -- the button was silently a no-op
    # for the ENTIRE initial stagger window. Now uses the same trigger
    # for the startup delay too.
    _trig = FT5_BACKTEST_TRIGGER.wait(timeout=270)
    FT5_BACKTEST_TRIGGER.clear()
    bt_startup_skip("ft5", FT5_BACKTEST_TRIGGER, max(3600, FT5_REFRESH_SEC), "ft5_backtest_loop", _trig)   # v0.99.385
    while True:
        _ft5_sem_acquired = False
        try:
            if not FT5_ENABLED:
                time.sleep(60)
                continue
            t0 = time.time()
            # v0.99.268 — same shared concurrency cap as msnr_backtest_loop's
            # own (see its comment for the full reasoning).
            BACKTEST_CONCURRENCY_SEMAPHORE.acquire()
            _ft5_sem_acquired = True
            universe = ft5_build_universe()
            with state_lock:
                STATE["ft5_universe"] = universe
                STATE["ft5_symbols_done"] = 0
            for symbol in universe:
                try:
                    result = ft5_optimize_symbol(symbol)
                    with state_lock:
                        STATE["ft5_symbol_overrides"][symbol] = result
                        STATE["ft5_symbols_done"] += 1
                except Exception as e:
                    log_error(f"ft5_optimize {symbol}: {e}")
            # Rank the full FT5_UNIVERSE_SIZE analysis pool by ft5_ranking_
            # score() (a lower-confidence-bound on the mean, v0.98.7 —
            # computed once per symbol in ft5_optimize_symbol()) and keep
            # only the best FT5_LIVE_TOP_N for live scanning — per direct
            # user request: analyze widely, trade narrowly. Went through
            # two fixes: raw avg_pnl_pct (v0.98.0) let a small lucky
            # sample rank above a symbol firing far more often at a
            # slightly lower average; sample-size shrinkage (v0.98.3)
            # fixed that but still let a combo with MORE losses outrank
            # one with fewer losses and a higher average, since it never
            # separately weighed loss frequency, only n. The confidence-
            # bound version naturally penalizes both small samples and
            # high-variance ones (frequent large losses inflate variance
            # directly) with one formula instead of two stacked ad-hoc
            # discounts. Symbols with no result, an error, or too few
            # backtested trades sort to the bottom and naturally never
            # make the live cut.
            with state_lock:
                overrides = dict(STATE["ft5_symbol_overrides"])
                ranked = sorted(
                    overrides.items(),
                    key=lambda kv: (kv[1].get("score") if kv[1] and not kv[1].get("error") else None) or -999,
                    reverse=True,
                )
                STATE["ft5_live_universe"] = [sym for sym, _ in ranked[:FT5_LIVE_TOP_N]]
                STATE["ft5_last_backtest_finished"] = time.time()
                STATE["ft5_last_backtest_duration"] = round(time.time() - t0, 1)
        except Exception as e:
            log_error(f"ft5_backtest_loop: {e}")
        finally:
            if _ft5_sem_acquired:
                BACKTEST_CONCURRENCY_SEMAPHORE.release()
        FT5_BACKTEST_TRIGGER.wait(timeout=max(3600, FT5_REFRESH_SEC))
        FT5_BACKTEST_TRIGGER.clear()


def ft5_live_loop():
    while True:
        try:
            if not FT5_ENABLED:
                time.sleep(60)
                continue
            with state_lock:
                live_universe = list(STATE["ft5_live_universe"])
            if live_universe:
                # v0.99.286 — same CRITICAL FIX as the main scan cycle's
                # own (see its own comment for the full incident) — this
                # had the identical no-timeout context-manager pattern.
                FT5_LIVE_PER_SYMBOL_TIMEOUT = HTTP_TIMEOUT * 3 + 30
                ex = ThreadPoolExecutor(max_workers=min(WORKERS, len(live_universe)))
                try:
                    futs = [ex.submit(ft5_scan_symbol_live, s) for s in live_universe]
                    try:
                        for fut in as_completed(futs, timeout=FT5_LIVE_PER_SYMBOL_TIMEOUT * math.ceil(len(futs) / WORKERS)):
                            try:
                                fut.result(timeout=FT5_LIVE_PER_SYMBOL_TIMEOUT)
                            except (TimeoutError, FutureTimeoutError):
                                log_error(f"ft5_live_loop: a symbol exceeded {FT5_LIVE_PER_SYMBOL_TIMEOUT}s — skipping, abandoning stuck thread")
                            except Exception as e:
                                log_error(f"ft5_live_loop: {e}")
                    except (TimeoutError, FutureTimeoutError):
                        log_error("ft5_live_loop: overall ceiling exceeded waiting on a stuck symbol — proceeding with whatever completed")
                finally:
                    ex.shutdown(wait=False)
            update_ft5_signal_outcomes()
        except Exception as e:
            log_error(f"ft5_live_loop: {e}")
        time.sleep(max(60, FT5_SCAN_INTERVAL_SEC))


