NEURO_VALID_MIN_TRADES = int(os.environ.get("VP_NEURO_VALID_MIN_TRADES", 15))   # closed trades in B needed to rank a coin; v0.99.416 — 10 -> 15 (user: 3-4 lucky RR-4 wins put a coin on top)
NEURO_TEST_MIN_TRADES = int(os.environ.get("VP_NEURO_TEST_MIN_TRADES", 10))   # v0.99.416 — test trades needed for the test gate
NEURO_MINE_MIN_R = float(os.environ.get("VP_NEURO_MINE_MIN_R", 0.1))   # v0.99.432 — net R/trade the dependencies must make on the mining part itself
NEURO_HISTORY_DAYS   = int(os.environ.get("VP_NEURO_HISTORY_DAYS", 1500))  # ask for as much as possible; exchange will just return what it has
NEURO_REFRESH_SEC    = int(os.environ.get("VP_NEURO_REFRESH_SEC", 24 * 3600))  # v0.99.236 — raised 4h->24h per direct user request: with the universe now 120 coins instead of a fixed 20, a full cycle takes MUCH longer, and re-mining more than once a day added little value anyway (the underlying ~13-month rolling window barely shifts hour to hour — established during an earlier session discussion)
NEURO_MINING_TRIGGER = threading.Event()  # v0.99.212 — same "Очистить X doesn't wake the sleeping loop" fix as LSW/MSNR's own trigger events, for the new "Очистить Neuro" button
NEURO_PER_SYMBOL_MAX_SEC = int(os.environ.get("VP_NEURO_PER_SYMBOL_MAX_SEC", 1500))  # v0.99.212, raised 300->480 in v0.99.216, raised 480->720 in v0.99.261 — per direct user report of multiple real symbols hitting the old 480s ceiling on real hardware after this session's cumulative additions (38->47 conditions, veto filters, early-exit rule search) made per-symbol processing genuinely slower even after removing a redundant condition-recomputation (see neuro_simulate_trades()'s own return_conds param) — real devices are slower than the sandbox this was tuned against, so the ceiling needed headroom, not just the one fixable inefficiency
# v0.99.358 — per user ("может таки дольше ждать, если оно не зависло?"):
# a coin is no longer cut off by a fixed clock. The worker reports progress
# at every checkpoint; it is stopped only if it made NO progress for
# NEURO_STALL_SEC (a real hang), or as a last resort after
# NEURO_PER_SYMBOL_HARD_MAX_SEC. A slow-but-working coin is waited for.
# NEURO_PER_SYMBOL_MAX_SEC above is kept only for old references.
NEURO_STALL_SEC = int(os.environ.get("VP_NEURO_STALL_SEC", 600))
NEURO_PER_SYMBOL_HARD_MAX_SEC = int(os.environ.get("VP_NEURO_PER_SYMBOL_HARD_MAX_SEC", 4 * 3600))
NEURO_WAIT_POLL_SEC = 30
_neuro_worker_progress = {}   # thread ident -> time.monotonic() of the last checkpoint
# v0.99.357 — raised 720->1500 per user report (every coin hitting 720s).
# The bigger fix is below: a timed-out coin's thread used to keep computing
# in the background (Python can't kill a thread), so each timeout left a
# zombie eating CPU/GIL, the NEXT coin got slower and timed out too — a
# cascade that made every coin fail. Now the worker checks a cancel flag at
# its loop checkpoints and stops itself within seconds of being abandoned.


class NeuroCancelled(BaseException):
    """Raised inside an abandoned Neuro worker thread. BaseException so the
    many broad `except Exception` blocks on the way up don't swallow it."""


_neuro_cancelled_threads = set()   # thread idents told to stop
_neuro_cancel_lock = threading.Lock()


def neuro_check_cancel():
    """Cheap checkpoint: records progress (v0.99.358) and stops the thread
    if it was abandoned."""
    ident = threading.get_ident()
    _neuro_worker_progress[ident] = time.monotonic()
    if _neuro_cancelled_threads and ident in _neuro_cancelled_threads:
        raise NeuroCancelled()


def _neuro_run_cancellable(ident_box, fn, *args):
    ident = threading.get_ident()
    _neuro_worker_progress[ident] = time.monotonic()
    ident_box.append(ident)
    try:
        return fn(*args)
    finally:
        _neuro_worker_progress.pop(ident, None)
        with _neuro_cancel_lock:
            _neuro_cancelled_threads.discard(ident)


def neuro_wait_worker(fut, ident_box, on_wait=None):
    """v0.99.358 — wait for a Neuro worker while it keeps making progress.
    Returns the result; raises FutureTimeoutError (after cancelling the
    worker) on a real stall or the hard cap. The message says which."""
    started = time.monotonic()
    while True:
        try:
            return fut.result(timeout=NEURO_WAIT_POLL_SEC)
        except (TimeoutError, FutureTimeoutError):
            now = time.monotonic()
            last = _neuro_worker_progress.get(ident_box[0], started) if ident_box else started
            if now - last > NEURO_STALL_SEC:
                neuro_cancel_thread(ident_box)
                raise FutureTimeoutError(f"stalled: no checkpoint for {NEURO_STALL_SEC // 60} min, after {int(now - started) // 60} min total")
            if now - started > NEURO_PER_SYMBOL_HARD_MAX_SEC:
                neuro_cancel_thread(ident_box)
                raise FutureTimeoutError(f"hard limit: still computing after {NEURO_PER_SYMBOL_HARD_MAX_SEC // 3600} h")
            if on_wait:
                on_wait()


POOL_STALL_SEC = int(os.environ.get("VP_POOL_STALL_SEC", 600))
POOL_HARD_MAX_SEC = int(os.environ.get("VP_POOL_HARD_MAX_SEC", 2 * 3600))


def run_pool_with_progress(fn, items, workers, loop_name, on_result, on_stop, stall_sec=None, hard_sec=None, on_tick=None):
    """v0.99.362 — parallel per-coin backtest (S/R, P/R) without a fixed
    per-coin clock. Every worker reports progress through
    neuro_check_cancel() checkpoints; one that made no progress for
    POOL_STALL_SEC (a real hang) or ran POOL_HARD_MAX_SEC is told to stop
    and actually stops at its next checkpoint — no CPU-eating zombie left
    behind (the old "exceeded 300s — abandoning stuck thread" did leave
    one, and each zombie slowed the rest until everything timed out).
    on_result(item, fut) is called for each finished worker, on_stop(item,
    reason) for each stopped one."""
    ex = ThreadPoolExecutor(max_workers=max(1, workers))
    boxes, futs, first_seen = {}, {}, {}
    for it in items:
        box = []
        f = ex.submit(_neuro_run_cancellable, box, fn, it)
        futs[f], boxes[f] = it, box
    pending = set(futs)
    try:
        while pending:
            done, pending = futures_wait(pending, timeout=NEURO_WAIT_POLL_SEC, return_when=FIRST_COMPLETED)
            heartbeat(loop_name)
            for f in done:
                on_result(futs[f], f)
            now = time.monotonic()
            for f in list(pending):
                box = boxes[f]
                if not box:
                    continue   # still queued, not started
                started = first_seen.setdefault(f, now)
                last = _neuro_worker_progress.get(box[0], started)
                reason = None
                st = stall_sec or POOL_STALL_SEC
                hd = hard_sec or POOL_HARD_MAX_SEC
                if now - last > st:
                    reason = f"stalled: no checkpoint for {st // 60} min"
                elif now - started > hd:
                    reason = f"hard limit: still computing after {hd // 3600} h"
                if reason:
                    neuro_cancel_thread(box)
                    pending.discard(f)
                    on_stop(futs[f], reason)
            if on_tick and pending:
                on_tick()   # v0.99.371 — workers still progressing: tell the caller's watchdog
    finally:
        ex.shutdown(wait=False)


# ============================================================================
# v0.99.370 — calculation worker PROCESSES (user: "переделать под больше
# ядер ... для s/r делай"). Python threads share one core (GIL); separate
# processes each get their own. multiprocessing needs sem_open, which
# Android/Termux lacks, so workers are plain child processes started with
# `python vp_poc_screener.py --calc-worker`, talking JSON lines over
# stdin/stdout. Only pure functions (no network, no shared state) are sent
# there; downloads stay in the main process. A worker that hangs or is
# abandoned is simply killed — no zombie threads. CALC_WORKERS = 0 turns it
# off (everything computed in-process, as before).
# Protocol, worker -> main: "P" = progress tick, "R <json>" = result,
# "E <json text>" = error.
# ============================================================================
CALC_WORKERS = int(os.environ.get("VP_CALC_WORKERS", 3))
CALC_FUNCS = ("snr_optimize_core", "prv_optimize_core", "neuro_backtest_core", "neuro_conditions_core",
              "lsw_backtest_core", "emw_touches_core")
# settings that can change at runtime are sent with every task, so a worker
# always computes with the main process's current values
CALC_CONST_PREFIXES = ("SNR_", "PRV_", "NEURO_", "MSNR_", "LSW_", "EMW_", "AUTOTRADE_SIM_FEE_PCT")
_calc_pool = []            # idle worker Popen objects
_calc_busy = 0
_calc_cond = threading.Condition()
_calc_failures = 0         # consecutive worker failures -> fall back to in-process
_calc_stats = {"tasks": 0, "fallbacks": 0, "restarts": 0}
# v0.99.371 — first run / after "Очистить": use more cores, then back to CALC_WORKERS
CALC_WORKERS_BOOST = int(os.environ.get("VP_CALC_WORKERS_BOOST", min(8, os.cpu_count() or 4)))
_calc_boost = set()        # modules currently in a first / post-reset run
_calc_busy_by = {}         # v0.99.372 — module -> worker processes it is using right now
_CALC_FN_MODULE = {"snr_optimize_core": "snr", "prv_optimize_core": "prv",
                   "neuro_backtest_core": "neuro", "neuro_conditions_core": "cond",
                   "lsw_backtest_core": "lsw", "emw_touches_core": "emw"}


def calc_status(mod):
    """v0.99.372 — for the UI: processes this module uses now, the current
    limit, all busy, CPU cores, and whether the first-run boost is on."""
    with _calc_cond:
        return {"mine": _calc_busy_by.get(mod, 0), "busy": _calc_busy, "limit": calc_limit(),
                "cores": os.cpu_count() or 0, "boost": bool(_calc_boost), "enabled": CALC_WORKERS > 0}


class calc_boost:
    """with calc_boost("snr", first_run): ... — while any module's first
    (or post-reset) cycle runs, calc_limit() allows CALC_WORKERS_BOOST."""
    def __init__(self, mod, active):
        self.mod, self.active = mod, bool(active)

    def __enter__(self):
        if self.active:
            with _calc_cond:
                _calc_boost.add(self.mod)
        return self

    def __exit__(self, *exc):
        with _calc_cond:
            _calc_boost.discard(self.mod)
            _calc_cond.notify_all()
        return False


def _calc_boosted(mod, first_run, fn, *args):
    """v0.99.375 — run a backtest cycle with the first-run core boost."""
    with calc_boost(mod, first_run):
        return fn(*args)


def calc_apply_limit():
    """v0.99.373 — a changed cores setting applies right away: waiting
    tasks re-check the limit now, idle processes above it are closed.
    Busy ones finish their current coin first."""
    extra = []
    with _calc_cond:
        while _calc_pool and len(_calc_pool) + _calc_busy > calc_limit():
            extra.append(_calc_pool.pop())
        _calc_cond.notify_all()
    for proc in extra:
        _calc_kill(proc)


def calc_limit():
    if CALC_WORKERS <= 0:
        return 0
    return max(CALC_WORKERS, CALC_WORKERS_BOOST) if _calc_boost else CALC_WORKERS


class _CalcWorkerDied(Exception):
    pass


def neuro_is_cancelled():
    return bool(_neuro_cancelled_threads) and threading.get_ident() in _neuro_cancelled_threads


def _calc_spawn():
    import subprocess
    errlog = open(os.path.join(os.path.dirname(os.path.abspath(__file__)), "vp_calc_worker.log"), "ab")
    proc = subprocess.Popen([sys.executable, "-u", os.path.abspath(__file__), "--calc-worker"],
                            stdin=subprocess.PIPE, stdout=subprocess.PIPE, stderr=errlog,
                            cwd=os.path.dirname(os.path.abspath(__file__)))
    errlog.close()
    return proc


def _calc_kill(proc):
    try:
        proc.kill()
        proc.wait(timeout=5)
    except Exception:
        pass


def _calc_acquire():
    global _calc_busy
    with _calc_cond:
        while _calc_busy >= max(1, calc_limit()):
            _calc_cond.wait(timeout=20)
            neuro_check_cancel()   # queued for a worker: alive, and still stoppable
        _calc_busy += 1
        proc = _calc_pool.pop() if _calc_pool else None
    if proc is None or proc.poll() is not None:
        proc = _calc_spawn()
    return proc


def _calc_release(proc, healthy):
    global _calc_busy
    with _calc_cond:
        _calc_busy -= 1
        if healthy and proc.poll() is None and len(_calc_pool) + _calc_busy < max(0, calc_limit()):
            _calc_pool.append(proc)
            proc = None
        _calc_cond.notify()
    if proc is not None:
        _calc_kill(proc)


def _calc_exchange(proc, fn, kwargs):
    import select
    consts = {k: v for k, v in list(globals().items())
              if k.startswith(CALC_CONST_PREFIXES) and isinstance(v, (int, float, str, bool, list))}
    payload = (json.dumps({"fn": fn, "kw": kwargs, "consts": consts}, separators=(",", ":")) + "\n").encode()
    try:
        proc.stdin.write(payload)
        proc.stdin.flush()
    except (BrokenPipeError, OSError) as e:
        raise _CalcWorkerDied(f"send failed: {e}")
    fd = proc.stdout.fileno()
    buf = b""
    while True:
        if neuro_is_cancelled():
            raise NeuroCancelled()
        ready, _, _ = select.select([fd], [], [], 2.0)
        if not ready:
            if proc.poll() is not None:
                raise _CalcWorkerDied(f"worker exited ({proc.returncode})")
            continue
        chunk = os.read(fd, 1 << 20)
        if not chunk:
            raise _CalcWorkerDied(f"worker closed its output ({proc.poll()})")
        buf += chunk
        while b"\n" in buf:
            line, buf = buf.split(b"\n", 1)
            if line == b"P":
                neuro_check_cancel()   # real progress in the worker -> progress here
            elif line.startswith(b"R "):
                return json.loads(line[2:])
            elif line.startswith(b"E "):
                raise RuntimeError(json.loads(line[2:]))


def calc_run(fn, kwargs):
    """Run a pure calculation function `fn(**kwargs)` in a worker process
    (or in-process when CALC_WORKERS is 0 or workers keep failing). The
    result is the same either way (JSON round trip of plain data)."""
    global _calc_failures
    assert fn in CALC_FUNCS
    if CALC_WORKERS <= 0 or _calc_failures >= 3:
        return globals()[fn](**kwargs)
    proc = _calc_acquire()
    healthy = False
    mod = _CALC_FN_MODULE.get(fn, fn)
    with _calc_cond:
        _calc_busy_by[mod] = _calc_busy_by.get(mod, 0) + 1
    try:
        res = _calc_exchange(proc, fn, kwargs)
        healthy = True
        _calc_failures = 0
        _calc_stats["tasks"] += 1
        return res
    except _CalcWorkerDied as e:
        _calc_failures += 1
        _calc_stats["fallbacks"] += 1
        log_error(f"calc worker: {e} — computing this one in the main process")
        return globals()[fn](**kwargs)
    finally:
        with _calc_cond:
            _calc_busy_by[mod] = max(0, _calc_busy_by.get(mod, 1) - 1)
        _calc_release(proc, healthy)


def calc_worker_main():
    """Entry point of a worker process (`--calc-worker`)."""
    proto = os.fdopen(os.dup(1), "w", buffering=1)
    sys.stdout = sys.stderr            # any stray print() must not break the protocol
    last = [0.0]

    def tick():
        now = time.monotonic()
        if now - last[0] >= 1.0:
            last[0] = now
            proto.write("P\n")

    globals()["neuro_check_cancel"] = tick
    globals()["log_error"] = lambda msg: print("[ERR]", msg, file=sys.stderr)
    for line in sys.stdin:
        if not line.strip():
            continue
        try:
            task = json.loads(line)
            globals().update(task.get("consts") or {})
            if task.get("fn") not in CALC_FUNCS:
                raise ValueError(f"unknown function {task.get('fn')}")
            res = globals()[task["fn"]](**task["kw"])
            proto.write("R " + json.dumps(res, separators=(",", ":")) + "\n")
        except Exception as e:
            proto.write("E " + json.dumps(f"{type(e).__name__}: {e}") + "\n")
        proto.flush()


def neuro_cancel_thread(ident_box):
    if ident_box:
        with _neuro_cancel_lock:
            _neuro_cancelled_threads.add(ident_box[0])
NEURO_RR             = float(os.environ.get("VP_NEURO_RR", 2.0))  # fallback/default only — see NEURO_RR_CANDIDATES below for the actual per-symbol auto-tuned value
NEURO_RR_CANDIDATES  = [1.5, 1.75, 2.0, 2.25, 2.5, 2.75, 3.0]   # v0.99.412 — back to max 3 (user); v0.99.398 had added 3.5/4/5  # v0.99.210 — small step (0.25), modest range, per direct user request ("вариативность RR, но не с гигантским шагом"). Best one picked per-symbol from TRAIN-period trades only (same walk-forward discipline as the condition mining itself), then applied to the reported trade history and live signals.
NEURO_RR_MIN_TRADES  = int(os.environ.get("VP_NEURO_RR_MIN_TRADES", 15))  # don't trust an RR pick based on fewer than this many train-period trades
NEURO_DECAY_WINDOW_DAYS = int(os.environ.get("VP_NEURO_DECAY_WINDOW_DAYS", 40))  # v0.99.220 — explicit CALENDAR-time recency window for decay detection, per direct user follow-up ("не только 40%, это не 1 месяц — ещё хотя бы за последние 40 дней"): a percentage-of-occurrences split doesn't map to any fixed real-world timeframe (a rare pattern's last 40% of occurrences could span many months; a frequent one's could be just days) — this checks an ACTUAL calendar window on top of that
NEURO_DECAY_MIN_RECENT_N = 8  # minimum occurrences in a recency window before trusting a decay verdict from it
# v0.99.221 — AGGREGATE per-symbol decay check, per direct user report of
# a genuinely bad recent stretch (16.7% WR over the last ~24 closed BTC
# trades) that no single pattern's own decay flag caught, because the
# losing streak was spread across 8 DIFFERENT patterns (each contributing
# only a handful of trades — none individually hitting its own minimum
# recency sample). Per-pattern decay is necessary but not sufficient: a
# shared regime shift can drag down many different patterns' live results
# a little each, without any ONE of them crossing its own threshold. This
# checks the actual combined trade OUTCOME for the whole symbol, ignoring
# which pattern produced each trade.
NEURO_AGG_DECAY_WINDOW = 30       # look at the last N CLOSED (non-timeout) trades for this symbol
NEURO_AGG_DECAY_MIN_N = 15        # minimum closed trades in that window before trusting the verdict
NEURO_AGG_DECAY_MARGIN_PP = 5.0   # flag if recent WR is more than this many percentage points below RR breakeven

# v0.99.255 — "veto filter" second-layer, per direct user request ("есть
# смысл на бэктесте к сделкам по стопам отдельно прогнать ещё раз фильтры,
# может можно спасти часть сделок?"). A GENUINELY DIFFERENT question than
# the main mining loop's own ("does condition X predict forward return"):
# given that a CONFIRMED pattern already fired a trade, does some EXTRA
# condition at entry time discriminate between THAT pattern's own wins and
# losses? Found on TRAIN only, then VALIDATED it still holds on TEST
# before being trusted — the exact same walk-forward discipline as
# everything else in this module, deliberately NOT just re-running
# filters against the fixed historical losses and declaring victory
# (which would just curve-fit to noise in that specific sample — flagged
# to the user directly before building this).
NEURO_VETO_MIN_TRAIN_TRADES = 30   # minimum (win+loss) trades for a pattern before even attempting veto-filter discovery
NEURO_VETO_MIN_VALUE_SAMPLE = 10   # minimum trades within one candidate value-slice to trust its own win rate
NEURO_VETO_MIN_TEST_TRADES = 10    # minimum matching TEST trades to trust the validation
NEURO_VETO_MIN_WR_LIFT_PP = 15.0   # minimum win-rate percentage-point improvement on TRAIN to even consider a candidate
NEURO_VETO_TEST_LIFT_FRACTION = 0.5  # the TEST lift must retain at least this fraction of the TRAIN lift to be trusted


def neuro_find_early_exit_rule(trades, boundary_time):
    """v0.99.260 — per direct user request: find, on TRAIN only, an (mae_
    threshold, mfe_threshold) pair such that trades matching "mae_at_k >=
    mae_threshold AND mfe_at_k <= mfe_threshold" turn out overwhelmingly
    to be LOSSES — then VALIDATE the exact same rule against TEST-period
    trades before trusting it, same walk-forward discipline as neuro_
    find_veto_filters(). Only considers trades that survived_k (resolved
    AFTER the checkpoint — nothing to decide early for a trade that
    already closed by then). Returns a rule dict or None."""
    candidates_mae = [0.3, 0.4, 0.5, 0.6, 0.7, 0.8]
    candidates_mfe = [0.1, 0.15, 0.2, 0.25, 0.3]

    train_pool = [t for t in trades if t["survived_k"] and t["result"] in ("WIN", "LOSS") and t["time"] <= boundary_time]
    test_pool = [t for t in trades if t["survived_k"] and t["result"] in ("WIN", "LOSS") and t["time"] > boundary_time]
    if len(train_pool) < NEURO_EARLY_EXIT_MIN_TRAIN_N:
        return None

    best = None
    for mae_th in candidates_mae:
        for mfe_th in candidates_mfe:
            matching = [t for t in train_pool if t["mae_at_k"] >= mae_th and t["mfe_at_k"] <= mfe_th]
            if len(matching) < NEURO_EARLY_EXIT_MIN_TRAIN_N:
                continue
            wr = sum(1 for t in matching if t["result"] == "WIN") / len(matching) * 100
            if wr > NEURO_EARLY_EXIT_MAX_WR_PP:
                continue
            # Prefer the candidate with the MOST matching trades among
            # those clearing the win-rate bar — more coverage is more
            # useful in practice than shaving a couple more points off
            # an already-low win rate on a smaller slice.
            if best is None or len(matching) > best["train_n"]:
                best = {"mae_threshold": mae_th, "mfe_threshold": mfe_th,
                        "train_wr": round(wr, 1), "train_n": len(matching)}
    if not best:
        return None

    test_matching = [t for t in test_pool if t["mae_at_k"] >= best["mae_threshold"] and t["mfe_at_k"] <= best["mfe_threshold"]]
    if len(test_matching) < NEURO_EARLY_EXIT_MIN_TEST_N:
        return None
    test_wr = sum(1 for t in test_matching if t["result"] == "WIN") / len(test_matching) * 100
    if abs(test_wr - best["train_wr"]) > NEURO_EARLY_EXIT_TEST_WR_TOLERANCE_PP or test_wr > NEURO_EARLY_EXIT_MAX_WR_PP * 2:
        return None  # didn't hold up on TEST — reject rather than trust a TRAIN-only fluke

    # Honest expected benefit: average realized pnl if exiting AT the
    # checkpoint bar's own close (close_at_k_pnl) vs the trade's actual
    # historical pnl_r (waiting for full resolution) — for the SAME
    # matching TEST trades, so this is an out-of-sample estimate, not a
    # backfit number.
    avg_actual = sum(t["pnl_r"] for t in test_matching) / len(test_matching)
    avg_if_exited_early = sum((t["close_at_k_pnl"] if t["close_at_k_pnl"] is not None else t["pnl_r"]) for t in test_matching) / len(test_matching)

    best["test_wr"] = round(test_wr, 1)
    best["test_n"] = len(test_matching)
    best["avg_pnl_actual"] = round(avg_actual, 3)
    best["avg_pnl_if_early_exit"] = round(avg_if_exited_early, 3)
    best["k"] = NEURO_EARLY_EXIT_K
    return best


def neuro_find_veto_filters(confirmed_patterns, trades, full_conds, boundary_time):
    """Returns {(pattern_type, pattern_value): veto_filter_dict} for every
    confirmed pattern where a second condition was found (on TRAIN) and
    confirmed (on TEST) to meaningfully discriminate between that
    pattern's own wins and losses. `full_conds` must be computed over the
    SAME candle series `trades`' own bar_idx values index into (i.e. the
    full train+test series, not a separately-indexed slice)."""
    train_group, test_group = {}, {}
    for t in trades:
        if t["result"] not in ("WIN", "LOSS"):
            continue
        key = (t["pattern_type"], t["pattern_value"])
        bucket = train_group if t["time"] <= boundary_time else test_group
        bucket.setdefault(key, []).append(t)

    veto_filters = {}
    for pat in confirmed_patterns:
        key = (pat["type"], str(pat["value"]))
        own_keys = set(pat["type"].split("+"))
        train_trades_for_pat = train_group.get(key, [])
        if len(train_trades_for_pat) < NEURO_VETO_MIN_TRAIN_TRADES:
            continue
        overall_wr = sum(1 for t in train_trades_for_pat if t["result"] == "WIN") / len(train_trades_for_pat) * 100

        by_val = {}
        for t in train_trades_for_pat:
            bucket = full_conds[t["bar_idx"]]
            for other_key in NEURO_CONDITION_KEYS:
                if other_key in own_keys:
                    continue
                v = bucket.get(other_key)
                if v is not None:
                    by_val.setdefault((other_key, v), []).append(t)

        best = None
        for (other_key, val), group in by_val.items():
            if len(group) < NEURO_VETO_MIN_VALUE_SAMPLE:
                continue
            wr = sum(1 for t in group if t["result"] == "WIN") / len(group) * 100
            lift = wr - overall_wr
            if lift >= NEURO_VETO_MIN_WR_LIFT_PP and (best is None or lift > best["lift"]):
                best = {"key": other_key, "value": val, "train_wr": round(wr, 1),
                        "train_n": len(group), "train_overall_wr": round(overall_wr, 1), "lift": round(lift, 1)}
        if not best:
            continue

        test_trades_for_pat = test_group.get(key, [])
        test_matching = [t for t in test_trades_for_pat if full_conds[t["bar_idx"]].get(best["key"]) == best["value"]]
        if len(test_matching) < NEURO_VETO_MIN_TEST_TRADES or not test_trades_for_pat:
            continue
        test_wr = sum(1 for t in test_matching if t["result"] == "WIN") / len(test_matching) * 100
        test_overall_wr = sum(1 for t in test_trades_for_pat if t["result"] == "WIN") / len(test_trades_for_pat) * 100
        test_lift = test_wr - test_overall_wr
        if test_lift >= best["lift"] * NEURO_VETO_TEST_LIFT_FRACTION:
            veto_filters[key] = {**best, "test_wr": round(test_wr, 1), "test_n": len(test_matching),
                                  "test_lift": round(test_lift, 1)}
    return veto_filters

NEURO_SL_ATR_MULT    = float(os.environ.get("VP_NEURO_SL_ATR_MULT", 1.5))
NEURO_MAX_WAIT_BARS  = int(os.environ.get("VP_NEURO_MAX_WAIT_BARS", 48))

# v0.99.260 — early-exit ("cut losses early") layer, per direct user
# request ("сигнал закрывается по стопу если сразу идёт к нему... минусовые
# сделки можно закрывать раньше, при этом писать статистику для таких
# сигналов, закрытых раньше времени, чтобы знать его исход"). Verified the
# underlying idea directly on synthetic data BEFORE building anything: at
# a fixed early checkpoint (bar 3), trades already showing a large adverse
# excursion (MAE) with little favorable movement (MFE) turned out to have
# a dramatically lower eventual win rate than the overall average (0.1%
# vs 22.4% baseline in the synthetic test) — consistent with basic first-
# passage-time intuition (already being close to a barrier makes hitting
# it far more likely), not a fluke pattern-specific correlation. Still
# found and validated the SAME honest train-then-test way as the veto-
# filter feature (v0.99.255) before ever wiring it into anything real.
NEURO_EARLY_EXIT_K = 3            # bar count checkpoint for the early MAE/MFE reading
NEURO_EARLY_EXIT_MIN_TRAIN_N = 30  # minimum TRAIN trades surviving to bar K before even searching for a rule
NEURO_EARLY_EXIT_MIN_TEST_N = 10   # minimum matching TEST trades to trust the validation
NEURO_EARLY_EXIT_MAX_WR_PP = 15.0  # candidate rule's own TRAIN win rate among matching trades must be at most this many points, i.e. a strong loss-skew
NEURO_EARLY_EXIT_TEST_WR_TOLERANCE_PP = 15.0  # the TEST win rate among matching trades must stay within this many points of the TRAIN win rate to trust it held up
NEURO_MIN_AGREE_Z    = float(os.environ.get("VP_NEURO_MIN_AGREE_Z", 2.5))  # combined |z| needed to fire a live signal
TELEGRAM_ALERTS_NEURO = os.environ.get("VP_TG_ALERTS_NEURO", "1") == "1"
TELEGRAM_ALERTS_NEURO_SUMMARY = os.environ.get("VP_TG_ALERTS_NEURO_SUMMARY", "0") == "1"  # v0.99.248 — separate toggle, per direct user request ("присылать в кратком формате статистику бэктеста... галочку в настройки на уведомление такого типа") — a compact per-symbol digest at the end of each full mining cycle, distinct from TELEGRAM_ALERTS_NEURO's own live-signal alerts


def neuro_ema_series(prices, period):
    if len(prices) < period:
        return [None] * len(prices)
    k = 2.0 / (period + 1)
    out = [None] * (period - 1)
    ema = sum(prices[:period]) / period
    out.append(ema)
    for p in prices[period:]:
        ema = p * k + ema * (1 - k)
        out.append(ema)
    return out


def neuro_rsi_series(closes, period=14):
    if len(closes) < period + 1:
        return [None] * len(closes)
    gains, losses = [], []
    for i in range(1, len(closes)):
        d = closes[i] - closes[i - 1]
        gains.append(max(d, 0))
        losses.append(max(-d, 0))
    out = [None] * period
    avg_gain = sum(gains[:period]) / period
    avg_loss = sum(losses[:period]) / period
    rs = avg_gain / avg_loss if avg_loss > 0 else float("inf")
    out.append(100 - 100 / (1 + rs) if avg_loss > 0 else 100)
    for i in range(period, len(gains)):
        avg_gain = (avg_gain * (period - 1) + gains[i]) / period
        avg_loss = (avg_loss * (period - 1) + losses[i]) / period
        rs = avg_gain / avg_loss if avg_loss > 0 else float("inf")
        out.append(100 - 100 / (1 + rs) if avg_loss > 0 else 100)
    return out


def neuro_atr_series(candles, period=14):
    if len(candles) < 2:
        return [None] * len(candles)
    trs = [candles[0]["high"] - candles[0]["low"]]
    for i in range(1, len(candles)):
        c = candles[i]
        tr = max(c["high"] - c["low"], abs(c["high"] - candles[i - 1]["close"]), abs(c["low"] - candles[i - 1]["close"]))
        trs.append(tr)
    out = [None] * (period - 1) if len(trs) >= period else [None] * len(trs)
    if len(trs) >= period:
        atr = sum(trs[:period]) / period
        out.append(atr)
        for tr in trs[period:]:
            atr = (atr * (period - 1) + tr) / period
            out.append(atr)
    return out


def neuro_stoch_k_series(candles, period=14):
    out = [None] * len(candles)
    for i in range(period - 1, len(candles)):
        window = candles[i - period + 1:i + 1]
        hh = max(c["high"] for c in window)
        ll = min(c["low"] for c in window)
        if hh > ll:
            out[i] = (candles[i]["close"] - ll) / (hh - ll) * 100
    return out


def neuro_williams_r_series(candles, period=14):
    out = [None] * len(candles)
    for i in range(period - 1, len(candles)):
        window = candles[i - period + 1:i + 1]
        hh = max(c["high"] for c in window)
        ll = min(c["low"] for c in window)
        if hh > ll:
            out[i] = (hh - candles[i]["close"]) / (hh - ll) * -100
    return out


def neuro_adx_series(candles, period=14):
    """Average Directional Index — trend STRENGTH (0-100), independent of
    direction. Distinct from EMA-side/htf_trend which say WHICH way the
    trend points; ADX says HOW STRONG it currently is."""
    n = len(candles)
    if n < period * 2:
        return [None] * n
    plus_dm, minus_dm, tr = [0.0], [0.0], [candles[0]["high"] - candles[0]["low"]]
    for i in range(1, n):
        c, p = candles[i], candles[i - 1]
        up, down = c["high"] - p["high"], p["low"] - c["low"]
        plus_dm.append(up if (up > down and up > 0) else 0.0)
        minus_dm.append(down if (down > up and down > 0) else 0.0)
        tr.append(max(c["high"] - c["low"], abs(c["high"] - p["close"]), abs(c["low"] - p["close"])))

    def _smooth(vals):
        out = [None] * (period - 1)
        s = sum(vals[:period])
        out.append(s)
        for v in vals[period:]:
            s = s - s / period + v
            out.append(s)
        return out

    str_, spdm, smdm = _smooth(tr), _smooth(plus_dm), _smooth(minus_dm)
    dx = [None] * n
    for i in range(n):
        if str_[i] and str_[i] > 0:
            pdi, mdi = 100 * spdm[i] / str_[i], 100 * smdm[i] / str_[i]
            if pdi + mdi > 0:
                dx[i] = 100 * abs(pdi - mdi) / (pdi + mdi)
    valid = [(i, d) for i, d in enumerate(dx) if d is not None]
    if len(valid) < period:
        return [None] * n
    out = [None] * n
    first_i = valid[0][0]
    if first_i + period > n:
        return out
    adx_val = sum(dx[first_i:first_i + period]) / period
    out[first_i + period - 1] = adx_val
    for i in range(first_i + period, n):
        if dx[i] is not None:
            adx_val = (adx_val * (period - 1) + dx[i]) / period
            out[i] = adx_val
    return out


def neuro_vwap_series(candles, period=20):
    """Rolling VWAP over the last `period` bars (resets each window — a
    simple rolling approximation, not a session-anchored VWAP, since crypto
    trades 24/7 with no natural session boundary)."""
    out = [None] * len(candles)
    for i in range(period - 1, len(candles)):
        window = candles[i - period + 1:i + 1]
        vol_sum = sum(c["volume"] for c in window)
        if vol_sum > 0:
            typical_sum = sum(((c["high"] + c["low"] + c["close"]) / 3) * c["volume"] for c in window)
            out[i] = typical_sum / vol_sum
    return out


def neuro_ichimoku_cloud(candles, tenkan_period=9, kijun_period=26, senkou_b_period=52, shift=26):
    """Classic Ichimoku Kumo (cloud): senkou span A/B, projected `shift` bars
    forward as per the original indicator. Returns (senkou_a, senkou_b) series
    aligned to the CURRENT bar index (i.e. already shifted)."""
    n = len(candles)
    highs = [c["high"] for c in candles]
    lows = [c["low"] for c in candles]

    def _mid(period, i):
        if i < period - 1:
            return None
        return (max(highs[i - period + 1:i + 1]) + min(lows[i - period + 1:i + 1])) / 2

    tenkan = [_mid(tenkan_period, i) for i in range(n)]
    kijun = [_mid(kijun_period, i) for i in range(n)]
    senkou_a_raw = [None if (tenkan[i] is None or kijun[i] is None) else (tenkan[i] + kijun[i]) / 2 for i in range(n)]
    senkou_b_raw = [_mid(senkou_b_period, i) for i in range(n)]

    senkou_a = [None] * n
    senkou_b = [None] * n
    for i in range(n):
        src = i - shift
        if 0 <= src < n:
            senkou_a[i] = senkou_a_raw[src]
            senkou_b[i] = senkou_b_raw[src]
    return senkou_a, senkou_b


def neuro_roc_series(closes, period=12):
    """Rate of Change — % price change over `period` bars, a straightforward
    momentum measure distinct from RSI/Stochastic (which are bounded
    oscillators; ROC is an unbounded % return)."""
    out = [None] * len(closes)
    for i in range(period, len(closes)):
        if closes[i - period] > 0:
            out[i] = (closes[i] - closes[i - period]) / closes[i - period] * 100
    return out


def neuro_align_agreement(candles, other_candles, lookback=4):
    """Generic version of the existing BTC-agreement check — whether this
    symbol's own N-bar return has the SAME sign as `other_candles`'s return
    over the same window. Reused for both BTC and ETH correlation checks."""
    if not other_candles or len(other_candles) < lookback + 2:
        return [None] * len(candles)
    other_times = [c["time"] for c in other_candles]
    other_closes = [c["close"] for c in other_candles]
    out = []
    for i, c in enumerate(candles):
        if i < lookback:
            out.append(None)
            continue
        own_ret = c["close"] - candles[i - lookback]["close"]
        pos = bisect.bisect_right(other_times, c["time"]) - 1
        pos_prev = pos - lookback
        if pos < 0 or pos_prev < 0:
            out.append(None)
            continue
        other_ret = other_closes[pos] - other_closes[pos_prev]
        if own_ret == 0 or other_ret == 0:
            out.append(None)
        else:
            out.append("agree" if (own_ret > 0) == (other_ret > 0) else "diverge")
    return out


def _neuro_align_recent_signals(candles, raw_sigs, lookback_bars=4):
    """Shared core for neuro_align_lsw_sweep()/neuro_align_mirror_signal():
    given a candle series and a list of already-detected signals (each
    with 'entry_time'/'direction'), label each bar by whether a signal
    fired in either direction within the last `lookback_bars` bars."""
    times = [c["time"] for c in candles]
    sig_by_time = {}
    for sig in raw_sigs:
        sig_by_time.setdefault(sig["entry_time"], []).append(sig["direction"])
    out = [None] * len(candles)
    for i, t in enumerate(times):
        window_start = candles[max(0, i - lookback_bars)]["time"]
        directions = set()
        for st, dirs in sig_by_time.items():
            if window_start <= st <= t:
                directions.update(dirs)
        if not directions:
            out[i] = "none"
        elif directions == {"LONG"}:
            out[i] = "long_recent"
        elif directions == {"SHORT"}:
            out[i] = "short_recent"
        else:
            out[i] = "both_recent"
    return out


def neuro_bb_width_series(closes, period=20):
    """Bollinger Band width (normalized by mean price) — a volatility
    SQUEEZE/EXPANSION measure distinct from the existing ATR-based
    vol_regime: BB width reflects dispersion of CLOSING prices over a
    shorter window, ATR reflects true range including gaps/wicks — the
    two can and do diverge (e.g. quiet closes with occasional violent
    wicks vs steadily widening closes with tame wicks)."""
    out = [None] * len(closes)
    for i in range(period - 1, len(closes)):
        window = closes[i - period + 1:i + 1]
        mean = sum(window) / period
        if mean <= 0:
            continue
        var = sum((x - mean) ** 2 for x in window) / period
        out[i] = (4 * var ** 0.5) / mean
    return out


def neuro_obv_series(candles):
    """On-Balance Volume — cumulative volume-weighted direction. A
    genuinely different momentum lens than vol_zone (a single bar's
    volume level) or vol_regime (ATR-based): OBV accumulates volume in
    the direction of each bar's own close-to-close move, so its TREND
    reflects whether volume has been persistently supporting the recent
    price direction or fighting it."""
    obv = [0.0] * len(candles)
    for i in range(1, len(candles)):
        if candles[i]["close"] > candles[i - 1]["close"]:
            obv[i] = obv[i - 1] + candles[i]["volume"]
        elif candles[i]["close"] < candles[i - 1]["close"]:
            obv[i] = obv[i - 1] - candles[i]["volume"]
        else:
            obv[i] = obv[i - 1]
    return obv


def neuro_supertrend_series(candles, period=10, mult=3.0):
    """Classic ATR-based Supertrend — a trend-following overlay with a
    genuinely different shape than EMA-side/MACD: it flips only when
    price closes decisively through a volatility-adjusted band, giving
    it more "stickiness" through noise than a simple moving-average
    cross."""
    atr = neuro_atr_series(candles, period)
    out = [None] * len(candles)
    final_upper = final_lower = None
    cur_trend = 1
    for i in range(len(candles)):
        if atr[i] is None:
            continue
        c = candles[i]
        hl2 = (c["high"] + c["low"]) / 2
        basic_upper = hl2 + mult * atr[i]
        basic_lower = hl2 - mult * atr[i]
        if final_upper is None:
            final_upper, final_lower = basic_upper, basic_lower
        else:
            final_upper = basic_upper if (basic_upper < final_upper or candles[i - 1]["close"] > final_upper) else final_upper
            final_lower = basic_lower if (basic_lower > final_lower or candles[i - 1]["close"] < final_lower) else final_lower
        if c["close"] > final_upper:
            cur_trend = 1
        elif c["close"] < final_lower:
            cur_trend = -1
        out[i] = "above" if cur_trend == 1 else "below"
    return out


def neuro_rsi_divergence_series(candles, rsi_series_vals, lookback=14):
    """Classic bullish/bearish RSI divergence: price makes a new N-bar
    extreme but RSI fails to confirm it — a well-known reversal-warning
    pattern distinct from rsi_zone's own simple level (oversold/
    overbought), since a divergence can occur at ANY RSI level, not
    just the extremes."""
    out = [None] * len(candles)
    for i in range(lookback, len(candles)):
        if rsi_series_vals[i] is None or rsi_series_vals[i - lookback] is None:
            continue
        window_low_idx = min(range(i - lookback, i + 1), key=lambda k: candles[k]["low"])
        window_high_idx = max(range(i - lookback, i + 1), key=lambda k: candles[k]["high"])
        if (window_low_idx == i and candles[i]["low"] < candles[i - lookback]["low"]
                and rsi_series_vals[i] is not None and rsi_series_vals[i - lookback] is not None
                and rsi_series_vals[i] > rsi_series_vals[i - lookback]):
            out[i] = "bullish"
        elif (window_high_idx == i and candles[i]["high"] > candles[i - lookback]["high"]
                and rsi_series_vals[i] is not None and rsi_series_vals[i - lookback] is not None
                and rsi_series_vals[i] < rsi_series_vals[i - lookback]):
            out[i] = "bearish"
        else:
            out[i] = "none"
    return out


def neuro_cci_series(candles, period=20):
    """Commodity Channel Index — an UNBOUNDED momentum oscillator (unlike
    RSI/Stochastic's fixed 0-100 range), measuring how far the typical
    price has strayed from its own recent mean in units of mean absolute
    deviation. Genuinely complementary to the existing bounded
    oscillators: because it's unbounded, CCI keeps discriminating during
    strong sustained moves where RSI/Stochastic simply pin at their caps
    — confirmed via web research (StockCharts/CrossTrade/AvaTrade) as a
    standard, asset-agnostic "team player" indicator specifically valued
    for this reason."""
    out = [None] * len(candles)
    tp = [(c["high"] + c["low"] + c["close"]) / 3 for c in candles]
    for i in range(period - 1, len(candles)):
        window = tp[i - period + 1:i + 1]
        sma = sum(window) / period
        mean_dev = sum(abs(x - sma) for x in window) / period
        if mean_dev > 0:
            out[i] = (tp[i] - sma) / (0.015 * mean_dev)
    return out


def neuro_chop_series(candles, period=14):
    """Choppiness Index — measures whether price is moving EFFICIENTLY
    (a strong trend, low value) or just churning back and forth without
    real net progress (high value = ranging/choppy), via log(sum of true
    range) vs log(net high-low range) over the window. Genuinely
    complementary to the existing ADX-based adx_zone: ADX measures
    DIRECTIONAL strength (are DI+/DI- diverging), CHOP measures movement
    EFFICIENCY (is the true range mostly "wasted" oscillating vs
    covering real ground) — confirmed via web research as a standard,
    mathematically distinct regime classifier widely paired WITH ADX
    rather than replacing it."""
    out = [None] * len(candles)
    trs = [None] * len(candles)
    for i in range(len(candles)):
        c = candles[i]
        if i == 0:
            trs[i] = c["high"] - c["low"]
            continue
        p = candles[i - 1]
        trs[i] = max(c["high"] - c["low"], abs(c["high"] - p["close"]), abs(c["low"] - p["close"]))
    log_period = math.log10(period)
    for i in range(period - 1, len(candles)):
        window = candles[i - period + 1:i + 1]
        sum_tr = sum(trs[i - period + 1:i + 1])
        hh = max(c["high"] for c in window)
        ll = min(c["low"] for c in window)
        if hh > ll and sum_tr > 0 and log_period > 0:
            out[i] = 100 * math.log10(sum_tr / (hh - ll)) / log_period
    return out


def neuro_rolling_poc_side(candles, window=50, buckets=15):
    """Lightweight per-bar approximation of price's position relative to
    the rolling Point of Control (POC) — the price level with the most
    traded volume over the recent window, this app's own namesake
    concept. Deliberately a cheap approximation (not the full compute_
    profile() used elsewhere in the app for a single live snapshot) so
    it's fast enough to run at every bar across a full history — verified
    at 0.43s for 9500 bars, negligible next to the rest of a symbol's own
    backtest cost. Genuinely distinct from vwap_side: POC is the volume-
    weighted MODE (where the most single-price agreement happened), VWAP
    is the volume-weighted MEAN — the two can and do sit at different
    prices, especially in a skewed/multi-peaked volume distribution."""
    out = [None] * len(candles)
    for i in range(window, len(candles)):
        seg = candles[i - window:i]
        hh = max(c["high"] for c in seg)
        ll = min(c["low"] for c in seg)
        if hh <= ll:
            continue
        inc = (hh - ll) / buckets
        vols = [0.0] * buckets
        for c in seg:
            lo_b = max(0, int((c["low"] - ll) / inc))
            hi_b = min(buckets - 1, int((c["high"] - ll) / inc))
            span = max(1, hi_b - lo_b + 1)
            for b in range(lo_b, hi_b + 1):
                vols[b] += c["volume"] / span
        poc_bucket = vols.index(max(vols))
        poc_price = ll + inc * (poc_bucket + 0.5)
        if poc_price <= 0:
            continue
        dist_pct = (candles[i]["close"] - poc_price) / poc_price * 100
        out[i] = "above" if dist_pct > 0.3 else "below" if dist_pct < -0.3 else "at_poc"
    return out


def neuro_align_lsw_sweep(candles, lookback_bars=4):
    """v0.99.233 — 'symbiosis' condition, per direct user request: reuses
    LSW's OWN real liquidity-sweep detector directly on the SAME 1h
    candles Neuro already has (LSW_INTERVAL == NEURO_TF == "1h", so no
    extra fetch or TF conversion needed) rather than reimplementing
    anything. For each bar, labels whether an LSW sweep signal fired
    (in either direction) within the last `lookback_bars` bars — lets
    Neuro's own walk-forward mining discover whether "a recent Sweep
    signal + <other condition>" combos have genuine out-of-sample edge,
    treating LSW's detector as just one more feature among many rather
    than a separate, disconnected module."""
    if len(candles) < 30:
        return [None] * len(candles)
    try:
        raw_sigs = lsw_detect_signals(candles)
    except Exception as e:
        log_error(f"neuro_align_lsw_sweep: {e}")
        return [None] * len(candles)
    return _neuro_align_recent_signals(candles, raw_sigs, lookback_bars)


def neuro_align_mirror_signal(candles, lookback_bars=4):
    """v0.99.234 — same 'symbiosis' idea as neuro_align_lsw_sweep(), this
    time reusing MIRROR's own detector (also a pure function over 1h
    candles, MIRROR_INTERVAL == NEURO_TF == "1h", no extra fetch)."""
    if len(candles) < 30:
        return [None] * len(candles)
    try:
        raw_sigs = mirror_detect_signals(candles)
    except Exception as e:
        log_error(f"neuro_align_mirror_signal: {e}")
        return [None] * len(candles)
    return _neuro_align_recent_signals(candles, raw_sigs, lookback_bars)


def _neuro_bar_sec(cs):
    """v0.99.403 — candle length in seconds, from the data itself."""
    d = [b["time"] - a["time"] for a, b in zip(cs[:6], cs[1:7]) if b["time"] > a["time"]]
    return min(d) if d else 3600


def neuro_align_h4_rsi(candles, h4_candles, period=14):
    """RSI computed on the 4h timeframe, aligned to each 1h bar — a genuine
    multi-timeframe momentum reading distinct from the existing 1h rsi_zone."""
    if not h4_candles or len(h4_candles) < period + 5:
        return [None] * len(candles)
    h4_closes = [c["close"] for c in h4_candles]
    h4_rsi = neuro_rsi_series(h4_closes, period)
    # v0.99.403 — LOOKAHEAD FIX: only 4h candles already CLOSED when this
    # 1h bar closes (before: the 4h candle still forming, i.e. its future close)
    h4_close_t = [c["time"] + _neuro_bar_sec(h4_candles) for c in h4_candles]
    bs = _neuro_bar_sec(candles)
    out = []
    j = -1
    for c in candles:
        while j + 1 < len(h4_close_t) and h4_close_t[j + 1] <= c["time"] + bs:
            j += 1
        if j < 0 or h4_rsi[j] is None:
            out.append(None)
        else:
            r = h4_rsi[j]
            out.append("low" if r < 30 else "high" if r > 70 else "mid")
    return out


def neuro_align_daily_streak(candles, d1_candles):
    """Consecutive same-direction DAILY candles, aligned to each 1h bar —
    a genuinely different timescale than the existing intraday "streak"
    (consecutive same-color HOURLY bars); a market can easily be choppy
    intrabar while still closing green/red for several days running, or
    vice versa."""
    if not d1_candles or len(d1_candles) < 5:
        return [None] * len(candles)
    d1_times = [c["time"] for c in d1_candles]
    d1_streak = [None] * len(d1_candles)
    cur_dir, cur_len = None, 0
    for i, c in enumerate(d1_candles):
        d = "up" if c["close"] > c["open"] else "down" if c["close"] < c["open"] else None
        if d is None:
            d1_streak[i] = None
            continue
        if d == cur_dir:
            cur_len += 1
        else:
            cur_dir, cur_len = d, 1
        capped = min(cur_len, 5)
        d1_streak[i] = f"{cur_dir}{capped}"
    # v0.99.403 — LOOKAHEAD FIX: only daily candles already closed
    d1_sec, bs = _neuro_bar_sec(d1_candles), _neuro_bar_sec(candles)
    out = []
    j = -1
    for c in candles:
        while j + 1 < len(d1_times) and d1_times[j + 1] + d1_sec <= c["time"] + bs:
            j += 1
        out.append(d1_streak[j] if j >= 0 else None)
    return out


def neuro_align_btc_vol_regime(candles, btc_candles):
    """BTC's OWN ATR-based volatility regime, aligned to each bar — the
    broader market's current volatility backdrop, distinct from each
    symbol's own vol_regime (an altcoin can be calm while BTC itself is
    thrashing, or vice versa — a regime shift in BTC often precedes or
    accompanies moves across the whole market)."""
    if not btc_candles or len(btc_candles) < 110:
        return [None] * len(candles)
    btc_atr = neuro_atr_series(btc_candles, 14)
    btc_times = [c["time"] for c in btc_candles]
    btc_regime = [None] * len(btc_candles)
    for i in range(100, len(btc_candles)):
        if not btc_atr[i]:
            continue
        recent = [a for a in btc_atr[i - 100:i] if a]
        if not recent:
            continue
        avg_atr = sum(recent) / len(recent)
        if avg_atr > 0:
            vr = btc_atr[i] / avg_atr
            btc_regime[i] = "high_vol" if vr >= 1.4 else "low_vol" if vr <= 0.7 else "normal_vol"
    out = []
    j = -1
    for c in candles:
        while j + 1 < len(btc_times) and btc_times[j + 1] <= c["time"]:
            j += 1
        out.append(btc_regime[j] if j >= 0 else None)
    return out


def neuro_macd_series(closes, fast=12, slow=26, signal=9):
    ema_fast = neuro_ema_series(closes, fast)
    ema_slow = neuro_ema_series(closes, slow)
    macd_line = [None if (a is None or b is None) else a - b for a, b in zip(ema_fast, ema_slow)]
    valid = [m for m in macd_line if m is not None]
    if len(valid) < signal:
        return macd_line, [None] * len(closes), [None] * len(closes)
    first_valid_idx = next(i for i, m in enumerate(macd_line) if m is not None)
    sig_series = [None] * first_valid_idx
    k = 2.0 / (signal + 1)
    sig = sum(valid[:signal]) / signal
    sig_series.extend([None] * (signal - 1))
    sig_series.append(sig)
    for m in valid[signal:]:
        sig = m * k + sig * (1 - k)
        sig_series.append(sig)
    while len(sig_series) < len(closes):
        sig_series.append(sig_series[-1] if sig_series else None)
    sig_series = sig_series[:len(closes)]
    hist = [None if (m is None or s is None) else m - s for m, s in zip(macd_line, sig_series)]
    return macd_line, sig_series, hist


def neuro_bollinger_pctb(closes, period=20, mult=2.0):
    out = [None] * len(closes)
    for i in range(period - 1, len(closes)):
        window = closes[i - period + 1:i + 1]
        mean = sum(window) / period
        var = sum((x - mean) ** 2 for x in window) / period
        sd = math.sqrt(var)
        upper, lower = mean + mult * sd, mean - mult * sd
        if upper > lower:
            out[i] = (closes[i] - lower) / (upper - lower)
    return out


def neuro_align_htf_trend(candles, htf_candles, htf_ema_period=50):
    """For each 1h bar, find the most recent CLOSED higher-timeframe candle
    and label whether price is above/below that HTF's own EMA — a simple
    multi-timeframe trend filter condition."""
    if not htf_candles or len(htf_candles) < htf_ema_period + 2:
        return [None] * len(candles)
    htf_closes = [c["close"] for c in htf_candles]
    htf_ema = neuro_ema_series(htf_closes, htf_ema_period)
    htf_times = [c["time"] for c in htf_candles]
    # v0.99.403 — LOOKAHEAD FIX: the docstring always said "CLOSED", the
    # code took the still-forming HTF candle (its future close)
    htf_sec, bs = _neuro_bar_sec(htf_candles), _neuro_bar_sec(candles)
    out = []
    j = -1
    for c in candles:
        while j + 1 < len(htf_times) and htf_times[j + 1] + htf_sec <= c["time"] + bs:
            j += 1
        if j < 0 or htf_ema[j] is None:
            out.append(None)
        else:
            out.append("above" if c["close"] > htf_ema[j] else "below")
    return out


def neuro_align_funding_rate(candles, funding_records):
    """funding_records: list of {time, rate}. Label each bar by the most
    recently known funding rate: very_positive / positive / negative /
    very_negative (extreme funding often precedes mean-reversion)."""
    if not funding_records:
        return [None] * len(candles)
    fr_sorted = sorted(funding_records, key=lambda f: f["time"])
    fr_times = [f["time"] for f in fr_sorted]
    fr_rates = [f["rate"] for f in fr_sorted]
    out = []
    j = -1
    for c in candles:
        while j + 1 < len(fr_times) and fr_times[j + 1] <= c["time"]:
            j += 1
        if j < 0:
            out.append(None)
        else:
            r = fr_rates[j]
            out.append("very_positive" if r >= 0.0005 else "positive" if r > 0.0001
                       else "very_negative" if r <= -0.0005 else "negative" if r < -0.0001 else "neutral")
    return out


def neuro_align_btc_agreement(candles, btc_candles, lookback=4):
    """For each bar, was BTC's own return over the last `lookback` bars the
    SAME sign as this coin's return over the same window? (agree/diverge)"""
    if not btc_candles or len(btc_candles) < lookback + 2:
        return [None] * len(candles)
    btc_times = [c["time"] for c in btc_candles]
    btc_closes = [c["close"] for c in btc_candles]
    btc_time_list = btc_times
    out = []
    for i, c in enumerate(candles):
        if i < lookback:
            out.append(None)
            continue
        own_ret = c["close"] - candles[i - lookback]["close"]
        # find nearest BTC candle at/just-before this bar's time, and lookback bars earlier
        pos = bisect.bisect_right(btc_time_list, c["time"]) - 1
        pos_prev = pos - lookback
        if pos < 0 or pos_prev < 0:
            out.append(None)
            continue
        btc_ret = btc_closes[pos] - btc_closes[pos_prev]
        if own_ret == 0 or btc_ret == 0:
            out.append(None)
        else:
            out.append("agree" if (own_ret > 0) == (btc_ret > 0) else "diverge")
    return out


def neuro_align_oi_trend(candles, oi_records, lookback_pct=0.03):
    """oi_records: list of {time, open_interest}. Label each bar by whether
    open interest has been rising/falling/flat vs its own value 20 OI-bars
    ago (a >lookback_pct% change is rising/falling, else flat)."""
    if not oi_records or len(oi_records) < 25:
        return [None] * len(candles)
    oi_sorted = sorted(oi_records, key=lambda o: o["time"])
    oi_times = [o["time"] for o in oi_sorted]
    oi_vals = [o["open_interest"] for o in oi_sorted]
    out = []
    for c in candles:
        pos = bisect.bisect_right(oi_times, c["time"]) - 1
        pos_prev = pos - 20
        if pos < 0 or pos_prev < 0 or oi_vals[pos_prev] <= 0:
            out.append(None)
            continue
        change = (oi_vals[pos] - oi_vals[pos_prev]) / oi_vals[pos_prev]
        out.append("rising" if change >= lookback_pct else "falling" if change <= -lookback_pct else "flat")
    return out


# ============================================================================
# v0.99.330 — 11 extra Neuro conditions, per user request ("1-11 сделаем").
# Toggle: NEURO_EXTRA_CONDS_ENABLED (settings "neuro_extra_conds_enabled").
# Off -> not computed and not used in combos, i.e. exactly the old
# condition set. Every value uses only data available at bar i's close.
# ============================================================================
NEURO_EXTRA_CONDS_ENABLED = os.environ.get("VP_NEURO_EXTRA_CONDS_ENABLED", "1") == "1"
NEURO_TRADE_FILTER_ENABLED = os.environ.get("VP_NEURO_TRADE_FILTER_ENABLED", "1") == "1"
NEURO_SINGLE_BEST_ENABLED = os.environ.get("VP_NEURO_SINGLE_BEST", "0") == "1"   # v0.99.403 — trade only the best card (else: the ticked cards)
NEURO_AUTOTRADE_SELECTED_ONLY = True  # v0.99.403 — always: ticked cards (or the best one) trade; the setting is gone   # v0.99.384   # v0.99.364 — see neuro_pick_trade_filter()
NEURO_EXTRA_KEYS = ("liq_zone", "lsr_zone", "oi_price_quad", "funding_delta", "premium_zone",
                    "weekly_open_side", "monthly_open_side", "pdhl_zone", "compression",
                    "long_streak", "rs_btc_zone", "round_level")
_neuro_ctx = threading.local()   # .index_close: {bar_time: index close} for premium_zone (set per symbol)


def _neuro_combo_keys():
    return NEURO_COMBO_KEYS + NEURO_EXTRA_KEYS if NEURO_EXTRA_CONDS_ENABLED else NEURO_COMBO_KEYS


def neuro_set_index_context(symbol, start_ts, end_ts):
    """Fetch index-price candles (Gate contract prefix "index_") for the
    premium/basis condition and make them visible to neuro_compute_
    conditions() in THIS thread. Failure -> premium_zone simply absent."""
    _neuro_ctx.index_close = {}
    if not NEURO_EXTRA_CONDS_ENABLED:
        return
    try:
        idx = get_candles_range(f"index_{symbol}", NEURO_TF, start_ts, end_ts) or []
        _neuro_ctx.index_close = {c["time"]: c["close"] for c in idx if c.get("close")}
    except Exception as e:
        log_error(f"neuro index candles {symbol}: {e}")


def neuro_clear_index_context():
    _neuro_ctx.index_close = {}


def neuro_extra_conditions(candles, oi_records=None, funding_records=None, btc_candles=None, d1_candles=None):
    n = len(candles)
    out = [dict() for _ in range(n)]
    if not n:
        return out
    closes = [c["close"] for c in candles]
    # contract_stats (liquidations, long/short, OI) aligned like neuro_align_oi_trend()
    st = sorted(oi_records or [], key=lambda o: o["time"])
    st_t = [o["time"] for o in st]
    fr = sorted(funding_records or [], key=lambda f: f["time"])
    fr_t = [f["time"] for f in fr]
    btc_close = {c["time"]: c["close"] for c in (btc_candles or [])}
    idx_close = getattr(_neuro_ctx, "index_close", None) or {}
    d1 = sorted(d1_candles or [], key=lambda c: c["time"])
    d1_t = [c["time"] for c in d1]
    h1_open = {c["time"]: c["open"] for c in candles}
    up = down = 0
    for i, c in enumerate(candles):
        b = out[i]
        t = c["time"]
        # 1. liquidation spikes: last 4 stat bars vs the 20 before
        pos = bisect.bisect_right(st_t, t) - 1
        if pos >= 24:
            def _sum(f, a, z):
                return sum((st[j].get(f) or 0.0) for j in range(a, z))
            ll, sl = _sum("long_liq_usd", pos - 3, pos + 1), _sum("short_liq_usd", pos - 3, pos + 1)
            base = (_sum("long_liq_usd", pos - 23, pos - 3) + _sum("short_liq_usd", pos - 23, pos - 3)) / 5.0
            if st[pos].get("long_liq_usd") is not None:
                if base > 0 and ll > 3 * base and ll >= sl:
                    b["liq_zone"] = "long_liq_spike"
                elif base > 0 and sl > 3 * base and sl > ll:
                    b["liq_zone"] = "short_liq_spike"
                else:
                    b["liq_zone"] = "calm"
        # 2. crowd positioning: long/short account ratio vs its own last 100
        if pos >= 50 and st[pos].get("lsr_account") is not None:
            hist = [st[j]["lsr_account"] for j in range(max(0, pos - 100), pos + 1) if st[j].get("lsr_account") is not None]
            if len(hist) >= 30:
                srt = sorted(hist)
                v = st[pos]["lsr_account"]
                b["lsr_zone"] = ("crowd_long" if v >= srt[int(len(srt) * 0.8)] else
                                 "crowd_short" if v <= srt[int(len(srt) * 0.2)] else "neutral")
        # 3. OI + price quadrant (20 bars, same OI thresholds as oi_trend)
        if pos >= 20 and i >= 20 and st[pos - 20]["open_interest"] > 0:
            oi_ch = (st[pos]["open_interest"] - st[pos - 20]["open_interest"]) / st[pos - 20]["open_interest"]
            px_ch = closes[i] / closes[i - 20] - 1 if closes[i - 20] else 0
            if abs(oi_ch) < 0.03 or abs(px_ch) < 0.01:
                b["oi_price_quad"] = "flat"
            else:
                b["oi_price_quad"] = f"price_{'up' if px_ch > 0 else 'down'}_oi_{'up' if oi_ch > 0 else 'down'}"
        # 4. funding change vs previous funding print
        fp = bisect.bisect_right(fr_t, t) - 1
        if fp >= 1:
            d = fr[fp]["rate"] - fr[fp - 1]["rate"]
            b["funding_delta"] = "rising" if d > 0.00003 else "falling" if d < -0.00003 else "flat"
        # 5. premium / basis vs index price
        ic = idx_close.get(t)
        if ic:
            basis = closes[i] / ic - 1
            b["premium_zone"] = "premium" if basis > 0.001 else "discount" if basis < -0.001 else "flat"
        # 6. weekly / monthly open side — open of the daily candle that
        #    CONTAINS Monday 00:00 / the 1st 00:00 UTC (robust to however
        #    Gate aligns its daily candles)
        if d1_t:
            day = t - t % 86400
            wk = day - ((day // 86400 + 3) % 7) * 86400          # Monday 00:00 UTC
            dt = datetime.fromtimestamp(day, timezone.utc)
            mo = int(datetime(dt.year, dt.month, 1, tzinfo=timezone.utc).timestamp())
            for key, start in (("weekly_open_side", wk), ("monthly_open_side", mo)):
                # v0.99.403 — the 1h candle opening the period first: the
                # same in the backtest and live, whether or not today's
                # forming daily candle is in the data
                h = h1_open.get(start)
                if h is not None:
                    b[key] = "above" if closes[i] >= h else "below"
                    continue
                k = bisect.bisect_right(d1_t, start) - 1
                if 0 <= k < len(d1) and d1_t[k] + 86400 > start:
                    b[key] = "above" if closes[i] >= d1[k]["open"] else "below"
            # 7. previous day's high / low: the daily candle BEFORE the one
            #    containing this bar (so it's fully closed)
            k = bisect.bisect_right(d1_t, t - 86400) - 1   # v0.99.403 — same with or without today's forming candle
            if k >= 0 and d1_t[k] + 86400 <= t + 3600:
                pdh, pdl = d1[k]["high"], d1[k]["low"]
                px = closes[i]
                b["pdhl_zone"] = ("above_pdh" if px > pdh else "below_pdl" if px < pdl else
                                  "near_pdh" if (pdh - px) / px < 0.003 else
                                  "near_pdl" if (px - pdl) / px < 0.003 else "inside")
        # 8. volatility compression: NR7 / inside bar
        if i >= 6:
            rng = c["high"] - c["low"]
            if rng <= min(candles[j]["high"] - candles[j]["low"] for j in range(i - 6, i)):
                b["compression"] = "nr7"
            elif c["high"] <= candles[i - 1]["high"] and c["low"] >= candles[i - 1]["low"]:
                b["compression"] = "inside_bar"
            else:
                b["compression"] = "normal"
        # 9. long same-colour runs (the existing "streak" caps at 4)
        if c["close"] > c["open"]:
            up, down = up + 1, 0
        elif c["close"] < c["open"]:
            up, down = 0, down + 1
        else:
            up = down = 0
        b["long_streak"] = "up5plus" if up >= 5 else "down5plus" if down >= 5 else "none"
        # 10. relative strength vs BTC over 24 bars
        if i >= 24 and btc_close:
            b0, b1 = btc_close.get(candles[i - 24]["time"]), btc_close.get(t)
            if b0 and b1 and closes[i - 24]:
                rs = (closes[i] / closes[i - 24] - 1) - (b1 / b0 - 1)
                b["rs_btc_zone"] = "outperform" if rs > 0.02 else "underperform" if rs < -0.02 else "inline"
        # 11. round-number proximity (step = half a power of ten below the price)
        px = closes[i]
        if px > 0:
            step = 5 * 10 ** (math.floor(math.log10(px)) - 1)
            nearest = round(px / step) * step
            b["round_level"] = "near_round" if abs(px - nearest) / px < 0.003 else "away"
    return out



def neuro_compute_conditions(candles, htf_candles=None, funding_records=None, btc_candles=None,
                              d1_candles=None, oi_records=None, eth_candles=None):
    """One bucket-label dict per bar, across many independent condition types.
    All extra-data params are OPTIONAL — when not supplied those specific
    condition types are simply skipped (bucket key absent for that bar)."""
    neuro_check_cancel()   # v0.99.357
    closes = [c["close"] for c in candles]
    ema20 = neuro_ema_series(closes, 20)
    ema50 = neuro_ema_series(closes, 50)
    ema100 = neuro_ema_series(closes, 100)
    ema200 = neuro_ema_series(closes, 200)
    rsi14 = neuro_rsi_series(closes, 14)
    atr14 = neuro_atr_series(candles, 14)
    vols = [c["volume"] for c in candles]
    _, _, macd_hist = neuro_macd_series(closes)
    bb_pctb = neuro_bollinger_pctb(closes)
    stoch_k = neuro_stoch_k_series(candles, 14)
    williams_r = neuro_williams_r_series(candles, 14)
    adx14 = neuro_adx_series(candles, 14)
    vwap20 = neuro_vwap_series(candles, 20)
    senkou_a, senkou_b = neuro_ichimoku_cloud(candles)
    roc12 = neuro_roc_series(closes, 12)
    htf_trend = neuro_align_htf_trend(candles, htf_candles) if htf_candles else [None] * len(candles)
    daily_trend = neuro_align_htf_trend(candles, d1_candles, htf_ema_period=20) if d1_candles else [None] * len(candles)
    funding_zone = neuro_align_funding_rate(candles, funding_records) if funding_records else [None] * len(candles)
    btc_agree = neuro_align_btc_agreement(candles, btc_candles) if btc_candles else [None] * len(candles)
    eth_agree = neuro_align_agreement(candles, eth_candles) if eth_candles else [None] * len(candles)
    oi_trend = neuro_align_oi_trend(candles, oi_records) if oi_records else [None] * len(candles)
    h4_rsi_zone = neuro_align_h4_rsi(candles, htf_candles) if htf_candles else [None] * len(candles)
    lsw_sweep = neuro_align_lsw_sweep(candles)  # no extra data needed — computed straight from `candles` itself
    mirror_signal = neuro_align_mirror_signal(candles)  # same — no extra data needed
    bb_width = neuro_bb_width_series(closes)  # no extra data needed
    obv = neuro_obv_series(candles)  # no extra data needed
    supertrend = neuro_supertrend_series(candles)  # no extra data needed
    rsi_divergence = neuro_rsi_divergence_series(candles, rsi14)  # reuses the already-computed rsi14 series
    daily_streak = neuro_align_daily_streak(candles, d1_candles) if d1_candles else [None] * len(candles)
    btc_vol_regime = neuro_align_btc_vol_regime(candles, btc_candles) if btc_candles else [None] * len(candles)
    cci20 = neuro_cci_series(candles)  # no extra data needed
    chop14 = neuro_chop_series(candles)  # no extra data needed
    poc_side = neuro_rolling_poc_side(candles)  # no extra data needed

    conds = []
    streak = 0
    prev_dir = None
    for i, c in enumerate(candles):
        bucket = {}
        dt = datetime.fromtimestamp(c["time"], tz=timezone.utc)
        h = dt.hour
        bucket["hour"] = h
        bucket["dow"] = dt.weekday()
        bucket["dom_third"] = "early" if dt.day <= 10 else "late" if dt.day >= 21 else "mid"
        bucket["weekend"] = "weekend" if dt.weekday() >= 5 else "weekday"
        bucket["session"] = ("asian" if 0 <= h < 8 else "london" if 8 <= h < 13
                              else "london_ny_overlap" if 13 <= h < 16 else "ny" if 16 <= h < 21
                              else "off_hours")

        if rsi14[i] is not None:
            r = rsi14[i]
            bucket["rsi_zone"] = "low" if r < 30 else "high" if r > 70 else "mid"
        if stoch_k[i] is not None:
            s = stoch_k[i]
            bucket["stoch_zone"] = "low" if s < 20 else "high" if s > 80 else "mid"
        if ema20[i] is not None:
            bucket["ema20_side"] = "above" if c["close"] > ema20[i] else "below"
        if ema50[i] is not None:
            bucket["ema50_side"] = "above" if c["close"] > ema50[i] else "below"
        if ema100[i] is not None:
            bucket["ema100_side"] = "above" if c["close"] > ema100[i] else "below"
        if ema200[i] is not None:
            bucket["ema200_side"] = "above" if c["close"] > ema200[i] else "below"
        if ema20[i] is not None and ema50[i] is not None and ema100[i] is not None:
            if ema20[i] > ema50[i] > ema100[i]:
                bucket["ema_stack"] = "bull_stack"
            elif ema20[i] < ema50[i] < ema100[i]:
                bucket["ema_stack"] = "bear_stack"
            else:
                bucket["ema_stack"] = "mixed"
        if macd_hist[i] is not None:
            bucket["macd_hist"] = "positive" if macd_hist[i] > 0 else "negative"
            if i > 0 and macd_hist[i - 1] is not None:
                if macd_hist[i - 1] <= 0 < macd_hist[i]:
                    bucket["macd_cross"] = "bull_cross"
                elif macd_hist[i - 1] >= 0 > macd_hist[i]:
                    bucket["macd_cross"] = "bear_cross"
        if bb_pctb[i] is not None:
            p = bb_pctb[i]
            bucket["bb_pctb"] = "above_upper" if p >= 1.0 else "near_upper" if p >= 0.8 \
                else "below_lower" if p <= 0.0 else "near_lower" if p <= 0.2 else "mid"
        if htf_trend[i] is not None:
            bucket["htf_trend"] = htf_trend[i]
        if daily_trend[i] is not None:
            bucket["daily_trend"] = daily_trend[i]
        if funding_zone[i] is not None:
            bucket["funding_zone"] = funding_zone[i]
        if btc_agree[i] is not None:
            bucket["btc_agree"] = btc_agree[i]
        if eth_agree[i] is not None:
            bucket["eth_agree"] = eth_agree[i]
        if oi_trend[i] is not None:
            bucket["oi_trend"] = oi_trend[i]
        if h4_rsi_zone[i] is not None:
            bucket["h4_rsi_zone"] = h4_rsi_zone[i]
        if lsw_sweep[i] is not None:
            bucket["lsw_sweep"] = lsw_sweep[i]
        if mirror_signal[i] is not None:
            bucket["mirror_signal"] = mirror_signal[i]
        if bb_width[i] is not None and i >= 40:
            recent_bbw = [w for w in bb_width[max(0, i - 100):i] if w is not None]
            if recent_bbw:
                avg_bbw = sum(recent_bbw) / len(recent_bbw)
                if avg_bbw > 0:
                    ratio = bb_width[i] / avg_bbw
                    bucket["bb_width_zone"] = "squeeze" if ratio <= 0.6 else "expansion" if ratio >= 1.6 else "normal"
        if i >= 20:
            recent_obv = [obv[k] for k in range(max(0, i - 20), i + 1)]
            if len(recent_obv) >= 2 and recent_obv[0] != recent_obv[-1]:
                obv_change_pct = (recent_obv[-1] - recent_obv[0]) / (abs(recent_obv[0]) + 1e-9)
                bucket["obv_trend"] = "rising" if obv_change_pct > 0.05 else "falling" if obv_change_pct < -0.05 else "flat"
        if supertrend[i] is not None:
            bucket["supertrend_side"] = supertrend[i]
        if rsi_divergence[i] is not None:
            bucket["rsi_divergence"] = rsi_divergence[i]
        if daily_streak[i] is not None:
            bucket["daily_streak"] = daily_streak[i]
        if btc_vol_regime[i] is not None:
            bucket["btc_vol_regime"] = btc_vol_regime[i]
        if cci20[i] is not None:
            v = cci20[i]
            bucket["cci_zone"] = "overbought" if v >= 100 else "oversold" if v <= -100 else "neutral"
        if chop14[i] is not None:
            v = chop14[i]
            bucket["chop_zone"] = "choppy" if v >= 61.8 else "trending" if v <= 38.2 else "transition"
        if poc_side[i] is not None:
            bucket["poc_side"] = poc_side[i]
        if williams_r[i] is not None:
            w = williams_r[i]
            bucket["williams_zone"] = "oversold" if w <= -80 else "overbought" if w >= -20 else "mid"
        if adx14[i] is not None:
            a = adx14[i]
            bucket["adx_zone"] = "strong" if a >= 25 else "weak" if a <= 15 else "moderate"
        if vwap20[i] is not None:
            bucket["vwap_side"] = "above" if c["close"] > vwap20[i] else "below"
        if senkou_a[i] is not None and senkou_b[i] is not None:
            cloud_top, cloud_bot = max(senkou_a[i], senkou_b[i]), min(senkou_a[i], senkou_b[i])
            bucket["ichimoku"] = "above_cloud" if c["close"] > cloud_top else "below_cloud" if c["close"] < cloud_bot else "in_cloud"
        if roc12[i] is not None:
            r = roc12[i]
            bucket["roc_zone"] = ("strong_up" if r >= 5 else "up" if r >= 1
                                   else "strong_down" if r <= -5 else "down" if r <= -1 else "flat")
        # Wick dominance — which side's rejection wick is bigger, a simple
        # single-candle exhaustion/rejection signature.
        body_top, body_bot = max(c["open"], c["close"]), min(c["open"], c["close"])
        upper_wick, lower_wick = c["high"] - body_top, body_bot - c["low"]
        total_wick = upper_wick + lower_wick
        if total_wick > 0:
            wr = upper_wick / total_wick
            bucket["wick_dominance"] = "upper" if wr >= 0.65 else "lower" if wr <= 0.35 else "balanced"
        # Proximity to a psychological round number (nearest power-of-10-
        # scaled round level within 0.3% of price) — crypto often reacts
        # near round numbers (e.g. BTC 100000, ETH 4000).
        if c["close"] > 0:
            magnitude = 10 ** (len(str(int(c["close"]))) - 1) if c["close"] >= 1 else 10 ** (math.floor(math.log10(c["close"])))
            nearest_round = round(c["close"] / magnitude) * magnitude
            if nearest_round > 0 and abs(c["close"] - nearest_round) / c["close"] <= 0.003:
                bucket["round_number"] = "near"
            else:
                bucket["round_number"] = "far"
        if i >= 30 and atr14[i]:
            recent_atr_window = [a for a in atr14[i - 20:i] if a]
            older_atr_window = [a for a in atr14[i - 40:i - 20] if a] if i >= 40 else []
            if recent_atr_window and older_atr_window:
                recent_avg = sum(recent_atr_window) / len(recent_atr_window)
                older_avg = sum(older_atr_window) / len(older_atr_window)
                if older_avg > 0:
                    change = (recent_avg - older_avg) / older_avg
                    bucket["atr_trend"] = "rising" if change >= 0.1 else "falling" if change <= -0.1 else "flat"

        if i >= 20:
            avg_vol = sum(vols[i - 20:i]) / 20
            if avg_vol > 0:
                ratio = c["volume"] / avg_vol
                bucket["vol_zone"] = ("spike" if ratio >= 2.0 else "high" if ratio >= 1.3
                                       else "low" if ratio <= 0.5 else "normal")

        if atr14[i] and atr14[i] > 0:
            rng = c["high"] - c["low"]
            ratio = rng / atr14[i]
            bucket["range_zone"] = "big" if ratio >= 1.8 else "small" if ratio <= 0.5 else "normal"
            body = abs(c["close"] - c["open"])
            bucket["body_zone"] = "big" if body / atr14[i] >= 1.2 else "small" if body / atr14[i] <= 0.3 else "normal"
        if i >= 100 and atr14[i]:
            recent_atrs = [a for a in atr14[i - 100:i] if a]
            if recent_atrs:
                avg_atr = sum(recent_atrs) / len(recent_atrs)
                if avg_atr > 0:
                    vr = atr14[i] / avg_atr
                    bucket["vol_regime"] = "high_vol" if vr >= 1.4 else "low_vol" if vr <= 0.7 else "normal_vol"

        cur_dir = "green" if c["close"] >= c["open"] else "red"
        if prev_dir == cur_dir:
            streak = min(streak + 1, 4)
        else:
            streak = 1
        bucket["streak"] = f"{prev_dir or 'na'}{min(streak, 4)}"
        prev_dir = cur_dir

        if i >= 20:
            window = candles[i - 20:i + 1]
            hi = max(w["high"] for w in window)
            lo = min(w["low"] for w in window)
            if hi > lo:
                pos = (c["close"] - lo) / (hi - lo)
                bucket["range_pos"] = "near_high" if pos >= 0.85 else "near_low" if pos <= 0.15 else "mid"
        if i >= 100:
            window = candles[i - 100:i + 1]
            hi = max(w["high"] for w in window)
            lo = min(w["low"] for w in window)
            if hi > lo:
                pos = (c["close"] - lo) / (hi - lo)
                bucket["dd_zone"] = "near_high" if pos >= 0.85 else "near_low" if pos <= 0.15 else "mid"

        conds.append(bucket)
    if NEURO_EXTRA_CONDS_ENABLED:   # v0.99.330
        for b, e in zip(conds, neuro_extra_conditions(candles, oi_records, funding_records, btc_candles, d1_candles)):
            b.update(e)
    return conds


def neuro_forward_returns(candles, k):
    n = len(candles)
    out = [None] * n
    for i in range(n - k):
        c0 = candles[i]["close"]
        c1 = candles[i + k]["close"]
        if c0 > 0:
            out[i] = (c1 - c0) / c0
    return out


def neuro_zscore(mean_a, n_a, mean_all, std_all):
    if not std_all or n_a < 2:
        return 0.0
    se = std_all / math.sqrt(n_a)
    if se == 0:
        return 0.0
    return (mean_a - mean_all) / se


NEURO_CONDITION_KEYS = ("hour", "dow", "dom_third", "weekend", "session", "rsi_zone", "stoch_zone",
                        "ema20_side", "ema50_side", "ema100_side", "ema200_side", "ema_stack",
                        "macd_hist", "macd_cross", "bb_pctb", "vol_zone", "vol_regime", "range_zone",
                        "body_zone", "streak", "range_pos", "dd_zone", "htf_trend", "daily_trend",
                        "funding_zone", "btc_agree", "oi_trend", "eth_agree", "h4_rsi_zone",
                        "williams_zone", "adx_zone", "vwap_side", "ichimoku", "roc_zone",
                        "wick_dominance", "round_number", "atr_trend", "lsw_sweep", "mirror_signal",
                        "bb_width_zone", "obv_trend", "supertrend_side", "rsi_divergence",
                        "daily_streak", "btc_vol_regime", "cci_zone", "chop_zone", "poc_side")

# Curated subset used for PAIRWISE combinations — deliberately excludes "hour"
# and "streak" (too many distinct values, would dilute sample sizes and
# explode the hypothesis count); "session"/"weekend" are the coarser
# time-of-day/day-type substitutes that DO go into combos instead.
# "daily_streak" excluded for the same reason as "streak" (up to 10
# distinct dir+count values).
# Combos get a stricter min_sample/z_threshold below since testing hundreds
# of pairs raises real false-discovery risk — same "don't fool yourself"
# discipline as the single-condition walk-forward.
NEURO_COMBO_KEYS = ("dow", "weekend", "session", "rsi_zone", "stoch_zone", "ema20_side", "ema50_side",
                    "ema100_side", "ema200_side", "ema_stack", "macd_hist", "bb_pctb", "vol_zone",
                    "vol_regime", "range_zone", "dd_zone", "htf_trend", "daily_trend", "funding_zone",
                    "btc_agree", "oi_trend", "dom_third", "eth_agree", "h4_rsi_zone", "williams_zone",
                    "adx_zone", "vwap_side", "ichimoku", "roc_zone", "wick_dominance", "atr_trend",
                    "lsw_sweep", "mirror_signal", "bb_width_zone", "obv_trend", "supertrend_side",
                    "rsi_divergence", "btc_vol_regime", "cci_zone", "chop_zone", "poc_side")
NEURO_FORWARD_HORIZONS = [4, 12, 24]  # test several forward-looking windows independently
NEURO_COMBO_MIN_SAMPLE_MULT = 2.0   # combos need more samples to trust (more hypotheses tested)
NEURO_COMBO_Z_BONUS = 0.5           # and a higher bar on z, same reasoning
# v0.99.213 — GREEDY multi-way combo growth, per direct user request ("если
# 2 дают результат, а добавить фильтр тренда — сразу же улучшится, логично
# же?"). Rather than blindly testing all C(22,3)=1540 triples (and
# C(22,4)=7315 quadruples) from scratch — a combinatorial explosion that
# would dilute sample sizes and multiply false-discovery risk — grow UP
# from whatever pairs already proved significant: for each of the
# strongest pairs, try adding ONE more condition on top and keep it only
# if the resulting 3-way (then 4-way, etc.) bucket still clears an even
# STRICTER bar. Same idea as apriori itemset mining / forward stepwise
# feature selection — the hypothesis space grows from validated building
# blocks, not from a blind full search.
NEURO_MAX_COMBO_DEPTH = 4        # 2=pairs (existing), 3=triples, 4=quadruples
NEURO_COMBO_GROW_TOP_N = 60      # v0.99.235 — raised 30->60: on real SOL data, only ~90 of 2470 significant pairs (3.6%) ever got a chance to grow into triples with the old value; still bounded, but roughly doubles real coverage
NEURO_COMBO_GROW_MAX_PER_KEY = 8  # v0.99.235 — diversity cap: no single underlying condition key (e.g. h4_rsi_zone, which occupied 25% of the old beam alone) can claim more than this many of the growth slots, so less-dominant-but-still-significant patterns get a real chance instead of the beam being monopolized by variations of 1-2 features


def _neuro_bucket_stats(buckets, mean_all, std_all, min_sample, z_threshold):
    out = []
    for (ktype, kval), rets in buckets.items():
        n = len(rets)
        if n < min_sample:
            continue
        mean_r = sum(rets) / n
        z = neuro_zscore(mean_r, n, mean_all, std_all)
        if abs(z) >= z_threshold:
            wins = sum(1 for r in rets if (r > 0) == (mean_r > 0))
            out.append({
                "type": ktype, "value": kval, "n": n,
                "mean_fwd_return": round(mean_r, 5), "baseline_mean": round(mean_all, 5),
                "z": round(z, 2), "direction": "LONG" if mean_r > 0 else "SHORT",
                "consistency": round(wins / n, 3),
            })
    return out


def _neuro_pattern_value(pat, cond_bucket):
    """Return the observed compound value for a pattern (single OR any-depth
    combo) given one bar's condition bucket, or None if any component key is
    missing on this bar. Generalizes the old hardcoded 2-key split to any
    number of stacked conditions."""
    if not pat.get("is_combo"):
        return cond_bucket.get(pat["type"])
    keys = pat["type"].split("+")
    vals = []
    for k in keys:
        v = cond_bucket.get(k)
        if v is None:
            return None
        vals.append(str(v))
    return "|".join(vals)


def _neuro_select_diverse_beam(patterns, top_n, max_per_key=None):
    """v0.99.235 — per direct user question ('может ли быть тупик в
    нейро на бэктесте, когда новым вариациям не даётся шанс?'), confirmed
    empirically: pure top-N-by-|z| let a couple of dominant features
    (h4_rsi_zone, vol_regime) claim a disproportionate share of growth
    slots, starving out less-dominant-but-still-genuinely-significant
    patterns from EVER getting a chance to combine into deeper combos.
    Greedy selection by |z|, but capping how many slots any single
    underlying condition key can occupy — once a key hits its cap, further
    candidates involving it are skipped (not discarded from the overall
    confirmed-pattern pool, just not used as GROWTH SEEDS), making room
    for genuinely different variations."""
    max_per_key = max_per_key if max_per_key is not None else NEURO_COMBO_GROW_MAX_PER_KEY
    sorted_pats = sorted(patterns, key=lambda p: -abs(p["z"]))
    key_counts = {}
    selected = []
    for p in sorted_pats:
        if len(selected) >= top_n:
            break
        keys = p["type"].split("+")
        if any(key_counts.get(k, 0) >= max_per_key for k in keys):
            continue
        selected.append(p)
        for k in keys:
            key_counts[k] = key_counts.get(k, 0) + 1
    return selected


def _neuro_grow_combos(base_patterns, conds, fwd, valid_idx, mean_all, std_all, depth):
    """Given significant patterns from depth-1 (pairs, triples, ...), try
    extending each of the top-N with one more NEURO_COMBO_KEYS dimension.
    Deduplicates by the CANONICAL (sorted) set of (key, value) pairs, since
    the same N-way combo can be reached by growing from any of its several
    (N-1)-way parent subsets — without this, the same real condition would
    show up multiple times under different key orderings."""
    min_sample = NEURO_MIN_SAMPLE * NEURO_COMBO_MIN_SAMPLE_MULT * depth
    z_threshold = NEURO_Z_THRESHOLD + NEURO_COMBO_Z_BONUS * (depth - 1)
    top_parents = _neuro_select_diverse_beam(base_patterns, NEURO_COMBO_GROW_TOP_N)

    seen_signatures = set()
    grown = []
    for parent in top_parents:
        neuro_check_cancel()   # v0.99.357
        base_keys = parent["type"].split("+")
        base_vals = parent["value"].split("|")
        # v0.99.323 — speed: the parent-match filter doesn't depend on
        # extra_key, so compute it once per parent (was re-scanned for every
        # one of NEURO_COMBO_KEYS). Same expression, same order, same result.
        parent_idx = [i for i in valid_idx
                      if all(conds[i].get(k) == v for k, v in zip(base_keys, base_vals))]
        for extra_key in _neuro_combo_keys():
            if extra_key in base_keys:
                continue
            buckets = {}
            for i in parent_idx:
                b = conds[i]
                extra_val = b.get(extra_key)
                if extra_val is not None:
                    buckets.setdefault(extra_val, []).append(fwd[i])
            for val, rets in buckets.items():
                n = len(rets)
                if n < min_sample:
                    continue
                mean_r = sum(rets) / n
                z = neuro_zscore(mean_r, n, mean_all, std_all)
                if abs(z) < z_threshold:
                    continue
                all_keys = base_keys + [extra_key]
                all_vals = base_vals + [str(val)]
                signature = tuple(sorted(zip(all_keys, all_vals)))
                if signature in seen_signatures:
                    continue
                seen_signatures.add(signature)
                sorted_keys, sorted_vals = zip(*signature)
                wins = sum(1 for r in rets if (r > 0) == (mean_r > 0))
                grown.append({
                    "type": "+".join(sorted_keys), "value": "|".join(sorted_vals), "n": n,
                    "mean_fwd_return": round(mean_r, 5), "baseline_mean": round(mean_all, 5),
                    "z": round(z, 2), "direction": "LONG" if mean_r > 0 else "SHORT",
                    "consistency": round(wins / n, 3), "is_combo": True, "combo_depth": depth,
                })
    return grown


def neuro_mine(candles, forward_bars=None, min_sample=None, z_threshold=None,
               htf_candles=None, funding_records=None, btc_candles=None,
               d1_candles=None, oi_records=None, eth_candles=None, include_combos=True):
    """Mine both single-condition and pairwise-combination dependencies,
    across multiple forward-return horizons, from ONE set of pre-computed
    per-bar condition buckets (computed once, reused for every horizon)."""
    min_sample = min_sample or NEURO_MIN_SAMPLE
    z_threshold = z_threshold if z_threshold is not None else NEURO_Z_THRESHOLD
    horizons = [forward_bars] if forward_bars else NEURO_FORWARD_HORIZONS

    conds = neuro_compute_conditions(candles, htf_candles, funding_records, btc_candles, d1_candles, oi_records, eth_candles)
    combo_pairs = list(itertools.combinations(_neuro_combo_keys(), 2)) if include_combos else []

    discovered = []
    for horizon in horizons:
        fwd = neuro_forward_returns(candles, horizon)
        valid_idx = [i for i in range(len(candles)) if fwd[i] is not None]
        all_returns = [fwd[i] for i in valid_idx]
        if len(all_returns) < min_sample:
            continue
        mean_all = sum(all_returns) / len(all_returns)
        var_all = sum((r - mean_all) ** 2 for r in all_returns) / len(all_returns)
        std_all = math.sqrt(var_all)

        single_buckets = {}
        combo_buckets = {}
        for i in valid_idx:
            neuro_check_cancel()   # v0.99.357
            b = conds[i]
            for key in NEURO_CONDITION_KEYS:
                v = b.get(key)
                if v is not None:
                    single_buckets.setdefault((key, v), []).append(fwd[i])
            if combo_pairs:
                for k1, k2 in combo_pairs:
                    v1, v2 = b.get(k1), b.get(k2)
                    if v1 is not None and v2 is not None:
                        combo_key = f"{k1}+{k2}"
                        combo_val = f"{v1}|{v2}"
                        combo_buckets.setdefault((combo_key, combo_val), []).append(fwd[i])

        for pat in _neuro_bucket_stats(single_buckets, mean_all, std_all, min_sample, z_threshold):
            pat["horizon"] = horizon
            pat["is_combo"] = False
            discovered.append(pat)
        pairs_this_horizon = []
        if combo_buckets:
            combo_min = min_sample * NEURO_COMBO_MIN_SAMPLE_MULT
            combo_z = z_threshold + NEURO_COMBO_Z_BONUS
            for pat in _neuro_bucket_stats(combo_buckets, mean_all, std_all, combo_min, combo_z):
                pat["horizon"] = horizon
                pat["is_combo"] = True
                pat["combo_depth"] = 2
                pairs_this_horizon.append(pat)
            discovered.extend(pairs_this_horizon)

        # v0.99.213 — grow 3-way, then 4-way (etc, up to NEURO_MAX_COMBO_
        # DEPTH) combos from whatever pairs/triples already proved
        # significant at THIS horizon, instead of testing every possible
        # N-tuple from scratch.
        prev_level = pairs_this_horizon
        for depth in range(3, NEURO_MAX_COMBO_DEPTH + 1):
            if not prev_level:
                break
            grown = _neuro_grow_combos(prev_level, conds, fwd, valid_idx, mean_all, std_all, depth)
            for pat in grown:
                pat["horizon"] = horizon
            discovered.extend(grown)
            prev_level = grown

    discovered.sort(key=lambda d: -abs(d["z"]))
    return discovered


def _neuro_norm_sf(t):
    """one-sided P(Z >= t) for a standard normal"""
    return 0.5 * math.erfc(t / math.sqrt(2.0))


def neuro_walk_forward(candles, forward_bars=None, min_sample=None, z_threshold=None, train_frac=None,
                        htf_candles=None, funding_records=None, btc_candles=None,
                        d1_candles=None, oi_records=None, eth_candles=None, valid_end=None):
    """v0.99.389 — mine on candles[:split] (split = train_frac, default
    NEURO_MINE_FRAC), VALIDATE on candles[split:valid_end] (default: to the
    end). A dependency is confirmed only if, on the validation part:
      - its occurrences, thinned so no two forward windows overlap (the old
        test counted 24 overlapping 24-bar returns as 24 independent
        samples), number >= NEURO_VALID_MIN_N,
      - their mean forward return points the mined direction with a
        one-sided t-test p-value that survives Benjamini-Hochberg at
        NEURO_FDR_Q across ALL candidates tested (thousands of candidates
        -> without this almost every "confirmation" is luck),
      - and its mined z agrees in sign with its direction (a "LONG" that is
        only less bad than a falling baseline is not a long edge).
    Everything after valid_end is untouched here."""
    min_sample = min_sample or NEURO_MIN_SAMPLE
    z_threshold = z_threshold if z_threshold is not None else NEURO_Z_THRESHOLD
    train_frac = train_frac or NEURO_MINE_FRAC

    split = int(len(candles) * train_frac)
    valid_end = len(candles) if valid_end is None else valid_end
    train, test = candles[:split], candles[split:valid_end]
    if not train or not test:
        return []
    boundary_time = candles[split - 1]["time"] if split > 0 else candles[0]["time"]
    end_time = candles[valid_end - 1]["time"]

    def _cut(extra):
        if not extra:
            return None, None
        return ([c for c in extra if c["time"] <= boundary_time],
                [c for c in extra if boundary_time < c["time"] <= end_time])

    htf_train, htf_test = _cut(htf_candles)
    d1_train, d1_test = _cut(d1_candles)
    fr_train, fr_test = _cut(funding_records)
    oi_train, oi_test = _cut(oi_records)
    btc_train, btc_test = _cut(btc_candles)
    eth_train, eth_test = _cut(eth_candles)

    train_patterns = neuro_mine(train, None, min_sample, z_threshold,
                                 htf_candles=htf_train, funding_records=fr_train, btc_candles=btc_train,
                                 d1_candles=d1_train, oi_records=oi_train, eth_candles=eth_train)
    train_patterns = [p for p in train_patterns if (p["z"] > 0) == (p["direction"] == "LONG")]
    if not train_patterns:
        return []

    # v0.99.417 — conditions of the validation bars computed over the whole
    # series up to its end and then sliced: indicators (EMA200, RSI...) are
    # warmed up exactly as in the simulation and live, instead of restarting
    # from zero at the start of the validation part. Causal indicators ->
    # no look-ahead.
    def _upto_end(extra):
        return [c for c in extra if c["time"] <= end_time] if extra else None
    test_conds = neuro_compute_conditions(candles[:valid_end], _upto_end(htf_candles), _upto_end(funding_records),
                                          _upto_end(btc_candles), _upto_end(d1_candles), _upto_end(oi_records),
                                          _upto_end(eth_candles))[split:valid_end]
    by_horizon = {}
    for pat in train_patterns:
        by_horizon.setdefault(pat["horizon"], []).append(pat)

    tested = []   # (p_value, pattern, extra fields)
    for horizon, pats in by_horizon.items():
        test_fwd = neuro_forward_returns(test, horizon)
        valid_test_idx = [i for i in range(len(test)) if test_fwd[i] is not None]
        latest_test_time = test[valid_test_idx[-1]]["time"] if valid_test_idx else 0
        day_cutoff = latest_test_time - NEURO_DECAY_WINDOW_DAYS * 86400
        # the validation part's own drift: a dependency must beat simply
        # holding in its direction, not just ride whatever trend the
        # validation months happened to have
        base = (sum(test_fwd[i] for i in valid_test_idx) / len(valid_test_idx)) if valid_test_idx else 0.0
        _val_index = {}
        for pat in pats:
            neuro_check_cancel()
            _vk = (pat["type"], bool(pat.get("is_combo")))
            if _vk not in _val_index:
                _d = {}
                for i in valid_test_idx:
                    _d.setdefault(_neuro_pattern_value(pat, test_conds[i]), []).append(i)
                _val_index[_vk] = _d
            matched_idx = _val_index[_vk].get(pat["value"], ())
            thin, last = [], -10**9
            for i in matched_idx:          # ascending: non-overlapping forward windows only
                if i - last >= horizon:
                    thin.append(i)
                    last = i
            if len(thin) < NEURO_VALID_MIN_N:
                continue
            rets = [test_fwd[i] for i in thin]
            n = len(rets)
            mean = sum(rets) / n
            var = sum((r - mean) ** 2 for r in rets) / (n - 1) if n > 1 else 0.0
            sd = math.sqrt(var)
            sign = 1.0 if pat["direction"] == "LONG" else -1.0
            exc = sign * (mean - base)
            t = exc / (sd / math.sqrt(n)) if sd > 0 else (float("inf") if exc > 0 else float("-inf"))
            pval = _neuro_norm_sf(t) if math.isfinite(t) else (0.0 if t > 0 else 1.0)
            if sign * mean <= 0:
                pval = 1.0   # beats the drift but still loses money in its own direction

            split_i = max(1, int(n * 0.6))
            recent_pct = rets[split_i:]
            recent_days = [test_fwd[i] for i in thin if test[i]["time"] >= day_cutoff]

            def _decay(rr_):
                if len(rr_) < NEURO_DECAY_MIN_RECENT_N:
                    return None, False
                m = sum(rr_) / len(rr_)
                flipped = (m > 0) != (pat["mean_fwd_return"] > 0)
                weak = abs(mean) > 1e-12 and abs(m) < 0.3 * abs(mean)
                return round(m, 5), (flipped or weak)
            rp_mean, d1_ = _decay(recent_pct)
            rd_mean, d2_ = _decay(recent_days)
            tested.append((pval, pat, {
                "test_n": n, "test_n_raw": len(matched_idx), "test_base_fwd_return": round(base, 5),
                "test_mean_fwd_return": round(mean, 5), "test_t": round(t, 2) if math.isfinite(t) else None,
                "test_p": round(pval, 5), "held_up": True,
                "recent_test_n": len(recent_pct), "recent_test_mean_fwd_return": rp_mean,
                "recent_days_n": len(recent_days), "recent_days_mean_fwd_return": rd_mean,
                "decaying": bool(d1_ or d2_)}))

    # Benjamini-Hochberg over every candidate that could be tested
    m_tests = len(tested)
    tested.sort(key=lambda x: x[0])
    k_max = 0
    for k, (pv, _, _) in enumerate(tested, 1):
        if pv <= NEURO_FDR_Q * k / m_tests:
            k_max = k
    confirmed = [{**pat, **extra, "fdr_tested": m_tests} for pv, pat, extra in tested[:k_max]]
    confirmed.sort(key=lambda d: -abs(d["z"]))
    return confirmed


_neuro_sim_cache = threading.local()


_NEURO_UNSET = object()


def _neuro_pattern_groups(confirmed_patterns):
    """v0.99.323 — patterns grouped by type: [(representative, {value:
    (best_pattern, list_order)})]. Per (type, value) keeps the FIRST
    pattern with the largest |z| (the old per-bar loop's strict ">")."""
    groups = {}
    for order, p in enumerate(confirmed_patterns):
        if p.get("value") is None:
            continue  # old loop: a non-None cur_val can never equal None
        g = groups.setdefault((p["type"], bool(p.get("is_combo"))), [p, {}])
        cur = g[1].get(p["value"])
        if cur is None or abs(p["z"]) > abs(cur[0]["z"]):
            g[1][p["value"]] = (p, order)
    return list(groups.values())


def _neuro_best_match_at(groups, cond_bucket):
    """v0.99.323 — the pattern the old per-bar loop picked for one bar:
    largest |z| among matching patterns, ties to the earliest list order.
    One value evaluation per pattern TYPE + a dict lookup."""
    matched = None
    m_order = None
    for rep_pat, by_val in groups:
        cur_val = _neuro_pattern_value(rep_pat, cond_bucket)
        if cur_val is None:
            continue
        hit = by_val.get(cur_val)
        if hit is None:
            continue
        p, o = hit
        if (matched is None or abs(p["z"]) > abs(matched["z"])
                or (abs(p["z"]) == abs(matched["z"]) and o < m_order)):
            matched, m_order = p, o
    return matched


def _neuro_signal_groups(confirmed_patterns):
    """v0.99.389 — [(representative, {value: [patterns]})] per pattern type,
    ALL patterns kept (several horizons of the same condition each vote, as
    in the live scan)."""
    groups = {}
    for p in confirmed_patterns:
        if p.get("value") is None:
            continue
        g = groups.setdefault((p["type"], bool(p.get("is_combo"))), [p, {}])
        g[1].setdefault(p["value"], []).append(p)
    return list(groups.values())


def _neuro_signal_at(groups, cond):
    """v0.99.389 — THE signal rule, shared by the backtest and the live scan
    (before, the backtest traded the single strongest matching dependency
    while live required the combined score, and live summed signed z so a
    SHORT dependency voted LONG). Every matching, non-decaying dependency
    whose veto filter (if any) passes votes |z| in its own direction; a
    signal needs |score| >= NEURO_MIN_AGREE_Z. Returns (direction, score,
    matched list) or None."""
    score = 0.0
    matched = []
    for rep_pat, by_val in groups:
        v = _neuro_pattern_value(rep_pat, cond)
        if v is None:
            continue
        lst = by_val.get(v)
        if not lst:
            continue
        for p in lst:
            if p.get("decaying"):
                continue
            veto = p.get("veto_filter")
            if veto and cond.get(veto["key"]) != veto["value"]:
                continue
            score += abs(p["z"]) if p["direction"] == "LONG" else -abs(p["z"])
            matched.append(p)
    if not matched or abs(score) < NEURO_MIN_AGREE_Z:
        return None
    return ("LONG" if score > 0 else "SHORT"), score, matched


def neuro_simulate_trades(candles, confirmed_patterns, htf_candles=None, funding_records=None, btc_candles=None,
                           d1_candles=None, oi_records=None, eth_candles=None, rr=None, return_conds=False):
    """Turn confirmed dependencies into an actual trade history: whenever a
    confirmed condition (single OR pairwise combo) is true on a bar, enter at
    the NEXT bar's open in the confirmed direction, SL/TP from ATR, track the
    real outcome. This is the honest track record shown alongside the raw
    pattern list. `rr` defaults to NEURO_RR but callers pass the per-symbol
    auto-tuned value once neuro_pick_best_rr() has chosen one.
    v0.99.261 — return_conds=True also returns the condition series this
    function computes internally, per direct user report of neuro_mining_
    loop hitting its own 480s per-symbol ceiling on real hardware — the
    caller (neuro_backtest_symbol(), for the veto-filter search added in
    v0.99.255) was recomputing this SAME 47-condition series a second time
    right after calling this function, since there was no way to get it
    back otherwise. Doubling that cost on every symbol was a real,
    avoidable contributor to symbols timing out."""
    if not confirmed_patterns:
        return ([], []) if return_conds else []
    rr = rr if rr is not None else NEURO_RR

    # v0.99.323 — speed: neuro_pick_best_rr() calls this once per RR
    # candidate with the SAME candles/patterns; conditions, ATR and the
    # per-bar best-matching pattern don't depend on rr, so they're computed
    # once and reused (thread-local, keyed on the identity of every input
    # object — the cache holds references, so ids can't be recycled).
    _inputs = (candles, confirmed_patterns, htf_candles, funding_records, btc_candles,
               d1_candles, oi_records, eth_candles)
    # v0.99.389 — the per-bar signal cache is keyed by the pattern set AND
    # its veto/decay state (vetoes are attached between two simulations)
    _pkey = (len(confirmed_patterns), sum(1 for p in confirmed_patterns if p.get("veto_filter")),
             sum(1 for p in confirmed_patterns if p.get("decaying")))
    _c = getattr(_neuro_sim_cache, "entry", None)
    if _c is not None and all(a is b for a, b in zip(_c["inputs"], _inputs)):
        conds, atr14 = _c["conds"], _c["atr14"]
        if _c["pkey"] != _pkey:
            _c["pkey"] = _pkey
            _c["best"] = [_NEURO_UNSET] * max(len(candles) - 1, 0)
            _c["groups"] = _neuro_signal_groups(confirmed_patterns)
        _best = _c["best"]
    else:
        conds = neuro_compute_conditions(candles, htf_candles, funding_records, btc_candles, d1_candles, oi_records, eth_candles)
        atr14 = neuro_atr_series(candles, 14)
        _best = [_NEURO_UNSET] * max(len(candles) - 1, 0)
        _neuro_sim_cache.entry = {"inputs": _inputs, "pkey": _pkey,
                                  "conds": conds, "atr14": atr14, "best": _best,
                                  "groups": _neuro_signal_groups(confirmed_patterns)}
    _groups = _neuro_sim_cache.entry["groups"]
    neuro_check_cancel()   # v0.99.357
    trades = []
    occupied_until_i = -10**9
    # v0.99.251 — CRITICAL FIX, per direct user report ("нет ли такой
    # проблемы, когда бэктест считает все точки входа, даже если открыта
    # предыдущая сделка... открывает множество сделок перекрывающих друг
    # друга?"): confirmed yes. The old gap check only enforced min_gap —
    # the SMALLEST of NEURO_FORWARD_HORIZONS (as low as 4 bars) — between
    # ENTRY bars, using `last_entry_i = i` (the entry bar itself), while a
    # real trade can stay open up to NEURO_MAX_WAIT_BARS=48 bars before
    # timing out. Since 4 << 48, the backtest could and did open new
    # "trades" while a previous one on the SAME symbol was still fully
    # unresolved — inflating the trade count with overlapping, highly-
    # correlated observations no real account (with one real position
    # per symbol) could have actually taken simultaneously. Fixed by
    # tracking the bar index where the PREVIOUS trade actually resolved
    # (its SL/TP hit, or its timeout bar if neither hit in time) and
    # gating the next entry on THAT instead of the old entry-based gap.
    for i in range(len(candles) - 1):
        neuro_check_cancel()   # v0.99.357
        if i < occupied_until_i:
            continue  # previous trade on this symbol hasn't resolved yet
        sig = _best[i]
        if sig is _NEURO_UNSET:
            sig = _best[i] = _neuro_signal_at(_groups, conds[i])
        if not sig or not atr14[i]:
            continue
        direction, score, _m = sig
        matched = max(_m, key=lambda p: abs(p["z"]))   # strongest vote — for attribution / veto search
        entry_bar = candles[i + 1]
        entry = entry_bar["open"]
        atr = atr14[i]
        sl_dist = NEURO_SL_ATR_MULT * atr
        if _sl_too_tight(entry, sl_dist):   # v0.99.599
            continue
        sl = entry - sl_dist if direction == "LONG" else entry + sl_dist
        tp = entry + sl_dist * rr if direction == "LONG" else entry - sl_dist * rr

        result = "TIMEOUT"; exit_price = exit_time = None
        _hold = max_hold_bars(NEURO_TF, NEURO_MAX_WAIT_BARS)   # v0.99.398
        exit_j = min(i + _hold, len(candles) - 1)  # default: occupied through the timeout bar even if the loop below never finds an explicit SL/TP hit
        # v0.99.260 — measure the max adverse/favorable excursion (in R)
        # within the first NEURO_EARLY_EXIT_K bars, purely as DATA on
        # every trade — neuro_find_early_exit_rule() decides afterward,
        # from honest train/test validation, whether this actually
        # predicts eventual outcome; this loop never acts on it itself.
        mae_at_k = mfe_at_k = 0.0
        close_at_k_pnl = None
        for j in range(i + 1, min(i + 1 + _hold, len(candles))):
            b = candles[j]
            if j - i <= NEURO_EARLY_EXIT_K:
                if direction == "LONG":
                    mae_at_k = max(mae_at_k, (entry - b["low"]) / sl_dist)
                    mfe_at_k = max(mfe_at_k, (b["high"] - entry) / sl_dist)
                else:
                    mae_at_k = max(mae_at_k, (b["high"] - entry) / sl_dist)
                    mfe_at_k = max(mfe_at_k, (entry - b["low"]) / sl_dist)
                if j - i == NEURO_EARLY_EXIT_K:
                    # v0.99.260 — the price we'd REALISTICALLY capture by
                    # exiting right at this checkpoint (a market close at
                    # bar K's own close), as distinct from mae_at_k (the
                    # single worst intra-window excursion, not necessarily
                    # where an exit decision would actually be made).
                    close_at_k_pnl = ((b["close"] - entry) / sl_dist if direction == "LONG"
                                      else (entry - b["close"]) / sl_dist)
            if direction == "LONG":
                if b["low"] <= sl:
                    result, exit_price, exit_time = "LOSS", sl, b["time"]; exit_j = j; break
                if b["high"] >= tp:
                    result, exit_price, exit_time = "WIN", tp, b["time"]; exit_j = j; break
            else:
                if b["high"] >= sl:
                    result, exit_price, exit_time = "LOSS", sl, b["time"]; exit_j = j; break
                if b["low"] <= tp:
                    result, exit_price, exit_time = "WIN", tp, b["time"]; exit_j = j; break

        if result == "TIMEOUT" and i + _hold <= len(candles) - 1:   # v0.99.398 — max holding time: close at market
            b = candles[i + _hold]
            result, exit_price, exit_time, exit_j = "TIME_EXIT", b["close"], b["time"], i + _hold
        pnl_r = None
        if exit_price:
            raw = (exit_price - entry) / sl_dist if direction == "LONG" else (entry - exit_price) / sl_dist
            pnl_r = round(raw, 2)
            if result == "LOSS":
                pnl_r = -abs(pnl_r)

        trades.append({
            "time": candles[i]["time"], "entry_time": entry_bar["time"], "bar_idx": i,
            "entry": round(entry, 8), "sl": round(sl, 8), "tp": round(tp, 8), "rr": rr,
            "direction": direction, "pattern_type": matched["type"], "pattern_value": str(matched["value"]),
            "z": matched["z"], "is_combo": matched.get("is_combo", False), "result": result,
            "score": round(score, 2), "n_votes": len(_m),
            "exit_price": round(exit_price, 8) if exit_price else None,
            "exit_time": exit_time, "pnl_r": pnl_r,
            "fee_r": trade_fee_r(entry, sl),   # v0.99.389 — round-trip taker fee in R
            "pnl_r_net": round(pnl_r - trade_fee_r(entry, sl), 3) if pnl_r is not None else None,
            # v0.99.260 — see NEURO_EARLY_EXIT_K's own comment. survived_k
            # is False when the trade already resolved AT or BEFORE the
            # checkpoint bar — there's no "early exit decision" to have
            # made for those, so mae_at_k/mfe_at_k aren't meaningful.
            "mae_at_k": round(mae_at_k, 3), "mfe_at_k": round(mfe_at_k, 3),
            "close_at_k_pnl": round(close_at_k_pnl, 3) if close_at_k_pnl is not None else None,
            "survived_k": (exit_j - i) > NEURO_EARLY_EXIT_K,
        })
        occupied_until_i = exit_j
    return (trades, conds) if return_conds else trades


def neuro_fetch_funding_rate(symbol, start_ts, end_ts, limit=1000):
    """GET /futures/usdt/funding_rate — Gate.io's historical funding rate.
    v0.99.427 — per the user's real-data check (tools/edge_research.py on
    the phone): the old form (limit together with from/to, halving the range
    on a 400) returned NOTHING for all 40 coins tried — every attempt was
    refused and the function silently gave up, so Neuro's funding
    conditions never had data. The plain request (limit only, newest
    records) worked for 100 of 100 coins. Now: the newest `limit` records
    first, then older pages with from/to and no limit while Gate answers;
    a refusal is logged, never hidden. Returns records in [start_ts, end_ts]."""
    out = {}
    params = {"contract": symbol, "limit": limit}
    for page in range(8):
        try:
            r = requests.get(f"{GATE_BASE}/futures/usdt/funding_rate", params=params, timeout=HTTP_TIMEOUT)
            if r.status_code != 200:
                if page == 0:
                    log_error(f"neuro_fetch_funding_rate {symbol}: HTTP {r.status_code} {r.text[:120]}")
                break
            rows = r.json()
        except Exception as e:
            if page == 0:
                log_error(f"neuro_fetch_funding_rate {symbol}: {e}")
            break
        new = 0
        for row in rows:
            try:
                t_ = int(row.get("t", row.get("time", 0)))
                v = float(row.get("r", row.get("rate", 0)))
            except (TypeError, ValueError):
                continue
            if t_ not in out:
                out[t_] = v
                new += 1
        if not new or min(out) <= start_ts:
            break
        # older page: a from/to window WITHOUT limit (Gate refuses the two together)
        earliest = min(out)
        params = {"contract": symbol, "from": max(int(start_ts), earliest - 90 * 86400), "to": earliest - 1}
    return [{"time": t_, "rate": v} for t_, v in sorted(out.items()) if start_ts <= t_ <= end_ts]


def neuro_pick_best_rr(train_candles, confirmed_patterns, htf_candles=None, funding_records=None,
                        btc_candles=None, d1_candles=None, oi_records=None, eth_candles=None):
    """Sweep NEURO_RR_CANDIDATES over the TRAIN-period trade simulation only
    (same walk-forward discipline as the condition mining itself — never
    pick RR by peeking at test/live-period results) and return the RR with
    the best expectancy, plus the full sweep table for transparency. Falls
    back to NEURO_RR if there aren't enough train-period trades to trust a
    pick either way."""
    sweep = []
    best_rr, best_score = NEURO_RR, None
    for rr in NEURO_RR_CANDIDATES:
        trades = neuro_simulate_trades(train_candles, confirmed_patterns, htf_candles=htf_candles,
                                        funding_records=funding_records, btc_candles=btc_candles,
                                        d1_candles=d1_candles, oi_records=oi_records,
                                        eth_candles=eth_candles, rr=rr)
        closed = [t for t in trades if t["result"] in CLOSED_RESULTS]
        if len(closed) < NEURO_RR_MIN_TRADES:
            sweep.append({"rr": rr, "n": len(closed), "winrate": None, "avg_pnl_r": None})
            continue
        wins = sum(1 for t in closed if t["result"] == "WIN")
        wr = round(wins / len(closed) * 100, 1)
        total = sum(_net_r(t) for t in closed)
        avg_pnl = round(total / len(closed), 3)
        sweep.append({"rr": rr, "n": len(closed), "winrate": wr, "avg_pnl_r": avg_pnl, "total_r": round(total, 1)})
        # v0.99.398 — pick by TOTAL net R over the train period, not R per
        # trade: one position per coin, so an RR whose trades sit for days
        # takes fewer trades in the same time — per-trade R alone would
        # reward long holds; the total over the same period doesn't.
        if best_score is None or total > best_score:
            best_score, best_rr = total, rr
    return best_rr, sweep


def _neuro_sel(summary):
    """v0.99.389 — the stats coins are SELECTED by. v0.99.417 — the clean
    check part V (no choice saw it); older results: the validation part."""
    if summary.get("method") == "holdout":
        sp = summary.get("split") or {}
        return sp.get("check") or sp.get("valid") or {}
    return summary


def neuro_fail_reason(summary):
    """v0.99.416 — why a coin does NOT pass (None = passes). Validation
    decides the choice; the test is one pass/fail gate after it (user: a
    coin with test 0 wins / 14 trades was #1 on a lucky 10-trade
    validation) — the same scheme as S/R and P/R: the test never ranks,
    it only removes what didn't hold up on data the search never saw."""
    if summary.get("method") != "holdout":
        return None if ((summary.get("n") or 0) >= NEURO_TOP_N_MIN_TRADES and summary.get("avg_pnl_r") is not None) else "старый расчёт"
    v = _neuro_sel(summary)
    sp = summary.get("split") or {}
    h = sp.get("holdout") or {}
    if "check" not in sp:
        return "старый расчёт — пересчитается при следующем майнинге"   # v0.99.417
    if (sp.get("history_days") or 0) < NEURO_MIN_HISTORY_DAYS:
        return f"история {round(sp.get('history_days') or 0)} дн. — нужно ≥ {NEURO_MIN_HISTORY_DAYS}"
    if not (summary.get("patterns_confirmed") or 0) > 0:
        return "нет подтверждённых зависимостей"
    # v0.99.432 — per user (the #1 card: +0.023R/trade on the very part its
    # dependencies were found on): a dependency that doesn't make money where it
    # was found makes money elsewhere only by luck
    mn = sp.get("mine") or {}
    if mn.get("avg_pnl_r") is None or mn["avg_pnl_r"] < NEURO_MINE_MIN_R:
        return (f"на поиске, где нашли зависимости, {mn.get('avg_pnl_r') if mn.get('avg_pnl_r') is not None else '—'}R"
                f"/сделку — нужно ≥ +{NEURO_MINE_MIN_R}R")
    if (v.get("n") or 0) < NEURO_VALID_MIN_TRADES:
        return f"мало сделок на проверке ({v.get('n') or 0}, нужно ≥ {NEURO_VALID_MIN_TRADES})"
    if (v.get("n") or 0) + (summary.get("n") or 0) < NEURO_TOP_N_MIN_TRADES:
        return f"мало сделок (нужно ≥ {NEURO_TOP_N_MIN_TRADES})"
    if v.get("avg_pnl_r") is None or v["avg_pnl_r"] <= 0:
        return "проверка в минусе"
    if (h.get("n") or 0) < NEURO_TEST_MIN_TRADES:
        return f"мало сделок на тесте ({h.get('n') or 0}, нужно ≥ {NEURO_TEST_MIN_TRADES})"
    if h.get("avg_pnl_r") is None or h["avg_pnl_r"] <= 0:
        return "тест не подтвердил (в минусе после комиссий)"
    return None


def neuro_eligible(summary):
    """v0.99.389 — top-N eligibility (see neuro_fail_reason). v0.99.416 —
    plus the test gate and >= 15 validation trades."""
    return neuro_fail_reason(summary) is None


def neuro_effective_winrate(summary):
    """v0.99.298 winrate floor input — see the v0.99.316 note below:
    now min(full-history WR, recent-window WR when trustworthy)."""
    # v0.99.316 — per user report ("в бэктесте Neuro вижу винрейт ниже,
    # чем я поставил минимально"): the floor used to judge ONLY the recent
    # window when it had enough trades, while the card shows the FULL-
    # history winrate — so a coin at e.g. 31% overall with a lucky last-30
    # stretch at 38% passed a 35% floor and showed "31%" on its card.
    # Now the floor takes the LOWER of the two: a coin must clear the
    # minimum both overall (what the card shows) and recently (the
    # original v0.99.298 protection against a coin that's gone bad).
    # v0.99.389 — honest (holdout) summaries: the VALIDATION win rate (the
    # holdout on the card must not be used for any choice).
    if summary.get("method") == "holdout":
        return _neuro_sel(summary).get("winrate")
    full = summary.get("winrate")
    agg = summary.get("aggregate_recent") or {}
    recent = agg.get("wr") if agg.get("n", 0) >= NEURO_AGG_DECAY_MIN_N else None
    vals = [v for v in (full, recent) if v is not None]
    return min(vals) if vals else None


def neuro_rank_metric(summary):
    """v0.99.417 — ranking score (user: "делай как предлагаешь"): the sum of
    net R over the clean check + test parts divided by sqrt(trades) —
    average R per trade weighted by how many trades back it (a t-like
    score: 20 trades at +0.3R beat 3 lucky trades at +1R). The $15
    va-bank % per day stays on the card for information: with leverage it
    swings wildly on one or two trades, so it no longer orders the cards."""
    sp = summary.get("split") or {}
    if summary.get("method") == "holdout" and "check" in sp:
        n = r = 0.0
        for part in (sp.get("check") or {}, sp.get("holdout") or {}):
            pn = part.get("n") or 0
            n += pn
            r += part.get("sum_r") if part.get("sum_r") is not None else (part.get("avg_pnl_r") or 0) * pn
        return round(r / math.sqrt(n), 3) if n else None
    if summary.get("method") == "holdout":
        return _neuro_sel(summary).get("avg_pnl_r")
    return summary.get("avg_pnl_r")


def neuro_check_aggregate_decay(trades, chosen_rr):
    """Aggregate, pattern-agnostic recency check: look at the actual
    combined outcome of the last NEURO_AGG_DECAY_WINDOW closed trades for
    this symbol, regardless of which specific pattern produced each one.
    Catches a regime shift that drags down many different patterns a
    little each — something no single pattern's own decay flag would."""
    closed = [t for t in trades if t["result"] in ("WIN", "LOSS", "LOSS_EARLY", "TIME_EXIT")]  # v0.99.260 — count early-exited losses too, same as the main summary
    recent = closed[-NEURO_AGG_DECAY_WINDOW:]
    if len(recent) < NEURO_AGG_DECAY_MIN_N:
        return {"n": len(recent), "wr": None, "avg_pnl_r": None, "underperforming": False}
    wins = sum(1 for t in recent if t["result"] == "WIN")
    wr = wins / len(recent) * 100
    avg_pnl = sum(t["pnl_r"] for t in recent if t.get("pnl_r") is not None) / len(recent)
    breakeven_wr = 1 / (1 + chosen_rr) * 100
    underperforming = wr < (breakeven_wr - NEURO_AGG_DECAY_MARGIN_PP)
    return {"n": len(recent), "wr": round(wr, 1), "avg_pnl_r": round(avg_pnl, 3),
            "breakeven_wr": round(breakeven_wr, 1), "underperforming": underperforming}


def neuro_find_culprit_patterns(trades, window=None):
    """Per direct user follow-up ("убирать конкретные зависимости, виновные
    в плохой серии, из списка подтверждённых целиком, а не просто глушить
    сигналы"): when the aggregate window is underperforming, identify
    WHICH specific (pattern_type, pattern_value) combos had a net-losing
    outcome within that same recent window, so only THOSE get purged from
    the confirmed list — a surgical fix instead of muting the whole
    symbol regardless of which pattern would actually fire next. Needs at
    least 3 of its own trades within the window before judging a pattern
    (a single bad trade shouldn't condemn it)."""
    window = window or NEURO_AGG_DECAY_WINDOW
    closed = [t for t in trades if t["result"] in ("WIN", "LOSS", "LOSS_EARLY", "TIME_EXIT")]  # v0.99.260 — count early-exited losses too, same as the main summary
    recent = closed[-window:]
    by_pattern = {}
    for t in recent:
        key = (t["pattern_type"], t["pattern_value"])
        by_pattern.setdefault(key, []).append(t["pnl_r"])
    culprits = set()
    for key, pnls in by_pattern.items():
        if len(pnls) >= 3 and sum(pnls) < 0:
            culprits.add(key)
    return culprits


def neuro_build_universe():
    """v0.99.236 — dynamic, volume-ranked candidate pool (same shape as
    lsw_build_universe()), merged with the small always-included
    NEURO_COINS seed set (so BTC/ETH — needed for correlation regardless
    of their own ranking — and other established majors are never
    dropped just because a smaller-cap coin briefly out-volumes them)."""
    try:
        tickers = get_tickers()
        seen_vol = {}
        for t in tickers:
            name = t.get("contract", "")
            if not name.endswith("_USDT"):
                continue
            vol = t.get("volume_24h_quote") or t.get("volume_24h_settle") or t.get("volume_24h") or 0
            try:
                vol = float(vol)
            except (TypeError, ValueError):
                vol = 0.0
            if vol < MIN_VOL_USD:
                continue
            if name not in seen_vol or vol > seen_vol[name]:
                seen_vol[name] = vol
        ranked = sorted(seen_vol.items(), key=lambda x: -x[1])
        dynamic = [s[0] for s in ranked[:NEURO_UNIVERSE_SIZE]]
    except Exception as e:
        log_error(f"neuro_build_universe: {e}")
        dynamic = []
    # Merge: seed coins first (guaranteed inclusion), then whatever the
    # dynamic scan adds that isn't already in the seed set.
    seen = set(NEURO_COINS)
    universe = list(NEURO_COINS)
    for s in dynamic:
        if s not in seen:
            universe.append(s)
            seen.add(s)
    return universe


def neuro_backtest_core(candles, htf_candles, d1_candles, funding_records, oi_records,
                        btc_candles, eth_candles, index_close):
    """v0.99.371 — the pure-CPU part of neuro_backtest_symbol(), no network:
    mining + walk-forward, RR choice, trade simulation, veto filters,
    early-exit rule, culprit removal, summary (without the $15 fields).
    index_close ({time: close}, keys as strings for JSON) is the
    premium_zone context the caller fetched.

    v0.99.417 — four parts (user asked to walk through the logic and fix it):
      A mining (50%)  — dependencies are searched here;
      B fitting (20%) — dependencies confirmed (FDR), RR, veto filters,
                        early-exit rule and culprit removal are all chosen
                        on A+B. Before, the part coins were then SELECTED
                        and RANKED by was this same B, which every one of
                        those choices had been tuned to -> its numbers were
                        good by construction (e.g. +1.29R on B, -0.25R on
                        the test);
      V check (15%)   — no choice ever saw it: coins are chosen and ranked
                        on it;
      C test (15%)    — a single pass/fail gate at the very end.
    Culprit removal used to look at the latest trades = the test part and
    changed the live pattern set after the stats were computed; now it
    uses trades up to the end of B, and the trades are re-simulated with
    the final rule set, so the card describes exactly what trades live."""
    _neuro_ctx.index_close = {int(k): v for k, v in (index_close or {}).items()}
    try:
        neuro_check_cancel()   # v0.99.357 — abandoned while fetching? stop before the heavy part
        n_c = len(candles)
        a_end = max(1, int(n_c * NEURO_MINE_FRAC))
        b_end = max(a_end + 1, min(n_c, int(n_c * (NEURO_MINE_FRAC + NEURO_VALID_FRAC))))
        v_end = max(b_end + 1, min(n_c, int(n_c * (NEURO_MINE_FRAC + NEURO_VALID_FRAC + NEURO_CHECK_FRAC))))
        mine_end_time = candles[a_end - 1]["time"]
        valid_end_time = candles[b_end - 1]["time"]   # end of B (fitting)
        check_end_time = candles[min(v_end, n_c) - 1]["time"]   # end of V (clean check)
        confirmed = neuro_walk_forward(candles, htf_candles=htf_candles, funding_records=funding_records,
                                        btc_candles=btc_candles, d1_candles=d1_candles, oi_records=oi_records,
                                        eth_candles=eth_candles, train_frac=NEURO_MINE_FRAC, valid_end=b_end)

        def _upto(extra):
            return [c for c in extra if c["time"] <= valid_end_time] if extra else extra
        chosen_rr, rr_sweep = neuro_pick_best_rr(
            candles[:b_end], confirmed, htf_candles=_upto(htf_candles),
            funding_records=_upto(funding_records), btc_candles=_upto(btc_candles),
            d1_candles=_upto(d1_candles), oi_records=_upto(oi_records),
            eth_candles=_upto(eth_candles))

        def _sim():
            return neuro_simulate_trades(candles, confirmed, htf_candles=htf_candles, funding_records=funding_records,
                                         btc_candles=btc_candles, d1_candles=d1_candles, oi_records=oi_records,
                                         eth_candles=eth_candles, rr=chosen_rr, return_conds=True)
        trades, full_conds = _sim()

        neuro_check_cancel()
        fit = [t for t in trades if t["time"] <= valid_end_time]   # A+B only
        veto_filters = neuro_find_veto_filters(confirmed, fit, full_conds, mine_end_time)
        if veto_filters:
            for pat in confirmed:
                vf = veto_filters.get((pat["type"], str(pat["value"])))
                if vf:
                    pat["veto_filter"] = vf
            trades, full_conds = _sim()   # vetoes are part of the signal rule (as live)

        # culprit removal — on A+B trades only (v0.99.417), then re-simulate
        culprits_removed = 0
        fit = [t for t in trades if t["time"] <= valid_end_time]
        if neuro_check_aggregate_decay(fit, chosen_rr).get("underperforming"):
            culprits = neuro_find_culprit_patterns(fit)
            if culprits:
                before = len(confirmed)
                confirmed = [p for p in confirmed if (p["type"], p["value"]) not in culprits]
                culprits_removed = before - len(confirmed)
                if culprits_removed:
                    trades, full_conds = _sim()

        early_exit_rule = neuro_find_early_exit_rule([t for t in trades if t["time"] <= valid_end_time], mine_end_time)
        if early_exit_rule:
            for t in trades:
                if not t["survived_k"] or t["result"] not in ("WIN", "LOSS"):
                    continue
                if t["mae_at_k"] >= early_exit_rule["mae_threshold"] and t["mfe_at_k"] <= early_exit_rule["mfe_threshold"]:
                    k_bar = candles[t["bar_idx"] + NEURO_EARLY_EXIT_K]
                    t["would_have_been_result"] = t["result"]
                    t["would_have_been_pnl_r"] = t["pnl_r"]
                    t["result"] = "LOSS_EARLY"
                    t["pnl_r"] = t["close_at_k_pnl"] if t["close_at_k_pnl"] is not None else t["pnl_r"]
                    t["pnl_r_net"] = round(t["pnl_r"] - (t.get("fee_r") or 0), 3) if t["pnl_r"] is not None else None
                    t["exit_price"] = round(k_bar["close"], 8)
                    t["exit_time"] = k_bar["time"]

        def _stats(ts):
            cl = [t for t in ts if t["result"] in ("WIN", "LOSS", "LOSS_EARLY", "TIME_EXIT")]
            w = sum(1 for t in cl if t["result"] == "WIN")
            return {"n": len(cl), "wins": w, "losses": len(cl) - w,
                    "timeouts": sum(1 for t in ts if t["result"] == "TIMEOUT"), "total": len(ts),
                    "winrate": round(w / len(cl) * 100, 1) if cl else None,
                    "avg_pnl_r": round(sum(_net_r(t) for t in cl) / len(cl), 3) if cl else None,
                    "sum_r": round(sum(_net_r(t) for t in cl), 3) if cl else 0.0,
                    "avg_pnl_r_gross": round(sum(t["pnl_r"] for t in cl) / len(cl), 3) if cl else None}
        st_mine = _stats([t for t in trades if t["time"] <= mine_end_time])
        st_valid = _stats([t for t in trades if mine_end_time < t["time"] <= valid_end_time])
        st_check = _stats([t for t in trades if valid_end_time < t["time"] <= check_end_time])
        st_hold = _stats([t for t in trades if t["time"] > check_end_time])
        aggregate_recent = neuro_check_aggregate_decay(trades, chosen_rr)   # display only (latest trades)

        summary = {"n": st_hold["n"], "wins": st_hold["wins"], "losses": st_hold["losses"],
                   "timeouts": st_hold["timeouts"], "winrate": st_hold["winrate"],
                   "avg_pnl_r": st_hold["avg_pnl_r"], "total": st_hold["total"],
                   "method": "holdout", "fees_included": True, "split_version": 4,
                   "split": {"mine": st_mine, "valid": st_valid, "check": st_check, "holdout": st_hold,
                             "mine_end": mine_end_time, "valid_end": valid_end_time, "check_end": check_end_time,
                             "holdout_days": round((candles[-1]["time"] - check_end_time) / 86400, 1),
                             "check_days": round((check_end_time - valid_end_time) / 86400, 1),
                             "valid_days": round((valid_end_time - mine_end_time) / 86400, 1),
                             "history_days": round((candles[-1]["time"] - candles[0]["time"]) / 86400, 1),
                             "fdr_q": NEURO_FDR_Q,
                             "fdr_tested": confirmed[0].get("fdr_tested") if confirmed else None},
                   "patterns_confirmed": len(confirmed), "history_bars": len(candles),
                   "combos_confirmed": sum(1 for p in confirmed if p.get("is_combo")),
                   "decaying_confirmed": sum(1 for p in confirmed if p.get("decaying")),
                   "chosen_rr": chosen_rr, "rr_sweep": rr_sweep,
                   "aggregate_recent": aggregate_recent, "culprits_removed": culprits_removed,
                   "early_exit_rule": early_exit_rule,
                   }   # $15 va-bank fields are added by the caller (network)
        return {"confirmed": confirmed, "trades": trades, "summary": summary}
    finally:
        _neuro_ctx.index_close = {}


def neuro_daily_pct(summary):
    """v0.99.403 — average daily growth of the $15 va-bank simulation, in %
    (geometric: (final/start)^(1/days) - 1). Per day, so a coin with 6
    months of history and one with 3 months compare fairly."""
    fb, st = summary.get("compound_final_balance"), summary.get("compound_start")
    days = summary.get("compound_days") or (summary.get("split") or {}).get("holdout_days")
    if fb is None or not st or not days or days <= 0 or not summary.get("compound_trades"):
        return None
    if fb <= 0:
        return -100.0
    return round(((fb / st) ** (1.0 / days) - 1) * 100, 3)


def _neuro_sim_start(summary):
    """(end of the part the $ simulation skips, days the simulation covers)"""
    sp = summary.get("split") or {}
    if "check" in sp:   # v0.99.417 — the clean check part V + test C (no choice saw them)
        return sp.get("valid_end"), (sp.get("check_days") or 0) + (sp.get("holdout_days") or 0)
    return sp.get("mine_end"), (sp.get("valid_days") or 0) + (sp.get("holdout_days") or 0)


def neuro_mark_train(trades, summary):
    """v0.99.536 — marks the trades of the part the model learned on, so the
    "$15→" column can say why they have no balance (cheap: run on every poll)"""
    me, _ = _neuro_sim_start(summary)
    for t in trades:
        if isinstance(t, dict):
            t["compound_train"] = bool(me is not None and t.get("time") is not None and t["time"] <= me)


def neuro_compound_fields(trades, summary, symbol):
    """v0.99.403 — per user ("лучшую карточку по доходу в процентах ... не
    сумму, а в день среднюю", period "проверка + тест"): the $15 va-bank
    simulation over the trades AFTER the mining part (validation + test —
    none of them was used to find the dependencies), and its daily %."""
    me, days = _neuro_sim_start(summary)
    neuro_mark_train(trades, summary)
    comp = rr_compound_annotate([t for t in trades if me is None or t["time"] > me], symbol, mod="neuro")
    comp["compound_days"] = round(days, 1) if me else None
    comp["compound_period"] = "проверка + тест" if me else "вся история"
    comp["daily_pct"] = neuro_daily_pct({**summary, **comp})
    return comp


def neuro_money_ok(symbol):
    """v0.99.429 — per user (the "best" card ALGO: +0.18R/trade on test but
    $15 -> $0 at the 30% risk): False when the $15 simulation over check +
    test, sized like the live orders at the CURRENT risk settings, ends below
    its start. Such a card isn't traded and can't be the best card. Recomputed
    here when the risk settings changed since (compound_sig)."""
    with _neuro_state_lock:
        sm = dict(_neuro_summary.get(symbol) or {})
        tr = list(_neuro_trades.get(symbol) or [])
    if tr and sm.get("compound_sig") != compound_sig("neuro"):
        try:
            comp = neuro_compound_fields(tr, sm, symbol)
            with _neuro_state_lock:
                if symbol in _neuro_summary:
                    _neuro_summary[symbol].update(comp)
            sm.update(comp)
        except Exception as e:
            log_error(f"neuro_money_ok {symbol}: {e}")
            return True
    fb, st = sm.get("compound_final_balance"), sm.get("compound_start")
    if fb is None or not st or not sm.get("compound_trades"):
        return True
    return fb > st


def neuro_trade_symbols():
    """v0.99.403 — the coins Neuro actually trades (and scans live): the
    best card only when "только лучшая карточка" is on, otherwise the cards
    ticked "🤖 торговать" — in both cases only coins that pass the check
    (_neuro_active_symbols = passing coins, best daily % first).
    v0.99.429 — and whose $15 simulation at the current risk makes money."""
    act = [s for s in list(_neuro_active_symbols) if neuro_money_ok(s)]
    if NEURO_SINGLE_BEST_ENABLED:
        return act[:1]
    return [s for s in act if _neuro_autotrade_selected.get(s)]


def neuro_not_traded_reason(symbol):
    """v0.99.587 — why neuro_trade_symbols() leaves a coin out at this moment
    (shown in the result message of a signal that stayed virtual)"""
    act = [s for s in list(_neuro_active_symbols) if neuro_money_ok(s)]
    if symbol not in _neuro_active_symbols:
        return "монета не прошла проверку на момент сигнала"
    if symbol not in act:
        return "симуляция $15 при текущем риске уходит в минус — такая карточка не торгуется"
    if NEURO_SINGLE_BEST_ENABLED:
        return f"включено «только лучшая карточка» — торговалась {act[0] if act else '—'}"
    if not _neuro_autotrade_selected.get(symbol):
        return "монета не отмечена «🤖 торговать»"
    return ""


def neuro_backtest_symbol(symbol, precomputed_btc_candles=None, precomputed_eth_candles=None):
    """Fetch max available history PLUS extra data sources (4h+1d trend,
    funding rate, open interest, BTC/ETH correlation), mine + walk-forward
    validate across many condition types and horizons, pick the best RR
    from train-period trades only, simulate the resulting trade history
    with that RR. Returns (confirmed_patterns, trades, summary).

    precomputed_btc_candles/precomputed_eth_candles let the caller (the
    mining loop, processing 20 symbols per cycle) fetch BTC's and ETH's
    OWN 1h history ONCE and reuse it for every other symbol's correlation
    check, instead of every one of the other 18 symbols independently
    re-fetching the exact same BTC+ETH history each — a ~22-request-per-
    cycle redundancy that was straining the app-wide shared
    GLOBAL_HTTP_SEMAPHORE (10 concurrent) enough to make most symbols
    time out against NEURO_PER_SYMBOL_MAX_SEC, per direct user report of
    8-of-10 coins "hanging". Falls back to self-fetching when not
    supplied (e.g. for a standalone/manual call)."""
    try:
        with _neuro_fetch_phase():   # v0.99.404 — counted for the UI ("скачивают данные")
            fetched = _neuro_backtest_fetch(symbol, precomputed_btc_candles, precomputed_eth_candles)
        if fetched is None:
            return [], [], {}
        candles, htf_candles, d1_candles, funding_records, oi_records, btc_candles, eth_candles = fetched
        neuro_check_cancel()   # v0.99.357 — abandoned while fetching? stop before the heavy part
        # v0.99.371 — the heavy part runs in neuro_backtest_core() (possibly in
        # a worker process on another core); the $15 compounding needs the
        # exchange, so it is added here.
        out = calc_run("neuro_backtest_core", {
            "candles": candles, "htf_candles": htf_candles, "d1_candles": d1_candles,
            "funding_records": funding_records, "oi_records": oi_records,
            "btc_candles": btc_candles, "eth_candles": eth_candles,
            "index_close": {str(k): v for k, v in (getattr(_neuro_ctx, "index_close", None) or {}).items()}})
        confirmed, trades, summary = out["confirmed"], out["trades"], out["summary"]
        # v0.99.389 — $15 va-bank over the HOLDOUT trades only
        summary.update(neuro_compound_fields(trades, summary, symbol))   # v0.99.403 — validation + test, % per day
        return confirmed, trades, summary
    except Exception as e:
        log_error(f"neuro_backtest_symbol {symbol}: {e}")
        return [], [], {}


_neuro_fetching = [0]   # v0.99.404 — coins downloading their history right now


class _neuro_fetch_phase:
    def __enter__(self):
        with _neuro_state_lock:
            _neuro_fetching[0] += 1

    def __exit__(self, *exc):
        with _neuro_state_lock:
            _neuro_fetching[0] = max(0, _neuro_fetching[0] - 1)
        return False


def _neuro_backtest_fetch(symbol, precomputed_btc_candles=None, precomputed_eth_candles=None):
    """v0.99.404 — the exchange part of neuro_backtest_symbol() (network,
    not CPU): the coin's 1h/4h/1d history, index price, funding, OI."""
    now = int(time.time())
    start_ts = now - NEURO_HISTORY_DAYS * 86400
    candles = get_candles_range(symbol, NEURO_TF, start_ts, now)
    if not candles or len(candles) < 500:
        return None

    htf_candles = get_candles_range(symbol, "4h", start_ts, now) or []
    d1_candles = get_candles_range(symbol, "1d", start_ts, now) or []
    neuro_set_index_context(symbol, start_ts, now)   # v0.99.330 — premium_zone
    # v0.99.257 — CRITICAL FIX, per direct user report (screenshot of
    # the new global errors panel showing repeated "neuro_fetch_
    # funding_rate ...: 400 Client Error" across many symbols, every
    # mining cycle). Root cause: this call reused `start_ts` — the
    # SAME start of the FULL NEURO_HISTORY_DAYS (1500-day, ~4.1-year)
    # candle-fetch window — for the funding-rate request too, and
    # Gate's own funding_rate endpoint appears to reject a range that
    # wide outright with a flat 400.
    # v0.99.258 — per direct user follow-up ("лучше же больше дней
    # для бэктеста"): rather than permanently settling for v0.99.257's
    # own guessed-conservative 60-day compromise, passes the FULL
    # start_ts back here and lets neuro_fetch_funding_rate() itself
    # adaptively halve the window on a 400 until it finds the actual
    # widest range Gate allows — see that function's own docstring.
    # neuro_align_funding_rate() already degrades gracefully for bars
    # outside whatever range ends up actually returned (plain None,
    # not a crash).
    funding_records = neuro_fetch_funding_rate(symbol, start_ts, now)
    oi_records = []
    try:
        oi_records = get_contract_stats(symbol, interval="1h", limit=999)
    except Exception as e:
        log_error(f"neuro_backtest_symbol {symbol} OI: {e}")
    if symbol == "BTC_USDT":
        btc_candles = None
    elif precomputed_btc_candles is not None:
        btc_candles = precomputed_btc_candles
    else:
        btc_candles = get_candles_range("BTC_USDT", NEURO_TF, start_ts, now) or []
    if symbol == "ETH_USDT":
        eth_candles = None
    elif precomputed_eth_candles is not None:
        eth_candles = precomputed_eth_candles
    else:
        eth_candles = get_candles_range("ETH_USDT", NEURO_TF, start_ts, now) or []
    return candles, htf_candles, d1_candles, funding_records, oi_records, btc_candles, eth_candles


def neuro_scan_live(symbol, confirmed_patterns, rr=None, precomputed_btc_candles=None, precomputed_eth_candles=None):
    """Check the most recently closed bar's conditions against this symbol's
    confirmed dependencies (single + combo); combine agreeing ones into a
    single signal. `rr` should be this symbol's own auto-tuned value from
    neuro_pick_best_rr(), falling back to NEURO_RR when not supplied.
    Patterns implicated in a recent bad aggregate stretch are already
    purged from `confirmed_patterns` by neuro_backtest_symbol (see
    neuro_find_culprit_patterns()) before this is ever called — no
    separate whole-symbol mute needed here anymore.
    v0.99.253 — precomputed_btc_candles/precomputed_eth_candles let the
    caller (neuro_live_loop(), scanning all active symbols every 15 min)
    fetch BTC's/ETH's OWN 1h history ONCE per pass and reuse it for every
    other symbol's correlation check, instead of every symbol
    independently re-fetching the exact same BTC+ETH history on every
    single pass — the same redundant-fetch bug already fixed for the
    mining loop back in v0.99.216, found still present here during a
    full audit of the module. Falls back to self-fetching when not
    supplied (e.g. a standalone/manual call)."""
    rr = rr if rr is not None else NEURO_RR
    try:
        if not confirmed_patterns:
            return None
        now = int(time.time())
        interval_sec = INTERVAL_SECONDS.get(NEURO_TF, 3600)
        start_ts = now - 250 * interval_sec
        candles = get_candles_range(symbol, NEURO_TF, start_ts, now)
        closed_candles = [c for c in candles if c["time"] + interval_sec <= now]
        if len(closed_candles) < 30:
            return None

        htf_start = now - 60 * INTERVAL_SECONDS.get("4h", 14400)
        htf_candles = get_candles_range(symbol, "4h", htf_start, now) or []
        d1_start = now - 130 * 86400
        d1_candles = get_candles_range(symbol, "1d", d1_start, now) or []
        funding_records = neuro_fetch_funding_rate(symbol, now - 30 * 86400, now)
        neuro_set_index_context(symbol, start_ts, now)   # v0.99.330 — premium_zone (live)
        oi_records = []
        try:
            oi_records = get_contract_stats(symbol, interval="1h", limit=200)
        except Exception as e:
            log_error(f"neuro_scan_live {symbol} OI: {e}")
        if symbol == "BTC_USDT":
            btc_candles = None
        elif precomputed_btc_candles is not None:
            btc_candles = precomputed_btc_candles
        else:
            btc_candles = get_candles_range("BTC_USDT", NEURO_TF, start_ts, now) or []
        if symbol == "ETH_USDT":
            eth_candles = None
        elif precomputed_eth_candles is not None:
            eth_candles = precomputed_eth_candles
        else:
            eth_candles = get_candles_range("ETH_USDT", NEURO_TF, start_ts, now) or []

        conds = neuro_compute_conditions(closed_candles, htf_candles, funding_records, btc_candles, d1_candles, oi_records, eth_candles)
        atr14 = neuro_atr_series(closed_candles, 14)
        last = conds[-1]
        atr = atr14[-1]
        if not atr:
            return None

        # v0.99.389 — the SAME rule as the backtest (_neuro_signal_at): the
        # old inline loop summed signed z, so a SHORT dependency (negative
        # z) pushed the score towards LONG. Decaying dependencies and ones
        # whose veto condition isn't met don't vote (as before).
        sig = _neuro_signal_at(_neuro_signal_groups(confirmed_patterns), last)
        if not sig:
            return None
        direction, score, matched = sig
        price = closed_candles[-1]["close"]
        sl_dist = NEURO_SL_ATR_MULT * atr
        sl = price - sl_dist if direction == "LONG" else price + sl_dist
        tp = price + sl_dist * rr if direction == "LONG" else price - sl_dist * rr
        return {
            "symbol": symbol, "time": closed_candles[-1]["time"],
            "direction": direction, "entry": round(price, 8),
            "sl": round(sl, 8), "tp": round(tp, 8), "rr": rr,
            "score": round(score, 2),
            "patterns": [{"type": p["type"], "value": str(p["value"]), "z": p["z"]} for p in matched],
            "scanned_at": now,
        }
    except Exception as e:
        log_error(f"neuro_scan_live {symbol}: {e}")
        return None


_neuro_state_lock = threading.RLock()   # v0.99.430 — re-entrant: neuro_money_ok() may run under it
_neuro_patterns = {}     # symbol -> confirmed patterns list
_neuro_trades = {}       # symbol -> trades list
_neuro_summary = {}      # symbol -> summary dict
_neuro_live_signals = {}  # symbol -> latest live signal or None
_neuro_last_mined = None
# v0.99.403 — bumped when a fix changes what mining produces (here: the
