NEURO_PAPER_START = 500.0
NEURO_PAPER_SLIP_PCT = 0.0005   # slippage on a stop / early / time exit (a market fill on a thin coin)
_neuro_paper = {"enabled": False, "start": NEURO_PAPER_START, "balance": NEURO_PAPER_START,
                "started_at": None, "trades": []}


def neuro_close_position_early(symbol, direction):
    """v0.99.260 — closes a REAL open Neuro position early, once the
    validated early-exit rule triggers on a live signal. `direction` is
    the signal's OWN original direction — the close order goes the
    OPPOSITE way, reduce_only, for whatever the position's ACTUAL
    current size is (re-fetched fresh, not assumed from the original
    entry size). Also cancels any pending SL/TP trigger orders for this
    contract first, so they don't linger as orphaned orders (or, worse,
    fire after the position is already flat) once it's gone."""
    try:
        positions = get_open_positions()
        pos = next((p for p in positions if p.get("contract") == symbol), None)
        if not pos:
            return {"ok": False, "reason": "no open position found"}
        size = float(pos.get("size", 0) or 0)
        if size == 0:
            return {"ok": False, "reason": "position size is zero"}
        contracts = abs(size)
        actual_direction = "LONG" if size > 0 else "SHORT"
        close_direction = "SHORT" if actual_direction == "LONG" else "LONG"
        try:
            for order in (get_open_price_orders() or []):
                if order.get("initial", {}).get("contract") == symbol:
                    cancel_price_order(order.get("id"))
        except Exception as e:
            log_error(f"neuro_close_position_early {symbol}: order cleanup: {e}")
        result = place_market_order(symbol, close_direction, contracts, reduce_only=True)
        return {"ok": True, "result": result}
    except Exception as e:
        log_error(f"neuro_close_position_early {symbol}: {e}")
        return {"ok": False, "reason": str(e)}


def neuro_track_signal_outcomes():
    """Same shared MFE/MAE/WIN/LOSS/TIMEOUT tracking shape as
    _lsw_track_signal_outcomes()/_mirror_track_signal_outcomes().
    v0.99.260 — per direct user request ("минусовые сделки можно закрывать
    раньше, при этом писать статистику для таких сигналов... чтобы знать
    его исход"): a signal whose symbol has a validated early_exit_rule
    (see neuro_find_early_exit_rule()) gets checked at the SAME
    NEURO_EARLY_EXIT_K-bar checkpoint used during backtesting — if it
    matches, the REAL position gets closed early (when AUTOTRADE_ENABLED_
    NEURO) and the signal is marked CLOSED/LOSS_EARLY immediately, but
    ALSO flagged shadow_pending=True so this same function keeps
    tracking it on later passes purely to fill in would_have_been_
    result/would_have_been_pnl_r once the ORIGINAL sl/tp/timeout would
    have actually resolved — the honest counterfactual, for stats only,
    never re-opening or otherwise touching the real (already-closed)
    position."""
    now = time.time()
    with _neuro_signal_log_lock:
        open_signals = [s for s in _neuro_signal_log if s["status"] == "OPEN" or s.get("shadow_pending")]
    if not open_signals:
        return
    interval_sec = INTERVAL_SECONDS.get(NEURO_TF, 3600)
    all_candles = fetch_candles_concurrent([(s["symbol"], NEURO_TF, 300) for s in open_signals])
    with _neuro_state_lock:
        summary_snapshot = dict(_neuro_summary)
    for sig, candles in zip(open_signals, all_candles):
        try:
            if candles is None:
                continue
            candles = [c for c in candles if c["time"] + interval_sec <= now]
            future = [c for c in candles if c["time"] > sig["time"]]
            direction = sig["direction"]
            entry = sig["entry"]
            risk = abs(entry - sig["sl"]) or 1e-9
            is_shadow = sig["status"] == "CLOSED" and sig.get("shadow_pending")

            if not is_shadow:
                rule = (summary_snapshot.get(sig["symbol"]) or {}).get("early_exit_rule")
                if rule and len(future) >= NEURO_EARLY_EXIT_K and not sig.get("early_exit_checked"):
                    with _neuro_signal_log_lock:
                        sig["early_exit_checked"] = True  # evaluate this exactly once per signal
                    window = future[:NEURO_EARLY_EXIT_K]
                    mae_k = mfe_k = 0.0
                    for c in window:
                        if direction == "LONG":
                            mae_k = max(mae_k, (entry - c["low"]) / risk)
                            mfe_k = max(mfe_k, (c["high"] - entry) / risk)
                        else:
                            mae_k = max(mae_k, (c["high"] - entry) / risk)
                            mfe_k = max(mfe_k, (entry - c["low"]) / risk)
                    if mae_k >= rule["mae_threshold"] and mfe_k <= rule["mfe_threshold"]:
                        k_bar = window[-1]
                        realized = ((k_bar["close"] - entry) / risk if direction == "LONG"
                                    else (entry - k_bar["close"]) / risk)
                        with _neuro_signal_log_lock:
                            sig["status"] = "CLOSED"
                            sig["result"] = "LOSS_EARLY"
                            sig["exit_price"] = k_bar["close"]
                            sig["exit_time"] = k_bar["time"]
                            sig["pnl_r"] = round(realized, 3)
                            sig["shadow_pending"] = True
                            sig["would_have_been_result"] = None
                        if AUTOTRADE_ENABLED_NEURO and sig.get("autotrade_fired", True):   # v0.99.547 — never a position another signal / module opened
                            with using_account("neuro"):   # v0.99.331
                                close_result = neuro_close_position_early(sig["symbol"], direction)
                            log_error(f"neuro early-exit {sig['symbol']}: real close attempt -> {close_result}")
                        send_telegram(
                            f"\u2702\ufe0f NEURO {sig['symbol']}: \u0437\u0430\u043a\u0440\u044b\u0442 \u0440\u0430\u043d\u044c\u0448\u0435 \u0441\u0440\u043e\u043a\u0430 "
                            f"\u043f\u043e \u043f\u0440\u0430\u0432\u0438\u043b\u0443 \u0440\u0430\u043d\u043d\u0435\u0433\u043e \u0432\u044b\u0445\u043e\u0434\u0430 "
                            f"({realized:+.2f}R) \u2014 \u0446\u0435\u043d\u0430 \u0441\u0440\u0430\u0437\u0443 \u043f\u043e\u0448\u043b\u0430 \u043a \u0441\u0442\u043e\u043f\u0443",
                            category="neuro",
                        )
                        continue

            result = exit_price = exit_time = None
            bars_seen = 0
            for c in future:
                bars_seen += 1
                if direction == "LONG":
                    if c["low"] <= sig["sl"]:
                        result, exit_price, exit_time = "LOSS", sig["sl"], c["time"]
                        break
                    if c["high"] >= sig["tp"]:
                        result, exit_price, exit_time = "WIN", sig["tp"], c["time"]
                        break
                else:
                    if c["high"] >= sig["sl"]:
                        result, exit_price, exit_time = "LOSS", sig["sl"], c["time"]
                        break
                    if c["low"] <= sig["tp"]:
                        result, exit_price, exit_time = "WIN", sig["tp"], c["time"]
                        break
                if bars_seen >= max_hold_bars(NEURO_TF, NEURO_MAX_WAIT_BARS):   # v0.99.398
                    result, exit_price, exit_time = "TIME_EXIT", c["close"], c["time"]
                    break
            if result:
                pnl_r = None
                if exit_price is not None:
                    raw = (exit_price - entry) / risk if direction == "LONG" else (entry - exit_price) / risk
                    pnl_r = round(raw if result != "LOSS" else -abs(raw), 3)
                if result == "TIME_EXIT" and not is_shadow and AUTOTRADE_ENABLED_NEURO and sig.get("autotrade_fired", True):   # v0.99.398 — really close at market
                    log_error(f"neuro time exit {sig['symbol']}: {close_position_for_mode('neuro', sig['symbol'], direction)}")
                with _neuro_signal_log_lock:
                    if is_shadow:
                        sig["would_have_been_result"] = result
                        sig["would_have_been_pnl_r"] = pnl_r
                        sig["shadow_pending"] = False
                    else:
                        sig["status"] = "CLOSED"
                        sig["result"] = result
                        sig["exit_price"] = exit_price
                        sig["exit_time"] = exit_time
                        sig["pnl_r"] = pnl_r
                if not is_shadow:
                    _pnote = neuro_paper_sweep().get((sig["symbol"], sig["time"]), "") if sig.get("paper") else ""   # v0.99.547
                    if AUTOTRADE_ENABLED_NEURO and not sig.get("autotrade_fired") and sig.get("autotrade_skip"):   # v0.99.587
                        _pnote = (_pnote + "\n" if _pnote else "") + f"ℹ️ на биржу не открывалась: {sig['autotrade_skip']}"
                    notify_trade_result("neuro", sig["symbol"], direction, entry, exit_price, result, pnl_r,
                                        real=bool(AUTOTRADE_ENABLED_NEURO and sig.get("autotrade_fired")), note=_pnote)
        except Exception as e:
            log_error(f"neuro_outcome {sig['symbol']}: {e}")


def neuro_paper_symbols():
    """v0.99.547 — the coins the paper account trades: every coin that
    passes the check (no minimum order size on paper)."""
    return list(_neuro_active_symbols) if _neuro_paper.get("enabled") else []


def neuro_paper_open(symbol, sig, record):
    """one paper position for a new live signal, risk % of the paper balance"""
    with _neuro_signal_log_lock:
        if not _neuro_paper.get("enabled"):
            return None
        bal = _neuro_paper["balance"]
        if bal <= 0:
            return None
        entry, sl = float(sig["entry"]), float(sig["sl"])
        sl_pct = abs(entry - sl) / entry if entry else 0
        if sl_pct <= 0:
            return None
        try:
            risk_pct = float(auto_risk_for("neuro", symbol) or MODULE_RISK_PCT.get("neuro") or AUTOTRADE_RISK_PCT_OF_BALANCE)
        except Exception:
            risk_pct = AUTOTRADE_RISK_PCT_OF_BALANCE
        notional = bal * risk_pct / 100.0 / (sl_pct + 2 * AUTOTRADE_SIM_FEE_PCT + NEURO_PAPER_SLIP_PCT)
        t = {"symbol": symbol, "direction": sig["direction"], "entry": entry, "sl": sl, "tp": sig["tp"],
             "sig_time": record["time"], "opened_at": time.time(), "risk_pct": round(risk_pct, 3),
             "notional": round(notional, 4), "lev": max(1, math.ceil(notional / bal)), "status": "OPEN"}
        _neuro_paper["trades"].append(t)
        del _neuro_paper["trades"][:-500]
        record["paper"] = True
        return t


def neuro_paper_sweep():
    """settles open paper positions whose signal has closed; returns
    {(symbol, sig_time): text} for the trades settled now"""
    out = {}
    with _neuro_signal_log_lock:
        by_key = {(x["symbol"], x["time"]): x for x in _neuro_signal_log}
        for t in _neuro_paper["trades"]:
            if t.get("status") != "OPEN":
                continue
            sig = by_key.get((t["symbol"], t["sig_time"]))
            if sig is None:   # the signal fell out of the log — close at the entry, fees only
                sig = {"status": "CLOSED", "result": "LOST", "exit_price": t["entry"]}
            if sig.get("status") != "CLOSED" or sig.get("exit_price") is None:
                continue
            d = 1 if t["direction"] == "LONG" else -1
            ex = float(sig["exit_price"])
            move = d * (ex - t["entry"]) / t["entry"]
            slip = 0.0 if sig.get("result") == "WIN" else NEURO_PAPER_SLIP_PCT
            fees = t["notional"] * AUTOTRADE_SIM_FEE_PCT * (2 + move)
            pnl = t["notional"] * (move - slip) - fees
            risk_usd = t["notional"] * (abs(t["entry"] - t["sl"]) / t["entry"]) or 1e-9
            _neuro_paper["balance"] = round(_neuro_paper["balance"] + pnl, 4)
            t.update({"status": "CLOSED", "result": sig.get("result"), "exit_price": ex,
                      "closed_at": sig.get("exit_time") or time.time(), "pnl": round(pnl, 4),
                      "r_net": round(pnl / risk_usd, 3), "balance_after": _neuro_paper["balance"],
                      "settled_at": time.time()})
            out[(t["symbol"], t["sig_time"])] = (f"📝 бумажный счёт Neuro: {'+' if pnl >= 0 else '−'}${abs(pnl):.2f} "
                                                f"→ ${_neuro_paper['balance']:.2f}")
    return out


def neuro_paper_status():
    neuro_paper_sweep()
    with _neuro_signal_log_lock:
        p = {k: v for k, v in _neuro_paper.items() if k != "trades"}
        trades = [dict(t) for t in _neuro_paper["trades"]]
    closed = [t for t in trades if t.get("status") == "CLOSED"]
    rs = [t["r_net"] for t in closed if t.get("r_net") is not None]
    n = len(rs)
    days = (time.time() - p["started_at"]) / 86400 if p.get("started_at") else 0
    gain = p["balance"] - p["start"]
    st = {"n": n, "open": sum(1 for t in trades if t.get("status") == "OPEN"),
          "wins": sum(1 for t in closed if (t.get("pnl") or 0) > 0), "days": round(days, 2),
          "pnl": round(gain, 2), "pnl_pct": round(gain / p["start"] * 100, 2) if p["start"] else None,
          "per_day_usd": round(gain / days, 2) if days >= 1 else None,
          "per_day_pct": round(((p["balance"] / p["start"]) ** (1 / days) - 1) * 100, 3) if days >= 1 and p["balance"] > 0 and p["start"] else None,
          "per_trade_usd": round(sum(t.get("pnl") or 0 for t in closed) / len(closed), 2) if closed else None,
          "avg_r": round(sum(rs) / n, 3) if n else None,
          "wr": round(sum(1 for r in rs if r > 0) / n * 100, 1) if n else None,
          "trades_per_day": round(len(trades) / days, 2) if days >= 1 else None}
    if n > 1:
        avg = sum(rs) / n
        se = (sum((r - avg) ** 2 for r in rs) / (n - 1)) ** 0.5 / n ** 0.5
        st["lo"], st["hi"] = round(avg - 1.96 * se, 3), round(avg + 1.96 * se, 3)
    peak, dd = p["start"], 0.0
    for t in sorted(closed, key=lambda x: x.get("settled_at") or 0):
        b = t.get("balance_after") or 0
        peak = max(peak, b)
        dd = max(dd, (peak - b) / peak * 100 if peak else 0)
    st["max_dd_pct"] = round(dd, 2)
    return {**p, "stats": st, "trades": trades[::-1][:60], "coins": neuro_paper_symbols()}


def neuro_compute_signal_stats(active_symbols=None):
    active_symbols = active_symbols if active_symbols is not None else NEURO_COINS
    with _neuro_signal_log_lock:
        signals = list(_neuro_signal_log)
    closed = [s for s in signals if s["status"] == "CLOSED" and s["result"] in ("WIN", "LOSS", "LOSS_EARLY", "TIME_EXIT")]  # v0.99.261 — count early-exited losses too
    wins = sum(1 for s in closed if s["result"] == "WIN")
    losses = len(closed) - wins
    open_n = sum(1 for s in signals if s["status"] == "OPEN")
    winrate = round(wins / len(closed) * 100, 1) if closed else None
    avg_pnl = round(sum(s["pnl_r"] for s in closed if s.get("pnl_r") is not None) / len(closed), 3) if closed else None
    by_symbol = {}
    for sym in active_symbols:
        sym_closed = [s for s in closed if s["symbol"] == sym]
        sym_wins = sum(1 for s in sym_closed if s["result"] == "WIN")
        if sym_closed or any(s["symbol"] == sym and s["status"] == "OPEN" for s in signals):
            by_symbol[sym] = {
                "n": len(sym_closed), "wins": sym_wins, "losses": len(sym_closed) - sym_wins,
                "winrate": round(sym_wins / len(sym_closed) * 100, 1) if sym_closed else None,
                "open": sum(1 for s in signals if s["symbol"] == sym and s["status"] == "OPEN"),
            }
    return {"total": len(signals), "wins": wins, "losses": losses, "open": open_n,
            "winrate": winrate, "avg_pnl_r": avg_pnl, "by_symbol": by_symbol}

# v0.99.217 — WATCHDOG, per direct user report of the mining loop stuck on
# one symbol (BNB_USDT, "5/20") for an entire night despite the v0.99.212/
# 216 per-symbol ceiling (NEURO_PER_SYMBOL_MAX_SEC). Future.result(timeout=)
# only stops the CALLING thread from waiting — it cannot force-kill the
# submitted worker thread (a hard Python/threading limitation, no clean
# primitive exists for this), so if the ceiling itself somehow didn't fire
# in time (e.g. the main mining-loop thread got stuck BEFORE even reaching
# that wait — most plausibly contending for the shared app-wide `state_lock`
# that log_error() and dozens of other loops all use), the whole loop can
# stall indefinitely with no self-recovery. This watchdog is a genuinely
# independent second line of defense: it doesn't try to kill anything (not
# possible), it just notices "no progress for way too long" and starts a
# FRESH mining thread so the app keeps moving forward — the old stuck
# thread is abandoned (a zombie, same as any single-symbol timeout already
# accepts), but that's strictly better than permanent zero progress.
NEURO_WATCHDOG_CHECK_SEC = 60
NEURO_WATCHDOG_STUCK_SEC = NEURO_STALL_SEC * 2 + 120  # v0.99.358 — the loop beats while a coin makes progress  # generous margin beyond the per-symbol ceiling itself


class _NeuroAbandoned(Exception):
    """v0.99.393 — raised inside a mining cycle the watchdog replaced."""


def neuro_mining_watchdog():
    global _neuro_mining_running, _neuro_mining_current_symbol, _neuro_mining_progress_ts
    global _neuro_loop_gen, _neuro_sem_holder_gen
    while True:
        time.sleep(NEURO_WATCHDOG_CHECK_SEC)
        try:
            with _neuro_state_lock:
                running = _neuro_mining_running
                last_progress = _neuro_mining_progress_ts
                current = _neuro_mining_current_symbol
            if running and (time.time() - last_progress) > NEURO_WATCHDOG_STUCK_SEC:
                log_error(f"neuro_mining_watchdog: mining loop stuck on {current} for over "
                          f"{NEURO_WATCHDOG_STUCK_SEC}s despite the per-symbol ceiling — starting a "
                          f"fresh mining thread (old one abandoned as a zombie, cannot be force-killed)")
                orphan_permit = False
                with _neuro_state_lock:
                    _neuro_mining_running = False
                    _neuro_mining_current_symbol = None
                    _neuro_mining_progress_ts = time.time()
                    _neuro_loop_gen += 1  # v0.99.320 — zombie exits at its next loop turn
                    if _neuro_sem_holder_gen is not None:
                        _neuro_sem_holder_gen = None
                        orphan_permit = True
                if orphan_permit:
                    BACKTEST_CONCURRENCY_SEMAPHORE.release()  # v0.99.320 — reclaim the zombie's permit (it skips its own release)
                bt_log_end("neuro", ok=False, note=f"завис на {current}, перезапущен сторожем")   # v0.99.393
                bt_set_reason("neuro", "сторож: предыдущий цикл завис")
                threading.Thread(target=neuro_mining_loop, daemon=True).start()
        except Exception as e:
            log_error(f"neuro_mining_watchdog: {e}")


def _neuro_waiting_beat():
    """v0.99.358 — called every 30s while the current coin is still making
    progress, so the watchdogs see a slow coin as alive, not hung."""
    global _neuro_mining_progress_ts
    with _neuro_state_lock:
        _neuro_mining_progress_ts = time.time()
        heartbeat("neuro_mining_loop")


def neuro_mining_loop():
    global _neuro_last_mined, _neuro_results_algo, _neuro_mining_running, _neuro_mining_done, _neuro_mining_total
    global _neuro_mining_current_symbol, _neuro_mining_progress_ts, _neuro_active_symbols, _neuro_display_symbols
    # v0.99.267 -- staggered backtest-cycle startup, see msnr_backtest_
    # loop()'s own comment for the full reasoning. This module's first
    # cycle waits 180s before starting, spreading all 7 backtest
    # loops' initial burst of network activity across ~9 minutes
    # instead of all colliding on the shared semaphore at once.
    # v0.99.272 -- same CRITICAL FIX as ft5_backtest_loop()'s own — see
    # that function's own comment for the full incident.
    global _neuro_sem_holder_gen, _neuro_waiting_slot_since, _neuro_last_error
    with _neuro_state_lock:
        my_gen = _neuro_loop_gen
    triggered = NEURO_MINING_TRIGGER.wait(timeout=180)
    NEURO_MINING_TRIGGER.clear()
    if triggered:
        bt_set_reason("neuro", BT_REASON_BUTTON)   # v0.99.393
    # v0.99.383 — per user ("Neuro сам пошёл на перебэктест после перезапуска"):
    # on a server START, if the saved results are still fresh (mined less than
    # NEURO_REFRESH_SEC ago), wait until they are due instead of re-mining
    # right away. "Очистить" / "↻ Бэктест" (trigger) still start it at once;
    # a watchdog-restarted loop (mid-cycle) is not affected.
    global _neuro_startup_checked
    if not _neuro_startup_checked:
        _neuro_startup_checked = True
        with _neuro_state_lock:
            last, have = _neuro_last_mined, bool(_neuro_summary)
        if not triggered and have and last and time.time() - last < NEURO_REFRESH_SEC:
            if bt_wait("neuro", NEURO_MINING_TRIGGER, NEURO_REFRESH_SEC - (time.time() - last), "neuro_mining_loop"):   # v0.99.393 — journaled
                NEURO_MINING_TRIGGER.clear()
    while True:
        heartbeat("neuro_mining_loop")  # v0.99.322 — see system_health_watchdog()
        with _neuro_state_lock:
            if my_gen != _neuro_loop_gen:
                return  # v0.99.320 — abandoned by the watchdog; a fresh loop replaced this one
        _neuro_sem_acquired = False
        _cycle_failed = False
        try:
            if not NEURO_ENABLED:
                # v0.99.320 — was a plain time.sleep(24h): toggling Neuro
                # off and back on left mining dead for up to a day.
                wait_beating(NEURO_MINING_TRIGGER, 60, "neuro_mining_loop")  # v0.99.325 — beats while idle
                NEURO_MINING_TRIGGER.clear()
                continue
            # v0.99.268 — same shared concurrency cap as msnr_backtest_loop's
            # own (see its comment for the full reasoning): Neuro's own
            # cycle has no single ThreadPoolExecutor wrapper like MSNR/LSW,
            # so this acquires directly and releases via this same try's own
            # `finally` below (added there instead of a nested try, to avoid
            # re-indenting the whole cycle body).
            with _neuro_state_lock:
                _neuro_waiting_slot_since = time.time()
            acquire_backtest_slot("neuro_mining_loop")  # v0.99.325 — beats while queued
            _neuro_sem_acquired = True
            _neuro_slot_held_since = time.monotonic()   # v0.99.362
            with _neuro_state_lock:
                _neuro_waiting_slot_since = None
                _neuro_sem_holder_gen = my_gen
            bt_log_start("neuro")   # v0.99.393
            # v0.99.236 — dynamic, volume-ranked universe (up to
            # NEURO_UNIVERSE_SIZE=120 candidates) instead of the old fixed
            # 20-coin list, per direct user request ("развяжем руки нейро
            # по количеству монет, пускай сканирует и проверяет всё").
            universe = neuro_build_universe()
            with _neuro_state_lock:
                _neuro_mining_running = True
                _neuro_mining_total = len(universe)
                _neuro_mining_done = 0
                _neuro_mining_progress_ts = time.time()
                heartbeat("neuro_mining_loop")  # v0.99.325 — progress beat

            # v0.99.216 — fetch BTC's and ETH's OWN 1h history ONCE per
            # cycle here, instead of every other symbol independently
            # re-fetching the exact same BTC+ETH history for their own
            # correlation check. Even more valuable now with up to 120
            # symbols instead of 20 — this alone avoids ~240 redundant
            # requests/cycle. Best-effort — if this fails, individual
            # symbols still self-fetch as a fallback (see neuro_backtest_
            # symbol's own precomputed_* params).
            now = int(time.time())
            start_ts = now - NEURO_HISTORY_DAYS * 86400
            shared_btc_candles = shared_eth_candles = None
            try:
                shared_btc_candles = get_candles_range("BTC_USDT", NEURO_TF, start_ts, now) or []
            except Exception as e:
                log_error(f"neuro_mining_loop: shared BTC prefetch failed: {e}")
            try:
                shared_eth_candles = get_candles_range("ETH_USDT", NEURO_TF, start_ts, now) or []
            except Exception as e:
                log_error(f"neuro_mining_loop: shared ETH prefetch failed: {e}")
            with _neuro_state_lock:
                _neuro_mining_progress_ts = time.time()
                heartbeat("neuro_mining_loop")  # v0.99.325 — progress beat

            # v0.99.236 — full-universe results are held in a LOCAL,
            # transient dict for the duration of this one cycle only (not
            # written into the persistent _neuro_patterns/_neuro_trades
            # globals yet) — up to 120 coins' worth of confirmed-pattern
            # lists is real memory on a phone; only the eventual top-N
            # survivors' full data gets promoted into persistent state
            # after ranking, keeping steady-state memory use the same as
            # the old fixed-20 design regardless of how wide the scan was.
            all_results = {}
            # v0.99.371 — with calculation worker processes the coins are
            # computed several at a time (one per core); results are put back
            # in universe order, so the ranking below sees exactly what the
            # sequential loop would. CALC_WORKERS = 0 keeps the old loop.
            with calc_boost("neuro", not _neuro_summary):
                _nw = calc_limit()
                if _nw <= 1:
                    for symbol in universe:
                        with _neuro_state_lock:
                            if my_gen != _neuro_loop_gen:
                                raise _NeuroAbandoned()   # v0.99.393 — replaced by the watchdog: stop, don't finish a second copy of the cycle
                            _neuro_mining_current_symbol = symbol
                            _neuro_mining_progress_ts = time.time()
                            heartbeat("neuro_mining_loop")  # v0.99.325 — progress beat
                        # v0.99.212 — same "no with-block, bounded per-item time"
                        # fix as LSW/MSNR's own v0.99.194/195: this loop is
                        # SEQUENTIAL (not a thread pool), so without an explicit
                        # per-symbol ceiling, one stuck coin (e.g. a network call
                        # deep inside get_candles_range/neuro_fetch_funding_rate
                        # hanging past its own timeout) would block every
                        # subsequent symbol in the list forever, not just itself.
                        ex = ThreadPoolExecutor(max_workers=1)
                        _ident_box = []
                        try:
                            fut = ex.submit(_neuro_run_cancellable, _ident_box, neuro_backtest_symbol, symbol, shared_btc_candles, shared_eth_candles)
                            try:
                                confirmed, trades, summary = neuro_wait_worker(fut, _ident_box, _neuro_waiting_beat)
                                if summary.get("n"):
                                    all_results[symbol] = (confirmed, trades, summary)
                            except (TimeoutError, FutureTimeoutError) as e:
                                neuro_cancel_thread(_ident_box)   # v0.99.357 — worker stops itself, no CPU-eating zombie
                                log_error(f"neuro_mining_loop: {symbol} {e} — skipping, calculation stopped")
                            except Exception as e:
                                log_error(f"neuro_mining_loop {symbol}: {e}")
                        finally:
                            ex.shutdown(wait=False)  # never block on a stuck worker thread
                        with _neuro_state_lock:
                            _neuro_mining_done += 1
                            _neuro_mining_progress_ts = time.time()
                            heartbeat("neuro_mining_loop")  # v0.99.325 — progress beat
                        # v0.99.359 — a Neuro cycle can run for hours; holding a
                        # backtest slot the whole time starved MSNR (user saw
                        # "Последний бэктест был 2.7 ч назад" while MSNR sat in the
                        # queue). Between coins, if another backtest is queued,
                        # hand the slot over and queue behind it. Each coin is
                        # computed independently, so results don't change.
                        if (_neuro_sem_acquired and backtest_others_waiting()
                                and time.monotonic() - _neuro_slot_held_since >= NEURO_YIELD_AFTER_SEC):
                            with _neuro_state_lock:
                                mine = _neuro_sem_holder_gen == my_gen
                                if mine:
                                    _neuro_sem_holder_gen = None
                            if mine:
                                _neuro_sem_acquired = False
                                BACKTEST_CONCURRENCY_SEMAPHORE.release()
                                bt_log("neuro", "pause", None, "уступил слот модулю в очереди")   # v0.99.393
                                time.sleep(3)   # let the queued loop take the permit first
                                with _neuro_state_lock:
                                    _neuro_waiting_slot_since = time.time()
                                while not BACKTEST_CONCURRENCY_SEMAPHORE.acquire(timeout=60):
                                    _neuro_waiting_beat()   # paused mid-cycle on purpose — not a hang
                                _neuro_sem_acquired = True
                                _neuro_slot_held_since = time.monotonic()
                                with _neuro_state_lock:
                                    _neuro_waiting_slot_since = None
                                    _neuro_sem_holder_gen = my_gen
                                bt_log("neuro", "resume", None, "продолжил")   # v0.99.393

                else:
                    _tmp_results = {}
                    _order = list(universe)

                    def _nm_done(sym, fut):
                        global _neuro_mining_done, _neuro_mining_progress_ts
                        try:
                            c_, t_, s_ = fut.result()
                            if s_.get("n"):
                                _tmp_results[sym] = (c_, t_, s_)
                        except Exception as e:
                            log_error(f"neuro_mining_loop {sym}: {e}")
                        with _neuro_state_lock:
                            _neuro_mining_done += 1
                            _neuro_mining_progress_ts = time.time()
                            heartbeat("neuro_mining_loop")

                    def _nm_stop(sym, reason):
                        global _neuro_mining_done
                        log_error(f"neuro_mining_loop: {sym} {reason} — skipping, calculation stopped")
                        with _neuro_state_lock:
                            _neuro_mining_done += 1

                    _bi = 0
                    while _bi < len(_order):
                        with _neuro_state_lock:
                            if my_gen != _neuro_loop_gen:
                                raise _NeuroAbandoned()   # v0.99.393 — see the sequential branch
                        # v0.99.373 — batch size re-read every batch, so a change of
                        # the cores setting applies mid-cycle
                        _nw = max(1, calc_limit())
                        # v0.99.404 — per user ("идёт майнинг, а ядер 0 из 8, 1 из 8"):
                        # a batch of exactly N coins spent most of its time
                        # downloading history (network, not cores) and then
                        # waited for its slowest coin with the cores idle. Now
                        # more coins are in flight than cores: while some
                        # download, others compute (a coin waits for a free
                        # core in calc_run, so cores never exceed the limit),
                        # and a chunk of 3N coins leaves far fewer idle tails.
                        _batch = _order[_bi:_bi + 3 * _nw]
                        _bi += len(_batch)
                        _nthreads = min(len(_batch), _nw + max(2, _nw // 2))
                        with _neuro_state_lock:
                            _neuro_mining_current_symbol = ", ".join(x.replace("_USDT", "") for x in _batch[:6]) + (f" +{len(_batch) - 6}" if len(_batch) > 6 else "")
                            _neuro_mining_progress_ts = time.time()
                            heartbeat("neuro_mining_loop")
                        run_pool_with_progress(
                            lambda s_: neuro_backtest_symbol(s_, shared_btc_candles, shared_eth_candles),
                            _batch, _nthreads, "neuro_mining_loop", _nm_done, _nm_stop,
                            stall_sec=NEURO_STALL_SEC, hard_sec=NEURO_PER_SYMBOL_HARD_MAX_SEC,
                            on_tick=_neuro_waiting_beat)
                        # v0.99.359 — a Neuro cycle can run for hours; holding a
                        # backtest slot the whole time starved MSNR (user saw
                        # "Последний бэктест был 2.7 ч назад" while MSNR sat in the
                        # queue). Between coins, if another backtest is queued,
                        # hand the slot over and queue behind it. Each coin is
                        # computed independently, so results don't change.
                        if (_neuro_sem_acquired and backtest_others_waiting()
                                and time.monotonic() - _neuro_slot_held_since >= NEURO_YIELD_AFTER_SEC):
                            with _neuro_state_lock:
                                mine = _neuro_sem_holder_gen == my_gen
                                if mine:
                                    _neuro_sem_holder_gen = None
                            if mine:
                                _neuro_sem_acquired = False
                                BACKTEST_CONCURRENCY_SEMAPHORE.release()
                                bt_log("neuro", "pause", None, "уступил слот модулю в очереди")   # v0.99.393
                                time.sleep(3)   # let the queued loop take the permit first
                                with _neuro_state_lock:
                                    _neuro_waiting_slot_since = time.time()
                                while not BACKTEST_CONCURRENCY_SEMAPHORE.acquire(timeout=60):
                                    _neuro_waiting_beat()   # paused mid-cycle on purpose — not a hang
                                _neuro_sem_acquired = True
                                _neuro_slot_held_since = time.monotonic()
                                with _neuro_state_lock:
                                    _neuro_waiting_slot_since = None
                                    _neuro_sem_holder_gen = my_gen
                                bt_log("neuro", "resume", None, "продолжил")   # v0.99.393

                    for _s in _order:
                        if _s in _tmp_results:
                            all_results[_s] = _tmp_results[_s]
            # v0.99.252 — CRITICAL FIX, per direct user report of a real
            # coin's "recent 40 signals" record looking terrible (~25.7%
            # WR against a ~25% breakeven, effectively coin-flip) despite
            # having made the top-N cut: ranking by FULL-HISTORY avg_pnl_r
            # let an early great stretch mask a currently-bad one — a coin
            # "shone in month 1, terrible since" still averages out to a
            # decent number over the whole period. The decay/culprit-
            # removal protections built earlier (v0.99.219-222) only ever
            # gated NEW live signals going forward; they never fed back
            # into this ranking step or the displayed trade history, so
            # they couldn't have prevented exactly this. Fixed by ranking
            # on aggregate_recent's own avg_pnl_r — the LAST NEURO_AGG_
            # DECAY_WINDOW (30) closed trades' average, the SAME recency
            # window already computed for decay detection — instead of
            # the full-history one, so a coin currently on a bad stretch
            # can no longer coast into the top on an inflated historical
            # average. Falls back to the full-history figure only when a
            # coin doesn't yet have enough recent trades for aggregate_
            # recent's own verdict to be trustworthy (NEURO_AGG_DECAY_
            # MIN_N=15) — a newly-added or rarely-firing symbol with too
            # few recent trades shouldn't be unrankable outright, just
            # judged on what's actually available. The overall min-
            # trades floor (NEURO_TOP_N_MIN_TRADES, on the FULL history)
            # stays as the base eligibility gate — per the user's own
            # earlier request, unchanged.
            with _neuro_state_lock:
                if my_gen != _neuro_loop_gen:
                    raise _NeuroAbandoned()   # v0.99.393 — never publish results from an abandoned cycle
            # v0.99.403 — every coin with results is kept and shown (user: "выводить
            # все карточки всегда"): coins passing the check first, each group by
            # the $15 va-bank % per day (validation + test); no count / win-rate cut
            def _rk(item):
                m_ = neuro_rank_metric(item[1][2])
                return (not neuro_eligible(item[1][2]), -(m_ if m_ is not None else -1e9))
            ranked_all = sorted(all_results.items(), key=_rk)
            eligible = [(sym, res) for sym, res in ranked_all if neuro_eligible(res[2])]
            # v0.99.262 — per direct user request ("не количество топ для
            # авто торговли, а ещё и для просто отображения... остальные
            # показывать серым"): keep max(NEURO_DISPLAY_N, NEURO_TOP_N)
            # symbols for STORAGE/DISPLAY, but only the first NEURO_TOP_N
            # of those (still the best-ranked ones) are actually traded/
            # live-scanned — the rest are shown read-only.
            display_top = ranked_all
            top = eligible[:5]   # the Telegram summary lists the best few
            new_active = [sym for sym, _ in eligible]
            new_display = [sym for sym, _ in display_top]
            with _neuro_state_lock:
                _old_rank = {s_: i for i, s_ in enumerate(_neuro_display_symbols)}
                _old_pass = set(_neuro_active_symbols)
                _ticked = [s_ for s_, on in _neuro_autotrade_selected.items() if on]

            if not all_results:
                # v0.99.236 — safety net: a totally empty all_results (e.g.
                # a full network outage this cycle) must NOT wipe out
                # whatever active set/patterns/trades already existed —
                # keep the previous state and just log it, rather than
                # silently blanking the whole tab out from under a real
                # network hiccup.
                log_error("neuro_mining_loop: universe scan produced zero usable results this cycle — keeping previous active set")
                with _neuro_state_lock:
                    _neuro_last_mined = int(time.time())
                    _neuro_mining_running = False
                    _neuro_mining_current_symbol = None
                    _neuro_mining_progress_ts = time.time()
                    heartbeat("neuro_mining_loop")  # v0.99.325 — progress beat
            else:
                with _neuro_state_lock:
                    _neuro_patterns.clear()
                    _neuro_trades.clear()
                    _neuro_summary.clear()
                    for sym, (confirmed, trades, summary) in display_top:
                        _neuro_patterns[sym] = confirmed
                        _neuro_trades[sym] = trades
                        _neuro_summary[sym] = summary
                    _neuro_active_symbols = new_active
                    _neuro_display_symbols = new_display
                    _neuro_results_algo = NEURO_ALGO_VERSION   # v0.99.403
                    # Drop live-signal state for any symbol that fell out of
                    # the DISPLAY set entirely — its badge shouldn't linger
                    # in the UI. A symbol still shown but no longer traded
                    # (dropped from active, kept in display) keeps whatever
                    # historical live-signal badge it already had — it's
                    # just not scanned for NEW ones anymore.
                    for sym in list(_neuro_live_signals.keys()):
                        if sym not in new_display:
                            del _neuro_live_signals[sym]
                    _neuro_last_mined = int(time.time())
                    _neuro_mining_running = False
                    _neuro_mining_current_symbol = None
                    _neuro_mining_progress_ts = time.time()
                    heartbeat("neuro_mining_loop")  # v0.99.325 — progress beat
                save_neuro_state()  # v0.99.240 — persist the freshly-promoted top-N so a restart doesn't lose potentially hours of full-universe compute
                # v0.99.403 — per user ("уведомлять меня когда карточка с галочкой
                # потеряла позицию"): ticked coins that moved down or stopped passing
                _new_rank = {s_: i for i, s_ in enumerate(new_display)}
                _msgs = []
                for s_ in _ticked:
                    if s_ in _old_pass and s_ not in new_active:
                        _msgs.append(f"{s_.replace('_USDT', '')}: перестала проходить проверку — не торгуется")
                    elif s_ in _old_rank and (s_ not in _new_rank or _new_rank[s_] > _old_rank[s_]):
                        _msgs.append(f"{s_.replace('_USDT', '')}: место #{_old_rank[s_] + 1} → "
                                     + (f"#{_new_rank[s_] + 1}" if s_ in _new_rank else "нет результатов"))
                if _msgs:
                    send_telegram("\U0001f9e0 Neuro — отмеченные монеты сдвинулись после пересчёта:\n" + "\n".join(_msgs), category="neuro")
                if TELEGRAM_ALERTS_NEURO_SUMMARY and top:
                    # v0.99.249 — per direct user follow-up ("зачем что-то
                    # там умножать и т.п., монета-wr-rr, всё — то что в
                    # бэктесте карточка показывает короче"): no derived
                    # math — just the SAME winrate/RR numbers already shown
                    # on each coin's own backtest card, one line per symbol
                    # in rank order.
                    lines = []
                    for sym, (_, _, summary) in top:
                        wr = summary.get("winrate")
                        wr_txt = f"{wr:.0f}%" if wr is not None else "?%"
                        rr = summary.get("chosen_rr")
                        rr_txt = f"RR{rr:.0f}" if rr is not None else "RR?"
                        lines.append(f"{sym.replace('_USDT', '')}-{wr_txt}-{rr_txt}")
                    send_telegram("\U0001f9e0 Neuro \u0431\u044d\u043a\u0442\u0435\u0441\u0442:\n" + "\n".join(lines), category="neuro_summary")
            bt_log_end("neuro", ok=bool(all_results),
                       note=f"в топе: {len(new_active)}" if all_results else "нет данных с биржи")   # v0.99.393
        except _NeuroAbandoned:
            log_error("neuro_mining_loop: abandoned by the watchdog — this old cycle stops, the fresh one continues")
            return   # the finally below skips the permit release (the watchdog reclaimed it)
        except Exception as e:
            _cycle_failed = True
            if "neuro" in _bt_started:
                bt_log_end("neuro", ok=False, note=str(e)[:80])   # v0.99.393
            log_error(f"neuro_mining_loop: {e}")
            with _neuro_state_lock:
                _neuro_mining_running = False
                _neuro_last_error = (int(time.time()), str(e)[:300])
        finally:
            release_now = False
            with _neuro_state_lock:
                _neuro_waiting_slot_since = None
                if _neuro_sem_acquired and _neuro_sem_holder_gen == my_gen:
                    _neuro_sem_holder_gen = None
                    release_now = True
            if release_now:  # v0.99.320 — skip if the watchdog already reclaimed this permit
                BACKTEST_CONCURRENCY_SEMAPHORE.release()
        # v0.99.212 — Event.wait(timeout=...) instead of a plain sleep, same
        # fix as LSW/MSNR's own "Очистить X doesn't wake the sleeping loop"
        # — the new "Очистить Neuro" button can cut this short immediately.
        # v0.99.320 — a FAILED cycle retries in 30 min instead of waiting
        # the full 24h (a daily-recurring failure used to mean days with
        # no fresh backtest and nothing visible in the tab).
        bt_wait("neuro", NEURO_MINING_TRIGGER, NEURO_RETRY_AFTER_ERROR_SEC if _cycle_failed else max(300, NEURO_REFRESH_SEC), "neuro_mining_loop", failed=_cycle_failed)  # v0.99.325 — beats while idle; v0.99.393 — journaled
        NEURO_MINING_TRIGGER.clear()


def neuro_live_loop():
    global _neuro_prev_signal_keys
    while True:
        heartbeat("neuro_live_loop")  # v0.99.322 — see system_health_watchdog()
        try:
            if not NEURO_ENABLED:
                time.sleep(900)
                continue
            with _neuro_state_lock:
                patterns_snapshot = dict(_neuro_patterns)
                summary_snapshot = dict(_neuro_summary)
            active_symbols = neuro_trade_symbols()   # v0.99.403 — ticked (or the best) passing coins only; v0.99.430 — outside the lock
            active_symbols += [s_ for s_ in neuro_paper_symbols() if s_ not in active_symbols]   # v0.99.547 — paper account
            # v0.99.253 — same shared BTC/ETH prefetch already applied to
            # the mining loop back in v0.99.216, found still missing here
            # during a full audit: with only ~5 active symbols this isn't
            # nearly as costly as the original 20-coin case, but it's the
            # exact same unnecessary redundant fetch, happening on every
            # 15-min pass instead of once/day like the mining loop.
            now_ts = int(time.time())
            neuro_live_start_ts = now_ts - 250 * INTERVAL_SECONDS.get(NEURO_TF, 3600)
            shared_btc_candles = shared_eth_candles = None
            try:
                shared_btc_candles = get_candles_range("BTC_USDT", NEURO_TF, neuro_live_start_ts, now_ts) or []
            except Exception as e:
                log_error(f"neuro_live_loop: shared BTC prefetch failed: {e}")
            try:
                shared_eth_candles = get_candles_range("ETH_USDT", NEURO_TF, neuro_live_start_ts, now_ts) or []
            except Exception as e:
                log_error(f"neuro_live_loop: shared ETH prefetch failed: {e}")
            new_signals = {}
            for symbol in active_symbols:
                confirmed = patterns_snapshot.get(symbol) or []
                sym_summary = summary_snapshot.get(symbol) or {}
                chosen_rr = sym_summary.get("chosen_rr")
                sig = neuro_scan_live(symbol, confirmed, rr=chosen_rr,
                                       precomputed_btc_candles=shared_btc_candles,
                                       precomputed_eth_candles=shared_eth_candles)
                new_signals[symbol] = sig
            with _neuro_state_lock:
                _neuro_live_signals.update(new_signals)
            new_keys = {s: sig["time"] for s, sig in new_signals.items() if sig}
            fired = {s: t for s, t in new_keys.items()
                     if (s, t) not in _neuro_prev_signal_keys}
            for symbol, sig_time in fired.items():
                sig = new_signals[symbol]
                # v0.99.251 — no-open-position guard, per direct user
                # report ("бэктест считает все точки входа, даже если
                # открыта предыдущая сделка... не ждёт закрытия"). The
                # same underlying condition can stay true across several
                # consecutive hourly bars (e.g. "weekend"), so `fired`'s
                # own (symbol, sig_time) dedup alone would let a genuinely
                # NEW signal fire — and a real trade open — every single
                # hour the condition holds, piling multiple overlapping
                # REAL positions onto the same symbol. Skip (but still
                # log) a new signal while the previous one on this symbol
                # is still OPEN in the persistent live-signal log.
                with _neuro_signal_log_lock:
                    already_open = any(s["symbol"] == symbol and s["status"] == "OPEN" for s in _neuro_signal_log)
                    _dup = signal_already_logged(_neuro_signal_log, symbol, sig_time)   # v0.99.386
                if _dup:
                    continue
                if already_open:
                    pass  # v0.99.349 — normal one-position-per-coin rule (same as the backtest); no longer reported as an error
                    continue
                arrow = "\u2b06\ufe0f" if sig["direction"] == "LONG" else "\u2b07\ufe0f"
                pat_txt = ", ".join(f"{p['type']}={p['value']}(z={p['z']})" for p in sig["patterns"][:3])
                # v0.99.384 — "только отмеченные монеты"
                _sel_ok = symbol in neuro_trade_symbols()   # v0.99.403; v0.99.430 — outside the lock
                if _sel_ok or not neuro_paper_symbols():   # v0.99.547 — a paper-only coin: quiet, only its result
                  send_telegram(
                    f"{arrow} NEURO {symbol} ({sig['direction']}, score {sig['score']})\n"
                    f"entry: {sig['entry']}, SL: {sig['sl']}, TP: {sig['tp']}\n"
                    f"\u0441\u043e\u0432\u043f\u0430\u0432\u0448\u0438\u0435\u0441\u044f \u0437\u0430\u0432\u0438\u0441\u0438\u043c\u043e\u0441\u0442\u0438: {pat_txt}"
                    + ("" if _sel_ok or not AUTOTRADE_ENABLED_NEURO else "\n☑️ не торгуется — монета не отмечена для автоторговли")
                    + ("\n📝 + бумажный счёт" if symbol in neuro_paper_symbols() else ""),
                    category="neuro",
                  )
                with _neuro_signal_log_lock:
                    record = {
                        "symbol": symbol, "direction": sig["direction"],
                        "entry": sig["entry"], "sl": sig["sl"], "tp": sig["tp"],
                        "rr": sig.get("rr"), "score": sig.get("score"),
                        "time": sig_time, "detected_at": time.time(),
                        "status": "OPEN", "result": None,
                        "exit_price": None, "exit_time": None, "pnl_r": None,
                        "autotrade_fired": False,
                    }
                    if not _sel_ok:
                        record["not_selected"] = True   # v0.99.384
                        if AUTOTRADE_ENABLED_NEURO:
                            record["autotrade_skip"] = neuro_not_traded_reason(symbol)   # v0.99.587
                    _neuro_signal_log.appendleft(record)
                if symbol in neuro_paper_symbols():
                    neuro_paper_open(symbol, sig, record)   # v0.99.547
                if AUTOTRADE_ENABLED_NEURO and _sel_ok:
                    # v0.99.245 — same live_universe-snapshot race guard as
                    # LSW's/Mirror's own (v0.99.239): active_symbols above
                    # is a one-time snapshot from the top of this pass; if
                    # a mining cycle rebuilds _neuro_active_symbols WHILE
                    # this pass is still scanning, re-check current
                    # membership right before spending real money — the
                    # signal stays logged either way.
                    still_active = symbol in neuro_trade_symbols()   # v0.99.403; v0.99.430 — outside the lock
                    if not still_active:
                        log_error(f"neuro_live_loop {symbol}: signal fired but symbol was dropped from _neuro_active_symbols mid-scan — signal logged, real trade skipped")
                        record["autotrade_skip"] = neuro_not_traded_reason(symbol) or "монета выпала из списка во время скана"   # v0.99.587
                        continue
                    # v0.99.245 — per direct user request ("надо сделать как
                    # в свип, настройки такие же, процент из настроек,
                    # расчет до ликвидации и ТП все так же"): identical
                    # call shape to LSW's/Mirror's own live trade-firing —
                    # execute_autotrade() is the SAME shared function every
                    # module's real orders go through, so Neuro
                    # automatically inherits everything already built
                    # there: risk-%-of-balance sizing from settings, tier-
                    # aware safe leverage (v0.99.237/238/242), and fee-
                    # aware position sizing so the realized SL loss matches
                    # the configured risk % exactly (v0.99.243) — no
                    # separate reimplementation, so it can never drift out
                    # of sync with LSW's own behavior the way past copy-
                    # pasted sizing logic has.
                    _neuro_all_in = NEURO_ALL_IN_MARGIN_PCT if NEURO_ALL_IN_ENABLED else None   # v0.99.418
                    autotrade_result = execute_autotrade("neuro", symbol, sig["direction"], sig["entry"], sig["sl"], sig["tp"],
                                                          all_in_margin_pct=_neuro_all_in,
                                                          risk_pct_override=auto_risk_for("neuro", symbol))   # v0.99.422
                    record["autotrade_fired"] = autotrade_result.get("status") in ("OPENED", "OPENED_TP_SL_FAILED")   # v0.99.436
                    if not record["autotrade_fired"]:   # v0.99.587 — the exchange side's reason, for the result message
                        record["autotrade_skip"] = str(autotrade_result.get("detail") or autotrade_result.get("status") or "")[:300]
                    sim_execute_trade("neuro", symbol, sig["direction"], sig["entry"], sig["sl"], sig["tp"],
                                       autotrade_result.get("leverage") or AUTOTRADE_LEVERAGE_NEURO, record,
                                       autotrade_result=autotrade_result, all_in_margin_pct=_neuro_all_in)
            _neuro_prev_signal_keys = {(s, t) for s, t in new_keys.items()}
            neuro_track_signal_outcomes()
            neuro_paper_sweep()   # v0.99.547
            save_neuro_state()  # v0.99.240 — persist any new fired signal / outcome update from this pass
        except Exception as e:
            log_error(f"neuro_live_loop: {e}")
        time.sleep(900)  # check every 15m regardless of the (usually 1h) structure TF


@app.route("/api/neuro/status")
def api_neuro_status():
    with _neuro_state_lock:
        patterns = dict(_neuro_patterns)
        trades = dict(_neuro_trades)
        summary = dict(_neuro_summary)
        live_signals = dict(_neuro_live_signals)
        last_mined = _neuro_last_mined
        waiting_slot_since = _neuro_waiting_slot_since
        last_error = _neuro_last_error
        running = _neuro_mining_running
        mining_done = _neuro_mining_done
        mining_total = _neuro_mining_total
        mining_current = _neuro_mining_current_symbol
        active_symbols = list(_neuro_active_symbols)
        display_symbols = list(_neuro_display_symbols)
    with _neuro_signal_log_lock:
        signal_log = list(_neuro_signal_log)
    signal_stats = neuro_compute_signal_stats(active_symbols)
    active_set = set(active_symbols)
    trade_set = set(neuro_trade_symbols())   # v0.99.403
    # v0.99.318 — coins mined before the $15 compounding simulation existed
    # (Neuro re-mines only every 24h): compute it once now and cache it
    # into the stored summary so it isn't recomputed on every poll.
    for symbol in display_symbols:
        if trades.get(symbol) and ("daily_pct" not in summary.get(symbol, {})
                                   or summary.get(symbol, {}).get("compound_sig") != compound_sig("neuro")):   # v0.99.418
            try:
                comp = neuro_compound_fields(trades[symbol], summary.get(symbol, {}), symbol)   # v0.99.403
            except Exception as e:
                log_error(f"neuro compound {symbol}: {e}")
                continue
            with _neuro_state_lock:
                if symbol in _neuro_summary:
                    _neuro_summary[symbol].update(comp)
            summary[symbol] = {**summary.get(symbol, {}), **comp}
    coins = []
    for symbol in display_symbols:
        recent_trades = (trades.get(symbol) or [])[-40:][::-1]
        neuro_mark_train(recent_trades, summary.get(symbol, {}))   # v0.99.536 — cards mined before the label existed too
        recent_live_signals = [s for s in signal_log if s["symbol"] == symbol][:40]
        coins.append({
            "symbol": symbol,
            "is_active": symbol in active_set,  # v0.99.403 — passes the check (can trade if ticked / best)
            "fail_reason": None if symbol in active_set else neuro_fail_reason(summary.get(symbol, {})),   # v0.99.416
            "money_blocked": symbol in active_set and not neuro_money_ok(symbol),   # v0.99.429
            "score": neuro_rank_metric(summary.get(symbol, {})),   # v0.99.417 — what the cards are ordered by
            "rank": len(coins) + 1,
            "trading": symbol in trade_set,
            "summary": summary.get(symbol, {}),
            "top_patterns": (patterns.get(symbol) or [])[:8],
            "live_signal": live_signals.get(symbol),
            "recent_trades": recent_trades,
            "live_signal_stats": signal_stats["by_symbol"].get(symbol),
            "recent_live_signals": recent_live_signals,
        })
    # v0.99.416 — passing coins first (a coin that fails the new test gate
    # may still sit high in the order saved by the last mining)
    coins.sort(key=lambda c: not c["is_active"])
    for i, c in enumerate(coins):
        c["rank"] = i + 1
    return jsonify({
        "autotrade_selected": sorted(_neuro_autotrade_selected),   # v0.99.384
        "paper": neuro_paper_status(),   # v0.99.547
        "stale_results": _neuro_results_algo < NEURO_ALGO_VERSION,   # v0.99.403
        "mining_fetching": _neuro_fetching[0],   # v0.99.404
        "single_best": NEURO_SINGLE_BEST_ENABLED,
        "best_symbol": next((s_ for s_ in active_symbols if neuro_money_ok(s_)), None),   # v0.99.403; v0.99.429 — first card that makes money at the current risk
        "autotrade_enabled": AUTOTRADE_ENABLED_NEURO,
        "enabled": NEURO_ENABLED,   # v0.99.562
        "calc": calc_status("neuro"), "calc_cond": calc_status("cond"),   # v0.99.372
        "coins": coins, "last_mined": last_mined, "mining_running": running,
        "waiting_slot_since": waiting_slot_since,
        "last_error_ts": last_error[0] if last_error else None,
        "last_error": last_error[1] if last_error else None,
        "next_mining_ts": (last_mined + NEURO_REFRESH_SEC) if last_mined else None,
        "mining_done": mining_done, "mining_total": mining_total, "mining_current_symbol": mining_current,
        "live_signal_stats": signal_stats,
        "config": {"tf": NEURO_TF, "forward_bars": NEURO_FORWARD_BARS, "rr": NEURO_RR,
                   "history_days": NEURO_HISTORY_DAYS, "z_threshold": NEURO_Z_THRESHOLD,
                   "min_agree_z": NEURO_MIN_AGREE_Z, "refresh_sec": NEURO_REFRESH_SEC,
                   "universe_size": NEURO_UNIVERSE_SIZE, "top_n_min_trades": NEURO_TOP_N_MIN_TRADES},
    })


@app.route("/api/neuro/chart/<symbol>")
def api_neuro_chart(symbol):
    try:
        sig_time = request.args.get("time")
        if not sig_time:
            return jsonify({"error": "нужен параметр time"}), 400
        target = float(sig_time)
        interval_sec = INTERVAL_SECONDS.get(NEURO_TF, 3600)
        # v0.99.588 — the card's live signals first: before, only the backtest trades
        # were searched, so a fresh live signal said "сделка не найдена"
        with _neuro_signal_log_lock:
            live = [dict(x) for x in _neuro_signal_log if x.get("symbol") == symbol]
        match = min((t for t in live if abs(t["time"] - target) < interval_sec), key=lambda t: abs(t["time"] - target), default=None)
        if not match:
            with _neuro_state_lock:
                trades = list(_neuro_trades.get(symbol, []))
            match = next((t for t in trades if abs(t["time"] - target) < interval_sec), None)
        if not match:
            return jsonify({"error": "\u0441\u0434\u0435\u043b\u043a\u0430 \u043d\u0435 \u043d\u0430\u0439\u0434\u0435\u043d\u0430"}), 404
        fetch_start = match["time"] - 60 * interval_sec
        fetch_end = (match["exit_time"] + 10 * interval_sec) if match.get("exit_time") else (match["time"] + 60 * interval_sec)
        candles = get_candles_range(symbol, NEURO_TF, fetch_start, fetch_end)
        return jsonify({
            "symbol": symbol, "candles": candles[-250:], "time": match["time"],
            "direction": match["direction"], "entry": match["entry"],
            "sl": match["sl"], "tp": match["tp"],
            "result": match.get("result"), "exit_time": match.get("exit_time"),
            "exit_price": match.get("exit_price"), "chart_source": "neuro",
        })
    except Exception as e:
        log_error(f"api_neuro_chart {symbol}: {e}")
        return jsonify({"error": str(e)}), 500


# ============================================================================
# NQ MODEL — Previous Day High/Low + daily bias + CISD confirmation, per
# direct user request based on an uploaded "NQ Motion Model" methodology
# PDF. Instrument: NAS100_USDT on Gate.io — a genuine Nasdaq-100 INDEX
# perpetual (launched by Gate.com Jan 2026), USDT-settled, trades 24/7 —
# NOT the real CME NQ futures contract, but tracks the same underlying
# index, and unlike a stock-backed xStock token it never pauses when the
# real NASDAQ market itself is closed. Reuses the exact same Gate.io
# candle-fetch infrastructure as every other module — no new data source.
#
# Signal logic (the two genuinely crypto-portable concepts from the PDF,
# per direct user choice — Key Opens/NWOG were explicitly excluded as
# CME-session-specific concepts that don't map onto a 24/7 instrument):
#   1. Previous Day High/Low: yesterday's high/low from daily candles.
#   2. Daily bias: yesterday's candle color — bullish (close>open) sets a
#      bias toward yesterday's HIGH getting swept; bearish sets a bias
#      toward the LOW getting swept (this is literally the PDF's own
#      "Bullish daily candle -> expect the high to get taken" rule).
#   3. Wait for an intraday bar to actually sweep (wick beyond) that
#      level during THIS day.
#   4. CISD confirmation: within NQ_CISD_MAX_WAIT_BARS bars after the
#      sweep, price must close back through the most recent short-term
#      swing point (the opposite extreme of the last NQ_CISD_LOOKBACK
#      bars before the sweep) — "price comes back and tests a level
#      quickly" per the PDF's own CISD definition.
#   5. Enter in the REVERSAL direction (opposite the sweep) — matches
#      the PDF's own AMD logic ("manipulated up -> expect down").
# Per direct user answers: no daily trade-count cap, no risk reduction
# after a loss (both PDF rules explicitly declined), but a HARD minimum
# RR of 3.0 (the PDF's own "1:3, no exceptions" — unlike every other
# module's freely-auto-tuned RR, here the walk-forward RR sweep is
# restricted to candidates that never go below 3.0).
# ============================================================================

NQ_ENABLED           = os.environ.get("VP_NQ_ENABLED", "0") == "1"  # v0.99.302 — same off-by-default UI removal as SCALP_SIGNALS_ENABLED's own
NQ_SYMBOL            = os.environ.get("VP_NQ_SYMBOL", "NAS100_USDT")
NQ_TF                = os.environ.get("VP_NQ_TF", "15m")
NQ_HISTORY_DAYS      = int(os.environ.get("VP_NQ_HISTORY_DAYS", 365))  # ask for a lot; NAS100_USDT only launched Jan 2026 so real history will be much shorter — code handles whatever comes back
NQ_CISD_LOOKBACK     = int(os.environ.get("VP_NQ_CISD_LOOKBACK", 8))   # bars before the sweep that define the "recent structure" level for CISD
NQ_CISD_MAX_WAIT_BARS = int(os.environ.get("VP_NQ_CISD_MAX_WAIT_BARS", 8))  # bars after the sweep to still accept a CISD close-through
NQ_SL_BUFFER_PCT     = float(os.environ.get("VP_NQ_SL_BUFFER_PCT", 0.05))
NQ_MAX_WAIT_BARS     = int(os.environ.get("VP_NQ_MAX_WAIT_BARS", 48))  # ~12h at 15m — how long a trade is tracked before TIMEOUT
NQ_RR                = float(os.environ.get("VP_NQ_RR", 3.0))          # fallback/default only — see NQ_RR_CANDIDATES
NQ_RR_CANDIDATES     = [3.0, 3.5, 4.0, 4.5, 5.0]  # HARD floor at 3.0 per the PDF's own "min RR 1:3, no exceptions" — unlike every other module, candidates never go below this
NQ_RR_TRAIN_FRAC     = float(os.environ.get("VP_NQ_RR_TRAIN_FRAC", 0.7))
NQ_RR_MIN_TRADES     = int(os.environ.get("VP_NQ_RR_MIN_TRADES", 10))  # NAS100_USDT's short real history means fewer trades to work with than crypto majors — lower bar than LSW/Neuro's own 15
NQ_PER_ITEM_MAX_SEC  = 300
NQ_SIGNAL_HISTORY    = 200
TELEGRAM_ALERTS_NQ   = os.environ.get("VP_TG_ALERTS_NQ", "1") == "1"

NQ_BACKTEST_TRIGGER = threading.Event()


def nq_daily_bounds(daily_candles):
    """Sort once, return (sorted_start_times, {start_time: candle}) for fast
    lookup of 'which UTC day does this intraday bar belong to' and 'what
    was the PREVIOUS day's own candle'."""
    by_start = {d["time"]: d for d in daily_candles}
    starts = sorted(by_start.keys())
    return starts, by_start


def nq_detect_signals(intraday_candles, daily_candles, rr=None):
    """Core PDH/PDL + daily-bias + CISD detector. Returns a list of signal
    dicts (time = the CISD-confirming bar's own time, entry at NEXT bar's
    open — same "don't enter on the same bar that confirmed it" convention
    as LSW's own entry confirmation)."""
    rr = rr if rr is not None else NQ_RR
    starts, by_start = nq_daily_bounds(daily_candles)
    if len(starts) < 2:
        return []
    day_sec = 86400
    signals = []
    for i in range(1, len(starts)):
        prev = by_start[starts[i - 1]]
        bias = "bullish" if prev["close"] > prev["open"] else "bearish"
        pdh, pdl = prev["high"], prev["low"]
        day_start, day_end = starts[i], starts[i] + day_sec
        today_bars = [b for b in intraday_candles if day_start <= b["time"] < day_end]
        if not today_bars:
            continue
        swept_idx = None
        for j, b in enumerate(today_bars):
            if bias == "bullish" and b["high"] > pdh:
                swept_idx = j
                break
            if bias == "bearish" and b["low"] < pdl:
                swept_idx = j
                break
        if swept_idx is None:
            continue
        pre_bars = today_bars[max(0, swept_idx - NQ_CISD_LOOKBACK):swept_idx]
        if not pre_bars:
            continue
        structure_lvl = min(b["low"] for b in pre_bars) if bias == "bullish" else max(b["high"] for b in pre_bars)
        for k in range(swept_idx, min(swept_idx + NQ_CISD_MAX_WAIT_BARS, len(today_bars))):
            b = today_bars[k]
            confirmed = (bias == "bullish" and b["close"] < structure_lvl) or \
                        (bias == "bearish" and b["close"] > structure_lvl)
            if not confirmed:
                continue
            # Find the NEXT bar in the full intraday series (not just today_bars)
            next_bar = None
            for c in intraday_candles:
                if c["time"] > b["time"]:
                    next_bar = c
                    break
            if next_bar is None:
                break
            entry = next_bar["open"]
            if bias == "bullish":
                sweep_extreme = max(x["high"] for x in today_bars[swept_idx:k + 1])
                sl = sweep_extreme * (1 + NQ_SL_BUFFER_PCT / 100)
                sl_dist = sl - entry
                if sl_dist <= 0:
                    break
                tp = entry - sl_dist * rr
                direction = "SHORT"
            else:
                sweep_extreme = min(x["low"] for x in today_bars[swept_idx:k + 1])
                sl = sweep_extreme * (1 - NQ_SL_BUFFER_PCT / 100)
                sl_dist = entry - sl
                if sl_dist <= 0:
                    break
                tp = entry + sl_dist * rr
                direction = "LONG"
            signals.append({
                "time": b["time"], "entry_time": next_bar["time"], "direction": direction,
                "entry": round(entry, 4), "sl": round(sl, 4), "tp": round(tp, 4), "rr": rr,
                "bias": bias, "pdh": round(pdh, 4), "pdl": round(pdl, 4),
                "day_start": day_start,
            })
            break
    return signals


def nq_track_outcome(candles, sig, max_wait_bars=None):
    max_wait_bars = max_wait_bars or NQ_MAX_WAIT_BARS
    future = [c for c in candles if c["time"] > sig["entry_time"]]
    direction = sig["direction"]
    for i, c in enumerate(future):
        if i >= max_wait_bars:
            return "TIMEOUT", c["close"], c["time"]
        if direction == "LONG":
            if c["low"] <= sig["sl"]:
                return "LOSS", sig["sl"], c["time"]
            if c["high"] >= sig["tp"]:
                return "WIN", sig["tp"], c["time"]
        else:
            if c["high"] >= sig["sl"]:
                return "LOSS", sig["sl"], c["time"]
            if c["low"] <= sig["tp"]:
                return "WIN", sig["tp"], c["time"]
    return "OPEN", None, None


def nq_simulate_trades(intraday_candles, daily_candles, rr=None):
    sigs = nq_detect_signals(intraday_candles, daily_candles, rr=rr)
    trades = []
    for sig in sigs:
        result, exit_price, exit_time = nq_track_outcome(intraday_candles, sig)
        pnl_r = None
        if result in ("WIN", "LOSS") and exit_price is not None:
            sl_dist = abs(sig["entry"] - sig["sl"]) or 1e-9
            raw = (exit_price - sig["entry"]) / sl_dist if sig["direction"] == "LONG" else (sig["entry"] - exit_price) / sl_dist
            pnl_r = round(raw if result == "WIN" else -abs(raw), 3)
        elif result == "TIMEOUT" and exit_price is not None:
            sl_dist = abs(sig["entry"] - sig["sl"]) or 1e-9
            raw = (exit_price - sig["entry"]) / sl_dist if sig["direction"] == "LONG" else (sig["entry"] - exit_price) / sl_dist
            pnl_r = round(raw, 3)
        trades.append({**sig, "result": result if result != "OPEN" else "TIMEOUT",
                       "exit_price": exit_price, "exit_time": exit_time, "pnl_r": pnl_r})
    return trades


def nq_pick_best_rr(intraday_candles, daily_candles, train_frac=None):
    """Same walk-forward discipline as LSW/Neuro's own RR auto-tuning —
    sweep candidates on the TRAIN portion only (never touches test), but
    candidates never go below 3.0 per the PDF's own hard RR floor."""
    train_frac = train_frac if train_frac is not None else NQ_RR_TRAIN_FRAC
    split_time = daily_candles[int(len(daily_candles) * train_frac)]["time"] if daily_candles else 0
    train_intraday = [c for c in intraday_candles if c["time"] < split_time]
    train_daily = [d for d in daily_candles if d["time"] < split_time]
    sweep = []
    best_rr, best_score = NQ_RR_CANDIDATES[0], None
    for rr in NQ_RR_CANDIDATES:
        trades = nq_simulate_trades(train_intraday, train_daily, rr=rr)
        closed = [t for t in trades if t["result"] in ("WIN", "LOSS")]
        if len(closed) < NQ_RR_MIN_TRADES:
            sweep.append({"rr": rr, "n": len(closed), "winrate": None, "expectancy_r": None})
            continue
        wins = sum(1 for t in closed if t["result"] == "WIN")
        wr = wins / len(closed)
        expectancy = round(wr * rr - (1 - wr), 3)
        sweep.append({"rr": rr, "n": len(closed), "winrate": round(wr * 100, 1), "expectancy_r": expectancy})
        if best_score is None or expectancy > best_score:
            best_score, best_rr = expectancy, rr
    return best_rr, sweep


def nq_backtest():
    """Fetch max available history for NAS100_USDT, auto-tune RR (train-
    only), simulate the resulting trade history on the full period.
    Returns (trades, summary)."""
    try:
        now = int(time.time())
        start_ts = now - NQ_HISTORY_DAYS * 86400
        intraday = get_candles_range(NQ_SYMBOL, NQ_TF, start_ts, now)
        daily = get_candles_range(NQ_SYMBOL, "1d", start_ts, now)
        if not intraday or not daily or len(daily) < 5:
            return [], {"history_bars": len(intraday or []), "history_days_daily": len(daily or [])}
        chosen_rr, rr_sweep = nq_pick_best_rr(intraday, daily)
        trades = nq_simulate_trades(intraday, daily, rr=chosen_rr)
        closed = [t for t in trades if t["result"] in ("WIN", "LOSS")]
        wins = sum(1 for t in closed if t["result"] == "WIN")
        losses = len(closed) - wins
        wr = round(wins / len(closed) * 100, 1) if closed else None
        avg_pnl = round(sum(t["pnl_r"] for t in closed if t.get("pnl_r") is not None) / len(closed), 3) if closed else None
        summary = {
            "n": len(closed), "wins": wins, "losses": losses,
            "timeouts": sum(1 for t in trades if t["result"] == "TIMEOUT"),
            "winrate": wr, "avg_pnl_r": avg_pnl, "total": len(trades),
            "chosen_rr": chosen_rr, "rr_sweep": rr_sweep,
            "history_bars": len(intraday), "history_days_daily": len(daily),
        }
        return trades, summary
    except Exception as e:
        log_error(f"nq_backtest: {e}")
        return [], {}


def nq_scan_live(chosen_rr=None):
    """Check only TODAY's bars (so far) for a fresh sweep+CISD — same
    detector, just scoped to the most recent 1-2 days of data."""
    try:
        rr = chosen_rr if chosen_rr is not None else NQ_RR
        now = int(time.time())
        interval_sec = INTERVAL_SECONDS.get(NQ_TF, 900)
        intraday = get_candles_range(NQ_SYMBOL, NQ_TF, now - 5 * 86400, now)
        daily = get_candles_range(NQ_SYMBOL, "1d", now - 10 * 86400, now)
        if not intraday or not daily or len(daily) < 2:
            return None
        intraday = [c for c in intraday if c["time"] + interval_sec <= now]
        sigs = nq_detect_signals(intraday, daily, rr=rr)
        if not sigs:
            return None
        latest = sigs[-1]
        # Only a genuinely fresh signal (from today's own trading day) counts as "live"
        today_start = (now // 86400) * 86400
        if latest["day_start"] < today_start:
            return None
        return latest
    except Exception as e:
        log_error(f"nq_scan_live: {e}")
        return None


_nq_state_lock = threading.Lock()
_nq_trades = []
_nq_summary = {}
_nq_signal_log = deque(maxlen=NQ_SIGNAL_HISTORY)
_nq_last_backtest_finished = None
_nq_backtest_running = False
_nq_live_signal = None
_nq_prev_signal_key = None


def nq_backtest_loop():
    global _nq_last_backtest_finished, _nq_backtest_running
    # v0.99.267 -- staggered backtest-cycle startup, see msnr_backtest_
    # loop()'s own comment for the full reasoning. This module's first
    # cycle waits 540s before starting, spreading all 7 backtest
    # loops' initial burst of network activity across ~9 minutes
    # instead of all colliding on the shared semaphore at once.
    # v0.99.272 -- same CRITICAL FIX as ft5_backtest_loop()'s own — see
    # that function's own comment for the full incident.
    NQ_BACKTEST_TRIGGER.wait(timeout=540)
    NQ_BACKTEST_TRIGGER.clear()
    while True:
        _nq_sem_acquired = False
        try:
            if not NQ_ENABLED:
                NQ_BACKTEST_TRIGGER.wait(timeout=3600)
                NQ_BACKTEST_TRIGGER.clear()
                continue
            with _nq_state_lock:
                _nq_backtest_running = True
            # v0.99.268 — same shared concurrency cap as msnr_backtest_loop's
            # own (see its comment for the full reasoning).
            BACKTEST_CONCURRENCY_SEMAPHORE.acquire()
            _nq_sem_acquired = True
            # Same no-with-block, bounded-time pattern as every other
            # module's own hang protection (LSW/MSNR/AMD v0.99.194/195/etc).
            ex = ThreadPoolExecutor(max_workers=1)
            try:
                fut = ex.submit(nq_backtest)
                try:
                    trades, summary = fut.result(timeout=NQ_PER_ITEM_MAX_SEC)
                    with _nq_state_lock:
                        _nq_trades[:] = trades
                        _nq_summary.clear()
                        _nq_summary.update(summary)
                except (TimeoutError, FutureTimeoutError):
                    log_error(f"nq_backtest_loop: exceeded {NQ_PER_ITEM_MAX_SEC}s — skipping this cycle")
                except Exception as e:
                    log_error(f"nq_backtest_loop: {e}")
            finally:
                ex.shutdown(wait=False)
            with _nq_state_lock:
                _nq_backtest_running = False
                _nq_last_backtest_finished = time.time()
            save_nq_state()  # v0.99.240 — persist the freshly-completed backtest
        except Exception as e:
            log_error(f"nq_backtest_loop: {e}")
            with _nq_state_lock:
                _nq_backtest_running = False
        finally:
            if _nq_sem_acquired:
                BACKTEST_CONCURRENCY_SEMAPHORE.release()
        NQ_BACKTEST_TRIGGER.wait(timeout=3600)  # re-mine hourly — daily-candle-driven signal, no need for Neuro/LSW-style frequent re-mining
        NQ_BACKTEST_TRIGGER.clear()


def nq_live_loop():
    global _nq_live_signal, _nq_prev_signal_key
    while True:
        try:
            if not NQ_ENABLED:
                time.sleep(900)
                continue
            with _nq_state_lock:
                chosen_rr = _nq_summary.get("chosen_rr")
            sig = nq_scan_live(chosen_rr)
            with _nq_state_lock:
                _nq_live_signal = sig
            key = (sig["time"], sig["direction"]) if sig else None
            if sig and key != _nq_prev_signal_key:
                arrow = "\u2b06\ufe0f" if sig["direction"] == "LONG" else "\u2b07\ufe0f"
                send_telegram(
                    f"{arrow} NQ MODEL {NQ_SYMBOL} ({sig['direction']}, PDH/PDL + CISD, bias={sig['bias']})\n"
                    f"entry: {sig['entry']}, SL: {sig['sl']}, TP: {sig['tp']} (RR {sig['rr']})",
                    category="nq",
                )
                with _nq_state_lock:
                    _nq_signal_log.appendleft({**sig, "status": "OPEN", "result": None,
                                               "exit_price": None, "exit_time": None, "pnl_r": None,
                                               "detected_at": time.time()})
            _nq_prev_signal_key = key
            # Track outcomes for OPEN entries in the live log
            with _nq_state_lock:
                open_entries = [s for s in _nq_signal_log if s["status"] == "OPEN"]
            if open_entries:
                now = int(time.time())
                candles = get_candles_range(NQ_SYMBOL, NQ_TF, now - 5 * 86400, now)
                interval_sec = INTERVAL_SECONDS.get(NQ_TF, 900)
                candles = [c for c in candles if c["time"] + interval_sec <= now]
                for entry in open_entries:
                    result, exit_price, exit_time = nq_track_outcome(candles, entry)
                    if result != "OPEN":
                        sl_dist = abs(entry["entry"] - entry["sl"]) or 1e-9
                        pnl_r = None
                        if exit_price is not None:
                            raw = (exit_price - entry["entry"]) / sl_dist if entry["direction"] == "LONG" else (entry["entry"] - exit_price) / sl_dist
                            pnl_r = round(-abs(raw), 3) if result == "LOSS" else round(raw, 3)
                        with _nq_state_lock:
                            entry["status"] = "CLOSED"
                            entry["result"] = result
                            entry["exit_price"] = exit_price
                            entry["exit_time"] = exit_time
                            entry["pnl_r"] = pnl_r
            save_nq_state()  # v0.99.240 — persist any new fired signal / outcome update from this pass
        except Exception as e:
            log_error(f"nq_live_loop: {e}")
        time.sleep(900)


def nq_compute_signal_stats():
    with _nq_state_lock:
        signals = list(_nq_signal_log)
    closed = [s for s in signals if s["status"] == "CLOSED" and s["result"] in ("WIN", "LOSS")]
    wins = sum(1 for s in closed if s["result"] == "WIN")
    losses = len(closed) - wins
    open_n = sum(1 for s in signals if s["status"] == "OPEN")
    winrate = round(wins / len(closed) * 100, 1) if closed else None
    avg_pnl = round(sum(s["pnl_r"] for s in closed if s.get("pnl_r") is not None) / len(closed), 3) if closed else None
    return {"total": len(signals), "wins": wins, "losses": losses, "open": open_n,
            "winrate": winrate, "avg_pnl_r": avg_pnl}


@app.route("/api/nq/status")
def api_nq_status():
    with _nq_state_lock:
        trades = list(_nq_trades)
        summary = dict(_nq_summary)
        live_signal = _nq_live_signal
        running = _nq_backtest_running
        last_finished = _nq_last_backtest_finished
        signal_log = list(_nq_signal_log)[:40]
    return jsonify({
        "symbol": NQ_SYMBOL, "trades": trades[-40:][::-1], "summary": summary,
        "live_signal": live_signal, "backtest_running": running,
        "last_backtest_finished": last_finished,
        "signal_log": signal_log, "signal_stats": nq_compute_signal_stats(),
        "config": {"tf": NQ_TF, "history_days": NQ_HISTORY_DAYS, "rr": NQ_RR,
                   "cisd_lookback": NQ_CISD_LOOKBACK, "cisd_max_wait_bars": NQ_CISD_MAX_WAIT_BARS},
    })


@app.route("/api/nq/chart")
def api_nq_chart():
    try:
        sig_time = request.args.get("time")
        if not sig_time:
            return jsonify({"error": "нужен параметр time"}), 400
        target = float(sig_time)
        with _nq_state_lock:
            trades = list(_nq_trades)
            signal_log = list(_nq_signal_log)
        match = next((t for t in trades if abs(t["time"] - target) < 60), None) or \
            next((s for s in signal_log if abs(s["time"] - target) < 60), None)
        if not match:
            return jsonify({"error": "\u0441\u0434\u0435\u043b\u043a\u0430 \u043d\u0435 \u043d\u0430\u0439\u0434\u0435\u043d\u0430"}), 404
        interval_sec = INTERVAL_SECONDS.get(NQ_TF, 900)
        fetch_start = match["time"] - 60 * interval_sec
        fetch_end = (match["exit_time"] + 10 * interval_sec) if match.get("exit_time") else (match["time"] + 60 * interval_sec)
        candles = get_candles_range(NQ_SYMBOL, NQ_TF, fetch_start, fetch_end)
        return jsonify({
            "symbol": NQ_SYMBOL, "candles": candles[-250:], "time": match["time"],
            "direction": match["direction"], "entry": match["entry"],
            "sl": match["sl"], "tp": match["tp"],
            "result": match.get("result"), "exit_time": match.get("exit_time"),
            "exit_price": match.get("exit_price"), "chart_source": "nq",
        })
    except Exception as e:
        log_error(f"api_nq_chart: {e}")
        return jsonify({"error": str(e)}), 500


@app.route("/api/reset/nq", methods=["POST"])
def api_reset_nq():
    try:
        with _nq_state_lock:
            _nq_trades.clear()
            _nq_summary.clear()
            _nq_signal_log.clear()
            global _nq_live_signal, _nq_prev_signal_key
            _nq_live_signal = None
            _nq_prev_signal_key = None
        save_nq_state()  # v0.99.240 — persist the reset immediately, so a restart right after doesn't resurrect the old cleared data from disk
        NQ_BACKTEST_TRIGGER.set()
        return jsonify({"ok": True})
    except Exception as e:
        log_error(f"api_reset_nq: {e}")
        return jsonify({"ok": False, "error": str(e)}), 500


@app.route("/api/amd/status")
def api_amd_status():
    with _amd_results_lock:
        results = list(_amd_results)
        last_scan = _amd_last_scan
    with _amd_backtest_lock2:
        top = [dict(s, symbol=sym) for sym, s in _amd_backtest_summary.items()]
        bt_running = _amd_backtest_running
        bt_total = _amd_backtest_total
        bt_done = _amd_backtest_done
        bt_last_finished = _amd_backtest_last_finished
        bt_last_duration = _amd_backtest_last_duration
    top.sort(key=lambda r: (r.get("winrate") or 0, r.get("n") or 0), reverse=True)
    return jsonify({
        "results": results, "last_scan": last_scan,
        "top": top,
        "backtest_running": bt_running, "backtest_total": bt_total, "backtest_done": bt_done,
        "last_backtest_finished": bt_last_finished, "last_backtest_duration": bt_last_duration,
        "config": {
            "structure_tf": AMD_STRUCTURE_TF, "entry_tf": AMD_ENTRY_TF,
            "rr": AMD_RR, "backtest_days": AMD_BACKTEST_DAYS,
            "a_atr_mult": AMD_A_ATR_MULT, "m_atr_mult": AMD_M_ATR_MULT,
            "refresh_sec": AMD_REFRESH_SEC,
        },
    })


@app.route("/api/amd/backtest/<symbol>")
def api_amd_backtest(symbol):
    with _amd_backtest_lock:
        cached = _amd_backtest_cache.get(symbol)
    if cached and time.time() - cached.get("computed_at", 0) < 3600:
        return jsonify(cached)
    trades, summary = amd_backtest_symbol(symbol)
    result = {"symbol": symbol, "trades": trades, "summary": summary,
              "computed_at": int(time.time())}
    with _amd_backtest_lock:
        _amd_backtest_cache[symbol] = result
    return jsonify(result)


@app.route("/api/amd/chart/<symbol>")
def api_amd_chart(symbol):
    """Same pattern as api_lsw_chart(): look up the signal's own recorded
    entry/sl/tp (live signal first, then background-backtest trades),
    never re-derive from current live params which could have drifted."""
    try:
        sig_time = request.args.get("time")
        found = None
        found_result = None
        found_exit_time = None
        found_exit_price = None
        interval_sec = INTERVAL_SECONDS.get(AMD_STRUCTURE_TF, 900)
        if sig_time:
            target = float(sig_time)
            with _amd_results_lock:
                live_match = min((s for s in _amd_results
                                   if s["symbol"] == symbol and abs(s["time"] - target) < interval_sec),
                                  key=lambda s: abs(s["time"] - target), default=None)   # v0.99.596 — the nearest
            if live_match:
                found = {"time": live_match["time"], "direction": live_match["direction"],
                         "entry": live_match["entry"], "sl": live_match["sl"], "tp": live_match["tp"],
                         "a_low": live_match.get("a_low"), "a_high": live_match.get("a_high")}
            else:
                with _amd_backtest_lock2:
                    bt_trades = list(_amd_backtest_trades.get(symbol, []))
                bt_match = next((t for t in bt_trades if abs(t["time"] - target) < interval_sec), None)
                if bt_match:
                    found = {"time": bt_match["time"], "direction": bt_match["direction"],
                             "entry": bt_match["entry"], "sl": bt_match["sl"], "tp": bt_match["tp"],
                             "a_low": bt_match.get("a_low"), "a_high": bt_match.get("a_high")}
                    found_result = bt_match.get("result")
                    found_exit_time = bt_match.get("exit_time")
                    found_exit_price = bt_match.get("exit_price")
        if found is None:
            return jsonify({"error": "сигнал не найден"}), 404
        fetch_start = found["time"] - (AMD_A_MAX_BARS + AMD_ATR_PERIOD + 10) * interval_sec
        fetch_end = (found_exit_time + 10 * interval_sec) if found_exit_time else (found["time"] + 60 * interval_sec)
        candles = get_candles_range(symbol, AMD_STRUCTURE_TF, fetch_start, fetch_end)
        return jsonify({
            "symbol": symbol, "candles": candles[-250:], "time": found["time"],
            "direction": found["direction"], "entry": found["entry"],
            "sl": found["sl"], "tp": found["tp"],
            "a_low": found.get("a_low"), "a_high": found.get("a_high"),
            "result": found_result, "exit_time": found_exit_time, "exit_price": found_exit_price,
            "chart_source": "amd", "tf": AMD_STRUCTURE_TF,
        })
    except Exception as e:
        log_error(f"api_amd_chart {symbol}: {e}")
        return jsonify({"error": str(e)}), 500


