# The research engine (tools/winrate/s15_engine.py, family deep2) re-done for the LAST closed 15m bar of one coin, in pure
# Python: the limit level of each side, and the model's 28 features. b15 = the coin's closed 15m bars (>= 2900, oldest
# first), d1 = its closed daily bars, bb15 = BTC's closed 15m bars.
DLM_FNAMES = ["fam", "side", "atrp", "datr", "depth", "hour", "dow", "r1h", "r4h", "r24h", "e20", "e50", "e200", "sl50", "rsi", "rsi4",
              "bbz", "vwz", "pos96", "volr", "b4h", "b24h", "batr", "wick", "rng", "since", "r7d", "dpos30"]


# v0.99.687 — the 4h model's 5 more daily features (tools/winrate s24_feat.py): the close vs the coin's daily EMA20 /
# EMA50 in daily ATRs, its daily RSI14, its place in the 20-day range, BTC's daily close vs its daily EMA50
DLM_FNAMES4 = DLM_FNAMES + ["d_e20", "d_e50", "d_rsi", "d_pos20", "b_d_e50"]


def dlm_wilder(H, L, C, n=14):
    out = [None] * len(C)
    if len(C) <= n:
        return out
    s = 0.0
    for i in range(n):
        s += (H[i] - L[i]) if i == 0 else max(H[i] - L[i], abs(H[i] - C[i - 1]), abs(L[i] - C[i - 1]))
    a = s / n
    out[n - 1] = a
    for i in range(n, len(C)):
        a = (a * (n - 1) + max(H[i] - L[i], abs(H[i] - C[i - 1]), abs(L[i] - C[i - 1]))) / n
        out[i] = a
    return out


def dlm_ema(x, n):
    out, k, e = [0.0] * len(x), 2.0 / (n + 1), x[0]
    for i, v in enumerate(x):
        e = v if i == 0 else e + k * (v - e)
        out[i] = e
    return out


def dlm_rsi(C, n):
    out = [50.0] * len(C)
    au = ad = 0.0
    for i in range(1, len(C)):
        d = C[i] - C[i - 1]
        u, dn = (d if d > 0 else 0.0), (-d if d < 0 else 0.0)
        if i <= n:
            au += u / n; ad += dn / n
        else:
            au = (au * (n - 1) + u) / n; ad = (ad * (n - 1) + dn) / n
        if i >= n:
            out[i] = 100 - 100 / (1 + au / ad) if ad > 0 else 100.0
    return out


def dlm_since(H, L, C, atr, side, i0, depth=2.0, alive=4, back=1000, wick=False):
    """bars from the last FILLED deep limit of this side (the research's event process: one order a bar while none is
    filled-and-open, alive `alive` bars) to the bar i0; fills known only up to i0. None = an earlier order filled at
    i0 itself (the research has no order at i0 then). wick (v0.99.687): the level from the bar's low / high, not its close"""
    last, busy = None, -1
    for j in range(max(300, i0 - back), i0):
        if busy > j or atr[j] is None or not atr[j] > 0:
            continue
        lv = ((L[j] if side > 0 else H[j]) if wick else C[j]) - side * depth * atr[j]
        for b in range(j + 1, min(j + alive, i0) + 1):
            if (L[b] <= lv) if side > 0 else (H[b] >= lv):
                last, busy = j, b + 1
                break
    if busy > i0:
        return None
    return min(999, i0 - last) if last is not None else 999


def dlm_candidates(b15, d1, bb15):
    """-> [{"side", "lv", "atr", "f": [28]}] for the last closed bar (both sides), [] when the data is short"""
    n = len(b15)
    if n < 2900 or len(d1) < 20 or len(bb15) < 120:
        return []
    T = [c["time"] for c in b15]
    O = [c["open"] for c in b15]; H = [c["high"] for c in b15]; L = [c["low"] for c in b15]; C = [c["close"] for c in b15]
    V = [float(c.get("volume") or 0) for c in b15]
    i = n - 1
    atr = dlm_wilder(H, L, C)
    a = atr[i]
    if not a or a <= 0:
        return []
    day_i = T[i] // 86400
    dd = [c for c in d1 if c["time"] // 86400 < day_i]   # the last closed day before the bar's day
    if len(dd) < 15:
        return []
    dat = dlm_wilder([c["high"] for c in dd], [c["low"] for c in dd], [c["close"] for c in dd])[-1]
    datr = dat / dd[-1]["close"] * 100 if dat else 0.0
    px = C[i]
    e20, e50, e200 = dlm_ema(C, 20), dlm_ema(C, 50), dlm_ema(C, 200)
    r15, r60 = dlm_rsi(C, 14), dlm_rsi(C, 56)
    w20 = C[i - 19:i + 1]; bbm = sum(w20) / 20; bbs = math.sqrt(max(sum(v * v for v in w20) / 20 - bbm * bbm, 0.0))
    vw = [0.0] * n; cv = cpv = 0.0
    for k in range(n):
        if k == 0 or T[k] // 86400 != T[k - 1] // 86400:
            cv = cpv = 0.0
        cv += V[k]; cpv += (H[k] + L[k] + C[k]) / 3 * V[k]
        vw[k] = cpv / cv if cv > 0 else C[k]
    dv = [C[k] - vw[k] for k in range(i - 95, i + 1)]
    m_ = sum(dv) / 96; vws = math.sqrt(max(sum(v * v for v in dv) / 96 - m_ * m_, 0.0))
    hi96, lo96 = max(H[i - 96:i]), min(L[i - 96:i])
    v4 = sum(V[i - 3:i + 1]); v96 = sum(V[i - 95:i + 1])
    volr = math.log((v4 + 1e-9) / (v96 / 24 + 1e-9))
    bT = [c["time"] for c in bb15]
    bj = bisect.bisect_right(bT, T[i]) - 1
    if bj < 96:
        return []
    bC = [c["close"] for c in bb15]
    batr = dlm_wilder([c["high"] for c in bb15], [c["low"] for c in bb15], bC)[bj]
    hi30, lo30 = max(H[max(0, i - 2880):i + 1]), min(L[max(0, i - 2880):i + 1])
    up_w = H[i] - max(O[i], C[i]); dn_w = min(O[i], C[i]) - L[i]
    out = []
    for side in (1, -1):
        since = dlm_since(H, L, C, atr, side, i)
        if since is None:
            continue
        s = float(side)
        ret = lambda k: s * (px / C[max(i - k, 0)] - 1) * 100
        rg = hi96 - lo96
        pos = (px - lo96) / rg if rg > 0 else 0.5
        p30 = (px - lo30) / (hi30 - lo30) if hi30 > lo30 else 0.5
        f = [0.0, s, a / px * 100, datr, 2.0, float((T[i] // 3600) % 24), float((day_i + 3) % 7), ret(4), ret(16), ret(96),
             s * (px - e20[i]) / a, s * (px - e50[i]) / a, s * (px - e200[i]) / a, s * (e50[i] - e50[max(i - 16, 0)]) / a,
             s * (r15[i] - 50), s * (r60[i] - 50), s * (px - bbm) / bbs if bbs > 0 else 0.0, s * (px - vw[i]) / vws if vws > 0 else 0.0,
             pos if side > 0 else 1 - pos, volr, s * (bC[bj] / bC[bj - 16] - 1) * 100, s * (bC[bj] / bC[bj - 96] - 1) * 100,
             (batr / bC[bj] * 100) if batr else 0.0, s * (dn_w - up_w) / a, (H[i] - L[i]) / a, math.log1p(since), ret(672),
             p30 if side > 0 else 1 - p30]
        out.append({"side": side, "lv": px - side * 2.0 * a, "atr": a, "f": f})
    return out


def dlm_candidates4(b4, bb4, streams=None, dmin=0.3, dmax=6.0, min_bars=2000):
    """v0.99.687 — the 4h "wick" limits (tools/winrate s20h4_engine.py, family wick1) for the LAST closed 4h bar of one
    coin: the limit 1 ATR(4h) beyond the bar's low (long) / high (short), and the same 28 features on 4h bars. The daily
    ATR from the 4h bars grouped by UTC day (the last closed day), as the research did. b4 = the coin's closed 4h bars
    (oldest first; the research skipped coins with < 2000), bb4 = BTC's closed 4h bars (~3000: its daily EMA50).
    v0.99.689: any chart (4h, 2h — the research engines are the same code on other bars); streams = the limit kinds of
    this chart — {"anchor": "wick" (beyond the bar's low / high) | "close", "depth_atr", "fam" (the research family's
    index, a feature)}; the default = the 4h wick stream.
    -> [{"side", "st" (the stream's index in `streams`), "lv", "atr", "f": [33]}], [] when the data is short"""
    streams = streams or [{"anchor": "wick", "depth_atr": 1.0, "fam": 2.0}]
    n = len(b4)
    if n < min_bars or len(bb4) < 120:
        return []
    T = [c["time"] for c in b4]
    O = [c["open"] for c in b4]; H = [c["high"] for c in b4]; L = [c["low"] for c in b4]; C = [c["close"] for c in b4]
    V = [float(c.get("volume") or 0) for c in b4]
    i = n - 1
    atr = dlm_wilder(H, L, C)
    a = atr[i]
    if not a or a <= 0:
        return []
    day_i = T[i] // 86400
    dH, dL, dC, last = [], [], [], None
    for k in range(n):
        d_ = T[k] // 86400
        if d_ >= day_i:
            break
        if d_ != last:
            dH.append(H[k]); dL.append(L[k]); dC.append(C[k]); last = d_
        else:
            dH[-1] = max(dH[-1], H[k]); dL[-1] = min(dL[-1], L[k]); dC[-1] = C[k]
    if len(dC) < 15:
        return []
    dat = dlm_wilder(dH, dL, dC)[-1]
    datr = dat / dC[-1] * 100 if dat else 0.0
    px = C[i]
    de20, de50, dr14 = dlm_ema(dC, 20)[-1], dlm_ema(dC, 50)[-1], dlm_rsi(dC, 14)[-1]   # the daily context (the last closed day)
    dhi, dlo = max(dH[-20:]), min(dL[-20:])
    bdC, last = [], None
    for c in bb4:
        d_ = c["time"] // 86400
        if d_ >= day_i:
            break
        if d_ != last:
            bdC.append(c["close"]); last = d_
        else:
            bdC[-1] = c["close"]
    be50 = dlm_ema(bdC, 50)[-1] if bdC else None
    e20, e50, e200 = dlm_ema(C, 20), dlm_ema(C, 50), dlm_ema(C, 200)
    r15, r60 = dlm_rsi(C, 14), dlm_rsi(C, 56)
    w20 = C[i - 19:i + 1]; bbm = sum(w20) / 20; bbs = math.sqrt(max(sum(v * v for v in w20) / 20 - bbm * bbm, 0.0))
    vw = [0.0] * n; cv = cpv = 0.0
    for k in range(n):
        if k == 0 or T[k] // 86400 != T[k - 1] // 86400:
            cv = cpv = 0.0
        cv += V[k]; cpv += (H[k] + L[k] + C[k]) / 3 * V[k]
        vw[k] = cpv / cv if cv > 0 else C[k]
    dv = [C[k] - vw[k] for k in range(i - 95, i + 1)]
    m_ = sum(dv) / 96; vws = math.sqrt(max(sum(v * v for v in dv) / 96 - m_ * m_, 0.0))
    hi96, lo96 = max(H[i - 96:i]), min(L[i - 96:i])
    v4 = sum(V[i - 3:i + 1]); v96 = sum(V[i - 95:i + 1])
    volr = math.log((v4 + 1e-9) / (v96 / 24 + 1e-9))
    bT = [c["time"] for c in bb4]
    bj = bisect.bisect_right(bT, T[i]) - 1
    if bj < 96:
        return []
    bC = [c["close"] for c in bb4]
    batr = dlm_wilder([c["high"] for c in bb4], [c["low"] for c in bb4], bC)[bj]
    hi30, lo30 = max(H[max(0, i - 2880):i + 1]), min(L[max(0, i - 2880):i + 1])
    up_w = H[i] - max(O[i], C[i]); dn_w = min(O[i], C[i]) - L[i]
    out = []
    for side, (si, st) in ((sd, x) for sd in (1, -1) for x in enumerate(streams)):
        wick, depth = st.get("anchor", "wick") == "wick", float(st.get("depth_atr", 1.0))
        lv = ((L[i] if side > 0 else H[i]) if wick else px) - side * depth * a
        dep = abs(lv - px) / a
        if dep < dmin or dep > dmax:
            continue
        since = dlm_since(H, L, C, atr, side, i, depth=depth, wick=wick)
        if since is None:
            continue
        s = float(side)
        ret = lambda k: s * (px / C[max(i - k, 0)] - 1) * 100
        rg = hi96 - lo96
        pos = (px - lo96) / rg if rg > 0 else 0.5
        p30 = (px - lo30) / (hi30 - lo30) if hi30 > lo30 else 0.5
        f = [float(st.get("fam", 2.0)), s, a / px * 100, datr, dep, float((T[i] // 3600) % 24), float((day_i + 3) % 7), ret(4), ret(16), ret(96),
             s * (px - e20[i]) / a, s * (px - e50[i]) / a, s * (px - e200[i]) / a, s * (e50[i] - e50[max(i - 16, 0)]) / a,
             s * (r15[i] - 50), s * (r60[i] - 50), s * (px - bbm) / bbs if bbs > 0 else 0.0, s * (px - vw[i]) / vws if vws > 0 else 0.0,
             pos if side > 0 else 1 - pos, volr, s * (bC[bj] / bC[bj - 16] - 1) * 100, s * (bC[bj] / bC[bj - 96] - 1) * 100,
             (batr / bC[bj] * 100) if batr else 0.0, s * (dn_w - up_w) / a, (H[i] - L[i]) / a, math.log1p(since), ret(672),
             p30 if side > 0 else 1 - p30]
        dp = (px - dlo) / (dhi - dlo) if dhi > dlo else 0.5
        f += [s * (px - de20) / dat if dat and dat > 0 else 0.0, s * (px - de50) / dat if dat and dat > 0 else 0.0, s * (dr14 - 50),
              dp if side > 0 else 1 - dp, s * (bdC[-1] / be50 - 1) * 100 if be50 else 0.0]
        out.append({"side": side, "st": si, "lv": lv, "atr": a, "f": f})
    return out


def dlm_model():
    with _dlm_lock:
        m = _DLM["model"]
    if m and m.get("ver") == DLM_MODEL_VER:
        return m
    m = None
    try:
        if os.path.exists(DLM_MODEL_FILE):
            with open(DLM_MODEL_FILE) as f:
                m = json.load(f)
            if m.get("ver") != DLM_MODEL_VER or m.get("feats") != DLM_FNAMES4:
                m = None
    except Exception as e:
        log_error(f"dlm model read: {e}")
        m = None
    if not m:
        try:
            r = requests.get(DLM_MODEL_URL.format(ref="main"), params={"nocache": int(time.time())}, timeout=120)
            r.raise_for_status()
            m = r.json()
            if m.get("ver") != DLM_MODEL_VER or not m.get("streams"):
                raise RuntimeError(f"версия модели {m.get('ver')} вместо {DLM_MODEL_VER}")
            if m.get("feats") != DLM_FNAMES4:
                raise RuntimeError("признаки модели не совпадают с кодом бота — нужно обновить бота")
            tmp = DLM_MODEL_FILE + ".new"
            with open(tmp, "w") as f:
                json.dump(m, f, separators=(",", ":"))
            os.replace(tmp, DLM_MODEL_FILE)
        except Exception as e:
            with _dlm_lock:
                _DLM["err"] = f"модель не скачалась: {e}"
            log_error(f"dlm model download: {e}")
            return None
    with _dlm_lock:
        _DLM.update({"model": m, "err": None})
    return m


def dlm_load():
    try:
        if os.path.exists(DLM_STATE_FILE):
            with open(DLM_STATE_FILE) as f:
                d = json.load(f)
            with _dlm_lock:
                for k in ("orders", "trades", "scan", "bar_done"):
                    if d.get(k) is not None:
                        _DLM[k] = d[k]
    except Exception as e:
        log_error(f"dlm state load: {e}")
    _DLM["loaded"] = True


def dlm_save():
    try:
        with _dlm_lock:
            data = json.dumps({"orders": _DLM["orders"][-400:], "trades": _DLM["trades"][-3000:], "scan": _DLM["scan"], "bar_done": _DLM.get("bar_done")})
        tmp = DLM_STATE_FILE + ".tmp"
        with open(tmp, "w") as f:
            f.write(data)
        os.replace(tmp, DLM_STATE_FILE)
    except Exception as e:
        log_error(f"dlm state save: {e}")


def _dlm_closed(sym, tf, sec, n, now):
    if DLM_BINANCE:   # v0.99.684 — trading on Binance: Binance's bars only (a coin Binance has no fresh bar of is not scanned)
        return bn_closed(sym, tf, sec, n, now) or []
    return _zm_closed(sym, tf, sec, n, now)   # v0.99.681 — Binance first


DLM_TF = {900: "15m", 7200: "2h", 14400: "4h"}


def _dlm_bars(sym, start, now, bs=900):
    """v0.99.684 — the closed bars from `start` for the virtual fills / exits: Binance's when trading there. bs = the
    chart's bar (v0.99.689: 4h / 2h for the streams' orders, 15m for the 15m module's last ones); 2h from Binance
    (Gate has no 2h — its 1h grouped when Binance does not answer)"""
    tf = DLM_TF.get(bs, "4h")
    if DLM_BINANCE or tf == "2h":
        b = bn_closed(sym, tf, bs, 400, now)
        if b:
            return [c for c in b if c["time"] >= start]
    if tf == "2h":
        return [c for c in bt_gate_bars(sym, "2h", start, int(now)) if not c.get("forming") and c["time"] + bs <= now]
    return [c for c in (get_candles_range(sym, tf, start, int(now)) or []) if c["time"] >= start and c["time"] + bs <= now]


def _dlm_hit(o, now):
    """v0.99.691 — the touch of a virtual order, found on the 1h candles (not waiting for its 4h / 2h bar to close):
    (the touch's 1h bar, the price's way to the level from that bar's open in ATR, the fill bar = the order chart's bar
    holding the touch, the fill price = the level or that bar's open if it opened through it) or None. The first of a
    coin & side to fill, and the side's 20, go by the touch and, in the same hour, the nearer level (the research's
    order, dlm4_export7.py). The replay found: by the 4h / 2h bar's open a 4h order won over a 2h one the price had
    reached hours earlier; waiting for the bars to close, a 2h order won over a 4h one reached in the same hour."""
    bs = int(o.get("bs") or 900)
    if DLM_BINANCE:
        b = bn_closed(o["symbol"], "1h", 3600, 200, now) or []
    else:
        b = [c for c in (get_candles_range(o["symbol"], "1h", int(o["t0"]), int(now)) or []) if c["time"] + 3600 <= now]
    b = [c for c in b if o["t0"] <= c["time"] < o["until"]]
    if not b:
        return None
    s_, lv = o["side"], o["lv"]
    for c in b:
        if (c["low"] <= lv) if s_ > 0 else (c["high"] >= lv):
            fb = c["time"] // bs * bs
            fo = next((x["open"] for x in b if x["time"] == fb), c["open"])
            return c["time"], s_ * (c["open"] - lv) / (o["atr"] or 1e-12), fb, (min(lv, fo) if s_ > 0 else max(lv, fo))
    return False


def _dlm_streams(m=None):
    """v0.99.689 — the model's limit streams: {"name", "tf", "bar_sec", "anchor", "depth_atr", "fam", "alive_bars",
    "take_atr", "stop_atr", "hold_bars", "models", "thr"}"""
    return (m or _DLM.get("model") or {}).get("streams") or []


def _dlm_stream(name):
    return next((x for x in _dlm_streams() if x.get("name") == name), None)


def _dlm_closed_gate(sym, tf, sec, n, now):
    cs = get_candles_range(sym, tf, int(now) - (n + 2) * sec, int(now)) or []
    return [c for c in cs if c["time"] + sec <= now][-n:]


def dlm_coins():
    """the coins ⚡ scans: the 127 (+ 83 more with DLM_MORE_COINS); on Binance all of them (its own bars), on Gate the ones
    Gate trades among its top 300"""
    coins = tuple(c for c in (RESEARCH_COINS_211 if DLM_MORE_COINS else RESEARCH_COINS_127) if c != "USDC_USDT")
    return list(coins) if DLM_BINANCE else _research_syms(coins)


def dlm_risk(equity=None):
    """the risk % of a new ⚡ trade: the module's field (empty = 4%), at most 10% (v0.99.687: up to 20 positions at once)"""
    return min(MODULE_RISK_PCT.get("dlm") or DLM_RISK_DEFAULT, 10.0)


def dlm_scan(t_bar, st):
    """at the close of a bar of the stream's chart (4h / 2h) that started at t_bar - its bar: the coins' limits of the
    stream scored by its models; the ones above its threshold become orders alive for its next 4 bars — one per coin &
    side a bar; another stream's order of the coin & side may stand too (the first to fill is the trade, the other one
    goes — dlm4_export4.py's pool). v0.99.691: an order is made even while a trade of the coin & side is open — as in
    the research, the coin being busy counts when the price reaches the order (an order of a trade that closed by then
    trades; the audit's replay of this code over 2026 found 5% of the backtest's trades missing for that)"""
    m = dlm_model()
    if not m:
        return
    rule = m.get("rule") or {}
    bs, tf = int(st["bar_sec"]), st["tf"]
    nb = 3000 if bs >= 14400 else 4500   # ≥ ~375 days: the daily EMA50 settled (the research's from the coin's whole history)
    bb = _dlm_closed("BTC_USDT", tf, bs, nb, t_bar)
    thr = float(st["thr"])
    src = {"binance": 0, "gate": 0}
    new, coins, cands, best = [], 0, 0, []
    for sym in dlm_coins():
        heartbeat("dlm_loop")
        try:
            bars = _dlm_closed(sym, tf, bs, nb, t_bar)
            if not bars or bars[-1]["time"] != t_bar - bs:
                continue   # the bar just closed is missing
            src["binance" if bars[-1].get("bn") else "gate"] += 1
            cs = dlm_candidates4(bars, bb, streams=[st], dmin=float(rule.get("depth_min", 0.3)), dmax=float(rule.get("depth_max", 6.0)),
                                 min_bars=int(rule.get("min_bars", 2000)))
            coins += 1
            for c in cs:
                cands += 1
                sc = sum(zm_tree_pred(t_, c["f"]) for t_ in st["models"]) / len(st["models"])
                best.append((sc / thr if thr > 0 else 0, sym, c["side"]))
                if sc < thr:
                    continue
                s, lv, a = c["side"], c["lv"], c["atr"]
                if _sl_too_tight(lv, float(st.get("stop_atr", 2.0)) * a):
                    continue
                new.append({"id": f"dlm_{sym}_{s}_{t_bar}" + ("" if st["name"] == "wick4h" else "_" + st["name"]), "symbol": sym, "side": s, "lv": lv,
                            "atr": a, "score": round(sc, 4), "bs": bs, "st": st["name"], "t0": t_bar, "until": t_bar + int(st.get("alive_bars", 4)) * bs,
                            "px": bars[-1]["close"], "status": "OPEN", "real": None})
        except Exception as e:
            log_error(f"dlm scan {sym} {tf}: {e}")
    new.sort(key=lambda o: -o["score"])
    best.sort(key=lambda x: -x[0])
    near = [{"symbol": s_, "side": sd, "pct": round(100 * x), "tf": tf} for x, s_, sd in best[:8]]
    with _dlm_lock:
        _DLM["orders"].extend(new)
        sc_all = dict(_DLM.get("scan") or {})
        sc_all.update({"t": int(time.time()), "bar": t_bar, "coins": coins, "src": src})
        sc_all.setdefault("by", {})[st["name"]] = {"t": int(time.time()), "bar": t_bar, "coins": coins, "cands": cands, "orders": len(new), "near": near}
        sc_all["near"] = sorted([x for v in sc_all["by"].values() for x in v.get("near") or []], key=lambda x: -x["pct"])[:8]
        _DLM["scan"] = sc_all
    if new and TELEGRAM_ALERTS_DLM:
        send_telegram(f"⚡ лимитки {tf}: " + ", ".join(f"{o['symbol'].replace('_USDT', '')} {'↑' if o['side'] > 0 else '↓'} {o['lv']:.6g}" for o in new[:10]), category="dlm")
    dlm_save()   # v0.99.691 — the real limits: _dlm_arm (dlm_real_tick) places them as the price comes


def _dlm_open_trade(o, t_fill_bar, fill, real=None):
    """an order filled: the trade (stop / take from the fill and the order bar's ATR)"""
    st = _dlm_stream(o.get("st") or "wick4h") or {}   # v0.99.689 — the stream's rule (4h orders before it: the wick stream)
    s = o["side"]; a = o["atr"]; bs = int(o.get("bs") or 900)
    hold = int(st.get("hold_bars", 32)) if bs != 900 else 16   # v0.99.687 — the 15m module's last orders keep its 16 bars
    risk = float(st.get("stop_atr", 2.0)) * a
    tp1 = fill + s * (float(st.get("take_atr", 1.0)) if bs != 900 else 0.5) * a
    far = st.get("far_take_atr") if bs != 900 else None   # v0.99.690 — the take at 2 ATR; back to 1 ATR after a 0.4 ATR dip
    tr = {"id": o["id"], "symbol": o["symbol"], "side": s, "direction": "LONG" if s > 0 else "SHORT", "entry": fill, "lv": o["lv"], "atr": a,
          "sl": fill - s * risk, "tp": fill + s * float(far) * a if far else tp1, "score": o["score"], "t0": o["t0"],
          "fbar": t_fill_bar, "t_in": int(time.time()), "until": t_fill_bar + hold * bs, "bs": bs, "hold": hold, "st": o.get("st") or ("wick4h" if bs != 900 else None),
          "status": "OPEN", "result": None, "r": None, "exit": None, "t_out": None, "real": real, "rv": DLM_MODEL_VER if bs != 900 else 1}
    if far:
        tr.update({"tp1": tp1, "tp2": tr["tp"], "pull": float(st.get("pull_atr", 0.4)), "take": "far", "mae": 0.0})
    with _dlm_lock:
        if any(t["id"] == tr["id"] for t in _DLM["trades"]):
            return None
        _DLM["trades"].append(tr)
        for x in _DLM["orders"]:   # the other orders of this coin & side: blocked while the trade is open (a real one: the
            if x["symbol"] == o["symbol"] and x["side"] == s and x["status"] == "OPEN" and x is not o and not (x.get("real") or {}).get("id"):
                x["status"] = "SKIP"   # exchange tick cancels it — a position is on the coin now)
        o["status"] = "FILLED"
    return tr


def _dlm_r(t, ex, k, kind):
    risk = abs(t["entry"] - t["sl"]) or 1e-12
    fee = (DLM_FEE_IN + (DLM_FEE_TAKE if kind == "WIN" else DLM_FEE_OUT) + DLM_FUND * (k + 1) * int(t.get("bs") or 900) / 86400) * t["entry"]
    return round((t["side"] * (ex - t["entry"]) - fee) / risk, 4)


def dlm_settle(now):
    """after each bar: the virtual orders filled by it (the candle reached the limit), the expired ones out, and the
    virtual trades walked on the candles of their chart — the stop first, no take in the fill bar, out after `hold` bars"""
    with _dlm_lock:
        orders = [o for o in _DLM["orders"] if o["status"] == "OPEN" and not (o.get("real") or {}).get("id")]
    hits = []
    for o in orders:
        try:
            if int(o.get("bs") or 900) > 3600:
                h = _dlm_hit(o, now)   # v0.99.691 — on the 1h candles
                if h is not None:   # None: no 1h candles — the chart's bars below
                    hits.append((h[0], h[1], -o.get("score", 0), o, {"time": h[2], "fill": h[3]}) if h else (float("inf"), 0.0, -o.get("score", 0), o, None))
                    continue
            cs = [c for c in _dlm_bars(o["symbol"], o["t0"], now, int(o.get("bs") or 900)) if c["time"] < o["until"]]
            hit = next((c for c in cs if ((c["low"] <= o["lv"]) if o["side"] > 0 else (c["high"] >= o["lv"]))), None)
            hits.append((hit["time"] if hit else float("inf"), 0.0, -o.get("score", 0), o,
                         hit and {"time": hit["time"], "fill": min(o["lv"], hit["open"]) if o["side"] > 0 else max(o["lv"], hit["open"])}))
        except Exception as e:
            log_error(f"dlm order {o['symbol']}: {e}")
    hits.sort(key=lambda x: (x[0], x[1], x[2]))   # the first of a coin & side to fill is the trade (v0.99.691: the touch's 1h bar, then the nearer level)
    for _, _, _, o, hit in hits:
        try:
            if hit:
                with _dlm_lock:
                    taken = any(t["status"] == "OPEN" and t["symbol"] == o["symbol"] and t["side"] == o["side"] for t in _DLM["trades"])
                    # v0.99.691 — at most side_cap (20) open a side, as the research pool (the replay: without it the
                    # virtual trades were twice the backtest's in mid-2026, 451 of the extra ones beyond 20 a side)
                    taken = taken or sum(1 for t in _DLM["trades"] if t["status"] == "OPEN" and t["side"] == o["side"]) >= int((_DLM.get("model") or {}).get("side_cap") or 20)
                if taken:
                    o["status"] = "SKIP"
                else:
                    _dlm_open_trade(o, hit["time"], hit["fill"])
            elif now >= o["until"]:
                o["status"] = "EXPIRED"
        except Exception as e:
            log_error(f"dlm order {o['symbol']}: {e}")
    with _dlm_lock:
        opn = [t for t in _DLM["trades"] if t["status"] == "OPEN" and not t.get("real")]
    for t in opn:
        try:
            bs = int(t.get("bs") or 900)
            hold = int(t.get("hold") or 16)
            cs = _dlm_bars(t["symbol"], t["fbar"], now, bs)
            res = None
            s, sl, tp = t["side"], t["sl"], t.get("tp1") or t["tp"]
            far, pull = t.get("tp2"), float(t.get("pull") or 0) * t["atr"]
            mae, ext = 0.0, False   # v0.99.690 — the take 2 ATR stays if the price reached 1 ATR without a dip of `pull` first
            for k, c in enumerate(cs[:hold]):
                adv = (t["entry"] - c["low"]) if s > 0 else (c["high"] - t["entry"])
                if (c["low"] <= sl) if s > 0 else (c["high"] >= sl):
                    gap = k > 0 and ((c["open"] <= sl) if s > 0 else (c["open"] >= sl))
                    res = ("LOSS", c["open"] if gap else sl, k)
                    break
                if ext:
                    if (c["high"] >= far) if s > 0 else (c["low"] <= far):
                        res = ("WIN", far, k)
                        break
                elif k > 0 and ((c["high"] >= tp) if s > 0 else (c["low"] <= tp)):
                    if far and max(mae, adv) < pull:   # the dip of the touch bar counts (its order inside the bar unknown)
                        ext = True
                    else:
                        res = ("WIN", tp, k)
                        break
                mae = max(mae, adv)
            if far:
                with _dlm_lock:
                    t["take"] = "locked" if ext else ("near" if mae >= pull else "far")
                    t["tp"] = res[1] if res and res[0] == "WIN" else (far if t["take"] != "near" else tp)
            if not res and len(cs) >= hold:
                res = ("TIME_EXIT", cs[hold - 1]["close"], hold - 1)
            if res:
                kind, ex, k = res
                with _dlm_lock:
                    t.update({"status": "CLOSED", "result": kind, "exit": ex, "t_out": int(cs[k]["time"] + bs), "r": _dlm_r(t, ex, k, kind)})
        except Exception as e:
            log_error(f"dlm trade {t.get('symbol')}: {e}")
    with _dlm_lock:   # the order book of the module: only the live ones and a short history
        _DLM["orders"] = [o for o in _DLM["orders"] if o["status"] == "OPEN" or now - o["t0"] < max(6 * 3600, 6 * int(o.get("bs") or 900))]
    dlm_save()


def _dlm_take_note(t):
    """the Telegram note on the take: 2 ATR, back to 1 ATR (its price) if the price first goes `pull` ATR against"""
    return f" (если цена сначала уйдёт против на {t.get('pull', 0.4):g} ATR — тейк {t['tp1']:.6g})" if t.get("tp2") and t.get("take") == "far" else ""


def _dlm_take_watch(t, mark=None, now=None):
    """v0.99.690 — a real trade's take starts at 2 ATR (tp2); if the price goes `pull` ATR against the trade before it has
    reached 1 ATR (tp1), the take comes back to 1 ATR -> True (the caller moves the order); reached 1 ATR first -> the take
    stays at 2 ATR for good. Watched on Binance 1m candles (every ~20 s, the dips between polls too) and the mark price; a
    minute with both counts as the dip (as in the research: the touch bar's dip counts)."""
    if not t.get("tp2") or t.get("take") != "far":
        return False
    now = now or time.time()
    s, e, a = t["side"], t["entry"], t["atr"]
    pull, tp1 = float(t.get("pull") or 0.4) * a, t["tp1"]
    pts = []
    m0 = int(t["t_in"]) // 60 * 60   # the fill's minute: its dip counts (a limit fills on the way down), its high may be from before
    if now - float(t.get("mw") or 0) >= 20:
        t["mw"] = now
        try:
            pts = [(c["low"], c["high"], c["time"] > m0) for c in binance_klines(t["symbol"], "1m", max(int(t.get("mw_from") or m0), m0), int(now))]
            if pts:
                t["mw_from"] = int(now) - 120   # the last two minutes again next time (the forming one changes)
        except Exception as e_:
            log_error(f"dlm take watch {t['symbol']}: {e_}")
    if mark:
        pts.append((mark, mark, True))
    for lo, hi, fav_ok in pts:   # the fill minute: its move against counts, its move our way may be from before the fill
        adv = (e - lo) if s > 0 else (hi - e)
        if adv >= pull:
            t["take"] = "near"; t["mae"] = round(max(float(t.get("mae") or 0), adv / a), 3)
            return True
        if fav_ok and ((hi >= tp1) if s > 0 else (lo <= tp1)):
            t["take"] = "locked"
            return False
        t["mae"] = round(max(float(t.get("mae") or 0), adv / a), 3)
    return False


# ---- the exchange side: a real GTC limit, then the stop (trigger) and the take (a reduce-only limit = maker) ----
DLM_ARM_ATR = float(os.environ.get("VP_DLM_ARM_ATR", "0.3"))   # v0.99.691 — a real limit goes on the exchange when the price is this close
DLM_DISARM_ATR = 1.0   # ... and comes off again (back to waiting) when the price goes this far from it


def _dlm_prices(syms):
    """{gate symbol: last price} of these coins — one request (Binance's tickers when trading there, else Gate's)"""
    out = {}
    if DLM_BINANCE:
        p = bnf_prices() or {}
        for sym in syms:
            mp = bn_map(sym)
            if mp and p.get(mp[0]):
                out[sym] = p[mp[0]] / mp[1]
        return out
    for x in get_tickers() or []:
        if x.get("contract") in syms and x.get("last"):
            out[x["contract"]] = float(x["last"])
    return out


def _dlm_cancel_back(o):
    """an armed real limit off the exchange, the order back to waiting -> True; filled meanwhile -> False (the tick takes it)"""
    r = o["real"]
    if r.get("ex") == "binance":
        if not bnf_cancel(r["bsym"], "order", r["id"]):
            return False
        try:
            if float(bnf_order(r["bsym"], r["id"]).get("executedQty") or 0) > 0:
                return False
        except BinanceError:
            return False
    else:
        if not _dlm_cancel_order(r["id"]):
            return False
        try:
            x = gate_signed_request("GET", f"/futures/usdt/orders/{r['id']}")
            if abs(int(float(x.get("size") or 0))) - abs(int(float(x.get("left") or 0))) > 0:
                return False
        except Exception:
            return False
    o["real"] = None
    return True


def _dlm_arm(now):
    """v0.99.691 — the real limits follow the price instead of standing from the scan (the audit: with the limit of 26
    limits + positions the real account took 188 of the backtest's 406 trades in Jun–Oct 2026; deciding when the price
    comes — 403): a waiting order goes on the exchange once the price is within DLM_ARM_ATR of it and there is room
    (dlm_real_place: no position / other limit of the coin, positions + armed limits < 20, < 20 a side); an armed one far
    away again comes off; the price through a waiting order's level: placed now if there is room (it fills at once, at
    the price or better), else no trade — the coin was busy / the side full when the price came, as in the research."""
    with _dlm_lock:
        wait = [o for o in _DLM["orders"] if o["status"] == "OPEN" and o.get("real") is None and int(o.get("bs") or 900) != 900 and now < o["until"]]
        armed = [o for o in _DLM["orders"] if o["status"] == "OPEN" and (o.get("real") or {}).get("id") and int(o.get("bs") or 900) != 900]
    if not wait and not armed:
        return
    px = _dlm_prices({o["symbol"] for o in wait + armed})
    dist = lambda o: o["side"] * (px[o["symbol"]] - o["lv"]) / (o["atr"] or 1e-12)   # > 0: not reached yet
    for o in armed:
        if o["symbol"] in px and dist(o) > DLM_DISARM_ATR and now < o["until"]:
            try:
                _dlm_cancel_back(o)
            except Exception as e:
                log_error(f"dlm disarm {o['symbol']}: {e}")
    for o in sorted((o for o in wait if o["symbol"] in px), key=dist):
        d = dist(o)
        if d > DLM_ARM_ATR:
            break
        if d < -DLM_ARM_ATR:   # far through the level (the bot was down / no prices): a fill now would be another trade
            o["real"] = {"status": "SKIPPED", "detail": "цена ушла за лимитку без бота (нет цен / бот не работал)"}
            continue
        try:
            dlm_real_place(o)
        except Exception as e:
            log_error(f"dlm place {o['symbol']}: {e}")
            o["real"] = {"status": "SKIPPED", "detail": str(e)[:160]}
            continue
        if o.get("real") is None and d <= 0:
            o["real"] = {"status": "SKIPPED", "detail": "цена дошла до лимитки, когда места не было (монета занята / 20 сделок)"}


def dlm_real_place(o):
    """the real limit of a ⚡ order, or nothing (no room: the order keeps waiting — _dlm_arm tries again)"""
    if AUTOTRADE_DRY_RUN:
        o["real"] = {"status": "DRY_RUN"}
        return
    sym, s = o["symbol"], o["side"]
    direction = "LONG" if s > 0 else "SHORT"
    with _dlm_lock:
        live = [x for x in _DLM["orders"] if (x.get("real") or {}).get("id") and x["status"] == "OPEN"]
        held = [t for t in _DLM["trades"] if t.get("real") and t["status"] == "OPEN"]
        mine = any(t["symbol"] == sym for t in held)
    # v0.99.682 — the cap counts the open positions too; v0.99.687: at most DLM_MAX_POS positions (the research's 20 at
    # 3–4%), limits + positions at most DLM_MAX_LIVE_ORDERS (a limit holds its margin on the exchange)
    side_cap = int((_DLM.get("model") or {}).get("side_cap") or 20)   # v0.99.691 — the room counts the armed limits as positions:
    if (mine or any(x["symbol"] == sym for x in live)   # one position or limit a coin (Binance one-way), positions + limits
            or len(held) + len(live) >= DLM_MAX_POS or len(live) + len(held) >= DLM_MAX_LIVE_ORDERS   # < 20, < 20 a side
            or sum(1 for t in held if t["side"] == s) + sum(1 for x in live if x["side"] == s) >= side_cap):
        return
    if DLM_BINANCE:   # v0.99.684
        return dlm_bn_place(o)
    with using_account("dlm"):
        pos = [p for p in (get_open_positions() or []) if p.get("contract") == sym]
        if pos:
            o["real"] = {"status": "SKIPPED", "detail": "по монете уже есть позиция"}
            return
        spec = get_contract_spec(sym)
        cap = spec.get("leverage_max") or 125
        tick = spec.get("order_price_round")
        with state_lock:
            mmr = (STATE.get("scalp_mmr_map") or {}).get(sym, SCALP_DEFAULT_MMR_PCT)
        tiers = get_risk_limit_tiers_for_symbol(sym)
        equity = get_futures_total_equity()
        risk = dlm_risk(equity)
        rule = ((_DLM.get("model") or {}).get("rule") or {})
        sl = o["lv"] - s * float((_dlm_stream(o.get("st") or "wick4h") or rule).get("stop_atr", 2.0)) * o["atr"]
        margin, lev, skip = compute_risk_based_position(direction, o["lv"], sl, cap, mmr, equity, risk_pct=risk, symbol=sym,
                                                        tiers_by_symbol={sym: tiers} if tiers else None)
        contracts = 0
        if not skip and margin:   # the margin within the free balance (many positions at once), the risk scaled down
            free = get_futures_wallet_balance()
            if free and margin > free * 0.9:
                risk = round(risk * free * 0.9 / margin, 2)
                margin, lev, skip = compute_risk_based_position(direction, o["lv"], sl, cap, mmr, equity, risk_pct=risk, symbol=sym,
                                                                tiers_by_symbol={sym: tiers} if tiers else None)
        if not skip:
            contracts, _n, _m, skip = compute_contracts_from_margin(sym, o["lv"], margin, lev)
        if skip or not contracts:
            o["real"] = {"status": "SKIPPED", "detail": str(skip or "0 контрактов")[:160]}
            return
        set_leverage(sym, lev)
        px = round_to_tick_directional(o["lv"], tick, round_up=(direction == "SHORT"))
        body = {"contract": sym, "size": int(contracts) if s > 0 else -int(contracts), "price": format_price_str(px, tick),
                "tif": "gtc", "text": "t-vpdlm"}
        r = gate_signed_request("POST", "/futures/usdt/orders", body=body)
        o["real"] = {"status": "LIMIT", "id": str(r.get("id")), "size": int(contracts), "price": px, "lev": lev, "tick": tick, "risk": risk}


def _dlm_cancel_order(oid):
    try:
        gate_signed_request("DELETE", f"/futures/usdt/orders/{oid}")
        return True
    except Exception as e:
        msg = str(e)
        if "ORDER_NOT_FOUND" in msg or "FINISHED" in msg.upper() or "not found" in msg.lower():
            return True
        log_error(f"dlm cancel {oid}: {e}")
        return False


def _dlm_place_exits(t):
    """the stop as a trigger, the take as a reduce-only limit (maker); a take the exchange refuses as a limit -> a trigger"""
    r = t["real"]; sym, d, s = t["symbol"], t["direction"], t["side"]
    tick = r.get("tick")
    if not r.get("sl_id"):
        o = place_close_trigger_order(sym, d, round_to_tick_directional(t["sl"], tick, round_up=(s < 0)), 2 if s > 0 else 1, tick)
        r["sl_id"] = str((o or {}).get("id") or "") or None
    if not r.get("tp_id"):
        try:
            o = gate_signed_request("POST", "/futures/usdt/orders", body={
                "contract": sym, "size": -s * int(r["filled"]), "price": format_price_str(round_to_tick_directional(t["tp"], tick, round_up=(s > 0)), tick),
                "tif": "gtc", "reduce_only": True, "text": "t-vpdlm-tp"})
            r["tp_id"], r["tp_kind"] = str(o.get("id")), "limit"
        except Exception as e:
            log_error(f"dlm take limit {sym}: {e} — a trigger instead")
            o = place_close_trigger_order(sym, d, round_to_tick_directional(t["tp"], tick, round_up=(s > 0)), 1 if s > 0 else 2, tick)
            r["tp_id"], r["tp_kind"] = str((o or {}).get("id") or "") or None, "trigger"


# ---- v0.99.684 — the same on Binance: the limit, then the stop (STOP_MARKET, the whole position) and the take ----
def dlm_bn_place(o):
    sym, s = o["symbol"], o["side"]
    direction = "LONG" if s > 0 else "SHORT"
    mp = bn_map(sym)
    if not mp:
        o["real"] = {"status": "SKIPPED", "ex": "binance", "detail": "монеты нет на Binance"}
        return
    bsym, scl = mp
    info = bnf_symbols().get(bsym)
    if not info or not info["ok"]:
        o["real"] = {"status": "SKIPPED", "ex": "binance", "detail": f"{bsym} сейчас не торгуется на Binance"}
        return
    if bnf_positions().get(bsym):
        o["real"] = {"status": "SKIPPED", "ex": "binance", "detail": "по монете уже есть позиция"}
        return
    dual = bnf_dual()
    rule = ((_DLM.get("model") or {}).get("rule") or {})
    lv = o["lv"] * scl
    sl = (o["lv"] - s * float((_dlm_stream(o.get("st") or "wick4h") or rule).get("stop_atr", 2.0)) * o["atr"]) * scl
    tiers = bnf_tiers(bsym)
    cap = max((t_[2] for t_ in tiers), default=20)
    mmr = tiers[0][1] if tiers else SCALP_DEFAULT_MMR_PCT
    acct = bnf_account()
    risk = dlm_risk(acct["equity"])
    tb = {bsym: tiers} if tiers else None
    margin, lev, skip = compute_risk_based_position(direction, lv, sl, cap, mmr, acct["equity"], risk_pct=risk, symbol=bsym, tiers_by_symbol=tb)
    if not skip and margin > acct["free"] * 0.9:   # the free margin checked: the risk scaled down to what the account carries
        if acct["free"] <= 1:
            skip = f"нет свободной маржи (свободно {acct['free']:.2f}$)"
        else:
            risk = round(risk * acct["free"] * 0.9 / margin, 2)
            margin, lev, skip = compute_risk_based_position(direction, lv, sl, cap, mmr, acct["equity"], risk_pct=risk, symbol=bsym, tiers_by_symbol=tb)
    if skip:
        o["real"] = {"status": "SKIPPED", "ex": "binance", "detail": str(skip)[:160]}
        return
    qty = bn_fmt(margin * lev / lv, info["step"])
    q = float(qty)
    if q < info["min_qty"] or q * lv < info["min_notional"]:
        o["real"] = {"status": "SKIPPED", "ex": "binance", "detail": f"позиция {q * lv:.2f}$ меньше минимума Binance ({info['min_notional']:g}$)"}
        return
    try:
        bnf_req("POST", "/fapi/v1/marginType", {"symbol": bsym, "marginType": "ISOLATED"})
    except BinanceError as e:
        if e.code != -4046:   # -4046 = already isolated
            log_error(f"binance isolated {bsym}: {e}")
    bnf_req("POST", "/fapi/v1/leverage", {"symbol": bsym, "leverage": int(lev)})
    px = bn_fmt(lv, info["tick"], up=(s < 0))
    r = bnf_req("POST", "/fapi/v1/order", dict(_bnf_side_params(s, False, dual), symbol=bsym, type="LIMIT", timeInForce="GTC", quantity=qty,
                                               price=px, newClientOrderId=f"vpdlm{int(time.time() * 1000)}"))
    o["real"] = {"status": "LIMIT", "ex": "binance", "id": str(r.get("orderId")), "bsym": bsym, "scl": scl, "qty": q, "price": float(px) / scl,
                 "lev": int(lev), "risk": risk, "dual": dual, "tick": info["tick"], "step": info["step"]}


def _dlm_bn_exits(t):
    r = t["real"]; s = t["side"]; bsym, scl = r["bsym"], r["scl"]
    if not r.get("sl_id"):
        r["sl_kind"], r["sl_id"] = bnf_place_cond(bsym, s, "STOP_MARKET", bn_fmt(t["sl"] * scl, r["tick"], up=(s < 0)), r.get("dual"))
    if not r.get("tp_id"):
        tp = bn_fmt(t["tp"] * scl, r["tick"], up=(s > 0))
        try:
            x = bnf_req("POST", "/fapi/v1/order", dict(_bnf_side_params(s, True, r.get("dual")), symbol=bsym, type="LIMIT", timeInForce="GTC",
                                                       quantity=bn_fmt(r["filled"], r["step"]), price=tp))
            r["tp_kind"], r["tp_id"] = "limit", str(x.get("orderId"))
        except BinanceError as e:
            log_error(f"binance take limit {bsym}: {e} — a trigger instead")
            r["tp_kind"], r["tp_id"] = bnf_place_cond(bsym, s, "TAKE_PROFIT_MARKET", tp, r.get("dual"))


def _dlm_bn_cancel_exits(t, keep_tp_limit=False):
    r = t["real"]
    if r.get("sl_id"):
        bnf_cancel(r["bsym"], r.get("sl_kind") or "algo", r["sl_id"])
    if r.get("tp_id") and not (keep_tp_limit and r.get("tp_kind") == "limit"):
        bnf_cancel(r["bsym"], "order" if r.get("tp_kind") == "limit" else r.get("tp_kind"), r["tp_id"])


def dlm_bn_tick(orders, trades):
    """dlm_real_tick() for the Binance orders and trades -> changed"""
    now = time.time()
    changed = False
    try:
        pos = bnf_positions()
    except Exception as e:
        log_error(f"dlm binance positions: {e}")
        return False
    for o in orders:
        r = o["real"]
        try:
            x = bnf_order(r["bsym"], r["id"])
        except BinanceError as e:
            log_error(f"dlm binance order {o['symbol']}: {e}")
            continue
        filled = float(x.get("executedQty") or 0)
        done = x.get("status") in ("FILLED", "CANCELED", "EXPIRED", "REJECTED", "EXPIRED_IN_MATCH")
        foreign = not filled and pos.get(r["bsym"])
        if not done and (now >= o["until"] or foreign or filled):
            if not bnf_cancel(r["bsym"], "order", r["id"]):   # the rest of a partly filled limit goes too
                continue
            try:
                x = bnf_order(r["bsym"], r["id"])
                filled = float(x.get("executedQty") or 0)
            except BinanceError:
                pass
            done = True
        if not done:
            continue
        changed = True
        if filled > 0:
            fill = (float(x.get("avgPrice") or 0) / r["scl"]) or r["price"]
            t = _dlm_open_trade(o, int(now // int(o.get("bs") or 900) * int(o.get("bs") or 900)), fill, real=dict({k: r.get(k) for k in ("ex", "bsym", "scl", "tick", "step", "dual", "risk", "lev")},
                                                                                        filled=filled, order=r["id"]))
            if t:
                try:
                    _dlm_bn_exits(t)
                except Exception as e:
                    log_error(f"dlm binance exits {t['symbol']}: {e}")
                if TELEGRAM_ALERTS_DLM:
                    send_telegram(f"⚡ {t['symbol'].replace('_USDT', '')} {t['direction']} · лимитка {DLM_TF.get(t.get('bs'), '4h')} исполнилась на Binance @ {fill:.6g}\n"
                                  f"тейк {t['tp']:.6g}{_dlm_take_note(t)} · стоп {t['sl']:.6g} · до {time.strftime('%H:%M', time.localtime(t['until']))}", category="dlm")
        else:
            o["status"] = "EXPIRED" if now >= o["until"] else "CANCELLED"
    for t in trades:
        r = t["real"]; bsym, s = r["bsym"], t["side"]
        p = next((x for x in pos.get(bsym) or [] if (x["amt"] > 0) == (s > 0)), None)
        if p:
            r["seen"] = True
            if not r.get("sl_id") or not r.get("tp_id"):
                try:
                    _dlm_bn_exits(t); changed = True
                except Exception as e:
                    log_error(f"dlm binance exits {bsym}: {e}")
            if r.get("tp_id") and _dlm_take_watch(t, (p["mark"] / r["scl"]) if p.get("mark") else None, now):   # v0.99.690 — the take back to 1 ATR
                changed = True
                if bnf_cancel(bsym, "order" if r.get("tp_kind") == "limit" else r.get("tp_kind"), r["tp_id"]):
                    done_ = 0.0
                    if r.get("tp_kind") == "limit":
                        try:
                            done_ = float(bnf_order(bsym, r["tp_id"]).get("executedQty") or 0)
                        except BinanceError:
                            pass
                    if done_ > 0:   # the far take had filled after all: it stays the exit
                        t["take"] = "locked"
                    else:
                        with _dlm_lock:
                            t["tp"] = t["tp1"]; r["tp_id"] = None
                        try:
                            _dlm_bn_exits(t)
                        except Exception as e:
                            log_error(f"dlm binance take 1 ATR {bsym}: {e}")
                else:
                    t["take"] = "far"   # not cancelled: again next tick
            nostop = not r.get("sl_id") and now - t["t_in"] > 30   # Binance refused the stop for 30 s: no position left without one
            if nostop:
                send_telegram(f"⚠️ ⚡ {bsym}: Binance не принял стоп — позиция закрыта по рынку", category="dlm")
            if now >= t["until"] or nostop:   # the time exit: the take / stop off, the rest at the market
                _dlm_bn_cancel_exits(t)
                try:
                    res = bnf_req("POST", "/fapi/v1/order", dict(_bnf_side_params(s, True, r.get("dual")), symbol=bsym, type="MARKET",
                                                                 quantity=bn_fmt(abs(p["amt"]), r["step"])))
                    r["close"] = str(res.get("orderId"))
                except BinanceError as e:
                    log_error(f"dlm binance time exit {bsym}: {e}")
                    send_telegram(f"⚠️ ⚡ {bsym}: выход по времени на Binance не прошёл ({bnf_err_ru(e)}) — закройте позицию вручную", category="dlm")
                    continue
                px = (p["mark"] / r["scl"]) or t["entry"]
                with _dlm_lock:
                    t.update({"status": "CLOSED", "result": "TIME_EXIT", "exit": px, "t_out": int(now), "r": _dlm_r(t, px, int(t.get("hold") or 16) - 1, "TIME_EXIT")})
                changed = True
                notify_trade_result("dlm", t["symbol"], t["direction"], t["entry"], px, "TIME_EXIT", t["r"], real=True, note=f"⚡ лимитка {DLM_TF.get(t.get('bs'), '4h')} · Binance")
            continue
        # no position: which exit took it (a just-filled position may not show yet — given a minute unless the take filled)
        win = False
        if r.get("tp_kind") == "limit" and r.get("tp_id"):
            try:
                x = bnf_order(bsym, r["tp_id"])
                win = float(x.get("executedQty") or 0) > 0
                if not win and not r.get("seen") and now - t["t_in"] < 60:
                    continue
            except BinanceError as e:
                log_error(f"dlm binance take status {bsym}: {e}")
                continue
        elif not r.get("seen") and now - t["t_in"] < 60:
            continue
        elif r.get("tp_id"):
            win = bool(bnf_cond_done(bsym, r.get("tp_kind"), r["tp_id"]))
        _dlm_bn_cancel_exits(t)
        ex = t["tp"] if win else t["sl"]
        kind = "WIN" if win else "LOSS"
        with _dlm_lock:
            t.update({"status": "CLOSED", "result": kind, "exit": ex, "t_out": int(now), "r": _dlm_r(t, ex, int((now - t["fbar"]) // int(t.get("bs") or 900)), kind)})
        changed = True
        notify_trade_result("dlm", t["symbol"], t["direction"], t["entry"], ex, kind, t["r"], real=True, note=f"⚡ лимитка {DLM_TF.get(t.get('bs'), '4h')} · Binance")
    return changed


def dlm_real_tick():
    """every DLM_POLL_SEC: the real limits (filled / expired / a foreign position on the coin) and the real trades
    (the stop / take on the exchange, the time exit, the result)"""
    now = time.time()
    try:
        _dlm_arm(now)   # v0.99.691 — the waiting orders go on the exchange as the price comes
    except Exception as e:
        log_error(f"dlm arm: {e}")
    with _dlm_lock:
        orders = [o for o in _DLM["orders"] if (o.get("real") or {}).get("id") and o["status"] == "OPEN"]
        trades = [t for t in _DLM["trades"] if t.get("real") and t["status"] == "OPEN"]
    bo = [o for o in orders if o["real"].get("ex") == "binance"]   # v0.99.684 — each order / trade on its own exchange
    bt = [t for t in trades if t["real"].get("ex") == "binance"]
    orders = [o for o in orders if o not in bo]
    trades = [t for t in trades if t not in bt]
    changed = bool((bo or bt) and dlm_bn_tick(bo, bt))
    if not orders and not trades:
        if changed:
            dlm_save()
        return
    with using_account("dlm"):
        try:
            pos = {}
            for p in get_open_positions() or []:
                pos.setdefault(p.get("contract"), []).append(p)
            open_ids = {str(x.get("id")): x for x in (gate_signed_request("GET", "/futures/usdt/orders", query_string="status=open") or [])}
        except Exception as e:
            log_error(f"dlm exchange read: {e}")
            return
        for o in orders:
            r = o["real"]
            x = open_ids.get(r["id"])
            if x is None:
                try:
                    x = gate_signed_request("GET", f"/futures/usdt/orders/{r['id']}")
                except Exception as e:
                    log_error(f"dlm order status {o['symbol']}: {e}")
                    continue
            filled = abs(int(float(x.get("size") or 0))) - abs(int(float(x.get("left") or 0)))
            done = x.get("status") == "finished"
            foreign = not filled and pos.get(o["symbol"])
            if not done and (now >= o["until"] or foreign or filled):
                if not _dlm_cancel_order(r["id"]):   # the rest of a partly filled limit goes too
                    continue
                try:
                    x = gate_signed_request("GET", f"/futures/usdt/orders/{r['id']}")
                    filled = abs(int(float(x.get("size") or 0))) - abs(int(float(x.get("left") or 0)))
                except Exception:
                    pass
                done = True
            if not done:
                continue
            changed = True
            if filled > 0:
                fill = float(x.get("fill_price") or r["price"])
                t = _dlm_open_trade(o, int(now // int(o.get("bs") or 900) * int(o.get("bs") or 900)), fill, real={"filled": filled, "tick": r.get("tick"), "order": r["id"], "risk": r.get("risk")})
                if t:
                    try:
                        _dlm_place_exits(t)
                    except Exception as e:
                        log_error(f"dlm exits {t['symbol']}: {e}")
                    if TELEGRAM_ALERTS_DLM:
                        send_telegram(f"⚡ {t['symbol'].replace('_USDT', '')} {t['direction']} · лимитка {DLM_TF.get(t.get('bs'), '4h')} исполнилась @ {fill:.6g} ({filled} контр.)\n"
                                      f"тейк {t['tp']:.6g}{_dlm_take_note(t)} · стоп {t['sl']:.6g} · до {time.strftime('%H:%M', time.localtime(t['until']))}", category="dlm")
            else:
                o["status"] = "EXPIRED" if now >= o["until"] else "CANCELLED"
        for t in trades:
            r = t["real"]; sym, s = t["symbol"], t["side"]
            p = next((x for x in pos.get(sym) or [] if (float(x.get("size") or 0) > 0) == (s > 0)), None)
            size = abs(float((p or {}).get("size") or 0))
            if size > 0:
                r["seen"] = True
                if not r.get("sl_id") or not r.get("tp_id"):
                    try:
                        _dlm_place_exits(t); changed = True
                    except Exception as e:
                        log_error(f"dlm exits {sym}: {e}")
                if r.get("tp_id") and _dlm_take_watch(t, float((p or {}).get("mark_price") or 0) or None, now):   # v0.99.690 — the take back to 1 ATR
                    changed = True
                    gone, done_ = False, 0
                    try:
                        if r.get("tp_kind") == "limit":
                            gone = _dlm_cancel_order(r["tp_id"])
                            x = gate_signed_request("GET", f"/futures/usdt/orders/{r['tp_id']}")
                            done_ = abs(int(float(x.get("size") or 0))) - abs(int(float(x.get("left") or 0)))
                        else:
                            cancel_price_order(r["tp_id"]); gone = True
                    except Exception as e:
                        log_error(f"dlm take move {sym}: {e}")
                    if not gone:
                        t["take"] = "far"   # again next tick
                    elif done_ > 0:
                        t["take"] = "locked"
                    else:
                        with _dlm_lock:
                            t["tp"] = t["tp1"]; r["tp_id"] = None
                        try:
                            _dlm_place_exits(t)
                        except Exception as e:
                            log_error(f"dlm take 1 ATR {sym}: {e}")
                if now >= t["until"]:   # the time exit: the take / stop off, the rest at the market
                    if r.get("tp_kind") == "limit":
                        _dlm_cancel_order(r["tp_id"])
                    for oid in (r.get("sl_id"), r.get("tp_id") if r.get("tp_kind") == "trigger" else None):
                        if oid:
                            try:
                                cancel_price_order(oid)
                            except Exception:
                                pass
                    res = close_position_for_mode("dlm", sym, t["direction"])
                    px = float((p or {}).get("mark_price") or 0) or t["entry"]
                    with _dlm_lock:
                        t.update({"status": "CLOSED", "result": "TIME_EXIT", "exit": px, "t_out": int(now), "r": _dlm_r(t, px, int(t.get("hold") or 16) - 1, "TIME_EXIT")})
                    r["close"] = str(res)[:120]; changed = True
                    notify_trade_result("dlm", sym, t["direction"], t["entry"], px, "TIME_EXIT", t["r"], real=True, note=f"⚡ лимитка {DLM_TF.get(t.get('bs'), '4h')}")
                continue
            # no position: which exit took it (a just-filled position may not show yet — given a minute unless the take filled)
            win = False
            if r.get("tp_kind") == "limit" and r.get("tp_id"):
                try:
                    x = gate_signed_request("GET", f"/futures/usdt/orders/{r['tp_id']}")
                    win = abs(int(float(x.get("size") or 0))) - abs(int(float(x.get("left") or 0))) > 0
                    if not win and not r.get("seen") and now - t["t_in"] < 60:
                        continue
                    if x.get("status") != "finished":
                        _dlm_cancel_order(r["tp_id"])
                except Exception as e:
                    log_error(f"dlm take status {sym}: {e}")
                    continue
            elif not r.get("seen") and now - t["t_in"] < 60:
                continue
            else:
                trig = None
                try:
                    trig = {str(x.get("id")) for x in (get_open_price_orders() or [])}
                except Exception:
                    pass
                win = trig is not None and r.get("tp_id") and str(r["tp_id"]) not in trig and str(r.get("sl_id")) in trig
            for oid in (r.get("sl_id"), r.get("tp_id") if r.get("tp_kind") == "trigger" else None):
                if oid:
                    try:
                        cancel_price_order(oid)
                    except Exception:
                        pass
            ex = t["tp"] if win else t["sl"]
            kind = "WIN" if win else "LOSS"
            with _dlm_lock:
                t.update({"status": "CLOSED", "result": kind, "exit": ex, "t_out": int(now), "r": _dlm_r(t, ex, int((now - t["fbar"]) // int(t.get("bs") or 900)), kind)})
            changed = True
            notify_trade_result("dlm", sym, t["direction"], t["entry"], ex, kind, t["r"], real=True, note=f"⚡ лимитка {DLM_TF.get(t.get('bs'), '4h')}")
    if changed:
        dlm_save()


def dlm_loop():
    time.sleep(110)
    dlm_load()
    try:
        dlm_model()
    except Exception as e:
        log_error(f"dlm_loop model: {e}")
    while True:
        heartbeat("dlm_loop")
        try:
            if DLM_ENABLED:
                now = time.time()
                t_bar = int(now // 900 * 900)
                if _DLM.get("bar_done") != t_bar and now - t_bar >= 15:   # every 15 min: settle; a stream's bar closed: its scan
                    dlm_settle(now)
                    for st in _dlm_streams(dlm_model()):   # v0.99.689 — 4h and 2h
                        if t_bar % int(st["bar_sec"]) == 0 and now - t_bar < 600:   # a scan later than 10 min into the bar is stale
                            # (v0.99.691: from this pass's start — a slow 4h scan, e.g. the first candles after a restart, no longer drops the 2h one)
                            dlm_scan(t_bar, st)
                    with _dlm_lock:
                        _DLM["bar_done"] = t_bar
                if AUTOTRADE_ENABLED_DLM:
                    with live_http():
                        dlm_real_tick()
        except Exception as e:
            log_error(f"dlm_loop: {e}")
            with _dlm_lock:
                _DLM["err"] = str(e)[:200]
        time.sleep(DLM_POLL_SEC)


def dlm_stats():
    m = _DLM.get("model") or {}
    with _dlm_lock:
        trades = list(_DLM["trades"])
        orders = [o for o in _DLM["orders"] if o["status"] == "OPEN"]
        scan, err = _DLM.get("scan"), _DLM.get("err")
    done = [t for t in trades if t["status"] == "CLOSED" and t.get("r") is not None]
    fin = [t for t in done if t.get("rv") == DLM_MODEL_VER]   # v0.99.687 — the 4h trades; the 15m module's apart
    old = [t for t in done if t.get("rv") != DLM_MODEL_VER]
    rs = [t["r"] for t in fin]
    t0 = min((t["t_in"] for t in trades if t.get("rv") == DLM_MODEL_VER), default=None)
    days = max(1.0, (time.time() - t0) / 86400) if t0 else None
    real = [t for t in fin if t.get("real")]
    return {"on": DLM_ENABLED, "auto": AUTOTRADE_ENABLED_DLM, "tg": TELEGRAM_ALERTS_DLM, "dry": AUTOTRADE_DRY_RUN,
            "binance": DLM_BINANCE, "bn_keys": bool(BINANCE_API_KEY and BINANCE_API_SECRET), "bn_check": _BNF.get("check"),   # v0.99.684
            "more_coins": DLM_MORE_COINS, "coins_n": 210 if DLM_MORE_COINS else 127,   # v0.99.686
            "risk": dlm_risk(), "risk_set": MODULE_RISK_PCT.get("dlm"), "max_pos": DLM_MAX_POS,   # v0.99.687
            "model": dict({k: m.get(k) for k in ("ver", "q", "trained_to", "rule", "research", "side_cap")},
                          streams=[{k: x.get(k) for k in ("name", "tf", "anchor", "depth_atr", "thr", "alive_bars", "take_atr", "stop_atr", "hold_bars", "far_take_atr", "pull_atr")} for x in m.get("streams") or []]) if m else None,
            "err": err, "scan": scan, "orders": orders[:40], "orders_n": len(orders),
            "open": [t for t in trades if t["status"] == "OPEN"][-40:],
            "n": len(rs), "avg": round(sum(rs) / len(rs), 3) if rs else None, "wr": round(100 * sum(1 for t in fin if t["result"] == "WIN") / len(fin), 1) if fin else None,
            "sum": round(sum(rs), 2) if rs else None, "per_day": round(len(fin) / days, 1) if days else None,
            "real_n": len(real), "real_sum": round(sum(t["r"] for t in real), 2) if real else None,
            "old_n": len(old), "old_sum": round(sum(t["r"] for t in old), 2) if old else None,
            "live_check": live_vs_bt("dlm", rs),
            "streams": {n: {"n": len(x), "avg": round(sum(t["r"] for t in x) / len(x), 3) if x else None,
                            "wr": round(100 * sum(1 for t in x if t["result"] == "WIN") / len(x), 1) if x else None}
                        for n in ("wick4h", "close2h") for x in [[t for t in fin if (t.get("st") or "wick4h") == n]]},   # v0.99.689
            "last": [{k: t.get(k) for k in ("symbol", "side", "t0", "fbar", "t_in", "r", "result", "real", "entry", "lv", "sl", "tp", "exit", "t_out", "bs", "st", "tp1", "tp2", "take")}
                     for t in sorted(fin, key=lambda t: -t["t_in"])[:40]]}


@app.route("/api/dlm/status")
def api_dlm_status():
    try:
        return jsonify(dlm_stats())
    except Exception as e:
        log_error(f"dlm status: {e}")
        return jsonify({"err": f"статистика не посчиталась: {e}"})


