_RBX = {"trades": [], "loaded": False, "scan": None, "watch": [], "err": None}
_rbx_lock = threading.Lock()


def rbx_ema(v, n):
    out, k, e = [], 2 / (n + 1), None
    for x in v:
        e = x if e is None else e + k * (x - e)
        out.append(e)
    return out


def rbx_bars(sym, chart, now, start=None):
    """the chart's closed bars: the exchange's daily candles, the 12h ones from the 1h candles (UTC 00 / 12)"""
    if chart == "1d":
        return _zm_closed(sym, "1d", 86400, 1000, now) if start is None else \
            [c for c in (get_candles_range(sym, "1d", start, int(now)) or []) if c["time"] + 86400 <= now]
    h1 = _zm_closed(sym, "1h", 3600, 8000, now) if start is None else \
        [c for c in (get_candles_range(sym, "1h", start, int(now)) or []) if c["time"] + 3600 <= now]
    return [b for b in _oc_agg(h1, 12) if b["time"] + 12 * 3600 <= now]


def rbx_state(bars, cfg):
    """the last closed bar: (side or 0, info) — the research's range breakout (rb_daily.py / rb_tf.py)"""
    n, N = len(bars), cfg["n"]
    if n < 230:
        return 0, None
    H = [c["high"] for c in bars]; L = [c["low"] for c in bars]; C = [c["close"] for c in bars]
    tr = _nx_tr(H, L, C)
    atr = _nx_wilder(tr, 14)
    i = n - 1
    a = atr[i]
    atr100 = sum(tr[i - 99:i + 1]) / 100
    e200 = rbx_ema(C, 200)[i]
    hh, ll = max(H[i - N:i]), min(L[i - N:i])
    hh_p, ll_p = max(H[i - 1 - N:i - 1]), min(L[i - 1 - N:i - 1])
    if not a or not atr100:
        return 0, None
    rg = (hh - ll) / atr100
    info = {"rg": round(rg, 2), "hh": hh, "ll": ll, "atr": a, "close": C[i], "e200": e200, "t": bars[i]["time"]}
    s = 0
    if C[i] > hh and C[i - 1] <= hh_p and C[i] > e200:
        s = 1
    elif C[i] < ll and C[i - 1] >= ll_p and C[i] < e200:
        s = -1
    if s and rg >= cfg["k"]:
        s = 0
    if s:
        info["brk"] = s * (C[i] - (hh if s > 0 else ll)) / a
    return s, info


def rbx_load():
    try:
        if os.path.exists(RBX_STATE_FILE):
            with open(RBX_STATE_FILE) as f:
                d = json.load(f)
            with _rbx_lock:
                _RBX["trades"] = d.get("trades") or []
                _RBX["scan"] = d.get("scan")
                _RBX["watch"] = d.get("watch") or []
    except Exception as e:
        log_error(f"rbx state load: {e}")
    _RBX["loaded"] = True


def rbx_save():
    try:
        with _rbx_lock:
            data = json.dumps({"trades": _RBX["trades"][-600:], "scan": _RBX["scan"], "watch": _RBX["watch"]})
        tmp = RBX_STATE_FILE + ".tmp"
        with open(tmp, "w") as f:
            f.write(data)
        os.replace(tmp, RBX_STATE_FILE)
    except Exception as e:
        log_error(f"rbx state save: {e}")


def rbx_scan_once(chart):
    """after the chart's bar closed: its breakouts; the strongest first while the chart's slots are free"""
    cfg = RBX_CHARTS[chart]
    sec = cfg["hrs"] * 3600
    now = time.time()
    t_bar = int(now // sec * sec)
    cands, watch, coins = [], [], 0
    for sym in (RBX_COINS or _own_top_syms(RBX_TOP)):   # v0.99.672 — the research's coins
        heartbeat("rbx_loop")
        try:
            bars = rbx_bars(sym, chart, now)
            if not bars or bars[-1]["time"] + sec != t_bar:
                continue
            coins += 1
            s, info = rbx_state(bars, cfg)
            if s:
                cands.append({"symbol": sym, "side": s, **info})
            elif info and info["rg"] < cfg["k"]:
                up = info["close"] > info["e200"]
                lvl = info["hh"] if up else info["ll"]
                watch.append({"symbol": sym, "chart": chart, "side": 1 if up else -1, "rg": info["rg"],
                              "dist": round((lvl - info["close"]) / info["close"] * 100, 2)})
        except Exception as e:
            log_error(f"rbx scan {chart} {sym}: {e}")
    watch.sort(key=lambda w: abs(w["dist"]))
    live = {}
    if cands:
        for t in get_tickers() or []:
            try:
                live[t["contract"]] = float(t.get("last") or 0) or None
            except (TypeError, ValueError):
                pass
    opened = crowd = 0
    weak = sum(1 for c in cands if c["brk"] < RBX_MIN_BRK)
    for c in sorted(cands, key=lambda c: -c["brk"]):
        if RBX_STOP_ATR * c["atr"] <= c["close"] * 0.003:   # a stop within the fees (as the research skipped)
            continue
        if c["brk"] < RBX_MIN_BRK:     # v0.99.655: a weak breakout (the close barely beyond the range)
            continue
        ls = binance_ls_d24(c["symbol"], t_bar) if RBX_LS_MAX else None
        if ls is not None and c["side"] * ls > RBX_LS_MAX:   # v0.99.667: the crowd already piled into this side
            crowd += 1
            continue
        with _rbx_lock:
            opn = [t for t in _RBX["trades"] if t["status"] in ("OPEN", "PENDING")]
        if any(t["symbol"] == c["symbol"] and t["side"] == c["side"] for t in opn) or \
                sum(1 for t in opn if t["side"] == c["side"] and t.get("chart", "1d") == chart) >= cfg["cap"]:
            continue
        rbx_open(c, chart, t_bar, live.get(c["symbol"]))
        opened += 1
    with _rbx_lock:
        sc = dict(_RBX.get("scan") or {})
        sc[chart] = {"t": int(now), "bar": t_bar, "coins": coins, "signals": len(cands) - weak, "weak": weak, "crowd": crowd, "opened": opened}
        sc["t"] = int(now)
        _RBX["scan"] = sc
        _RBX["watch"] = [w for w in (_RBX.get("watch") or []) if w.get("chart", "1d") != chart] + watch[:8]
    rbx_save()


def rbx_open(c, chart, t_bar, live_px=None):
    cfg = RBX_CHARTS[chart]
    s, sym = c["side"], c["symbol"]
    direction = "LONG" if s > 0 else "SHORT"
    risk = RBX_STOP_ATR * c["atr"]
    px = live_px or c["close"]
    sl = px - s * risk
    tp = px + 40 * risk if s > 0 else max(px - 40 * risk, px * 0.05)   # the exit is the 20-bar low / high; a far take only as a guard
    tr = {"id": f"rbx_{chart}_{sym}_{s}_{t_bar}", "symbol": sym, "side": s, "direction": direction, "chart": chart, "hrs": cfg["hrs"],
          "hold": cfg["hold"], "day": t_bar, "risk": risk, "entry": None, "sl": sl, "px": px, "rg": c["rg"], "brk": round(c["brk"], 2),
          "half": False, "half_done": False, "part": bool(RBX_PART), "part_r": RBX_PART_R, "part_f": RBX_PART_F, "part_done": False,
          "lvl": c["hh"] if s > 0 else c["ll"], "fail_k": RBX_FAIL_K, "status": "PENDING" if RBX_LIM_ATR else "OPEN",
          "lim_atr": RBX_LIM_ATR, "wait": RBX_LIM_WAIT, "lv": px - s * RBX_LIM_ATR * c["atr"], "result": None, "r": None, "exit": None, "t_out": None, "real": False,
          "rv": RBX_RULE_VER}
    if AUTOTRADE_ENABLED_RBX and live_px and not RBX_LIM_ATR:
        try:
            res = execute_autotrade("rbx", sym, direction, live_px, sl, tp, extra={"пробой": f"{cfg['name']} сжатие {c['rg']}"},
                                    risk_pct_override=MODULE_RISK_PCT.get("rbx") or RBX_RISK_DEFAULT)
            tr["real"] = (res or {}).get("status") in ("OPENED", "OPENED_TP_SL_FAILED")
            tr["autotrade"] = {"status": (res or {}).get("status"), "detail": str((res or {}).get("detail") or "")[:200]}
        except Exception as e:
            log_error(f"rbx autotrade {sym}: {e}")
    with _rbx_lock:
        if any(t["id"] == tr["id"] for t in _RBX["trades"]):
            return
        _RBX["trades"].append(tr)
    if TELEGRAM_ALERTS_RBX:
        exit_txt = (f"на +{RBX_PART_R:g}R закрыть {round(RBX_PART_F * 100)}% и стоп в безубыток, остаток — " if tr["part"] else "тейка нет: ") + \
                   f"выход, когда свеча {cfg['name']} закроется {'ниже 20-свечного минимума' if s > 0 else 'выше 20-свечного максимума'} (после +{RBX_TIGHT_R:g}R — {RBX_TIGHT_DC}-свечного)" + \
                   (f"; если в первые {RBX_FAIL_K} свечи закроется обратно в коридор — выход сразу" if RBX_FAIL_K else "")
        send_telegram(f"{'🟢' if s > 0 else '🔴'} {sym.replace('_USDT', '')} {direction} · 📈 Пробой ({cfg['name']})\n"
                      + (f"вход лимиткой ~{tr['lv']:.6g} ({(tr['lv'] - px) / px * 100:+.2f}%, ждать {RBX_LIM_WAIT} свечи — не дойдёт, сделки нет)" if RBX_LIM_ATR else f"вход по рынку ~{px:.6g}")
                      + f" · стоп {sl:.6g} ({(sl - px) / px * 100:+.1f}%)" +
                      (f" · {round(RBX_PART_F * 100)}% на {px + s * RBX_PART_R * risk:.6g}" if tr["part"] else "") + f"\n{exit_txt}\n"
                      f"{cfg['n']} свечей цена шла в коридоре {c['rg']} среднего хода · " + ("💰 сделка на бирже" if tr["real"] else "без сделки (только сигнал)"),
                      category="rbx")


def rbx_walk(cs, k0, t):
    """the trade on its chart's closed bars from the entry bar k0, exactly as the research (rb_tf.py): the stop
    first, the Donchian exit at the close; in the half mode half off at +2R, then the stop at the entry.
    Returns (result, exit, bars held, R) or None while open."""
    s, risk, e, sl = t["side"], t["risk"], t["entry"], t["sl"]
    hold, hrs = int(t["hold"]), int(t["hrs"])
    if t.get("part"):   # v0.99.654 — the partial take, exactly as tools/rr_hunt/rb_part.py
        pr, pf = float(t.get("part_r") or RBX_PART_R), float(t.get("part_f") or RBX_PART_F)
        st, took, best = sl, False, 0.0

        def fin2(k, ex):
            fee = (e * RBX_FEE + e * RBX_FUND * (k + 1) * hrs / 24) / risk
            rest = s * (ex - e) / risk
            return ((pf * pr + (1 - pf) * rest) if took else rest) - fee
        for k in range(k0, min(len(cs), k0 + hold)):
            c = cs[k]; j = k - k0
            if (c["low"] <= st) if s > 0 else (c["high"] >= st):
                gap = j > 0 and ((c["open"] <= st) if s > 0 else (c["open"] >= st))
                ex = c["open"] if gap else st
                return ("BREAKEVEN" if took else "LOSS"), ex, j, fin2(j, ex)
            best = max(best, ((c["high"] - e) if s > 0 else (e - c["low"])) / risk)
            if not took and best >= pr:
                took = True; st = e
            dc = RBX_TIGHT_DC if RBX_TIGHT_R and best >= RBX_TIGHT_R else RBX_DC
            lv = min(x["low"] for x in cs[k - dc:k]) if s > 0 else max(x["high"] for x in cs[k - dc:k])
            if (c["close"] < lv) if s > 0 else (c["close"] > lv):
                return "TREND_END", c["close"], j, fin2(j, c["close"])
            fk, lvl = int(t.get("fail_k") or 0), t.get("lvl")    # v0.99.655: the close back inside the range early on
            if fk and lvl is not None and j < fk and not took and ((c["close"] < lvl) if s > 0 else (c["close"] > lvl)):
                return "FAILED", c["close"], j, fin2(j, c["close"])
        if len(cs) - k0 >= hold:
            ex = cs[k0 + hold - 1]["close"]
            return "TIME_EXIT", ex, hold - 1, fin2(hold - 1, ex)
        return None
    fin = lambda k, ex, part=1.0, fee=1.0: (s * (ex - e) - e * RBX_FEE * fee - e * RBX_FUND * (k + 1) * hrs / 24) / risk * part
    half_at = None
    best = 0.0
    for k in range(k0, min(len(cs), k0 + hold)):
        c = cs[k]; j = k - k0
        if half_at is None:
            if (c["low"] <= sl) if s > 0 else (c["high"] >= sl):
                return "LOSS", sl, j, fin(j, sl)
        else:
            if (c["low"] <= e) if s > 0 else (c["high"] >= e):
                return "BREAKEVEN", e, j, half_at + 0.5 * (s * 0 - e * RBX_FEE / 2 - e * RBX_FUND * (j + 1) * hrs / 24) / risk
        best = max(best, ((c["high"] - e) if s > 0 else (e - c["low"])) / risk)
        dc = RBX_TIGHT_DC if RBX_TIGHT_R and best >= RBX_TIGHT_R else RBX_DC   # v0.99.647
        lv = min(x["low"] for x in cs[k - dc:k]) if s > 0 else max(x["high"] for x in cs[k - dc:k])
        if t.get("half") and half_at is None and ((c["high"] >= e + s * RBX_HALF_R * risk) if s > 0 else (c["low"] <= e + s * RBX_HALF_R * risk)):
            half_at = 0.5 * (RBX_HALF_R * risk - e * RBX_FEE / 2) / risk
            continue   # the rest from the next bar on (as the research)
        if (c["close"] < lv) if s > 0 else (c["close"] > lv):
            if half_at is None:
                return "TREND_END", c["close"], j, fin(j, c["close"])
            return "TREND_END", c["close"], j, half_at + 0.5 * (s * (c["close"] - e) - e * RBX_FEE / 2 - e * RBX_FUND * (j + 1) * hrs / 24) / risk
    if len(cs) - k0 >= hold:
        ex = cs[k0 + hold - 1]["close"]
        if half_at is None:
            return "TIME_EXIT", ex, hold - 1, fin(hold - 1, ex)
        return "TIME_EXIT", ex, hold - 1, half_at + 0.5 * (s * (ex - e) - e * RBX_FEE / 2 - e * RBX_FUND * hold * hrs / 24) / risk
    return None


def rbx_settle(now=None):
    now = now or time.time()
    changed = False
    with _rbx_lock:
        opn = [t for t in _RBX["trades"] if t["status"] in ("OPEN", "PENDING")]
    for t in opn:
        try:
            chart = t.get("chart", "1d")
            hrs = int(t.get("hrs") or 24); sec = hrs * 3600
            t.setdefault("hrs", hrs); t.setdefault("hold", RBX_CHARTS[chart]["hold"])
            cs = rbx_bars(t["symbol"], chart, now, start=t["day"] - (RBX_DC + 12) * sec)
            k0 = next((k for k, c in enumerate(cs) if c["time"] == t["day"]), None)
            if k0 is None or k0 < RBX_DC:
                continue
            if t.get("entry") is None:
                lim = float(t.get("lim_atr") or 0)
                kf = k0
                if lim:   # v0.99.663 — the limit lim ATR better than the entry bar's open, `wait` bars
                    s_ = t["side"]; lv = cs[k0]["open"] - s_ * lim * t["risk"] / RBX_STOP_ATR; wait = int(t.get("wait") or 3)
                    kf = next((k for k in range(k0, min(len(cs), k0 + wait)) if ((cs[k]["low"] <= lv) if s_ > 0 else (cs[k]["high"] >= lv))), None)
                    if kf is None:
                        if len(cs) - k0 >= wait:
                            with _rbx_lock:
                                t.update({"status": "CLOSED", "result": "NO_FILL", "r": None, "lv": lv, "t_out": int(cs[k0 + wait - 1]["time"] + sec)})
                            changed = True
                            if t.get("real") and AUTOTRADE_ENABLED_RBX:
                                log_error(f"rbx no-fill {t['symbol']}: {close_position_for_mode('rbx', t['symbol'], t['direction'])}")
                        continue
                    e = min(lv, cs[kf]["open"]) if s_ > 0 else max(lv, cs[kf]["open"])
                else:
                    e = cs[k0]["open"]
                with _rbx_lock:
                    t.update({"entry": e, "sl": e - t["side"] * t["risk"], "kf_t": cs[kf]["time"], "status": "OPEN"})
                changed = True
            if t.get("kf_t") is not None:
                k0 = next((k for k, c in enumerate(cs) if c["time"] == t["kf_t"]), k0)
            res = rbx_walk(cs, k0, t)
            if not res:
                continue
            kind, ex, j, r = res
            if kind in ("TREND_END", "TIME_EXIT", "FAILED") and t.get("real") and AUTOTRADE_ENABLED_RBX:
                log_error(f"rbx exit {t['symbol']}: {close_position_for_mode('rbx', t['symbol'], t['direction'])}")
            with _rbx_lock:
                t.update({"status": "CLOSED", "result": kind, "exit": ex, "t_out": int(cs[k0 + j]["time"] + sec), "r": round(r, 3)})
            changed = True
            notify_trade_result("rbx", t["symbol"], t["direction"], t["entry"], ex, "WIN" if r > 0 and kind != "LOSS" else kind, round(r, 3),
                                real=bool(t.get("real")), note=f"📈 Пробой {RBX_CHARTS[chart]['name']}" + (" · тренд кончился" if kind == "TREND_END" else "") + (" · ложный пробой — вернулась в коридор" if kind == "FAILED" else ""))
        except Exception as e_:
            log_error(f"rbx trade {t.get('symbol')}: {e_}")
    if changed:
        rbx_save()


def part_take_on_exchange(mode, t, frac):
    """v0.99.654 — the partial take of a real trade: `frac` of the position off at market (none when the position is a
    single contract), the stop moved to the entry; the take order, if any, stays for the rest. -> a note for the log"""
    s, e0 = t["side"], t["px"]
    with using_account(mode), live_http():
        pos = next((q for q in (get_open_positions() or []) if q.get("contract") == t["symbol"]), None)
        size = float((pos or {}).get("size", 0) or 0)
        if not size or ("LONG" if size > 0 else "SHORT") != t["direction"]:
            return "no position"
        n = int(round(abs(size) * frac)) if abs(size) >= 2 else 0
        if n >= 1:
            place_market_order(t["symbol"], "SHORT" if s > 0 else "LONG", n, reduce_only=True)
        for o in (get_open_price_orders() or []):   # the old stop out, a stop at the entry in
            ini = o.get("initial", {})
            if ini.get("contract") == t["symbol"] and o.get("trigger", {}).get("rule") == (2 if s > 0 else 1):
                cancel_price_order(o.get("id"))
        try:
            tick = get_contract_spec(t["symbol"]).get("order_price_round")
        except Exception:
            tick = None
        be = round_to_tick_directional(e0, tick, round_up=(s < 0))
        place_close_trigger_order(t["symbol"], t["direction"], be, 2 if s > 0 else 1, tick)
    return f"{n} of {abs(size)} off, the stop at the entry {e0}"


def rbx_half_tick():
    """the partial take on the exchange: once the price reached the level from the real entry — the share off at market,
    the stop to the entry. v0.99.654: a quarter at +1R (the old "half at +2R" trades finish as they were)"""
    with _rbx_lock:
        todo = [t for t in _RBX["trades"] if t["status"] == "OPEN" and t.get("real")
                and ((t.get("half") and not t.get("half_done")) or (t.get("part") and not t.get("part_done")))]
    if not todo:
        return
    px = {}
    for tk in get_tickers() or []:
        try:
            px[tk["contract"]] = float(tk.get("last") or 0)
        except (TypeError, ValueError):
            pass
    for t in todo:
        p = px.get(t["symbol"])
        s, e0, half = t["side"], t["px"], bool(t.get("half"))
        lvl_r = RBX_HALF_R if half else float(t.get("part_r") or RBX_PART_R)
        frac = 0.5 if half else float(t.get("part_f") or RBX_PART_F)
        if not p or not ((p >= e0 + s * lvl_r * t["risk"]) if s > 0 else (p <= e0 + s * lvl_r * t["risk"])):
            continue
        try:
            note = part_take_on_exchange("rbx", t, frac)
            with _rbx_lock:
                t["half_done" if half else "part_done"] = True
            log_error(f"rbx partial {t['symbol']}: {note} (at ~{p})")
            if TELEGRAM_ALERTS_RBX and note != "no position":
                send_telegram(f"📈 {t['symbol'].replace('_USDT', '')}: +{lvl_r:g}R — {round(frac * 100)}% закрыто, стоп в безубытке ({e0:.6g})", category="rbx")
        except Exception as e:
            log_error(f"rbx partial {t['symbol']}: {e}")
    rbx_save()


def rbx_watch_tick():
    """v0.99.663 — the breakout limit on the exchange: a pending signal whose price reached its limit within the wait opens
    the real trade at market (the stop 2 ATR from the fill, the far guard take)"""
    now = time.time()
    with _rbx_lock:
        todo = [t for t in _RBX["trades"] if t["status"] == "PENDING" and not t.get("rt") and t.get("lv")
                and now < t["day"] + int(t.get("wait") or 3) * int(t.get("hrs") or 24) * 3600]
    if not todo:
        return
    px = {}
    for tk in get_tickers() or []:
        try:
            px[tk["contract"]] = float(tk.get("last") or 0)
        except (TypeError, ValueError):
            pass
    for t in todo:
        p = px.get(t["symbol"]); s = t["side"]
        how = limit_touched(t["symbol"], s, t["lv"], p, t["day"]) if p else None
        if not how or s * (p - t["lv"]) > float(t.get("risk") or 0):   # v0.99.669: Binance's wick too; not > 1R past the limit
            continue
        with _rbx_lock:
            t["trig"] = how
            t["rt"] = True
        risk = t["risk"]; sl = p - s * risk
        tp = p + 40 * risk if s > 0 else max(p - 40 * risk, p * 0.05)
        try:
            res = execute_autotrade("rbx", t["symbol"], t["direction"], p, sl, tp, extra={"пробой": f"лимитка {t.get('chart')}"},
                                    risk_pct_override=MODULE_RISK_PCT.get("rbx") or RBX_RISK_DEFAULT)
            with _rbx_lock:
                t["real"] = (res or {}).get("status") in ("OPENED", "OPENED_TP_SL_FAILED")
                t["px"] = p    # the partial take's trigger and the break-even from the real fill
                t["autotrade"] = {"status": (res or {}).get("status"), "detail": str((res or {}).get("detail") or "")[:200]}
        except Exception as e:
            log_error(f"rbx limit autotrade {t['symbol']}: {e}")
    rbx_save()


def rbx_loop():
    time.sleep(200)
    rbx_load()
    last = (_RBX.get("scan") or {}).get("t")
    last_bar = int(last // 43200 * 43200) if last else None
    while True:
        heartbeat("rbx_loop")
        try:
            if RBX_ENABLED:
                now = time.time()
                b = int(now // 43200 * 43200)
                if b != last_bar and now - b >= 120:   # a 12h bar closed (and the daily one at 00:00 UTC)
                    rbx_settle(now)
                    if now - b < 6 * 3600:
                        if b % 86400 == 0:
                            rbx_scan_once("1d")
                        rbx_scan_once("12h")
                    last_bar = b
                if AUTOTRADE_ENABLED_RBX:
                    rbx_watch_tick()
                    rbx_half_tick()
        except Exception as e:
            log_error(f"rbx_loop: {e}")
            with _rbx_lock:
                _RBX["err"] = str(e)[:200]
        time.sleep(60)


def rbx_stats():
    with _rbx_lock:
        trades = list(_RBX["trades"])
        scan, watch, err = _RBX.get("scan"), list(_RBX.get("watch") or []), _RBX.get("err")
    fin = [t for t in trades if t["status"] == "CLOSED" and t.get("r") is not None]
    rs = [t["r"] for t in fin]
    return {"on": RBX_ENABLED, "auto": AUTOTRADE_ENABLED_RBX, "tg": TELEGRAM_ALERTS_RBX, "half": False, "part": RBX_PART, "part_r": RBX_PART_R, "part_f": RBX_PART_F, "risk": MODULE_RISK_PCT.get("rbx") or RBX_RISK_DEFAULT,
            "min_brk": RBX_MIN_BRK, "fail_k": RBX_FAIL_K, "research": RBX_RESEARCH, "months": RBX_RESEARCH_MONTHS, "charts": RBX_CHARTS, "stop_atr": RBX_STOP_ATR, "dc": RBX_DC, "half_r": RBX_HALF_R, "tight_r": RBX_TIGHT_R, "tight_dc": RBX_TIGHT_DC,
            "err": err, "scan": scan, "watch": watch, "open": [t for t in trades if t["status"] in ("OPEN", "PENDING")][-24:], "lim_atr": RBX_LIM_ATR, "lim_wait": RBX_LIM_WAIT,
            "n": len(rs), "avg": round(sum(rs) / len(rs), 2) if rs else None, "wr": round(100 * sum(1 for r in rs if r > 0) / len(rs), 1) if rs else None,
            "sum": round(sum(rs), 2) if rs else None,
            "live_check": live_vs_bt("rbx", [t["r"] for t in fin if t.get("rv") == RBX_RULE_VER and t.get("part")]),
            "last": [{k: t.get(k) for k in ("symbol", "side", "chart", "day", "r", "result", "real", "entry", "px", "sl", "exit", "t_out", "part", "part_r", "risk")} for t in sorted(fin, key=lambda t: -t["day"])[:30]]}


@app.route("/api/rbx/status")
def api_rbx_status():
    try:
        return jsonify(rbx_stats())
    except Exception as e:
        log_error(f"rbx status: {e}")
        return jsonify({"err": f"статистика не посчиталась: {e}"})


# ═══════════════════════════════════════════════════════════════════════════
# v0.99.628 — 🪞 Hedge mirror: every NEW position on the source account gets an opposite one on the target account,
# MULT x its size at the same leverage; the source's full-close triggers are copied with the same price / rule
# (its take = the mirror's stop, its stop = the mirror's take); a mirror stop beyond the liquidation is moved just
# before it (and when the mirror has no stop at all, one is put there); the source position gone (its stop / take
# or closed by hand) -> the mirror is closed at market and its triggers cancelled. Partial closes / adds are not
# copied; positions already open when it is switched on are left alone.
# ═══════════════════════════════════════════════════════════════════════════
HDG_STATE_FILE = os.path.join(os.path.dirname(os.path.abspath(__file__)), "vp_hdg_state.json")
HDG_POLL_SEC = 5
HDG_LIQ_BUF_PCT = 0.1    # the stop before the liquidation: 0.1% of the price (at least 3 ticks) — the user: "максимально близко"
_hdg_lock = threading.RLock()
_HDG = {"cfg": {"on": False, "src": "default", "dst": None, "mult": 2.0, "min_x": 2.0, "cap_pct": 50.0, "tg": True}, "armed": False, "ignored": [],
        "pairs": {}, "log": [], "err": None, "t": None, "loaded": False}


def hdg_accounts():
    """the accounts with keys: the main one + each module sub-account (Settings -> keys)"""
    out = [{"id": "default", "label": "Основной", "ok": bool(GATE_API_KEY and GATE_API_SECRET)}]
    for m in MODULE_ACCOUNT_MODES:
        out.append({"id": m, "label": f"Суб-аккаунт {MODULE_ACCOUNT_LABELS.get(m, m)}", "ok": m in MODULE_CREDENTIALS})
    return out


_hdg_bal = {"t": 0, "v": {}, "busy": False}


def hdg_balances():
    """each keyed account's futures balance for the account pickers — refreshed in the background at most once a
    minute (the page asks every few seconds)"""
    if time.time() - _hdg_bal["t"] > 60 and not _hdg_bal["busy"]:
        _hdg_bal["busy"] = True

        def run():
            v = {}
            for a in hdg_accounts():
                if not a["ok"]:
                    continue
                try:
                    with hdg_acc(a["id"]):
                        v[a["id"]] = round(hdg_equity(), 2)
                except Exception as e:
                    v[a["id"]] = None
                    log_error(f"hdg balance {a['id']}: {e}")
            _hdg_bal.update({"v": v, "t": time.time(), "busy": False})
        threading.Thread(target=run, daemon=True).start()
    return dict(_hdg_bal["v"])


_hdg_reco = {"t": 0, "v": None, "busy": False, "key": None}
HDG_RECO_N = 50          # the last closed positions taken (of those that pass the filter)
HDG_RECO_FETCH = 200     # how many closed positions are read to find them
HDG_RECO_MIN_PNL = 5.0   # $: only the positions closed at +5$ or more / -5$ or less (the user: the small ones are impulsive)


def hdg_move_pct(r):
    """the price move of a closed position in % (no leverage), signed for its side; None when unknown"""
    try:
        lp, sp = float(r.get("long_price") or 0), float(r.get("short_price") or 0)
    except (TypeError, ValueError):
        return None
    if lp <= 0 or sp <= 0:
        return None
    return (sp - lp) / lp * 100 if str(r.get("side")) == "long" else (sp - lp) / sp * 100


def hdg_reco_calc(rows, eq_src, eq_dst, mult, min_x):
    """the first account's last closed positions -> what the mirror would have made: per trade the opposite of the
    move and the funding, its own fees, scaled by k = mirror $ / first $; k for the best growth of the second
    balance (max sum of log(1 + k * y / balance), Kelly) and half of it (safer: 20 trades are few)"""
    f = lambda r, k: float(r.get(k) or 0)
    n_all = len(rows)
    rows = [r for r in rows if abs(f(r, "pnl")) >= HDG_RECO_MIN_PNL]
    rows = sorted(rows, key=lambda r: float(r.get("time") or 0))[-HDG_RECO_N:]
    ys, own, fees = [], 0.0, 0.0
    for r in sorted(rows, key=lambda r: float(r.get("time") or 0)):
        if r.get("pnl_pnl") is not None:
            move, fee, fund = f(r, "pnl_pnl"), f(r, "pnl_fee"), f(r, "pnl_fund")
        else:
            move, fee, fund = f(r, "pnl"), 0.0, 0.0
        ys.append(-move - fund + fee)         # the mirror of the same dollar size (fee < 0: paid again)
        own += f(r, "pnl"); fees += fee
    k_now = max(mult * eq_dst / eq_src, min_x)
    out = {"n": len(ys), "n_all": n_all, "skipped": n_all - len(ys), "min_pnl": HDG_RECO_MIN_PNL, "own": round(own, 2), "fees": round(fees, 2), "k_now": round(k_now, 2),
           "mirror_now": round(k_now * sum(ys), 2), "pos": sum(1 for y in ys if y > 0)}
    best_k, best_g = 0.0, 0.0
    for i in range(1, 401):
        k = i * 0.05
        g = 0.0
        for y in ys:
            v = 1 + k * y / eq_dst
            if v <= 0:
                g = -1e18; break
            g += math.log(v)
        if g > best_g:
            best_k, best_g = k, g
    out["best_k"] = round(best_k, 2)
    out["best_mult"] = round(min(best_k * eq_src / eq_dst, 10), 2)       # the field's own maximum
    out["half_mult"] = round(min(best_k / 2 * eq_src / eq_dst, 10), 2)
    out["growth_best"] = round((math.exp(best_g) - 1) * 100, 1)
    return out


def hdg_reco():
    """the recommendation from the first account's last 50 closed positions with |PnL| >= 5$ — refreshed in the
    background every 10 min"""
    with _hdg_lock:
        cfg = dict(_HDG["cfg"])
    key = (cfg.get("src"), cfg.get("dst"), cfg.get("mult"), cfg.get("min_x"))
    if (time.time() - _hdg_reco["t"] > 600 or _hdg_reco["key"] != key) and not _hdg_reco["busy"] and cfg.get("dst"):
        _hdg_reco["busy"] = True

        def run():
            v = None
            try:
                with hdg_acc(cfg["src"]), live_http():
                    rows = gate_signed_request("GET", "/futures/usdt/position_close", query_string=f"limit={HDG_RECO_FETCH}", retry_on_timeout=True) or []
                    eq_src = hdg_equity()
                with hdg_acc(cfg["dst"]), live_http():
                    eq_dst = hdg_equity()
                if rows and eq_src > 0 and eq_dst > 0:
                    v = hdg_reco_calc(rows, eq_src, eq_dst, float(cfg.get("mult") or 2), float(cfg.get("min_x") or 0))
                else:
                    v = {"n": len(rows), "err": None if rows else "закрытых сделок на первом счёте нет"}
            except Exception as e:
                v = {"err": str(e)[:160]}
            _hdg_reco.update({"v": v, "t": time.time(), "busy": False, "key": key})
        threading.Thread(target=run, daemon=True).start()
    return _hdg_reco["v"] if _hdg_reco["key"] == key else None


def hdg_acc_label(a):
    return next((x["label"] for x in hdg_accounts() if x["id"] == a), str(a))


class hdg_acc:
    """the requests inside go through that account's own keys — never a silent fallback to another account"""
    def __init__(self, a):
        if not (a == "default" and GATE_API_KEY and GATE_API_SECRET) and a not in MODULE_CREDENTIALS:
            raise RuntimeError(f"у счёта «{hdg_acc_label(a)}» нет ключей")
        self.ctx = using_account(None if a == "default" else a)

    def __enter__(self):
        self.ctx.__enter__(); return self

    def __exit__(self, *e):
        return self.ctx.__exit__(*e)


def hdg_load():
    try:
        if os.path.exists(HDG_STATE_FILE):
            with open(HDG_STATE_FILE) as f:
                d = json.load(f)
            with _hdg_lock:
                for k in ("cfg", "armed", "ignored", "pairs", "log"):
                    if k in d:
                        _HDG[k] = d[k] if k != "cfg" else {**_HDG["cfg"], **d[k]}
    except Exception as e:
        log_error(f"hdg state load: {e}")
    _HDG["loaded"] = True


def hdg_save():
    try:
        with _hdg_lock:
            pairs = _HDG["pairs"]
            done = sorted((k for k, p in pairs.items() if p.get("status") != "open"), key=lambda k: pairs[k].get("t_close") or 0)
            for k in done[:-60]:
                pairs.pop(k, None)
            data = json.dumps({k: _HDG[k] for k in ("cfg", "armed", "ignored", "pairs")} | {"log": _HDG["log"][-80:]})
        tmp = HDG_STATE_FILE + ".tmp"
        with open(tmp, "w") as f:
            f.write(data)
        os.replace(tmp, HDG_STATE_FILE)
    except Exception as e:
        log_error(f"hdg state save: {e}")


def hdg_event(text, tg=True):
    with _hdg_lock:
        _HDG["log"].append({"t": int(time.time()), "text": text})
        _HDG["log"] = _HDG["log"][-80:]
        on_tg = _HDG["cfg"].get("tg", True)
    log_error(f"hdg: {text}")
    if tg and on_tg:
        send_telegram("🪞 " + text, category="hdg")


def _hdg_side(p):
    sz = float(p.get("size", 0) or 0)
    return "long" if sz > 0 else "short"


def _hdg_full_close_side(o, pos_sides):
    """the side a trigger order closes FULLY ('long' / 'short'), else None (a partial close or an entry order)"""
    ini = o.get("initial") or {}
    ot = str(o.get("order_type") or "")
    if "close-long" in ot:
        return "long"
    if "close-short" in ot:
        return "short"
    a = ini.get("auto_size")
    if a in ("close_long", "close_short") and not float(ini.get("size", 0) or 0):
        return a.split("_")[1]
    if (ini.get("close") or ini.get("is_close")) and not float(ini.get("size", 0) or 0):
        return pos_sides[0] if len(pos_sides) == 1 else None
    return None


def _hdg_liq_buf(price, tick):
    return max(price * HDG_LIQ_BUF_PCT / 100, 3 * (tick or 0))


def hdg_equity():
    """the account's capital as the autotrade sizes by it: free + the open positions' margin (falls back to the
    Unified account's equity — the classic futures endpoint reads 0 there)"""
    return get_futures_total_equity()


def hdg_set_leverage(contract, lev, cll):
    dual = get_dual_mode()
    path = f"/futures/usdt/dual_comp/positions/{contract}/leverage" if dual else f"/futures/usdt/positions/{contract}/leverage"
    q = f"leverage={lev}"
    if str(lev) in ("0", "0.0") and cll:
        q += f"&cross_leverage_limit={cll}"
    return gate_signed_request("POST", path, query_string=q, retry_on_timeout=True)


def hdg_close_position(contract, direction):
    body = dict(_close_order_initial(contract, direction, get_dual_mode()))
    return gate_signed_request("POST", "/futures/usdt/orders", body=body)


def _hdg_dst_pos(dst_positions, contract, side):
    return next((q for q in dst_positions if q.get("contract") == contract and _hdg_side(q) == side), None)


def hdg_open(key, p, cfg):
    """the mirror of a new source position: opposite side, the same leverage; its margin = MULT x the source's share
    of its balance (of the target's balance), at least MIN_X x the source's margin in dollars, and all the mirrors
    together at most CAP_PCT % of the target's balance (the cap wins)"""
    contract, sside = p["contract"], _hdg_side(p)
    dside = "short" if sside == "long" else "long"
    ddir = "SHORT" if dside == "short" else "LONG"
    n_src = abs(float(p.get("size", 0) or 0))
    mult, min_x, cap_pct = float(cfg.get("mult") or 2), float(cfg.get("min_x") or 0), float(cfg.get("cap_pct") or 100)
    lev, cll = str(p.get("leverage") or "0"), p.get("cross_leverage_limit")
    price = float(p.get("mark_price") or 0) or float(p.get("entry_price") or 0)
    L = float(lev) if float(lev or 0) > 0 else (float(cll or 0) or 1.0)   # margin = notional / leverage (the same on both)
    with hdg_acc(cfg["src"]), live_http():
        eq_src = hdg_equity()
    qm = get_contract_spec(contract).get("quanto_multiplier") or 1
    coin = contract.replace("_USDT", "")
    pair = {"contract": contract, "src_side": sside, "src_size": n_src, "src_entry": float(p.get("entry_price") or 0) or None,
            "lev": lev, "cll": cll, "dst_side": dside, "dst_entry": None, "liq": None, "status": "open",
            "t_open": int(time.time()), "orders": {}, "liq_stop": None, "notes": []}
    with hdg_acc(cfg["dst"]), live_http():
        eq_dst = hdg_equity()
        if eq_src <= 0 or eq_dst <= 0 or price <= 0:
            raise RuntimeError(f"нет баланса / цены (первый {eq_src:.2f}$, второй {eq_dst:.2f}$)")
        dst_positions = get_open_positions()
        if any(q.get("contract") == contract for q in dst_positions):
            raise RuntimeError("на втором счёте уже есть позиция по этой монете — не трогаю её")
        src_margin = n_src * qm * price / L
        want = src_margin / eq_src * mult * eq_dst            # the same share of the balance x MULT
        margin = max(want, min_x * src_margin)
        with _hdg_lock:
            mine = {(q["contract"], q["dst_side"]) for q in _HDG["pairs"].values() if q.get("status") == "open"}
        used = sum(float(q.get("margin") or 0) for q in dst_positions if (q.get("contract"), _hdg_side(q)) in mine)
        room = cap_pct / 100 * eq_dst - used
        capped = margin > room
        if capped:
            margin = room
        n = int(margin * L / (qm * price))                   # down: never above the cap
        spec = get_contract_spec(contract)
        if n < (spec.get("order_size_min") or 1):
            raise RuntimeError(f"на втором счёте нет места: лимит {cap_pct:g}% баланса ({eq_dst:.2f}$) уже занят другими зеркалами ({used:.2f}$)"
                               if room <= 0 else f"зеркало {margin:.2f}$ меньше минимального ордера")
        margin = n * qm * price / L
        pair.update({"src_margin": round(src_margin, 2), "dst_margin": round(margin, 2), "dst_size": n, "capped": capped,
                     "share": round(src_margin / eq_src * 100, 2), "dst_share": round(margin / eq_dst * 100, 2),
                     "eq_src": round(eq_src, 2), "eq_dst": round(eq_dst, 2)})
        try:
            hdg_set_leverage(contract, int(float(lev)), cll)
        except Exception as e:
            pair["notes"].append(f"плечо не выставилось: {str(e)[:80]}")
        with _hdg_lock:
            _HDG["pairs"][key] = pair      # recorded BEFORE the order: a crash after it never opens a second mirror
        hdg_save()
        res = None
        try:
            res = place_market_order(contract, ddir, n)
        except Exception as e:
            if not _hdg_dst_pos(get_open_positions(), contract, dside):   # a timeout may still have filled — only a real miss fails
                with _hdg_lock:
                    _HDG["pairs"].pop(key, None)
                raise
        pos = _hdg_dst_pos(get_open_positions(), contract, dside)
        if pos:
            pair["dst_entry"] = float(pos.get("entry_price") or 0) or None
            pair["liq"] = float(pos.get("liq_price") or 0) or None
            pair["dst_size"] = abs(float(pos.get("size", 0) or 0))
        else:
            pair["dst_entry"] = float((res or {}).get("fill_price") or 0) or None
    lev_txt = f"x{lev}" if lev not in ("0", "0.0") else f"кросс x{cll}"
    why = ""
    if capped:
        why = f" · урезано лимитом {cap_pct:g}% баланса второго счёта" + (f" — меньше ×{min_x:g} от сделки" if margin < min_x * src_margin - 1e-9 else "")
    elif want < min_x * src_margin:
        why = f" · поднято до ×{min_x:g} от сделки (по доле баланса было бы {want:.2f}$)"
    hdg_event(f"{coin}: на первом счёте {'лонг' if sside == 'long' else 'шорт'} {src_margin:.2f}$ ({pair['share']:g}% баланса) — открыл зеркало "
              f"{'шорт' if dside == 'short' else 'лонг'} {margin:.2f}$ ({pair['dst_share']:g}% баланса второго счёта, {n:g} контр., {lev_txt})" +
              (f" по ~{pair['dst_entry']:.6g}" if pair["dst_entry"] else "") + why + (f" · {pair['notes'][0]}" if pair["notes"] else ""))
    return pair


def hdg_sync_orders(key, pair, src_orders, cfg):
    """copy the source's full-close triggers (same price and rule: its take = the mirror's stop and back); a stop
    beyond the liquidation -> just before it; no stop at all -> one just before the liquidation"""
    contract, sside, dside = pair["contract"], pair["src_side"], pair["dst_side"]
    ddir = "SHORT" if dside == "short" else "LONG"
    coin = contract.replace("_USDT", "")
    want = {}
    for o in src_orders:
        if (o.get("initial") or {}).get("contract") != contract:
            continue
        if _hdg_full_close_side(o, [sside]) != sside:
            continue
        tr = o.get("trigger") or {}
        try:
            want[str(o["id"])] = (float(tr.get("price")), int(tr.get("rule")), int(tr.get("price_type") or 0))
        except (TypeError, ValueError, KeyError):
            continue
    is_stop = lambda rule: (dside == "short" and rule == 1) or (dside == "long" and rule == 2)
    changed = False
    with hdg_acc(cfg["dst"]), live_http():
        tick = None
        try:
            tick = get_contract_spec(contract).get("order_price_round")
        except Exception:
            pass
        if not pair.get("liq"):
            pos = _hdg_dst_pos(get_open_positions(), contract, dside)
            if pos:
                pair["liq"] = float(pos.get("liq_price") or 0) or None
        liq = pair.get("liq")
        # the source's triggers gone / moved -> the mirror's copies out
        for sid, m in list(pair["orders"].items()):
            if sid not in want or (want[sid][0], want[sid][1]) != (m["src_price"], m["rule"]):
                try:
                    cancel_price_order(m["dst_id"])
                except Exception:
                    pass
                pair["orders"].pop(sid, None); changed = True
        for sid, (price, rule, ptype) in want.items():
            if sid in pair["orders"]:
                continue
            px, clamped = price, False
            if is_stop(rule) and liq:
                buf = _hdg_liq_buf(liq, tick)
                if dside == "short" and price >= liq - buf:
                    px, clamped = round_to_tick_directional(liq - buf, tick, round_up=False) if tick else liq - buf, True
                elif dside == "long" and price <= liq + buf:
                    px, clamped = round_to_tick_directional(liq + buf, tick, round_up=True) if tick else liq + buf, True
            r = place_close_trigger_order(contract, ddir, px, rule, tick, 1 if clamped else ptype)
            pair["orders"][sid] = {"dst_id": str((r or {}).get("id")), "src_price": price, "price": px, "rule": rule,
                                   "kind": "stop" if is_stop(rule) else "take", "clamped": clamped}
            changed = True
            if clamped:
                hdg_event(f"{coin}: стоп зеркала ({price:.6g} = тейк первого счёта) за ликвидацией {liq:.6g} — поставил перед ней: {px:.6g}")
        has_stop = any(m["kind"] == "stop" for m in pair["orders"].values())
        if has_stop and pair.get("liq_stop"):
            try:
                cancel_price_order(pair["liq_stop"]["dst_id"])
            except Exception:
                pass
            pair["liq_stop"] = None; changed = True
        if not has_stop and not pair.get("liq_stop") and liq:
            buf = _hdg_liq_buf(liq, tick)
            if dside == "short":
                px, rule = (round_to_tick_directional(liq - buf, tick, round_up=False) if tick else liq - buf), 1
            else:
                px, rule = (round_to_tick_directional(liq + buf, tick, round_up=True) if tick else liq + buf), 2
            r = place_close_trigger_order(contract, ddir, px, rule, tick, 1)
            pair["liq_stop"] = {"dst_id": str((r or {}).get("id")), "price": px}
            changed = True
            hdg_event(f"{coin}: у первого счёта нет тейка — стопа у зеркала нет; поставил стоп перед ликвидацией: {px:.6g} (ликвидация {liq:.6g})")
    return changed


def hdg_close(key, pair, cfg, why):
    contract, dside = pair["contract"], pair["dst_side"]
    ddir = "SHORT" if dside == "short" else "LONG"
    coin = contract.replace("_USDT", "")
    with hdg_acc(cfg["dst"]), live_http():
        pos = _hdg_dst_pos(get_open_positions(), contract, dside)
        if pos:
            hdg_close_position(contract, ddir)
        for m in list(pair["orders"].values()) + ([pair["liq_stop"]] if pair.get("liq_stop") else []):
            try:
                cancel_price_order(m["dst_id"])
            except Exception:
                pass
    pair.update({"status": "closed", "t_close": int(time.time()), "why": why, "orders": {}, "liq_stop": None})
    hdg_event(f"{coin}: {why} — зеркало {'закрыто' if pos else 'уже было закрыто'}, его ордера сняты")


def hdg_tick():
    with _hdg_lock:
        cfg = dict(_HDG["cfg"])
    if not cfg.get("on"):
        return
    if not cfg.get("dst") or cfg["dst"] == cfg.get("src"):
        raise RuntimeError("выберите два разных счёта")
    if AUTOTRADE_DRY_RUN:
        raise RuntimeError("включён режим dry-run автоторговли — ордера не отправляются")
    with hdg_acc(cfg["src"]), live_http():
        src_pos = get_open_positions()
        src_orders = get_open_price_orders() or []
    cur = {f"{p['contract']}|{_hdg_side(p)}": p for p in src_pos}
    changed = False
    with _hdg_lock:
        if not _HDG["armed"]:
            _HDG["ignored"] = sorted(cur)
            _HDG["armed"] = True
            changed = True
            if cur:
                hdg_event(f"включено: уже открытые позиции первого счёта ({len(cur)}) не зеркалю — только новые", tg=False)
        _HDG["ignored"] = [k for k in _HDG["ignored"] if k in cur]   # an ignored one closed -> its next opening is a new one
        ignored = set(_HDG["ignored"])
        pairs = dict(_HDG["pairs"])
    # the source position gone -> the mirror closes; the mirror gone on its own -> stays closed
    for key, pair in pairs.items():
        if pair.get("status") in ("dst_closed", "error") and key not in cur:
            pair["status"] = "closed" if pair["status"] == "dst_closed" else "failed"   # the source position is gone too
            changed = True
        if pair.get("status") != "open":
            continue
        try:
            if key not in cur:
                hdg_close(key, pair, cfg, "позиция на первом счёте закрыта")
                changed = True
                continue
            with hdg_acc(cfg["dst"]), live_http():
                pos = _hdg_dst_pos(get_open_positions(), pair["contract"], pair["dst_side"])
            if not pos:
                with hdg_acc(cfg["dst"]), live_http():
                    for m in list(pair["orders"].values()) + ([pair["liq_stop"]] if pair.get("liq_stop") else []):
                        try:
                            cancel_price_order(m["dst_id"])
                        except Exception:
                            pass
                pair.update({"status": "dst_closed", "t_close": int(time.time()), "why": "зеркало закрылось на бирже (стоп / тейк / вручную)",
                             "orders": {}, "liq_stop": None})
                hdg_event(f"{pair['contract'].replace('_USDT', '')}: зеркало закрылось само (стоп / тейк / вручную), первый счёт ещё в позиции — заново не открываю")
                changed = True
                continue
            liq = float(pos.get("liq_price") or 0) or None
            if liq and liq != pair.get("liq"):
                pair["liq"] = liq
            changed |= hdg_sync_orders(key, pair, src_orders, cfg)
        except Exception as e:
            pair.setdefault("errs", 0)
            pair["errs"] += 1
            if pair["errs"] in (1, 10):
                hdg_event(f"{pair['contract'].replace('_USDT', '')}: ошибка: {str(e)[:160]}")
    # new source positions -> mirrors
    for key, p in cur.items():
        if key in ignored or key in pairs and pairs[key].get("status") == "open":
            continue
        old = pairs.get(key)
        if old and old.get("status") == "dst_closed":
            continue   # the same source position is still open, its mirror closed on its own — not again
        if old and old.get("status") == "error" and (old.get("tries", 1) >= 3 or time.time() - old.get("t_close", 0) < 30):
            continue   # failed: up to 3 tries, 30 s apart
        try:
            pair = hdg_open(key, p, cfg)
            hdg_sync_orders(key, pair, src_orders, cfg)
        except Exception as e:
            tries = (old.get("tries", 1) + 1) if old and old.get("status") == "error" else 1
            with _hdg_lock:
                if (_HDG["pairs"].get(key) or {}).get("status") != "open":
                    _HDG["pairs"][key] = {"contract": p["contract"], "src_side": _hdg_side(p), "src_size": abs(float(p.get("size", 0) or 0)),
                                          "status": "error", "tries": tries, "t_open": int(time.time()), "t_close": int(time.time()),
                                          "why": str(e)[:200], "dst_side": "short" if _hdg_side(p) == "long" else "long", "orders": {}}
            if tries in (1, 3):
                hdg_event(f"{p['contract'].replace('_USDT', '')}: зеркало не открылось — {str(e)[:160]}" + (" (3 попытки, больше не пробую)" if tries == 3 else ""))
        changed = True
    if changed:
        hdg_save()


def hdg_loop():
    time.sleep(30)
    hdg_load()
    while True:
        heartbeat("hdg_loop")
        try:
            hdg_tick()
            with _hdg_lock:
                _HDG["err"] = None; _HDG["t"] = int(time.time())
        except Exception as e:
            with _hdg_lock:
                new = _HDG["err"] != str(e)[:200]
                _HDG["err"] = str(e)[:200]
            if new:
                log_error(f"hdg_loop: {e}")
        time.sleep(HDG_POLL_SEC)


def hdg_status():
    with _hdg_lock:
        cfg, pairs, log, err, t, armed = dict(_HDG["cfg"]), dict(_HDG["pairs"]), list(_HDG["log"]), _HDG["err"], _HDG["t"], _HDG["armed"]
    opn = [dict(p, key=k) for k, p in pairs.items() if p.get("status") == "open"]
    done = sorted((dict(p, key=k) for k, p in pairs.items() if p.get("status") != "open"), key=lambda p: -(p.get("t_close") or 0))[:20]
    bal = hdg_balances()
    reco = hdg_reco()
    accs = [dict(a, bal=bal.get(a["id"])) for a in hdg_accounts()]
    return {"cfg": cfg, "accounts": accs, "reco": reco, "open": opn, "done": done, "log": log[-30:][::-1], "err": err, "t": t,
            "armed": armed, "dry": AUTOTRADE_DRY_RUN, "buf_pct": HDG_LIQ_BUF_PCT, "poll": HDG_POLL_SEC}


