def zones_post_summary(post, new):
    when = time.strftime("%d.%m %H:%M", time.localtime(post["post_time"]))
    if not new and post.get("dup_of"):   # v0.99.542 — it said "цветных зон нет" for a duplicate too
        with _zones_lock:
            first = next((p_ for p_ in ZONES["posts"] if p_["id"] == post["dup_of"]), None)
        stn = {"watch": "слежу", "in_trade": "в сделке", "old": "уже отработала (в статистику)", "expired": "истекла",
               "closed": "закрыта", "broken": "пробита", "skipped": "не торгую — тот же сетап уже в работе",
               "hist_wait": "старый пост — только в статистику", "deleted": "удалена"}
        with _zones_lock:
            fz = [z for z in ZONES["zones"] if first and z.get("post_id") == first["id"] and z.get("status") != "deleted"]
        skn = {"dup": "не торгую — тот же сетап уже в работе (другая копия поста)", "recheck": "снята: при перепроверке это пост-отчёт",
               "scale": "не торгую — уровни не совпадают с ценой"}
        zl = "\n".join(f"• {'лонг' if z['side'] == 'long' else 'шорт'} {' / '.join(f'{v:g}' for v in z['levels'])} — "
                        f"{skn.get(z.get('skip'), stn.get(z['status'], z['status'])) if z['status'] == 'skipped' else stn.get(z['status'], z['status'])}"
                        for z in fz)
        if any(z["status"] == "skipped" for z in fz):
            zl += "\nВернуть пропущенные в работу — кнопка «▶ в работу» у зоны во вкладке «Зоны» (архив)."
        return (f"🔁 Пост от {when}: уже есть — тот же пост пришёл ещё раз"
                + (f" ({(first.get('symbol') or '').replace('_USDT', '')}, сохранён {time.strftime('%d.%m %H:%M', time.localtime(first.get('created') or first['post_time']))})" if first else "")
                + ", не дублирую." + (f" Его зоны:\n{zl}" if zl else " У того поста зон сейчас нет."))
    if not new and post.get("result_post"):
        return f"📊 Пост от {when}: пост-отчёт автора (результат отработки), а не новый сетап — пропущен."
    if not new and post.get("skipped"):
        return f"⏭ Пост от {when}: не похоже на скрин с зонами (цветных зон нет) — пропущен."
    if not new and post.get("index_read"):
        return (f"⏭ Пост от {when}: {post['index_read']} — индекс (например, доминация BTC), а не монета: "
                f"торговать нечего, скрин пропущен.")
    if not new and post.get("not_listed"):
        return f"⏭ Пост от {when}: {post['not_listed']} нет на фьючерсах Gate — скрин пропущен."
    if not new and post.get("pending"):
        zl = "\n".join(f"• {'лонг' if z['side'] == 'long' else 'шорт'} " + " / ".join(f"{v:.6g}" for v in z["levels"])
                       for z in post["pending"]["zones"])
        return (f"❓ Пост от {when}: зоны нашёл, а монету не прочитал.\n{zl}\n"
                f"Ответьте одним словом — тикер монеты (например ZEN), и я начну следить.")
    if not new:
        return (f"⚠️ Зоны: пост от {when} — не распознал{(' (' + post['symbol'] + ')') if post.get('symbol') else ''}. "
                f"{'; '.join(post['notes'][:3])}")
    if post.get("train"):
        lines = [f"📚 Обучение · {post['symbol']} · пост от {when} · зон: {len(new)} (не слежу и не торгую)"]
        for z in new:
            r_ = z.get("result")
            st = ("отработала: " + (f"{r_['result']} {r_['r']:+g}R" + (f" · {r_['pct']:+.2f}%" if r_.get("pct") is not None else "")
                                     if r_ else "входа не было")) if z["status"] == "old" \
                else "итога ещё нет — досчитаю по графику, когда будет"
            lines.append(f"• {zones_fmt(z)} — {st}")
        if post["notes"]:
            lines.append("⚠️ " + "; ".join(post["notes"][:3]))
        if post.get("own_txt"):
            lines.append(post["own_txt"])
        return "\n".join(lines)
    lines = ([post["approach_txt"]] if (post.get("approach_txt") or "").startswith("🚀") else []) \
        + [f"📥 {post['symbol']} · пост от {when} · зон: {len(new)}"]
    for z in new:
        st = {"watch": "слежу", "old": "уже отработала (в статистику)", "train": "обучение: жду итога", "hist_wait": "старый пост — только в статистику"}.get(z["status"], z["status"])
        if z["status"] == "old":
            r_ = z.get("result")
            st = (f"уже отработала: {r_['r']:+g}R" + (f" · {r_['pct']:+.2f}%" if r_.get("pct") is not None else "")) \
                if r_ else "уже отработала: входа не было"
        lines.append(f"• {zones_fmt(z)} — {st}")
    if (post.get("approach_txt") or "").startswith("ℹ️"):
        lines.append(post["approach_txt"])
    if post["notes"]:
        lines.append("⚠️ " + "; ".join(post["notes"][:3]))
    if post.get("own_txt"):
        lines.append(post["own_txt"])
    lines.append("Проверьте уровни во вкладке «Зоны».")
    return "\n".join(lines)


@app.route("/api/zones/status")
def api_zones_status():
    with _zones_lock:
        posts = [dict(p) for p in ZONES["posts"][:200]]
    for p_ in posts:   # v0.99.485 — the page doesn't need the learning samples (hundreds of KB every 15 s)
        if p_.get("own"):
            p_["own"] = {k: v for k, v in p_["own"].items() if k != "samples"}
    with _zones_lock:
        zones = [dict(z) for z in ZONES["zones"] if z.get("status") != "deleted"][:600]
        learned, stats, tg_err = ZONES.get("learned"), ZONES.get("stats"), ZONES.get("tg_last_error")
    with _zones_lock:
        approach = ZONES.get("approach")
        act = json.loads(json.dumps(ZONES_ACT, default=str))
        mon_ok = ZONES.get("monitor_ok")
    act["stuck"] = zones_monitor_stuck_txt()   # v0.99.601
    # v0.99.493 — what the ladders are doing now, for the "Состояние" block
    lad = [z["trade"] for z in zones if (z.get("trade") or {}).get("legs") and not z.get("own") and not z.get("oc")]
    live = [t for t in lad if t.get("status") in ("PENDING", "OPEN")]
    # v0.99.517 — our own finders' ladders (observation, no orders) are counted apart
    finder = [z for z in zones if (z.get("own") or z.get("oc")) and (z.get("trade") or {}).get("status") in ("PENDING", "OPEN")]
    act["ladders"] = {"pending": sum(1 for t in live if t["status"] == "PENDING"),
                      "open": sum(1 for t in live if t["status"] == "OPEN"),
                      "on_exchange": sum(1 for t in live if (t.get("real") or {}).get("legs") and not t["real"].get("done")),
                      "limits": sum(1 for t in live for l in ((t.get("real") or {}).get("legs") or []) if not l.get("done")),
                      "waiting": sum(1 for t in live if t["status"] == "PENDING" and not t.get("real") and not t.get("no_auto")),
                      # v0.99.516 — filled in the bot's record before any real order (e.g. before autotrade): followed to the end, no order
                      "virt_open": sum(1 for t in live if t["status"] == "OPEN" and not t.get("real")),
                      "no_auto": sum(1 for t in live if t.get("no_auto")),
                      "finder": len(finder)}
    act["monitor_age"] = round(time.time() - mon_ok) if mon_ok else None
    act["now"] = time.time()
    return jsonify({"posts": posts, "zones": zones, "learned": learned, "stats": stats, "params": zones_params(),
                    "stopx_live": zones_stopx_rule(), "stopx_txt": zones_stopx_txt(zones_stopx_rule()),   # v0.99.604
                    "conc": zones_conc_target(), "margin_use": ZONES_MARGIN_USE,   # v0.99.606
                    "tpv_live": zones_tpv_rule(),   # v0.99.609
                    "act": act,
                    "approach": approach, "autotrade_approach": AUTOTRADE_ENABLED_ZONES_APPROACH,
                    "pb": zones_pb_stats(), "pb_variant": zones_pb_variant(), "pb_tg": zones_pb_tg(),   # v0.99.523
                    "deps": zones_deps(), "tg": bool(TELEGRAM_BOT_TOKEN and TELEGRAM_CHAT_ID), "tg_error": tg_err,
                    "autotrade": AUTOTRADE_ENABLED_ZONES, "max_days": ZONES_MAX_DAYS, "tp_user": ZONES_TP_PCT,
                    "learn_min": ZONES_LEARN_MIN, "train_mode": bool(ZONES.get("train_mode")),
                    "own": own_stats(), "own_exams": own_exam_list(), "autotrade_own": AUTOTRADE_ENABLED_ZONES_OWN,
                    "oc": oc_stats(), "zm": zm_stats_safe()})


