@app.route("/api/zones/chart/<zid>")
def api_zones_chart(zid):
    """v0.99.482 — one zone on its candles: from a day before the post to the
    exit (take / stop / time) or now; the live trade as it was, a history zone
    replayed with the current rules."""
    with _zones_lock:
        z = next((dict(x) for x in ZONES["zones"] if x["id"] == zid), None)
    if not z or not z.get("symbol"):
        return jsonify({"ok": False, "error": "нет такой зоны"}), 404
    now = time.time()
    start = z["post_time"]
    end = min(now, start + ZONES_MAX_DAYS * 86400)
    p = zones_params()
    tr, src = None, None
    t = z.get("trade")
    with _zones_lock:   # v0.99.491 — a zone of a ladder: the ladder's trade sits on its lead zone
        kf = zones_group_key if (z.get("lead") or (z.get("trade") or {}).get("legs")) else zones_hist_key
        group = [x for x in ZONES["zones"] if kf(x) == kf(z) and x.get("status") != "deleted" and not x.get("own") and not x.get("oc")] or [z]
        if not t and z.get("lead"):
            t = next((x.get("trade") for x in group if x["id"] == z["lead"]), None)
    if t:
        tr = {"t_in": t.get("time"), "fill": t.get("entry"), "sl": t.get("sl"), "tp": t.get("tp"),
              "t_out": t.get("exit_time"), "exit": t.get("exit_price"), "result": t.get("result"),
              "r": t.get("pnl_r"), "pct": t.get("pnl_pct"), "real": bool(t.get("autotrade_fired"))}
        src = "живая сделка"
    else:
        cs_all = zones_candles(z["symbol"], start, end)
        ax_ = None if (z.get("own") or z.get("oc")) else zones_author_exit_t(zones_author_exits(), z["symbol"], start)   # v0.99.519
        r = zone_ladder_sim(cs_all, group, p["tp"], start, end, be=p.get("be"), ax=ax_) if cs_all else None
        if r:
            s_ = _zones_side(z)
            tr = {"t_in": r["t_in"], "fill": r["avg"], "sl": r["sl"], "tp": r["avg"] * (1 + s_ * p["tp"] / 100),
                  "t_out": r["t_out"], "exit": r["exit"],
                  "result": r["result"], "r": round(r["r"], 3), "pct": round(r["pct"], 2), "real": False}
        src = (f"по текущим правилам: лимитки на все линии зон поста, стоп {p['buf']:g}% за дальней линией, "
               f"тейк +{p['tp']:g}% от средней" + (f" · налилось {r['filled']} из {r['legs']}" if r else ""))
    # v0.99.484 — a little before the post (~15% of the width), more after the exit
    # (how the price went on after the stop / take)
    if tr and tr.get("t_out"):
        v1 = min(now, tr["t_out"] + max(86400, 0.6 * (tr["t_out"] - start)))
    else:
        v1 = end
    v0 = start - max(3 * 3600, 0.18 * (v1 - start))
    cs = zones_candles(z["symbol"], v0, v1)
    base_sec = 900
    if v0 < now - 9700 * 3600:
        base_sec = 14400
    elif v0 < now - 9700 * 900:
        base_sec = 3600
    k = 1
    if len(cs) > 360:   # thin out to ~360 candles (merge neighbours)
        k = math.ceil(len(cs) / 360)
        merged = []
        for i in range(0, len(cs), k):
            g = cs[i:i + k]
            merged.append({"time": g[0]["time"], "open": g[0]["open"], "high": max(c["high"] for c in g),
                           "low": min(c["low"] for c in g), "close": g[-1]["close"]})
        cs = merged
    tf_sec = base_sec * k
    tf_txt = (f"{tf_sec // 86400}д" if tf_sec % 86400 == 0 else f"{tf_sec // 3600}ч" if tf_sec % 3600 == 0 else f"{tf_sec // 60}м")
    return jsonify({"ok": True, "symbol": z["symbol"], "side": z["side"], "levels": z["levels"], "post_time": start,
                    "tf": tf_txt + (f" (свеча = {k}×{base_sec // 60 if base_sec < 3600 else base_sec // 3600}{'м' if base_sec < 3600 else 'ч'})" if k > 1 else ""),
                    "status": z.get("status"), "trade": tr, "source": src,
                    "candles": [[c["time"], c["open"], c["high"], c["low"], c["close"]] for c in cs]})


@app.route("/api/zones/upload", methods=["POST"])
def api_zones_upload():
    try:
        f = request.files.get("file")
        if not f:
            return jsonify({"ok": False, "error": "нет файла"}), 400
        pt = request.form.get("post_time")
        post_time = None
        if pt:
            try:
                post_time = float(pt)
            except ValueError:
                post_time = None
        train = request.form.get("train")
        train = None if train is None else train in ("1", "true", "on")
        with _zones_lock:
            train_eff = bool(ZONES.get("train_mode")) if train is None else train
        if train_eff and not post_time:
            return jsonify({"ok": False, "error": "для обучения укажите дату и время поста"}), 400
        post, new = zones_add_post(f.read(), post_time=post_time, source="web", train=train_eff)
        return jsonify({"ok": True, "post": post, "zones": new, "summary": zones_post_summary(post, new)})
    except Exception as e:
        log_error(f"api_zones_upload: {e}")
        return jsonify({"ok": False, "error": str(e)}), 500


@app.route("/api/zones/zone", methods=["POST"])
def api_zones_zone():
    """Create / edit / delete one zone (manual correction of the recognition)."""
    try:
        b = request.get_json(force=True, silent=True) or {}
        with _zones_lock:
            if b.get("id"):
                z = next((x for x in ZONES["zones"] if x["id"] == b["id"]), None)
                if z is None:
                    return jsonify({"ok": False, "error": "нет такой зоны"}), 404
                z["manual"] = True   # v0.99.516 — the history recheck leaves it alone
                if b.get("delete"):
                    z["status"] = "deleted"
                else:
                    if b.get("levels"):
                        s = 1 if (b.get("side") or z["side"]) == "long" else -1
                        z["levels"] = sorted({float(v) for v in b["levels"] if float(v) > 0}, reverse=(s > 0))
                        z["touched"] = [None] * len(z["levels"])
                    if b.get("side") in ("long", "short"):
                        z["side"] = b["side"]
                        s = 1 if z["side"] == "long" else -1
                        z["levels"] = sorted(z["levels"], reverse=(s > 0))
                    if b.get("symbol"):   # the coin is the post's: change it for all of the post's zones
                        new_sym = re.sub(r"[^A-Z0-9]", "", b["symbol"].upper().replace("USDT", "").replace(".P", "")) + "_USDT"
                        for z2 in ZONES["zones"]:
                            if z2.get("post_id") == z.get("post_id") and z2.get("status") in ("watch", "old", "expired", "train", "in_trade"):
                                if ((z2.get("trade") or {}).get("real") or {}).get("legs") and not z2["trade"]["real"].get("done"):
                                    continue   # orders on the exchange: left as they are
                                z2["symbol"] = new_sym
                                z2.pop("lead", None)
                                z2["trade"] = None   # v0.99.539 — the ladder of the wrong coin goes
                                z2["status"] = "train" if z2.get("train") else "watch"
                                z2["touched"], z2["result"] = [None] * len(z2["levels"]), None
                        for p_ in ZONES["posts"]:
                            if p_["id"] == z.get("post_id"):
                                p_["symbol"] = new_sym
                                p_.pop("price_doubt", None)   # v0.99.539 — the user checked the coin
                                p_["notes"] = [n for n in p_.get("notes", []) if "тикер" not in n]
            else:
                post = next((p for p in ZONES["posts"] if p["id"] == b.get("post_id")), None)
                if post is None:
                    post = {"id": f"p{int(time.time() * 1000)}", "created": time.time(), "post_time": time.time(),
                            "source": "manual", "symbol": None, "notes": [], "ok": True}
                    ZONES["posts"].insert(0, post)
                sym = (b.get("symbol") or post.get("symbol") or "").upper().replace("USDT", "").strip("_ /")
                if not sym or not b.get("levels") or b.get("side") not in ("long", "short"):
                    return jsonify({"ok": False, "error": "нужны монета, сторона и уровни"}), 400
                post["symbol"] = sym + "_USDT"
                z = zones_make(post, b["side"], b["levels"])
                z["manual"] = True   # v0.99.517
                ZONES["zones"].insert(0, z)
        if not b.get("delete") and not b.get("id"):
            zones_replay_past(z)
        if b.get("id") and b.get("symbol"):
            with _zones_lock:
                same = [z2 for z2 in ZONES["zones"] if z2.get("post_id") == z.get("post_id") and z2.get("status") in ("watch", "train")]
            for z2 in same:
                zones_replay_past(z2)
        zones_save()
        _zones_learn_event.set()
        return jsonify({"ok": True})
    except Exception as e:
        log_error(f"api_zones_zone: {e}")
        return jsonify({"ok": False, "error": str(e)}), 500


@app.route("/api/zones/reparse", methods=["POST"])
def api_zones_reparse():
    """Run the recognition again on stored posts (all not recognised ones, or one)."""
    b = request.get_json(force=True, silent=True) or {}
    with _zones_lock:
        if b.get("post_id"):
            posts = [p for p in ZONES["posts"] if p["id"] == b["post_id"]]
        else:
            posts = [p for p in ZONES["posts"] if not p.get("ok")]
    done, found = 0, 0
    for post in posts:
        path = os.path.join(ZONES_IMG_DIR, post["id"] + ".jpg")
        if not os.path.exists(path):
            continue
        with open(path, "rb") as f:
            data = f.read()
        new = zones_recognize_post(post, data)
        with _zones_lock:
            for z in ZONES["zones"]:
                if z["post_id"] == post["id"] and z.get("status") in ("watch", "old", "expired", "train") and new:
                    z["status"] = "deleted"   # replaced by the new recognition
            ZONES["zones"] = new + ZONES["zones"]
        for z in new:
            zones_replay_past(z)
        _own_after_post(post, new)
        done += 1
        found += len(new)
        zones_notify(zones_post_summary(post, new))
    zones_save()
    _zones_learn_event.set()
    return jsonify({"ok": True, "posts": done, "zones": found})


@app.route("/api/zones/revive", methods=["POST"])
def api_zones_revive():
    """v0.99.545 — "▶ вернуть в работу": a skipped / expired zone (and the others of its post,
    coin and side) watched again; replayed first — a zone the price already reached is history"""
    b = request.get_json(force=True, silent=True) or {}
    with _zones_lock:
        z = next((x for x in ZONES["zones"] if x["id"] == b.get("id")), None)
        if not z:
            return jsonify({"ok": False, "error": "нет такой зоны"}), 404
        grp = [x for x in ZONES["zones"] if x.get("post_id") == z.get("post_id") and x.get("symbol") == z.get("symbol")
               and x["side"] == z["side"] and x.get("status") in ("skipped", "expired", "hist_wait")]
        for x in grp:
            x["status"] = "watch"
            for k in ("skip", "lead"):
                x.pop(k, None)
            if not ((x.get("trade") or {}).get("real") or {}).get("legs"):
                x["trade"] = None
    for x in grp:
        zones_replay_past(x)
    zones_save()
    back = [x for x in grp if x["status"] == "watch"]
    return jsonify({"ok": True, "watched": len(back), "history": len(grp) - len(back),
                    "msg": (f"в работе: {len(back)}" + (f", уже отработали (цена дошла раньше): {len(grp) - len(back)}" if len(grp) > len(back) else ""))})


@app.route("/api/zones/close_ladder", methods=["POST"])
def api_zones_close_ladder():
    """v0.99.540 — close a ladder by hand: the position at market, its limits, stop and
    take off the exchange, the result recorded. Zones of a coin that is not the post's
    (a misread ticker: ETC zones left under a BTC post) go after it."""
    b = request.get_json(force=True, silent=True) or {}
    with _zones_lock:
        z = next((x for x in ZONES["zones"] if x["id"] == b.get("id")), None)
        if not z:
            return jsonify({"ok": False, "error": "нет такой зоны"}), 404
        lead = z if (z.get("trade") or {}).get("legs") else next((x for x in ZONES["zones"] if x["id"] == z.get("lead")), None)
        tr = (lead or {}).get("trade")
        if not tr or not tr.get("legs"):
            return jsonify({"ok": False, "error": "у зоны нет сделки"}), 400
        group = [x for x in ZONES["zones"] if x["id"] == lead["id"] or x.get("lead") == lead["id"]]
        post = next((p_ for p_ in ZONES["posts"] if p_["id"] == lead.get("post_id")), None)
    sym, s_ = tr["symbol"], (1 if tr["direction"] == "LONG" else -1)
    r = tr.get("real")
    if r and not r.get("done"):
        try:
            with using_account("zones"):
                pos_ = [x for x in (get_open_positions() or []) if x.get("contract") == sym]
            if _zones_pos({sym: pos_}, sym, s_) and sum(l_.get("filled") or 0 for l_ in r["legs"]) > 0:
                if not _zones_close_real(sym, tr["direction"], "closed by hand"):
                    return jsonify({"ok": False, "error": "биржа не подтвердила закрытие — попробуйте ещё раз"}), 502
            if not _zones_real_cancel_legs(tr):
                return jsonify({"ok": False, "error": "не удалось снять лимитки — попробуйте ещё раз"}), 502
            for oid in set(r.get("trigs") or []) | set(r.get("stale") or []):
                try:
                    cancel_price_order(oid)
                except Exception:
                    pass
            r["done"] = True
        except Exception as e:
            return jsonify({"ok": False, "error": f"биржа: {str(e)[:150]}"}), 502
    px = (_zones_symbols_and_prices() or {}).get(sym)
    if tr.get("status") == "OPEN" and px:
        _zones_ladder_finish(tr, group, "MANUAL", px, int(time.time()))
    elif tr.get("status") in ("PENDING", "OPEN"):
        with _zones_lock:
            tr["status"] = "EXPIRED"
            for zz in group:
                zz["status"] = "expired"
    if post and post.get("symbol") and post["symbol"] != sym:
        with _zones_lock:
            for zz in group:
                zz["status"] = "deleted"   # the misread coin's zones go
    zones_save()
    zones_notify(f"✋ {sym}: сделку зон закрыл вручную" + (f" по {px:.6g}" if px else "") + " · лимитки, стоп и тейк сняты")
    return jsonify({"ok": True})


