_zones_recheck_lock = threading.Lock()


ZONES_RECHECK_MARK = 515   # v0.99.515 — a post recognised again by this recogniser carries this mark


def zones_live_sanity(force=False):
    """v0.99.544 — the posts being watched / traded now were left out of the history
    re-reading (not to disturb a trade), so a mistake of the old recogniser could stay in
    work: the SEI result post — its "-19.13%" label read as a short zone — opened a real
    short. Once (and on demand) every live post is read again: a result post or other
    zones than the stored ones -> the zones without orders on the exchange stop, a ladder
    with orders gets a message to close it by hand (✖ закрыть)."""
    with _zones_lock:
        if ZONES.get("live_sanity_v544") and not force:
            return 0
        live_pids = {z.get("post_id") for z in ZONES["zones"] if z.get("status") in ("watch", "in_trade")
                     and not z.get("own") and not z.get("oc") and not z.get("manual")}
        posts = [p_ for p_ in ZONES["posts"] if p_["id"] in live_pids]
    try:
        prices = _zones_symbols_and_prices()
    except Exception:
        return 0
    n = 0
    for post in posts:
        path = os.path.join(ZONES_IMG_DIR, post["id"] + ".jpg")
        if not os.path.exists(path):
            continue
        try:
            with open(path, "rb") as f:
                rec = zones_recognize(f.read(), live_price_fn=lambda s_: prices.get(s_), symbols=set(prices) or None)
        except Exception as e:
            log_error(f"zones live sanity {post.get('symbol')}: {e}")
            continue
        with _zones_lock:
            zs = [z for z in ZONES["zones"] if z.get("post_id") == post["id"] and z.get("status") in ("watch", "in_trade")]
        key_old = {(z["side"], tuple(round(v, 6) for v in z["levels"])) for z in zs}
        px_ = prices.get(post.get("symbol") or "")
        new_z = [(z["side"], zones_scale_fix(z["levels"], px_)[0] if px_ else z["levels"]) for z in (rec.get("zones") or [])]
        same = lambda zo: any(zo[0] == sd and len(lv) == len(zo[1]) and all(abs(a_ - b_) <= 0.003 * abs(b_) for a_, b_ in zip(sorted(lv), sorted(zo[1])))
                              for sd, lv in new_z)
        sym = (post.get("symbol") or "").replace("_USDT", "")
        when = time.strftime('%d.%m %H:%M', time.localtime(post['post_time']))
        if not rec.get("result_post"):
            diff = [zo for zo in key_old if not same(zo)]
            if diff and new_z:   # only a message: the stored zones may have been set right by hand
                n += 1
                zones_notify(f"ℹ️ {sym}: пост от {when} сегодня распознаётся иначе — у бота "
                             + "; ".join(f"{'лонг' if sd == 'long' else 'шорт'} {' / '.join(f'{v:g}' for v in lv)}" for sd, lv in diff)
                             + ", на скрине сейчас " + "; ".join(f"{'лонг' if sd == 'long' else 'шорт'} {' / '.join(f'{v:g}' for v in lv)}" for sd, lv in new_z)
                             + ". Проверьте во вкладке «Зоны» (ничего не менял).")
            continue
        bad = key_old
        why = "это пост-отчёт автора (результат отработки), а не сетап"
        real_left = []
        with _zones_lock:
            for z in zs:
                if (z["side"], tuple(round(v, 6) for v in z["levels"])) not in bad:
                    continue
                lead = z if (z.get("trade") or {}).get("legs") else next((x for x in ZONES["zones"] if x["id"] == z.get("lead")), z)
                rl = (lead.get("trade") or {}).get("real") or {}
                if rl.get("legs") and not rl.get("done"):
                    real_left.append(z)
                    continue
                z["status"], z["skip"] = "skipped", "recheck"
                if z is lead:
                    z["trade"] = None
        n += 1
        zones_notify(f"⚠️ {sym}: пост от {when} — {why}. "
                     + (f"По нему на бирже есть ордера/позиция — проверьте и закройте кнопкой «✖ закрыть» во вкладке «Зоны»."
                        if real_left else "Его зоны без ордеров сняты с работы."))
    with _zones_lock:
        ZONES["live_sanity_v544"] = True
    zones_save()
    return n


def zones_recheck_results(force=False):
    """v0.99.502 — the stored history recognised again with the current recogniser
    (v0.99.503: every post, not only the "result" ones — old mistakes such as a
    hand-drawn red frame read as a short zone, a result label, a misread scale
    are fixed). A post whose zones come out different gets the new ones; posts
    with a zone the bot is watching or trading now are left as they are; a coin
    set by hand is kept. Background, no Telegram messages."""
    if not _zones_recheck_lock.acquire(blocking=False):
        return
    try:
        with _zones_lock:
            live_posts = {z.get("post_id") for z in ZONES["zones"]
                          if z.get("status") in ("watch", "in_trade") or (z.get("trade") or {}).get("status") in ("PENDING", "OPEN")}
            # v0.99.516 — a post corrected by hand keeps the user's zones
            manual_posts = {z.get("post_id") for z in ZONES["zones"] if z.get("manual")}
            posts = [p_ for p_ in ZONES["posts"] if p_["id"] not in live_posts and not p_.get("own")
                     and p_["id"] not in manual_posts]
            if force:   # the button: everything again
                for p_ in posts:
                    p_.pop("rechk", None)
            # v0.99.513 — after a restart it goes on where it stopped
            posts = [p_ for p_ in posts if p_.get("rechk") != ZONES_RECHECK_MARK]
        found = changed_n = 0
        zones_act("recheck", running=True, done=0, total=len(posts), found=0, changed=0, error=None)
        key = lambda zs: sorted((z["side"], tuple(round(v, 6) for v in z["levels"])) for z in zs)
        for i, post in enumerate(posts):
            zones_act("recheck", done=i, found=found, changed=changed_n)
            path = os.path.join(ZONES_IMG_DIR, post["id"] + ".jpg")
            if not os.path.exists(path):
                continue
            old_sym = post.get("symbol")
            with _zones_lock:
                old = [z for z in ZONES["zones"] if z.get("post_id") == post["id"] and z.get("status") != "deleted"]
            try:
                with open(path, "rb") as f:
                    new = zones_recognize_post(post, f.read())
                if not new and old_sym and (post.get("pending") or {}).get("zones"):   # the coin was set by hand before
                    pend = post.pop("pending")
                    post["symbol"] = old_sym
                    px_ = None
                    try:
                        cs_ = zones_candles(old_sym, post["post_time"], post["post_time"] + 4 * 3600)
                        px_ = cs_[0]["open"] if cs_ else None
                    except Exception:
                        pass
                    new = [zones_make(post, zr["side"], zones_scale_fix(zr["levels"], px_)[0]) for zr in pend["zones"]]
                    post["ok"] = bool(new)
                    post["notes"] = [n for n in post.get("notes", []) if not n.startswith("тикер не распознан")]
            except Exception as e:
                log_error(f"zones recheck {post.get('id')}: {e}")
                continue
            found += bool(post.get("result_post"))
            post["rechk"] = ZONES_RECHECK_MARK
            if i % 20 == 0:
                zones_save()   # the marks on disk as it goes
            if key(new) == key(old):
                continue   # the same zones: the stored ones (and their results) stay
            changed_n += 1
            with _zones_lock:
                for z in old:
                    if not z.get("trade"):
                        z["status"] = "deleted"
                ZONES["zones"] = new + ZONES["zones"]
            for z in new:
                zones_replay_past(z)
                # v0.99.516 — the history recognised again is history: an old post
                # (already traded / skipped / broken before) never opens a new ladder;
                # a zone not reached yet joins the learning when its 14 days are over
                with _zones_lock:
                    z["from_rechk"] = True
                    if z["status"] == "watch":
                        z["status"] = "hist_wait"
        with _zones_lock:
            ZONES["recheck_v515"] = True
        zones_save()
        zones_act("recheck", running=False, done=len(posts), found=found, changed=changed_n, finished=time.time())
        _zones_learn_event.set()
    except Exception as e:
        log_error(f"zones recheck: {e}")
        zones_act("recheck", running=False, error=str(e)[:200])
    finally:
        _zones_recheck_lock.release()


