@app.route("/api/emw/chart/<symbol>")
def api_emw_chart(symbol):
    """v0.99.573 — user: "хочу везде открыть график и посмотреть, где цена, у какой EMA, и так же
    на истории сделок": the week / month candles with EMA 7 / 14 / 28 around a moment (a signal,
    a backtest trade, or now) + the 4h candles around it"""
    try:
        tf = request.args.get("tf", "1w")
        tf = tf if tf in EMW_EMAS else "1w"
        t_at = int(float(request.args.get("time") or 0))
        exit_t = int(float(request.args.get("exit_time") or 0))
        now = int(time.time())
        daily = emw_fetch_daily(symbol)
        if not daily:
            return jsonify({"error": "нет свечей с биржи"}), 404
        bars = emw_bars(daily, tf)
        closes = [b["close"] for b in bars]
        emas = {n: emw_ema(closes, n) for n in EMW_EMAS[tf]}
        anchor = t_at or now
        ib = max([i for i, b in enumerate(bars) if b["time"] <= anchor] or [len(bars) - 1])
        i0, i1 = max(0, ib - 52), min(len(bars), ib + 9)
        out_bars = []
        for i in range(i0, i1):
            b = bars[i]
            out_bars.append({"time": b["time"], "open": b["open"], "high": b["high"], "low": b["low"], "close": b["close"],
                             "forming": emw_next_period(b["time"], tf) > now,
                             "ema": {str(n): emas[n][i] for n in emas}, "level": {str(n): (emas[n][i - 1] if i > 0 else None) for n in emas}})
        center = t_at or now
        # v0.99.578 — "внизу каша": just the trade and a little around it; a long one on daily candles
        h_from = (center - 2 * 86400) if t_at else min(bars[ib]["time"], center - 2 * 86400)
        h_to = min(now, max(exit_t, center) + 86400)
        if h_to - h_from > 14 * 86400:
            h_tf = "1d"
            h4 = [c for c in daily if h_from - 2 * 86400 <= c["time"] <= h_to][-90:]
        else:
            h_tf = "4h"
            h4 = get_candles_range(symbol, "4h", h_from, h_to) or []
            h4 = [c for c in h4 if h_from <= c["time"] <= h_to][-90:]
        # v0.99.574 — user: "линии стопа и тейка не вижу": a trade / row without its own stop and
        # take (older model, a watch row) gets them from the model's learned variant of its EMA:
        # the daily ATR known at that moment, the stop / take % the model chose
        calc = None
        key = request.args.get("key") or ""
        m = STATE.get("emw_model") or {}
        setup = next((x for x in m.get("setups") or [] if x.get("key") == key), None)
        b_ = (setup or {}).get("best")
        if b_ and b_.get("off") == "W":   # the stop sits beyond the wick — known only from the trade itself
            calc = {"mode": "wick"}
        elif b_ and b_.get("sl") is not None:
            sgn = -1 if key.endswith("|S") else 1
            day0 = (t_at or now) // 86400 * 86400
            closed = [c for c in daily if c["time"] < day0]
            datr = (neuro_atr_series(closed, EMW_DATR_LEN) or [None])[-1] if len(closed) > EMW_DATR_LEN else None
            n_ = int(key.split("|")[1]) if key.count("|") == 2 else None
            lv_ = request.args.get("level")
            lv_ = float(lv_) if lv_ else (emas[n_][ib - 1] if n_ in emas and ib > 0 else None)
            if datr and lv_:
                ent = request.args.get("entry")
                ent = float(ent) if ent else lv_ + sgn * EMW_TRIGGER_DATR * datr
                stop = emw_sl_price(ent, b_["sl"], sgn, datr)
                take = emw_take_price(ent, b_["tk"], sgn, datr)
                calc = {"entry": ent, "sl": stop, "tp": take, "level": lv_, "datr": datr, "stop_txt": emw_stop_pct_txt(b_, datr, ent),
                        "take_txt": emw_take_txt(b_, datr, ent), "hold": b_.get("hold")}
        return jsonify({"symbol": symbol, "tf": tf, "bars": out_bars, "anchor": bars[ib]["time"], "h4": h4, "h_tf": h_tf, "calc": calc,
                        "price": daily[-1]["close"], "now": now, "emas": [str(n) for n in EMW_EMAS[tf]]})
    except Exception as e:
        log_error(f"api_emw_chart {symbol}: {e}")
        return jsonify({"error": str(e)[:200]}), 500


