_POS_SUMMARY_CACHE = {"at": 0.0, "data": None}
_POS_SUMMARY_TTL = 15


# v0.99.406 — charging state for the screensaver's red outline, for browsers
# without the Battery API. Termux:API's `termux-battery-status` first (needs
# the Termux:API app + `pkg install termux-api`), then /sys (Linux; usually
# closed on Android). Cached 30 s; a missing tool is not retried for 10 min.
_battery_cache = {"ts": 0.0, "data": None, "tool_fail_ts": 0.0}


def read_battery_state():
    now = time.time()
    if _battery_cache["data"] is not None and now - _battery_cache["ts"] < 30:
        return _battery_cache["data"]
    data = {"ok": False}
    if now - _battery_cache["tool_fail_ts"] > 600:
        try:
            import subprocess
            out = subprocess.run(["termux-battery-status"], capture_output=True, text=True, timeout=8).stdout
            j = json.loads(out)
            st = str(j.get("status", "")).upper()
            plugged = str(j.get("plugged", "")).upper()
            data = {"ok": True, "charging": st in ("CHARGING", "FULL") or (plugged not in ("", "UNPLUGGED") and st != "DISCHARGING"),
                    "level": j.get("percentage"), "source": "termux-api"}
        except Exception:
            _battery_cache["tool_fail_ts"] = now
    if not data["ok"]:
        try:
            base = "/sys/class/power_supply"
            for name in sorted(os.listdir(base)):
                path = os.path.join(base, name, "status")
                if os.path.exists(path):
                    st = open(path).read().strip().upper()
                    if st:
                        data = {"ok": True, "charging": st in ("CHARGING", "FULL"), "level": None, "source": "sys"}
                        break
        except Exception:
            pass
    _battery_cache.update(ts=now, data=data)
    return data


@app.route("/api/battery")
def api_battery():
    return jsonify(read_battery_state())


# v0.99.582 — user: "на серверном телефоне села батарея, а в Telegram не пришло уведомление — иногда
# забываю поставить на зарядку": one Telegram message when the phone running the bot is at 10 %
# or less and NOT charging (once per discharge; again only after it has been charged).
BATTERY_ALERTS_ENABLED = os.environ.get("VP_BATTERY_ALERTS", "1") == "1"
BATTERY_ALERT_PCT = 10


def battery_watch_loop():
    time.sleep(60)
    sent, warned_unreadable = False, False
    while True:
        heartbeat("battery_watch_loop")
        try:
            b = read_battery_state()
            if not b.get("ok") or b.get("level") is None:
                if not warned_unreadable:
                    warned_unreadable = True
                    log_error("battery watch: заряд батареи не читается — нужен Termux:API "
                              "(приложение Termux:API + `pkg install termux-api`), без него предупреждения о батарее не будет")
            elif b.get("charging"):
                sent = False
            elif BATTERY_ALERTS_ENABLED and not sent and float(b["level"]) <= BATTERY_ALERT_PCT:
                sent = True
                send_telegram(f"🪫 Телефон с ботом: заряд {float(b['level']):.0f}% и не заряжается — поставь на зарядку, "
                              f"иначе бот выключится")
        except Exception as e:
            log_error(f"battery_watch_loop: {e}")
        time.sleep(300)


@app.route("/api/positions/summary")
def api_positions_summary():
    """v0.99.346 — REAL open positions on the exchange, across the main
    account and every module sub-account (user: "часы на скринсейвере
    зелёные, хотя сделок нет" — the clock used to go green on any OPEN
    live SIGNAL of MSNR/Mirror/Sweep, including dry-run and not-opened
    ones, and ignored Neuro/S&R/Peak). Cached 15s so several clients /
    fast polling don't add exchange load."""
    now = time.time()
    if _POS_SUMMARY_CACHE["data"] is not None and now - _POS_SUMMARY_CACHE["at"] < _POS_SUMMARY_TTL:
        return jsonify(_POS_SUMMARY_CACHE["data"])
    total, by_acc, ok_any, errors = 0, {}, False, []
    for acc in all_account_ids():
        try:
            with using_account(None if acc == "default" else acc):
                key, secret, _a = _current_credentials()
                if not key or not secret:
                    continue
                positions = get_open_positions() or []
            n = sum(1 for p in positions if float(p.get("size", 0) or 0) != 0)
            by_acc[account_label(acc)] = n
            total += n
            ok_any = True
        except Exception as e:
            errors.append(f"{account_label(acc)}: {e}")
    data = {"ok": ok_any, "open": total, "by_account": by_acc, "errors": errors[:3], "checked_at": now}
    _POS_SUMMARY_CACHE.update(at=now, data=data)
    return jsonify(data)


@app.route("/api/credentials/test", methods=["POST"])
def api_test_credentials():
    """v0.99.331, reworked v0.99.345 (user: "при проверке API везде остаток 0,
    а баланс всегда основного аккаунта, даже если это субаккаунт"). The
    first version showed /futures/usdt/accounts total/available — on a
    Gate UNIFIED account "available" there is always 0 and the money is in
    /unified/accounts, so it looked empty/wrong. Now it reports:
    - uid: the Gate user id the keys belong to (/account/detail) — the only
      reliable proof that a module's keys are the SUB-account's, not the
      main account's (a sub-account has its own uid);
    - trade_balance: exactly what autotrade sizes positions from
      (get_futures_total_equity(): futures available + position margin,
      with the unified-equity fallback), plus the raw futures / unified
      numbers for context."""
    body = request.get_json(force=True, silent=True) or {}
    mode = body.get("module") or None
    try:
        with using_account(mode):
            acc = current_account_id()
            uid = None
            try:
                det = gate_signed_request("GET", "/account/detail")
                uid = det.get("user_id")
            except Exception as e:
                log_error(f"credentials test {account_label(acc)}: /account/detail: {e}")
            fut = gate_signed_request("GET", "/futures/usdt/accounts") or {}
            unified = None
            try:
                unified = get_unified_account_equity()
            except Exception:
                pass
            try:
                trade_balance = get_futures_total_equity()
            except Exception as e:
                trade_balance = None
                log_error(f"credentials test {account_label(acc)}: equity: {e}")
            positions = get_open_positions() or []
        return jsonify({"ok": True, "account": account_label(acc), "uid": uid,
                        "trade_balance": trade_balance,
                        "futures_available": fut.get("available"), "futures_total": fut.get("total"),
                        "unified_equity": unified,
                        "dual_mode": bool(fut.get("in_dual_mode", False)), "open_positions": len(positions)})
    except Exception as e:
        return jsonify({"ok": False, "error": str(e)})


