  ctx.beginPath(); ctx.moveTo(xp, padT); ctx.lineTo(xp, padT + plotH); ctx.stroke(); ctx.setLineDash([]);
  ctx.fillStyle = '#8a93a3'; ctx.font = '11px sans-serif'; ctx.fillText('пост', xp + 3, padT + 11);
